const TANYA_TEXT: Record<string, string[]> = {"Tanya, Part I; Likkutei Amarim 10:1":["וְהִנֵּה, כְּשֶׁהָאָדָם מַגְבִּיר נַפְשׁוֹ הָאֱלֹהִית וְנִלְחָם כָּל כָּךְ עִם הַבַּהֲמִית, עַד שֶׁמְּגָרֵשׁ וּמְבַעֵר הָרָע שֶׁבָּהּ מֵחָלָל הַשְּׂמָאלִי, כְּמוֹ שֶׁכָּתוּב: ״וּבִעַרְתָּ הָרָע מִקִּרְבֶּךָ״, וְאֵין הָרָע נֶהְפָּךְ לְטוֹב מַמָּשׁ – נִקְרָא ״צַדִּיק שֶׁאֵינוֹ גָמוּר״ וְ״צַדִּיק וְרַע לוֹ״. דְּהַיְינוּ, שֶׁיֵּשׁ בּוֹ עֲדַיִין מְעַט מִזְּעֵר רָע בֶּחָלָל הַשְּׂמָאלִי, אֶלָּא שֶׁכָּפוּף וּבָטֵל לַטּוֹב מֵחֲמַת מִיעוּטוֹ, וְלָכֵן, נִדְמֶה לוֹ כִּי ״וַיְגָרְשֵׁהוּ וַיֵּלֶךְ לוֹ״ כּוּלּוֹ לְגַמְרֵי, אֲבָל בֶּאֱמֶת, אִלּוּ חָלַף וְהָלַךְ לוֹ לְגַמְרֵי כָּל הָרָע שֶׁבּוֹ – הָיָה נֶהְפָּךְ לְטוֹב מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 10:3":["וְצַדִּיק שֶׁאֵינוֹ גָמוּר, הוּא שֶׁאֵינוֹ שׂוֹנֵא הַסִּטְרָא אָחֳרָא בְּתַכְלִית הַשִּׂנְאָה, וְלָכֵן אֵינוֹ מוֹאֵס גַּם כֵּן בָּרַע בְּתַכְלִית."],"Tanya, Part I; Likkutei Amarim 10:5":["וְהִנֵּה, מַדְרֵגָה זוֹ מִתְחַלֶּקֶת לְרִבְבוֹת מַדְרֵגוֹת בְּעִנְיַן בְּחִינַת מִיעוּט הָרָע הַנִּשְׁאָר מֵאַחַת מֵאַרְבַּע יְסוֹדוֹת הָרָעִים, וּבְעִנְיַן בִּיטּוּלוֹ בְּמִיעוּטוֹ בְּשִׁשִּׁים עַל דֶּרֶךְ מָשָׁל, אוֹ בְּאֶלֶף וּרְבָבָה וְכַיּוֹצֵא עַל דֶּרֶךְ מָשָׁל. וְהֵן הֵם בְּחִינוֹת צַדִּיקִים הָרַבִּים שֶׁבְּכָל הַדּוֹרוֹת, כִּדְאִיתָא בַּגְּמָרָא, דִּתַמְנֵיסַר אַלְפֵי צַדִּיקֵי קָיְימֵי קַמֵּיהּ הַקָּדוֹשׁ־בָּרוּךְ־הוּא."],"Tanya, Part I; Likkutei Amarim 10:7":["וְעוֹד נִקְרָאִים בְּנֵי עֲלִיָּה, מִפְּנֵי שֶׁגַּם עֲבוֹדָתָם בִּבְחִינַת ״וַעֲשֵׂה טוֹב״ בְּקִיּוּם הַתּוֹרָה וּמִצְוֹתֶיהָ, הוּא לְצוֹרֶךְ גָּבוֹהַּ וּמַעְלָה מַּעְלָה עַד רוּם הַמַּעֲלוֹת, וְלֹא כְּדֵי לְדָבְקָה בּוֹ יִתְבָּרֵךְ בִּלְבָד לְרַוּוֹת צִמְאוֹן נַפְשָׁם הַצְּמֵאָה לַה׳, כְּמוֹ שֶׁכָּתוּב: ״הוֹי כָּל צָמֵא לְכוּ לַמַּיִם״, וּכְמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר, אֶלָּא כִּדְפֵירְשׁוּ בַּתִּיקּוּנִים: ״אֵיזֶהוּ חָסִיד – הַמִּתְחַסֵּד עִם קוֹנוֹ״; עִם קַן דִּילֵיהּ, לְיַיחֲדָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בַּתַּחְתּוֹנִים, וּכְמוֹ שֶׁכָּתוּב בְּרַעְיָא מְהֵימְנָא פָּרָשַׁת תֵּצֵא: ״כִּבְרָא דְּאִשְׁתַּדֵּל בָּתַר אֲבוֹי וְאִימֵּיהּ, דְּרָחִים לוֹן יַתִּיר מִגַּרְמֵיהּ וְנַפְשֵׁיהּ וְרוּחֵיהּ וְנִשְׁמְתֵיהּ כוּ׳, וּמָסַר גַּרְמֵיהּ לְמִיתָה עֲלַיְיהוּ לְמִיפְרַק לוֹן כוּ׳״, וּכְמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר."],"Tanya, Part I; Likkutei Amarim 11:1":["וְזֶה לְעוּמַּת זֶה, רָשָׁע וְטוֹב לוֹ לְעוּמַּת צַדִּיק וְרַע לוֹ."],"Tanya, Part I; Likkutei Amarim 12:1":["וְהַבֵּינוֹנִי, הוּא שֶׁלְּעוֹלָם אֵין הָרָע גּוֹבֵר כָּל כָּךְ לִכְבּוֹשׁ אֶת הָעִיר קְטַנָּה לְהִתְלַבֵּשׁ בַּגּוּף לְהַחֲטִיאוֹ; דְּהַיְינוּ, שֶׁשְּׁלֹשָׁה לְבוּשֵׁי נֶפֶשׁ הַבַּהֲמִית, שֶׁהֵם מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁמִּצַּד הַקְּלִיפָּה, אֵין גּוֹבְרִים בּוֹ עַל נֶפֶשׁ הָאֱלֹהִית לְהִתְלַבֵּשׁ בַּגּוּף – בַּמּוֹחַ וּבַפֶּה וּבִשְׁאָר רַמַ״ח אֵבָרִים, לְהַחֲטִיאָם וּלְטַמְּאָם חַס וְשָׁלוֹם."],"Tanya, Part I; Likkutei Amarim 12:10":["רַק שֶׁלָּזֶה מוֹעִיל הָרְשִׁימוּ בַּמּוֹחִין, וְיִרְאַת ה׳ וְאַהֲבָתוֹ הַמְסוּתֶּרֶת בֶּחָלָל הַיְמָנִי, לְהִתְגַּבֵּר וְלִשְׁלוֹט עַל הָרָע הַזֶּה הַמִּתְאַוֶּה תַּאֲוָה, שֶׁלֹּא לִהְיוֹת לוֹ שְׁלִיטָה וּמֶמְשָׁלָה בָּעִיר לְהוֹצִיא תַּאֲוָתוֹ מִכֹּחַ אֶל הַפּוֹעַל לְהִתְלַבֵּשׁ בְּאֵבְרֵי הַגּוּף."],"Tanya, Part I; Likkutei Amarim 12:3":["אַךְ מַהוּת וְעַצְמוּת נֶפֶשׁ הָאֱלֹהִית, שֶׁהֵן עֶשֶׂר בְּחִינוֹתֶיהָ, לֹא לָהֶן לְבַדָּן הַמְּלוּכָה וְהַמֶּמְשָׁלָה בָּעִיר קְטַנָּה, כִּי אִם בְּעִתִּים מְזוּמָּנִים, כְּמוֹ בִּשְׁעַת קְרִיאַת שְׁמַע וּתְפִלָּה שֶׁהִיא שְׁעַת מוֹחִין דְּגַדְלוּת לְמַעְלָה, וְגַם לְמַטָּה הִיא שְׁעַת הַכּוֹשֶׁר לְכָל אָדָם, שֶׁאָז מְקַשֵּׁר חָכְמָה־בִּינָה־דַּעַת שֶׁלּוֹ לַה׳ – לְהַעֲמִיק דַּעְתּוֹ בִּגְדוּלַּת אֵין־סוֹף בָּרוּךְ־הוּא, וּלְעוֹרֵר אֶת הָאַהֲבָה כְּרִשְׁפֵּי אֵשׁ בֶּחָלָל הַיְמָנִי שֶׁבְּלִבּוֹ, לְדָבְקָה בוֹ בְּקִיּוּם הַתּוֹרָה וּמִצְוֹתֶיהָ מֵאַהֲבָה, שֶׁזֶּהוּ עִנְיָן הַמְבוֹאָר בִּקְרִיאַת שְׁמַע דְּאוֹרַיְיתָא, וּבִרְכוֹתֶיהָ שֶׁלְּפָנֶיהָ וּלְאַחֲרֶיהָ שֶׁהֵן מִדְּרַבָּנָן – הֵן הֲכָנָה לְקִיּוּם הַקְּרִיאַת־שְׁמַע, כְּמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר; וְאָז, הָרָע שֶׁבֶּחָלָל הַשְּׂמָאלִי כָּפוּף וּבָטֵל לַטּוֹב הַמִּתְפַּשֵּׁט בֶּחָלָל הַיְמָנִי מֵחָכְמָה־בִּינָה־דַּעַת שֶׁבַּמּוֹחַ הַמְקוּשָּׁרִים בִּגְדוּלַּת אֵין־סוֹף בָּרוּךְ־הוּא."],"Tanya, Part I; Likkutei Amarim 12:5":["רַק מִפְּנֵי שֶׁלֹּא לוֹ לְבַדּוֹ מִשְׁפַּט הַמְּלוּכָה וְהַמֶּמְשָׁלָה בָּעִיר, אֵינוֹ יָכוֹל לְהוֹצִיא תַּאֲוָתוֹ מִכֹּחַ אֶל הַפּוֹעַל, לְהִתְלַבֵּשׁ בְּאֵבְרֵי הַגּוּף בְּמַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה מַמָּשׁ, לְהַעֲמִיק מַחֲשַׁבְתּוֹ בְּתַעֲנוּגֵי עוֹלָם הַזֶּה אֵיךְ לְמַלֹּאת תַּאֲוַת לִבּוֹ, כִּי הַמּוֹחַ שַׁלִּיט עַל הַלֵּב [כְּמוֹ שֶׁכָּתוּב בְּרַעְיָא מְהֵימְנָא פָּרָשַׁת פִּינְחָס] בְּתוֹלַדְתּוֹ וְטֶבַע יְצִירָתוֹ, שֶׁכָּךְ נוֹצַר הָאָדָם בְּתוֹלַדְתּוֹ, שֶׁכָּל אָדָם יָכוֹל בִּרְצוֹנוֹ שֶׁבְּמוֹחוֹ לְהִתְאַפֵּק וְלִמְשׁוֹל בְּרוּחַ תַּאֲוָתוֹ שֶׁבְּלִבּוֹ, שֶׁלֹּא לְמַלֹּאת מִשְׁאֲלוֹת לִבּוֹ בְּמַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה, וּלְהַסִּיחַ דַּעְתּוֹ לְגַמְרֵי מִתַּאֲוֹת לִבּוֹ אֶל הַהֵפֶךְ לְגַמְרֵי, וּבִפְרָט אֶל צַד הַקְּדוּשָּׁה."],"Tanya, Part I; Likkutei Amarim 12:7":["וְאַף־עַל־פִּי־כֵן אֵינוֹ נִקְרָא ״צַדִּיק״ כְּלָל, מִפְּנֵי שֶׁיִּתְרוֹן הַזֶּה אֲשֶׁר לְאוֹר נֶפֶשׁ הָאֱלֹהִית עַל הַחוֹשֶׁךְ וְסִכְלוּת שֶׁל הַקְּלִיפָּה הַנִּדְחֶה מִמֵּילָא – אֵינוֹ אֶלָּא בִּשְׁלֹשָׁה לְבוּשֶׁיהָ הַנִּזְכָּרִים לְעֵיל, וְלֹא בְּמַהוּתָהּ וְעַצְמוּתָהּ עַל מַהוּתָהּ וְעַצְמוּתָהּ שֶׁל הַקְּלִיפָּה, כִּי מַהוּתָהּ וְעַצְמוּתָהּ שֶׁל נֶפֶשׁ הַבַּהֲמִית שֶׁמֵּהַקְּלִיפָּה שֶׁבֶּחָלָל הַשְּׂמָאלִי – לֹא נִדְחָה כְּלָל מִמְּקוֹמוֹ בַּבֵּינוֹנִי אַחַר הַתְּפִלָּה, שֶׁאֵין רִשְׁפֵּי אֵשׁ אַהֲבַת ה׳ בְּהִתְגַּלּוּת לִבּוֹ בֶּחָלָל הַיְמָנִי, כִּי אִם תּוֹכוֹ רָצוּף ״אַהֲבָה מְסוּתֶּרֶת״, שֶׁהִיא אַהֲבָה הַטִּבְעִית שֶׁבַּנֶּפֶשׁ הָאֱלֹהִית, כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן."],"Tanya, Part I; Likkutei Amarim 13:1":["וּבָזֶה יוּבַן לְשׁוֹן מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״בֵּינוֹנִים זֶה וָזֶה שׁוֹפְטָן״ [פֵּירוּשׁ, יֵצֶר טוֹב וְיֵצֶר הָרָע], דִּכְתִיב: ״כִּי יַעֲמוֹד לִימִין אֶבְיוֹן לְהוֹשִׁיעַ מִשּׁוֹפְטֵי נַפְשׁוֹ״, וְלֹא אָמְרוּ ״זֶה וָזֶה מוֹשְׁלִים״ חַס וְשָׁלוֹם, כִּי כְּשֶׁיֵּשׁ אֵיזוֹ שְׁלִיטָה וּמֶמְשָׁלָה לַיֵּצֶר הָרָע בָּ״עִיר קְטַנָּה״, אֲפִילוּ לְפִי שָׁעָה קַלָּה – נִקְרָא רָשָׁע בְּאוֹתָהּ שָׁעָה."],"Tanya, Part I; Likkutei Amarim 13:11":["וְהִנֵּה, מִדַּת אַהֲבָה זוֹ, הָאֲמוּרָה בְּבֵינוֹנִים, בִּשְׁעַת הַתְּפִלָּה, עַל יְדֵי הִתְגַּבְּרוּת הַנֶּפֶשׁ הָאֱלֹהִית כוּ׳, הִנֵּה לְגַבֵּי מַדְרֵגַת הַצַּדִּיקִים עוֹבְדֵי ה׳ בֶּאֱמֶת לַאֲמִיתּוֹ, אֵין בְּחִינַת אַהֲבָה זוֹ נִקְרֵאת בְּשֵׁם ״עֲבוֹדַת אֱמֶת״ כְּלָל, מֵאַחַר שֶׁחוֹלֶפֶת וְעוֹבֶרֶת אַחַר הַתְּפִלָּה, וּכְתִיב: ״שְׂפַת אֱמֶת תִּכּוֹן לָעַד, וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר״."],"Tanya, Part I; Likkutei Amarim 13:5":["אַךְ מֵאַחַר שֶׁהָרָע שֶׁבֶּחָלָל הַשְּׂמָאלִי בַּבֵּינוֹנִי הוּא בְּתָקְפּוֹ כְּתוֹלַדְתּוֹ, לְהִתְאַוֹּת תַּאֲוָה לְכָל תַּעֲנוּגֵי עוֹלָם הַזֶּה, וְלֹא נִתְבַּטֵּל בְּמִיעוּט לְגַבֵּי הַטּוֹב וְלֹא נִדְחָה מִמְּקוֹמוֹ כְּלָל, רַק שֶׁאֵין לוֹ שְׁלִיטָה וּמֶמְשָׁלָה לְהִתְפַּשֵּׁט בְּאֵבְרֵי הַגּוּף, – מִפְּנֵי הַקָּדוֹשׁ־בָּרוּךְ־הוּא הָעוֹמֵד לִימִין אֶבְיוֹן וְעוֹזֵר וּמֵאִיר לַנֶּפֶשׁ הָאֱלֹהִית – לָכֵן נִקְרָא – ״כְּרָשָׁע״, – כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אֲפִילוּ כָּל הָעוֹלָם כּוּלּוֹ אוֹמְרִים לְךָ צַדִּיק אַתָּה – הֱיֵה בְעֵינֶיךָ כְּרָשָׁע״, וְלֹא רָשָׁע מַמָּשׁ, – אֶלָּא שֶׁיַּחֲזִיק עַצְמוֹ לְבֵינוֹנִי, וְלֹא לְהַאֲמִין לְהָעוֹלָם שֶׁאוֹמְרִים שֶׁהָרָע שֶׁבּוֹ נִתְבַּטֵּל לְגַבֵּי הַטּוֹב, שֶׁזּוֹ מַדְרֵגַת צַדִּיק, – אֶלָּא יִהְיֶה בְעֵינָיו כְּאִלּוּ מַהוּתוֹ וְעַצְמוּתוֹ שֶׁל הָרָע הוּא בְּתָקְפּוֹ וּבִגְבוּרָתוֹ בֶּחָלָל הַשְּׂמָאלִי כְּתוֹלַדְתּוֹ, וְלֹא חָלַף וְהָלַךְ מִמֶּנּוּ מְאוּמָה, וְאַדְּרַבָּה – נִתְחַזֵּק יוֹתֵר בְּהֶמְשֵׁךְ הַזְּמַן, שֶׁנִּשְׁתַּמֵּשׁ בּוֹ הַרְבֵּה בַּאֲכִילָה וּשְׁתִיָּה וּשְׁאָר עִנְיְינֵי עוֹלָם הַזֶּה."],"Tanya, Part I; Likkutei Amarim 13:6":["וְאַף מִי שֶׁבְּתוֹרַת ה׳ חֶפְצוֹ וְיֶהְגֶּה בָהּ יוֹמָם וָלַיְלָה לִשְׁמָהּ, אֵין זוֹ הוֹכָחָה כְּלָל שֶׁנִּדְחָה הָרָע מִמְּקוֹמוֹ, אֶלָּא יָכוֹל לִהְיוֹת, שֶׁמַּהוּתוֹ וְעַצְמוּתוֹ הוּא בְּתָקְפּוֹ וּבִגְבוּרָתוֹ בִּמְקוֹמוֹ בֶּחָלָל הַשְּׂמָאלִי, רַק שֶׁלְּבוּשָׁיו, שֶׁהֵם מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁל נֶפֶשׁ הַבַּהֲמִית – אֵינָן מִתְלַבְּשִׁים בַּמּוֹחַ וְהַפֶּה וְהַיָּדַיִם וּשְׁאָר אֵבְרֵי הַגּוּף, מִפְּנֵי ה׳ שֶׁנָּתַן שְׁלִיטָה וּמֶמְשָׁלָה לַמּוֹחַ עַל הַלֵּב, וְלָכֵן נֶפֶשׁ הָאֱלֹהִית שֶׁבַּמּוֹחַ מוֹשֶׁלֶת בָּ״עִיר קְטַנָּה״, אֵבְרֵי הַגּוּף כּוּלָּם, שֶׁיִּהְיוּ לְבוּשׁ וּמֶרְכָּבָה לִשְׁלֹשָׁה לְבוּשֶׁיהָ שֶׁיִּתְלַבְּשׁוּ בָּהֶם, שֶׁהֵם מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁל תַּרְיַ״ג מִצְוֹת הַתּוֹרָה."],"Tanya, Part I; Likkutei Amarim 14:1":["וְהִנֵּה, מִדַּת הַבֵּינוֹנִי, הִיא מִדַּת כָּל אָדָם וְאַחֲרֶיהָ כָּל אָדָם יִמְשׁוֹךְ, שֶׁכָּל אָדָם יָכוֹל לִהְיוֹת בֵּינוֹנִי בְּכָל עֵת וּבְכָל שָׁעָה. כִּי, הַבֵּינוֹנִי אֵינוֹ מוֹאֵס בְּרָע, שֶׁזֶּהוּ דָּבָר הַמָּסוּר לַלֵּב וְלֹא כָּל הָעִתִּים שָׁווֹת, אֶלָא ״סוּר מֵרַע וַעֲשֵׂה טוֹב״, דְּהַיְינוּ בְּפוֹעַל מַמָּשׁ, בְּמַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה, שֶׁבָּהֶם הַבְּחִירָה וְהַיְכוֹלֶת וְהָרְשׁוּת נְתוּנָה לְכָל אָדָם לַעֲשׂוֹת וּלְדַבֵּר וְלַחֲשׁוֹב גַּם מַה שֶּׁהוּא נֶגֶד תַּאֲוַת לִבּוֹ וְהֶפְכָּהּ מַמָּשׁ, כִּי גַּם בְּשָׁעָה שֶׁהַלֵּב חוֹמֵד וּמִתְאַוֶּה אֵיזוֹ תַּאֲוָה גַשְׁמִיִּית בְּהֶיתֵּר אוֹ בְּאִיסּוּר חַס וְשָׁלוֹם, יָכוֹל לְהִתְגַּבֵּר וּלְהַסִּיחַ דַּעְתּוֹ מִמֶּנָּה לְגַמְרֵי, בְּאָמְרוֹ לְלִבּוֹ: אֵינֶנִּי רוֹצֶה לִהְיוֹת רָשָׁע אֲפִילוּ שָׁעָה אַחַת, כִּי אֵינֶנִּי רוֹצֶה לִהְיוֹת מוּבְדָּל וְנִפְרָד חַס וְשָׁלוֹם מֵה׳ אֶחָד בְּשׁוּם אוֹפֶן, כְּדִכְתִיב: ״עֲוֹנוֹתֵיכֶם מַבְדִּילִים וְגוֹ׳״, רַק אֲנִי רוֹצֶה לְדָבְקָה בוֹ נַפְשִׁי רוּחִי וְנִשְׁמָתִי, בְּהִתְלַבְּשָׁן בִּשְׁלֹשָׁה לְבוּשָׁיו יִתְבָּרֵךְ, שֶׁהֵם: מַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה בַּה׳ וְתוֹרָתוֹ וּמִצְוֹתָיו, מֵאַהֲבָה מְסוּתֶּרֶת שֶׁבְּלִבִּי לַה׳, כְּמוֹ בְּלֵב כְּלָלוּת יִשְׂרָאֵל שֶׁנִּקְרְאוּ ״אוֹהֲבֵי שְׁמֶךָ״, וַאֲפִילוּ קַל שֶׁבְּקַלִּים יָכוֹל לִמְסוֹר נַפְשׁוֹ עַל קְדוּשַּׁת ה׳, וְלֹא נוֹפֵל אָנֹכִי מִמֶּנּוּ בְּוַדַּאי, אֶלָּא שֶׁנִּכְנַס בּוֹ רוּחַ שְׁטוּת, וְנִדְמֶה לוֹ שֶׁבַּעֲבֵירָה זוֹ עוֹדֶנּוּ בְּיַהֲדוּתוֹ וְאֵין נִשְׁמָתוֹ מוּבְדֶּלֶת מֵאֱלֹהֵי יִשְׂרָאֵל, וְגַם, שׁוֹכֵחַ אַהֲבָתוֹ לַה׳ הַמְסוּתֶּרֶת בְּלִבּוֹ, אֲבָל אֲנִי, אֵינֶנִּי רוֹצֶה לִהְיוֹת שׁוֹטֶה כָּמוֹהוּ לִכְפּוֹר הָאֱמֶת."],"Tanya, Part I; Likkutei Amarim 14:2":["מַה שֶּׁאֵין כֵּן בְּדָבָר הַמָּסוּר לַלֵּב, דְּהַיְינוּ, שֶׁיְּהֵא הָרָע מָאוּס מַמָּשׁ בַּלֵּב וְשָׂנאוּי בְּתַכְלִית שִׂנְאָה – אוֹ אֲפִילוּ שֶׁלֹּא בְּתַכְלִית שִׂנְאָה – הִנֵּה זֶה, אִי אֶפְשָׁר שֶׁיִּהְיֶה בֶּאֱמֶת לַאֲמִיתּוֹ, אֶלָּא עַל יְדֵי גּוֹדֶל וְתוֹקֶף הָאַהֲבָה לַה׳, בִּבְחִינַת ״אַהֲבָה בְּתַּעֲנוּגִים״, לְהִתְעַנֵּג עַל ה׳ מֵעֵין עוֹלָם הַבָּא, וְעַל זֶה אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״עוֹלָמְךָ תִּרְאֶה בְּחַיֶּיךָ כוּ׳״; וְאֵין כָּל אָדָם זוֹכֶה לָזֶה, כִּי זֶהוּ כְּעֵין קִבּוּל שָׂכָר, וּכְדִכְתִיב: ״עֲבוֹדַת מַתָּנָה אֶתֵּן אֶת כְּהוּנַּתְכֶם וְגוֹ׳״, כְּמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר."],"Tanya, Part I; Likkutei Amarim 14:4":["וּבָזֶה יוּבַן כֶּפֶל לְשׁוֹן הַשְּׁבוּעָה: ״תְּהִי צַדִּיק, וְאַל תְּהִי רָשָׁע״; דְּלִכְאוֹרָה תָּמוּהַּ, כִּי מֵאַחַר שֶׁמַּשְׁבִּיעִים אוֹתוֹ ״תְּהִי צַדִּיק״, לָמָּה צְרִיכִים לְהַשְׁבִּיעוֹ עוֹד שֶׁלֹּא יִהְיֶה רָשָׁע?"],"Tanya, Part I; Likkutei Amarim 15:1":["וּבָזֶה יוּבַן מַה שֶּׁכָּתוּב: ״וְשַׁבְתֶּם וּרְאִיתֶם בֵּין צַדִּיק לְרָשָׁע, בֵּין עוֹבֵד אֱלֹהִים לַאֲשֶׁר לֹא עֲבָדוֹ״."],"Tanya, Part I; Likkutei Amarim 15:4":["וּבַבֵּינוֹנִי יֵשׁ גַּם כֵּן שְׁתֵּי מַדְרֵגוֹת: ״עוֹבֵד אֱלֹהִים״, וַ״אֲשֶׁר לֹא עֲבָדוֹ״, וְאַף־עַל־פִּי־כֵן – אֵינוֹ רָשָׁע, כִּי לֹא עָבַר מִיָּמָיו שׁוּם עֲבֵירָה קַלָּה, וְגַם קִיֵּים כָּל הַמִּצְוֹת שֶׁאֶפְשָׁר לוֹ לְקַיְּימָן, וְתַלְמוּד תּוֹרָה כְּנֶגֶד כּוּלָּם, וְלָא פָסִיק פּוּמֵיהּ מִגִּירְסָא."],"Tanya, Part I; Likkutei Amarim 15:9":["וּבָזֶה יוּבַן מַה שֶּׁכָּתוּב בַּגְּמָרָא, דְּ״עוֹבֵד אֱלֹהִים״ – הַיְינוּ מִי שֶׁשּׁוֹנֶה פִּרְקוֹ מֵאָה פְעָמִים וְאֶחָד, וְ״לֹא עֲבָדוֹ״ – הַיְינוּ מִי שֶׁשּׁוֹנֶה פִּרְקוֹ מֵאָה פְעָמִים לְבַד."],"Tanya, Part I; Likkutei Amarim 16:1":["וְזֶה כְּלָל גָּדוֹל בַּעֲבוֹדַת ה׳ לַבֵּינוֹנִים: הָעִיקָּר, הוּא לִמְשׁוֹל וְלִשְׁלוֹט עַל הַטֶּבַע שֶׁבֶּחָלָל הַשְּׂמָאלִי עַל יְדֵי אוֹר ה׳ הַמֵּאִיר לַנֶּפֶשׁ הָאֱלֹהִית שֶׁבַּמּוֹחַ, וְלִשְׁלוֹט עַל הַלֵּב."],"Tanya, Part I; Likkutei Amarim 16:7":["וְזֶה רָמְזוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה בְּאָמְרָם: ״מַחֲשָׁבָה טוֹבָה הַקָּדוֹשׁ־בָּרוּךְ־הוּא מְצָרְפָהּ לְמַעֲשֶׂה״, וַהֲוָה־לֵיהּ־לְמֵימַר: ״מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ עֲשָׂאָהּ״, אֶלָּא הָעִנְיָן, כִּי דְּחִילוּ וּרְחִימוּ שֶׁבְּהִתְגַּלּוּת לִבּוֹ, הֵם הַמִּתְלַבְּשִׁים בְּמַעֲשֵׂה הַמִּצְוֹת לְהַחֲיוֹתָם לְפָרְחָא לְעֵילָא, כִּי הַלֵּב הוּא גַּם כֵּן חוּמְרִי, כִּשְׁאָר אֵבָרִים שֶׁהֵם כְּלֵי הַמַּעֲשֶׂה, אֶלָּא שֶׁהוּא פְּנִימִי וְחַיּוּת לָהֶם, וְלָכֵן יָכוֹל לְהִתְלַבֵּשׁ בָּהֶם לִהְיוֹת לָהֶם גַּדְפִין לְהַעֲלוֹתָם."],"Tanya, Part I; Likkutei Amarim 17:1":["וּבָזֶה יוּבַן מַה שֶּׁכָּתוּב: ״כִּי קָרוֹב אֵלֶיךָ הַדָּבָר מְאֹד, בְּפִיךָ וּבִלְבָבְךָ לַעֲשׂוֹתוֹ״."],"Tanya, Part I; Likkutei Amarim 17:4":["וְ״זֶה כָּל הָאָדָם״, כִּי – ״הַיּוֹם לַעֲשׂוֹתָם״ כְּתִיב, שֶׁ״הַיּוֹם״ הוּא עוֹלַם הַמַּעֲשֶׂה דַּוְקָא ״וּלְמָחָר כוּ׳״, כְּמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר."],"Tanya, Part I; Likkutei Amarim 17:5":["וְהַמּוֹחַ – שַׁלִּיט בְּטִבְעוֹ וְתוֹלַדְתּוֹ עַל חָלָל הַשְּׂמָאלִי שֶׁבַּלֵּב, וְעַל פִּיו, וְעַל כָּל הָאֵבָרִים שֶׁהֵם כְּלֵי הַמַּעֲשֶׂה. אִם לֹא מִי שֶׁהוּא רָשָׁע בֶּאֱמֶת, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁ״הָרְשָׁעִים הֵם בִּרְשׁוּת לִבָּם״, וְאֵין לִבָּם בִּרְשׁוּתָם כְּלָל, וְזֶה עוֹנֶשׁ עַל גּוֹדֶל וְעוֹצֶם עֲוֹנָם. וְלֹא דִבְּרָה תוֹרָה בְּמֵתִים אֵלּוּ, שֶׁבְּחַיֵּיהֶם קְרוּיִם מֵתִים."],"Tanya, Part I; Likkutei Amarim 17:7":["וְהִיא בְּחִינַת תְּשׁוּבָה תַּתָּאָה, לְהַעֲלוֹת הֵ״א תַּתָּאָה, לַהֲקִימָהּ מִנְּפִילָתָהּ שֶׁנָפְלָה אֶל הַחִיצוֹנִים, שֶׁהוּא סוֹד גָּלוּת הַשְּׁכִינָה, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״גָּלוּ לֶאֱדוֹם – שְׁכִינָה עִמָּהֶם״, דְּהַיְינוּ, כְּשֶׁאָדָם עוֹשֶׂה מַעֲשֵׂה אֱדוֹם מוֹרִיד וּמַמְשִׁיךְ לְשָׁם בְּחִינַת וְנִיצוֹץ אֱלֹהוּת הַמְחַיֶּה אֶת נֶפֶשׁ־רוּחַ־נְשָׁמָה שֶׁלּוֹ, הַמְלוּבָּשִׁים בּוֹ בַּנֶּפֶשׁ הַבַּהֲמִית מֵהַקְּלִיפָּה, שֶׁבְּלִבּוֹ שֶׁבֶּחָלָל הַשְּׂמָאלִי, הַמּוֹלֶכֶת בּוֹ בְּעוֹדוֹ רָשָׁע וּמוֹשֶׁלֶת בָּעִיר קְטַנָּה שֶׁלּוֹ, וְנֶפֶשׁ־רוּחַ־נְשָׁמָה כְּבוּשִׁים בַּגּוֹלָה אֶצְלָהּ."],"Tanya, Part I; Likkutei Amarim 18:1":["וּלְתוֹסֶפֶת בֵּיאוּר, בַּאֵר הֵיטֵב, מִלַּת ״מְאֹד״ שֶׁבַּפָּסוּק: ״כִּי קָרוֹב אֵלֶיךָ הַדָּבָר מְאֹד וְגוֹ׳״."],"Tanya, Part I; Likkutei Amarim 18:4":["וְהָעִנְיָן, כִּי הָאָבוֹת – הֵן הֵן הַמֶּרְכָּבָה, וְעַל כֵּן זָכוּ לְהַמְשִׁיךְ נֶפֶשׁ־רוּחַ־נְשָׁמָה לִבְנֵיהֶם אַחֲרֵיהֶם עַד עוֹלָם מֵעֶשֶׂר סְפִירוֹת דִּקְדוּשָּׁה שֶׁבְּאַרְבַּע עוֹלָמוֹת אֲצִילוּת־בְּרִיאָה־יְצִירָה־עֲשִׂיָּה, לְכָל אֶחָד וְאֶחָד כְּפִי מַדְרֵגָתוֹ וּכְפִי מַעֲשָׂיו."],"Tanya, Part I; Likkutei Amarim 18:9":["הִנֵּה, הַחָכְמָה הִיא מְקוֹר הַשֵּׂכֶל וְהַהֲבָנָה, וְהִיא לְמַעְלָה מֵהַבִּינָה שֶׁהוּא הֲבָנַת הַשֵּׂכֶל וְהַשָּׂגָתוֹ, וְהַחָכְמָה – הִיא לְמַעְלָה מֵהַהֲבָנָה וְהַהַשָּׂגָה, וְהִיא מָקוֹר לָהֶן."],"Tanya, Part I; Likkutei Amarim 19:1":["וּלְתוֹסֶפֶת בֵּיאוּר, צָרִיךְ לְבָאֵר הֵיטֵב מַה שֶּׁכָּתוּב: ״נֵר ה׳ נִשְׁמַת אָדָם״."],"Tanya, Part I; Likkutei Amarim 19:10":["אֶלָּא שֶׁגָּלוּת הַזֶּה לִבְחִינַת חָכְמָה – אֵינוֹ אֶלָּא לַבְּחִינָה הַמִּתְפַּשֶּׁטֶת מִמֶּנָּה בַּנֶּפֶשׁ כּוּלָּהּ לְהַחֲיוֹתָהּ, אֲבָל שֹׁרֶשׁ וְעִיקָּר שֶׁל בְּחִינַת חָכְמָה שֶׁבַּנֶּפֶשׁ הָאֱלֹהִית הוּא בַּמּוֹחִין, וְאֵינָהּ מִתְלַבֶּשֶׁת בִּלְבוּשׁ שַׂק דִּקְלִיפָּה שֶׁבַּלֵּב בֶּחָלָל הַשְּׂמָאלִי בִּבְחִינַת גָּלוּת מַמָּשׁ, רַק שֶׁהִיא בִּבְחִינַת שֵׁינָה בָּרְשָׁעִים, וְאֵינָהּ פּוֹעֶלֶת פְּעוּלָּתָהּ בָּהֶם – כָּל זְמַן שֶׁעֲסוּקִים בְּדַעְתָּם וּבִינָתָם בְּתַאֲוֹת הָעוֹלָם."],"Tanya, Part I; Likkutei Amarim 19:7":["וְזֶהוּ כְּלָל בְּכָל סִטְרָא דִקְדוּשָּׁה, שֶׁאֵינוֹ אֶלָּא מַה שֶּׁנִּמְשָׁךְ מֵחָכְמָה, שֶׁנִּקְרָא ״קוֹדֶשׁ הָעֶלְיוֹן״, הַבָּטֵל בִּמְצִיאוּת בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא הַמְלוּבָּשׁ בּוֹ, וְאֵינוֹ דָּבָר בִּפְנֵי עַצְמוֹ כַּנִּזְכָּר לְעֵיל, וְלָכֵן נִקְרָא ״כֹּ״חַ מָ״ה״."],"Tanya, Part I; Likkutei Amarim 1:1":["תַּנְיָא [בְּסוֹף פֶּרֶק ג׳ דְּנִדָּה]: ״מַשְׁבִּיעִים אוֹתוֹ, תְּהִי צַדִּיק וְאַל תְּהִי רָשָׁע. וַאֲפִילוּ כָּל הָעוֹלָם כּוּלּוֹ אוֹמְרִים לְךָ צַדִּיק אַתָּה – הֱיֵה בְעֵינֶיךָ כְּרָשָׁע״."],"Tanya, Part I; Likkutei Amarim 1:13":["וְהָא דְּאָמְרִינָן בְּעָלְמָא, דְּמֶחֱצָה עַל מֶחֱצָה מִקְרֵי בֵּינוֹנִי, וְרוֹב זְכֻיּוֹת מִקְרֵי צַדִּיק, הוּא שֵׁם הַמּוּשְׁאָל לְעִנְיַן שָׂכָר וְעוֹנֶשׁ, לְפִי שֶׁנִּדּוֹן אַחַר רוּבּוֹ, וּמִקְרֵי צַדִּיק בְּדִינוֹ מֵאַחַר שֶׁזּוֹכֶה בַּדִּין, אֲבָל לְעִנְיַן אֲמִיתַּת שֵׁם הַתּוֹאַר וְהַמַּעֲלָה שֶׁל מַעֲלַת וּמַדְרֵגוֹת חֲלוּקוֹת צַדִּיקִים וּבֵינוֹנִים, אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״צַדִּיקִים יֵצֶר טוֹב שׁוֹפְטָן, שֶׁנֶּאֱמַר: וְלִבִּי חָלַל בְּקִרְבִּי״ – שֶׁאֵין לוֹ יֵצֶר הָרָע, כִּי הֲרָגוֹ בְּתַעֲנִית; אֲבָל כָּל מִי שֶׁלֹּא הִגִּיעַ לְמַדְרֵגָה זוֹ, אַף שֶׁזְּכֻיוֹתָיו מְרוּבִּים עַל עֲוֹנוֹתָיו – אֵינוֹ בְּמַעֲלַת וּמַדְרֵגַת צַדִּיק כְּלָל."],"Tanya, Part I; Likkutei Amarim 20:1":["וְהִנֵּה מוּדַעַת זֹאת לַכֹּל, כִּי מִצְוַת וְאַזְהָרַת עֲבוֹדָה זָרָה, שֶׁהֵם שְׁנֵי דִבְּרוֹת הָרִאשׁוֹנִים, ״אָנֹכִי״ וְ״לֹא יִהְיֶה לְךָ״, הֵם כְּלָלוּת כָּל הַתּוֹרָה כוּלָּהּ; כִּי דִּבּוּר ״אָנֹכִי״ – כּוֹלֵל כָּל רַמַ״ח מִצְוֹת עֲשֵׂה, וְ״לֹא יִהְיֶה לְךָ״ – כּוֹלֵל כָּל שַׁסַ״ה מִצְוֹת לֹא תַעֲשֶׂה, וְלָכֵן שָׁמַעְנוּ ״אָנֹכִי״ וְ״לֹא יִהְיֶה לְךָ״ לְבַד מִפִּי הַגְּבוּרָה כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, מִפְּנֵי שֶׁהֵם כְּלָלוּת הַתּוֹרָה כוּלָּהּ."],"Tanya, Part I; Likkutei Amarim 20:4":["כִּי הִתְהַוּוּת כָּל הָעוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים מֵאַיִן לְיֵשׁ, וְחַיּוּתָם וְקִיּוּמָם הַמְקַיְּימָם שֶׁלֹּא יַחְזְרוּ לִהְיוֹת אַיִן וָאֶפֶס כְּשֶׁהָיָה, אֵינוֹ אֶלָּא דְּבַר ה׳ וְרוּחַ פִּיו יִתְבָּרֵךְ הַמְלוּבָּשׁ בָּהֶם."],"Tanya, Part I; Likkutei Amarim 20:5":["וּלְמָשָׁל, כְּמוֹ בְּנֶפֶשׁ הָאָדָם, כְּשֶׁמְּדַבֵּר דִּבּוּר אֶחָד; שֶׁדִּבּוּר זֶה לְבַדּוֹ כְּלָא מַמָּשׁ, אֲפִילוּ לְגַבֵּי כְּלָלוּת נַפְשׁוֹ הַמְדַבֶּרֶת, שֶׁהוּא בְּחִינַת לְבוּשׁ הָאֶמְצָעִי שֶׁלָּהּ, שֶׁהוּא כֹּחַ הַדִּבּוּר שֶׁלָּהּ, שֶׁיָּכוֹל לְדַבֵּר דִּבּוּרִים לְאֵין קֵץ וְתַכְלִית; וְכָל שֶׁכֵּן לְגַבֵּי בְּחִינַת לְבוּשׁ הַפְּנִימִי שֶׁלָּהּ שֶׁהוּא הַמַּחֲשָׁבָה, שֶׁמִּמֶּנָּה נִמְשְׁכוּ הַדִּבּוּרִים וְהִיא חַיּוּתָם; וְאֵין צָרִיךְ לוֹמַר לְגַבֵּי מַהוּת וְעַצְמוּת הַנֶּפֶשׁ, שֶׁהֵן עֶשֶׂר בְּחִינוֹתֶיהָ הַנִּזְכָּרוֹת לְעֵיל: חָכְמָה־בִּינָה־דַּעַת כוּ׳, שֶׁמֵּהֶן נִמְשְׁכוּ אוֹתִיּוֹת מַחֲשָׁבָה זוֹ הַמְלוּבָּשׁוֹת בְּדִבּוּר זֶה כְּשֶׁמְּדַבֵּר, כִּי הַמַּחֲשָׁבָה הִיא גַּם כֵּן בְּחִינַת אוֹתִיּוֹת כְּמוֹ הַדִּבּוּר, רַק שֶׁהֵן רוּחָנִיּוֹת וְדַקּוֹת יוֹתֵר."],"Tanya, Part I; Likkutei Amarim 20:6":["אֲבָל עֶשֶׂר בְּחִינוֹת חָכְמָה־בִּינָה־דַּעַת כוּ׳, הֵן שֹׁרֶשׁ וּמְקוֹר הַמַּחֲשָׁבָה, וְאֵין בָּהֶם בְּחִינַת אוֹתִיּוֹת עֲדַיִין קוֹדֶם שֶׁמִּתְלַבְּשׁוֹת בִּלְבוּשׁ הַמַּחֲשָׁבָה."],"Tanya, Part I; Likkutei Amarim 21:1":["וְהִנֵּה, מִדַּת הַקָּדוֹשׁ־בָּרוּךְ־הוּא שֶׁלֹּא כְּמִדַּת בָּשָׂר וָדָם; שֶׁהָאָדָם, כְּשֶׁמְּדַבֵּר דִּבּוּר, הֲרֵי הֶבֶל הַדִּבּוּר שֶׁבְּפִיו הוּא מוּרְגָּשׁ וְנִרְאֶה דָּבָר בִּפְנֵי עַצְמוֹ מוּבְדָּל מִשָּׁרְשׁוֹ, שֶׁהֵן עֶשֶׂר בְּחִינוֹת הַנֶּפֶשׁ עַצְמָהּ."],"Tanya, Part I; Likkutei Amarim 21:5":["וַהֲרֵי דִּבּוּרוֹ וּמַחֲשַׁבְתּוֹ כִּבְיָכוֹל מְיוּחָדוֹת עִמּוֹ בְּתַכְלִית הַיִּחוּד; דֶּרֶךְ מָשָׁל, כְּמוֹ דִּבּוּרוֹ וּמַחֲשַׁבְתּוֹ שֶׁל אָדָם בְּעוֹדָן בְּכֹחַ חָכְמָתוֹ וְשִׂכְלוֹ, אוֹ בִּתְשׁוּקָה וְחֶמְדָּה שֶׁבְּלִבּוֹ קוֹדֶם שֶׁעָלְתָה מֵהַלֵּב לַמּוֹחַ לְהַרְהֵר בָּהּ בִּבְחִינַת אוֹתִיּוֹת, שֶׁאָז, הָיוּ אוֹתִיּוֹת הַמַּחֲשָׁבָה וְהַדִּבּוּר הַזֶּה, הַנִּמְשָׁכוֹת מֵחֶמְדָּה וּתְשׁוּקָה זוֹ – בְּכֹחַ בַּלֵּב וּמְיוּחָדוֹת שָׁם בְּתַכְלִית הַיִּחוּד בְּשָׁרְשָׁן, שֶׁהֵן הַחָכְמָה וְשֵׂכֶל שֶׁבַּמּוֹחַ וְחֶמְדָּה וּתְשׁוּקָה שֶׁבַּלֵּב."],"Tanya, Part I; Likkutei Amarim 21:6":["וְכָכָה מַמָּשׁ, דֶּרֶךְ מָשָׁל, מְיוּחָדוֹת דִּבּוּרוֹ וּמַחֲשַׁבְתּוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא בְּתַכְלִית הַיִּחוּד בְּמַהוּתוֹ וְעַצְמוּתוֹ יִתְבָּרֵךְ, גַּם אַחַר שֶׁיָּצָא דִּבּוּרוֹ יִתְבָּרֵךְ אֶל הַפּוֹעַל בִּבְרִיאוֹת הָעוֹלָמוֹת, כְּמוֹ שֶׁהָיָה מְיוּחָד עִמּוֹ קוֹדֶם בְּרִיאַת הָעוֹלָמוֹת, וְאֵין שׁוּם שִׁינּוּי כְּלָל לְפָנָיו יִתְבָּרֵךְ, אֶלָּא אֶל הַבְּרוּאִים הַמְקַבְּלִים חַיּוּתָם מִבְּחִינַת דִּבּוּרוֹ יִתְבָּרֵךְ, בִּבְחִינַת יְצִיאָתוֹ כְּבָר אֶל הַפּוֹעַל בִּבְרִיאַת הָעוֹלָמוֹת, שֶׁמִּתְלַבֵּשׁ בָּהֶם לְהַחֲיוֹתָם עַל יְדֵי הִשְׁתַּלְשְׁלוּת מֵעִלָּה לְעָלוּל וִירִידַת הַמַּדְרֵגוֹת בְּצִמְצוּמִים רַבִּים וְשׁוֹנִים, עַד שֶׁיּוּכְלוּ הַבְּרוּאִים לְקַבֵּל חַיּוּתָם וְהִתְהַוּוּתָם מִמֶּנּוּ וְלֹא יִתְבַּטְּלוּ בִּמְצִיאוּת."],"Tanya, Part I; Likkutei Amarim 21:7":["וְכָל הַצִּמְצוּמִים הֵם בְּחִינַת ״הֶסְתֵּר פָּנִים״, לְהַסְתִּיר וּלְהַעֲלִים הָאוֹר וְהַחַיּוּת הַנִּמְשָׁךְ מִדִּבּוּרוֹ יִתְבָּרֵךְ, שֶׁלֹּא יִתְגַּלֶּה בִּבְחִינַת גִּילּוּי רַב שֶׁלֹּא יוּכְלוּ הַתַּחְתּוֹנִים לְקַבֵּל, וְלָכֵן גַּם כֵּן נִדְמֶה לָהֶם אוֹר וְחַיּוּת הַדִּבּוּר שֶׁל מָקוֹם בָּרוּךְ־הוּא הַמְלוּבָּשׁ בָּהֶם, כְּאִלּוּ הוּא דָּבָר מוּבְדָּל מִמַּהוּתוֹ וְעַצְמוּתוֹ יִתְבָּרֵךְ, רַק שֶׁנִּמְשָׁךְ מִמֶּנּוּ יִתְבָּרֵךְ – כְּמוֹ דִּבּוּר שֶׁל אָדָם מִנַּפְשׁוֹ."],"Tanya, Part I; Likkutei Amarim 22:1":["רַק שֶׁהַתּוֹרָה דִּבְּרָה כִּלְשׁוֹן בְּנֵי אָדָם, וְנִקְרָא בַּתּוֹרָה דִּבּוּרוֹ שֶׁל מָקוֹם בָּרוּךְ־הוּא בְּשֵׁם ״דִּבּוּר״ מַמָּשׁ, כְּדִבּוּרוֹ שֶׁל אָדָם, לְפִי שֶׁבֶּאֱמֶת כָּךְ הוּא דֶּרֶךְ יְרִידַת וְהַמְשָׁכַת הַחַיּוּת לַתַּחְתּוֹנִים, בְּצִמְצוּמִים רַבִּים וַעֲצוּמִים, מִינִים מִמִּינִים שׁוֹנִים, לְהִבָּרְאוֹת מֵהֶם בְּרוּאִים רַבִּים, מִינִים מִמִּינִים שׁוֹנִים."],"Tanya, Part I; Likkutei Amarim 22:6":["וְהִנֵּה, רָצוֹן הָעֶלְיוֹן בִּבְחִינַת ״פָּנִים״, הוּא מְקוֹר הַחַיִּים הַמְחַיֶּה אֶת כָּל הָעוֹלָמוֹת, וּלְפִי שֶׁאֵינוֹ שׁוֹרֶה כְּלָל עַל הַסִּטְרָא אָחֳרָא, וְגַם בְּחִינַת ״אֲחוֹרַיִים״ שֶׁל רָצוֹן הָעֶלְיוֹן אֵינוֹ מְלוּבָּשׁ בְּתוֹכָהּ מַמָּשׁ, אֶלָּא מַקִּיף עָלֶיהָ מִלְמַעְלָה, לְכָךְ הִיא מְקוֹם הַמִּיתָה וְהַטּוּמְאָה, ה׳ יִשְׁמְרֵנוּ, כִּי מְעַט מִזְּעֵר אוֹר וְחַיּוּת, שֶׁיּוֹנֶקֶת וּמְקַבֶּלֶת לְתוֹכָהּ מִבְּחִינַת ״אֲחוֹרַיִים״ דִּקְדוּשָּׁה שֶׁלְּמַעְלָה, הוּא בִּבְחִינַת גָּלוּת מַמָּשׁ בְּתוֹכָהּ, בְּסוֹד גָּלוּת הַשְּׁכִינָה הַנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 23:1":["וְעִם כָּל הַנִּזְכָּר לְעֵיל, יוּבַן וִיבוֹאַר הֵיטֵב בְּתוֹסֶפֶת בֵּיאוּר מַה שֶּׁאָמְרוּ בַּזֹּהַר דְּ״אוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד״, וּבַתִּיקוּנִים פֵּירְשׁוּ דְּ״רַמַ״ח פִּיקּוּדִין אִינּוּן רַמַ״ח אֵבָרִין דְּמַלְכָּא״."],"Tanya, Part I; Likkutei Amarim 23:10":["וּמֵאַחַר שֶׁרָצוֹן הָעֶלְיוֹן הַמְיוּחָד בְּאֵין־סוֹף בָּרוּךְ־הוּא בְּתַכְלִית הַיִּחוּד, הוּא בְּגִילּוּי לְגַמְרֵי, וְלֹא בְּהֶסְתֵּר פָּנִים כְּלָל וּכְלָל, בַּנֶּפֶשׁ הָאֱלֹהִית וּלְבוּשֶׁיהָ הַפְּנִימִים, שֶׁהֵם מַחֲשַׁבְתָּהּ וְדִבּוּרָהּ, בְּאוֹתָהּ שָׁעָה שֶׁהָאָדָם עוֹסֵק בְּדִבְרֵי תוֹרָה, הֲרֵי גַּם הַנֶּפֶשׁ וּלְבוּשֶׁיהָ אֵלּוּ – מְיוּחָדִים מַמָּשׁ בְּאֵין־סוֹף בָּרוּךְ־הוּא בְּאוֹתָהּ שָׁעָה בְּתַכְלִית הַיִּחוּד, כְּיִחוּד דִּבּוּרוֹ וּמַחֲשַׁבְתּוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא בְּמַהוּתוֹ וְעַצְמוּתוֹ כַּנִּזְכָּר לְעֵיל, כִּי אֵין שׁוּם דָּבָר נִפְרָד, כִּי אִם בְּהֶסְתֵּר פָּנִים כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 23:12":["וּבָזֶה יוּבַן לָמָּה גָּדְלָה מְאֹד מַעֲלַת הָעֵסֶק בַּתּוֹרָה יוֹתֵר מִכָּל הַמִּצְוֹת, וַאֲפִילוּ מִתְּפִלָּה – שֶׁהִיא יִחוּד עוֹלָמוֹת עֶלְיוֹנִים [וְהָא דְּמִי שֶׁאֵין תּוֹרָתוֹ אוּמָנוּתוֹ צָרִיךְ לְהַפְסִיק, הַיְינוּ מֵאַחַר דְּמַפְסִיק וּמְבַטֵּל בְּלָאו הָכֵי]."],"Tanya, Part I; Likkutei Amarim 23:13":["וּמִזֶּה יוּכַל הַמַּשְׂכִּיל לְהַמְשִׁיךְ עָלָיו יִרְאָה גְדוֹלָה בְּעָסְקוֹ בַּתּוֹרָה, כְּשֶׁיִּתְבּוֹנֵן אֵיךְ שֶׁנַּפְשׁוֹ וּלְבוּשֶׁיהָ שֶׁבְּמוֹחוֹ וּבְפִיו, הֵם מְיוּחָדִים מַמָּשׁ בְּתַכְלִית הַיִּחוּד בָּרָצוֹן הָעֶלְיוֹן וְאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא מַמָּשׁ הַמִּתְגַּלֶּה בָּהֶם, מַה שֶּׁכָּל הָעוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים – כְּלָא חֲשִׁיבֵי קַמֵּיהּ וּכְאַיִן וָאֶפֶס מַמָּשׁ, עַד שֶׁאֵינוֹ מִתְלַבֵּשׁ בְּתוֹכָם מַמָּשׁ, אֶלָּא, סוֹבֵב כָּל עָלְמִין, בִּבְחִינַת מַקִּיף – לְהַחֲיוֹתָם עִיקַּר חַיּוּתָם, רַק אֵיזוֹ הֶאָרָה מִתְלַבֶּשֶׁת בְּתוֹכָם, מַה שֶּׁיְּכוֹלִים לִסְבּוֹל, שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּת לְגַמְרֵי."],"Tanya, Part I; Likkutei Amarim 23:4":["וְלָכֵן נִקְרָאִים ״אֵבְרֵי דְמַלְכָּא״, דֶּרֶךְ מָשָׁל; כְּמוֹ שֶׁאֵבְרֵי גּוּף הָאָדָם הֵם לְבוּשׁ לְנַפְשׁוֹ וּבְטֵלִים לְגַמְרֵי אֵלֶיהָ מִכֹּל וָכֹל, כִּי מִיָּד שֶׁעוֹלֶה בִּרְצוֹנוֹ שֶׁל אָדָם לִפְשׁוֹט יָדוֹ אוֹ רַגְלוֹ, הֵן נִשְׁמָעוֹת לִרְצוֹנוֹ תֵּכֶף וּמִיָּד בְּלִי שׁוּם צִוּוּי וַאֲמִירָה לָהֶן, וּבְלִי שׁוּם שְׁהִיָּיה כְּלָל, אֶלָּא כְּרֶגַע מַמָּשׁ כְּשֶׁעָלָה בִּרְצוֹנוֹ, כָּךְ דֶּרֶךְ מָשָׁל, הַחַיּוּת שֶׁל מַעֲשֵׂה הַמִּצְוֹת וְקִיּוּמָן, הוּא בָּטֵל לְגַמְרֵי לְגַבֵּי רָצוֹן הָעֶלְיוֹן הַמְלוּבָּשׁ בּוֹ, וְנַעֲשֶׂה לוֹ מַמָּשׁ כְּגוּף לִנְשָׁמָה."],"Tanya, Part I; Likkutei Amarim 23:5":["וְכֵן הַלְּבוּשׁ הַחִיצוֹן שֶׁל נֶפֶשׁ הָאֱלֹהִית שֶׁבָּאָדָם הַמְקַיֵּם וְעוֹשֶׂה הַמִּצְוָה, שֶׁהוּא כֹּחַ וּבְחִינַת הַמַּעֲשֶׂה שֶׁלָּהּ, הוּא מִתְלַבֵּשׁ בַּחַיּוּת שֶׁל מַעֲשֵׂה הַמִּצְוָה, וְנַעֲשֶׂה גַּם כֵּן כְּגוּף לִנְשָׁמָה לָרָצוֹן הָעֶלְיוֹן וּבָטֵל אֵלָיו לְגַמְרֵי."],"Tanya, Part I; Likkutei Amarim 23:8":["אַךְ הַמַּחֲשָׁבָה וְהַהִרְהוּר בְּדִבְרֵי תוֹרָה שֶׁבַּמּוֹחַ, וְכֹחַ הַדִּבּוּר בְּדִבְרֵי תוֹרָה שֶׁבַּפֶּה, שֶׁהֵם לְבוּשִׁים הַפְּנִימִים שֶׁל נֶפֶשׁ הָאֱלֹהִית, וְכָל שֶׁכֵּן נֶפֶשׁ הָאֱלֹהִית עַצְמָהּ הַמְלוּבֶּשֶׁת בָּהֶם, כּוּלָּם מְיוּחָדִים מַמָּשׁ בְּיִחוּד גָּמוּר בָּרָצוֹן הָעֶלְיוֹן, וְלֹא מֶרְכָּבָה לְבַד, כִּי רָצוֹן הָעֶלְיוֹן הוּא הוּא הַדְּבַר הֲלָכָה עַצְמָהּ שֶׁמְּהַרְהֵר וּמְדַבֵּר בָּהּ, שֶׁכָּל הַהֲלָכוֹת הֵן פְּרָטֵי הַמְשָׁכוֹת פְּנִימִיּוּת רָצוֹן הָעֶלְיוֹן עַצְמוֹ, שֶׁכָּךְ עָלָה בִּרְצוֹנוֹ יִתְבָּרֵךְ, שֶׁדָּבָר זֶה מוּתָּר אוֹ כָּשֵׁר אוֹ פָּטוּר אוֹ זַכַּאי אוֹ לְהֵפֶךְ; וְכֵן כָּל צֵרוּפֵי אוֹתִיּוֹת תּוֹרָה־נְבִיאִים־כְּתוּבִים הֵן הַמְשָׁכַת רְצוֹנוֹ וְחָכְמָתוֹ הַמְיוּחָדוֹת בְּאֵין־סוֹף בָּרוּךְ־הוּא בְּתַכְלִית הַיִּחוּד, שֶׁהוּא הַיּוֹדֵעַ וְהוּא הַמַּדָּע כוּ׳."],"Tanya, Part I; Likkutei Amarim 24:1":["וְ״זֶה לְעוּמַּת זֶה״, הֵן שַׁסַ״ה מִצְוֹת לֹא תַעֲשֶׂה דְּאוֹרַיְיתָא וְכָל אִיסּוּרֵי דְרַבָּנָן, מֵאַחַר שֶׁהֵן נֶגֶד רְצוֹנוֹ וְחָכְמָתוֹ יִתְבָּרֵךְ וְהֶפְכָּם מַמָּשׁ – הֵם נִפְרָדִים מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ בְּתַכְלִית הַפֵּירוּד מַמָּשׁ, כְּמוֹ הַסִּטְרָא אָחֳרָא וְהַקְּלִיפָּה הַנִּקְרֵאת ״עֲבוֹדָה זָרָה״ וֵ״אלֹהִים אֲחֵרִים״, מֵחֲמַת הֶסְתֵּר פָּנִים שֶׁל רָצוֹן הָעֶלְיוֹן, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 24:12":["וּמַה שֶּׁפִּיקּוּחַ נֶפֶשׁ דּוֹחֶה שְׁאָר עֲבֵירוֹת, וְגַם ״יַעֲבוֹר וְאַל יֵהָרֵג״ הַיְינוּ, כְּפֵירוּשׁ חֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אָמְרָה תוֹרָה, חַלֵּל עָלָיו שַׁבָּת אַחַת, כְּדֵי שֶׁיִּשְׁמוֹר שַׁבָּתוֹת הַרְבֵּה״, וְלֹא מִשּׁוּם קַלּוּת הָעֲבֵירוֹת וְחוּמְרָן."],"Tanya, Part I; Likkutei Amarim 24:8":["וְלָכֵן אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה עַל פָּסוּק: ״כִּי תִשְׂטֶה אִשְׁתּוֹ״ – ״אֵין אָדָם עוֹבֵר עֲבֵירָה וְכוּ׳״, דַּאֲפִילוּ אִשָּׁה הַמְנָאֶפֶת שֶׁדַּעְתָּהּ קַלָּה, הָיְתָה מוֹשֶׁלֶת בְּרוּחַ תַּאֲוָתָהּ, לוּלֵי רוּחַ שְׁטוּת שֶׁבָּהּ – הַמְכַסֶּה וּמַסְתִּיר וּמַעֲלִים אֶת הָאַהֲבָה מְסוּתֶּרֶת שֶׁבְּנַפְשָׁהּ הָאֱלֹהִית, לְדָבְקָה בֶּאֱמוּנַת ה׳ וְיִחוּדוֹ וְאַחְדּוּתוֹ, וְלֹא לִיפָּרֵד חַס וְשָׁלוֹם מֵאַחְדּוּתוֹ, אֲפִילוּ נוֹטְלִים אֶת נַפְשָׁהּ מִמֶּנָּה לַעֲבוֹד עֲבוֹדָה זָרָה חַס וְשָׁלוֹם, וַאֲפִילוּ בְּהִשְׁתַּחֲוָאָה לְבַדָּהּ בְּלִי שׁוּם אֱמוּנָה בַּלֵּב כְּלָל, וְכָל שֶׁכֵּן לִכְבּוֹשׁ הַיֵּצֶר וְתַאֲוַת הַנִּיאוּף, שֶׁהֵם יִסּוּרִים קַלִּים מִמִּיתָה, ה׳ יִשְׁמְרֵנוּ."],"Tanya, Part I; Likkutei Amarim 25:1":["וְזֶהוּ שֶׁכָּתוּב: ״כִּי קָרוֹב אֵלֶיךָ הַדָּבָר מְאֹד וְגוֹ׳״, שֶׁבְּכָל עֵת וּבְכָל שָׁעָה, בְּיָדוֹ שֶׁל אָדָם וּבִרְשׁוּתוֹ הוּא – לְהַעֲבִיר רוּחַ שְׁטוּת וְהַשִּׁכְחָה מִקִּרְבּוֹ, וְלִזְכּוֹר וּלְעוֹרֵר אַהֲבָתוֹ לַה׳ אֶחָד, הַמְסוּתֶּרֶת בְּוַדַּאי בִּלְבָבוֹ בְּלִי שׁוּם סָפֵק."],"Tanya, Part I; Likkutei Amarim 25:10":["וְיִחוּד זֶה לְמַעְלָה – הוּא נִצְחִי לְעוֹלָם וָעֶד, כִּי הוּא יִתְבָּרֵךְ וּרְצוֹנוֹ לְמַעְלָה מֵהַזְּמַן. וְכֵן, גִּילּוּי רְצוֹנוֹ שֶׁבְּדִבּוּרוֹ, שֶׁהִיא הַתּוֹרָה, הוּא נִצְחִי, וּכְמוֹ שֶׁכָּתוּב: ״וּדְבַר אֱלֹהֵינוּ יָקוּם לְעוֹלָם״, ״וּדְבָרָיו חָיִים וְקַיָּימִים כוּ׳״, ״וְלֹא יַחֲלִיף וְלֹא יָמִיר דָּתוֹ לְעוֹלָמִים כוּ׳״."],"Tanya, Part I; Likkutei Amarim 25:11":["אֶלָּא שֶׁלְּמַטָּה, הוּא תַּחַת הַזְּמַן וּבְאוֹתָהּ שָׁעָה לְבַדָּהּ שֶׁעוֹסֵק בָּהּ בַּתּוֹרָה אוֹ בְּמִצְוָה, כִּי אַחַר כָּךְ, אִם עוֹסֵק בְּדָבָר אַחֵר – נִפְרָד מֵהַיִּחוּד הָעֶלְיוֹן לְמַטָּה, [וְהַיְינוּ, כְּשֶׁעוֹסֵק בִּדְבָרִים בְּטֵלִים לְגַמְרֵי, שֶׁאֵין בָּהֶם צוֹרֶךְ כְּלָל לַעֲבוֹדַת ה׳.]"],"Tanya, Part I; Likkutei Amarim 25:15":["וּבָזֶה יוּבַן, לָמָּה צִוָּה מֹשֶׁה רַבֵּינוּ עָלָיו הַשָּׁלוֹם, בְּמִשְׁנֵה תוֹרָה, לַדּוֹר שֶׁנִּכְנְסוּ לָאָרֶץ, לִקְרוֹת קְרִיאַת שְׁמַע פַּעֲמַיִם בְּכָל יוֹם, לְקַבֵּל עָלָיו מַלְכוּת שָׁמַיִם בִּמְסִירַת נֶפֶשׁ, וַהֲלֹא הִבְטִיחַ לָהֶם: ״פַּחְדְּכֶם וּמוֹרַאֲכֶם יִתֵּן ה׳ וְגוֹ׳״; אֶלָּא, מִשּׁוּם שֶׁקִּיּוּם הַתּוֹרָה וּמִצְוֹתֶיהָ, תָּלוּי בָּזֶה שֶׁיִּזְכּוֹר תָּמִיד עִנְיַן מְסִירַת נַפְשׁוֹ לַה׳ עַל יִחוּדוֹ, שֶׁיִּהְיֶה קָבוּעַ בְּלִבּוֹ תָּמִיד מַמָּשׁ, יוֹמָם וָלַיְלָה לֹא יָמִישׁ מִזִּכְרוֹנוֹ, כִּי, בָּזֶה יוּכַל לַעֲמוֹד נֶגֶד יִצְרוֹ לְנַצְּחוֹ תָּמִיד בְּכָל עֵת וּבְכָל שָׁעָה, – כַּנִּזְכָּר לְעֵיל:"],"Tanya, Part I; Likkutei Amarim 25:4":["[וְאַף שֶׁ״הָאוֹמֵר אֶחֱטָא וְאָשׁוּב – אֵין מַסְפִּיקִין כוּ׳״, הַיְינוּ, שֶׁאֵין מַחֲזִיקִים יָדוֹ לִהְיוֹת לוֹ שְׁעַת הַכּוֹשֶׁר לַעֲשׂוֹת תְּשׁוּבָה, אֲבָל אִם דָּחַק הַשָּׁעָה וְעָשָׂה תְּשׁוּבָה – אֵין לְךָ דָּבָר שֶׁעוֹמֵד בִּפְנֵי הַתְּשׁוּבָה.]"],"Tanya, Part I; Likkutei Amarim 25:6":["וְהֵן בִּבְחִינַת ״וַעֲשֵׂה טוֹב״, לְהִתְגַּבֵּר כָּאֲרִי בִּגְבוּרָה וְאוֹמֶץ הַלֵּב, נֶגֶד הַיֵּצֶר הַמַּכְבִּיד אֶת גּוּפוֹ וּמַפִּיל עָלָיו עַצְלָה, מִבְּחִינַת יְסוֹד הֶעָפָר שֶׁבַּנֶּפֶשׁ הַבַּהֲמִית, מִלְּהַטְרִיחַ גּוּפוֹ בִּזְרִיזוּת בְּכָל מִינֵי טוֹרַח וַעֲבוֹדַת מַשָּׂא בַּעֲבוֹדַת ה׳ שֶׁיֵּשׁ בָּהּ טוֹרַח וְעָמָל, כְּגוֹן: לַעֲמוֹל בַּתּוֹרָה בְּעִיּוּן וּבַפֶּה – לָא פָסִיק פּוּמֵיהּ מִגִּירְסָא, וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״לְעוֹלָם יָשִׂים אָדָם עַצְמוֹ עַל דִּבְרֵי תוֹרָה כְּשׁוֹר לְעוֹל וְכַחֲמוֹר לְמַשְׂאוֹי״, וְכֵן לִתְפִלָּה בְּכַוָּנָה – בְּכָל כֹּחוֹ מַמָּשׁ, וְכֵן בַּעֲבוֹדַת ה׳ שֶׁהִיא בְּדָבָר שֶׁבְּמָמוֹן, כְּמוֹ עֲבוֹדַת הַצְּדָקָה;"],"Tanya, Part I; Likkutei Amarim 25:7":["וְכַיּוֹצֵא בְאֵלּוּ מִמִּלְחֲמוֹת הַיֵּצֶר וְתַחְבּוּלוֹתָיו, לְקָרֵר נֶפֶשׁ הָאָדָם שֶׁלֹּא לְהַפְקִיר מָמוֹנוֹ וּבְרִיאוּת גּוּפוֹ, שֶׁלַּעֲמוֹד נֶגְדּוֹ וּלְכָבְשׁוֹ, קָרוֹב מְאֹד אֶל הָאָדָם, כְּשֶׁיָּשִׂים אֶל לִבּוֹ, שֶׁלְּנַצֵּחַ הַיֵּצֶר בְּכָל זֶה, וְיוֹתֵר מִזֶּה, וְלַעֲשׂוֹת הֶפְכּוֹ מַמָּשׁ – קַל מְאֹד מִיִּסּוּרֵי מִיתָה, ה׳ יִשְׁמְרֵנוּ, וְיִסּוּרֵי מִיתָה, ה׳ יִשְׁמְרֵנוּ, הָיָה מְקַבֵּל בְּאַהֲבָה וּבְרָצוֹן – שֶׁלֹּא לִיפָּרֵד מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ אֲפִילוּ לְפִי שָׁעָה, לְהִשְׁתַּחֲוֹת לַעֲבוֹדָה זָרָה חַס וְשָׁלוֹם."],"Tanya, Part I; Likkutei Amarim 26:1":["בְּרַם, כְּגוֹן דָּא צָרִיךְ לְאוֹדוֹעֵי כְּלָל גָּדוֹל: כִּי כְּמוֹ שֶׁנִּצָּחוֹן לְנַצֵּחַ דָּבָר גַּשְׁמִי, כְּגוֹן: שְׁנֵי אֲנָשִׁים הַמִּתְאַבְּקִים זֶה עִם זֶה לְהַפִּיל זֶה אֶת זֶה, הִנֵּה, אִם הָאֶחָד הוּא בְּעַצְלוּת וּכְבֵדוּת – יְנוּצַּח בְּקַל וְיִפּוֹל גַּם אִם הוּא גִּבּוֹר יוֹתֵר מֵחֲבֵירוֹ, כָּכָה מַמָּשׁ בְּנִצְחוֹן הַיֵּצֶר, אִי אֶפְשָׁר לְנַצְּחוֹ בְּעַצְלוּת וּכְבֵדוּת – הַנִּמְשָׁכוֹת מֵעַצְבוּת וְטִמְטוּם הַלֵּב כָּאֶבֶן, כִּי אִם, בִּזְרִיזוּת – הַנִּמְשֶׁכֶת מִשִּׂמְחָה וּפְתִיחַת הַלֵּב, וְטָהֳרָתוֹ מִכָּל נִדְנוּד דְּאָגָה וָעֶצֶב בָּעוֹלָם."],"Tanya, Part I; Likkutei Amarim 26:5":["וְהִנֵּה, עֵצָה הַיְּעוּצָה לְטַהֵר לִבּוֹ מִכָּל עֶצֶב וְנִדְנוּד דְּאָגָה מִמִּילֵּי דְעָלְמָא, וַאֲפִילוּ בָּנֵי חַיֵּי וּמְזוֹנֵי, מוּדַעַת זֹאת לַכֹּל מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״כְּשֵׁם שֶׁמְּבָרֵךְ עַל הַטּוֹבָה כוּ׳״, וּפֵירְשׁוּ בַּגְּמָרָא: ״לְקַבּוּלֵי בְּשִׂמְחָה״, כְּמוֹ שִׂמְחַת הַטּוֹבָה הַנִּגְלֵית וְנִרְאֵית, כִּי ״גַּם זוֹ – לְטוֹבָה״, רַק שֶׁאֵינָהּ נִגְלֵית וְנִרְאֵית לְעֵינֵי בָשָׂר, כִּי, הִיא מֵ״עָלְמָא דְאִתְכַּסְיָא״ שֶׁלְּמַעְלָה מֵ״עָלְמָא דְאִתְגַּלְיָיא״, שֶׁהוּא – ו״ה מִשֵּׁם הֲוָיָ״ה בָּרוּךְ־הוּא, וְ״עָלְמָא דְאִתְכַּסְיָא״ – הוּא י״ה, וְזֶהוּ שֶׁכָּתוּב: ״אַשְׁרֵי הַגֶּבֶר אֲשֶׁר תְּיַסְּרֶנּוּ יָּ״הּ וְגוֹ׳״."],"Tanya, Part I; Likkutei Amarim 26:7":["אַךְ הָעַצְבוּת מִמִּילֵּי דִשְׁמַיָּא צָרִיךְ לָשִׁית עֵצוֹת בְּנַפְשׁוֹ לִיפָּטֵר מִמֶּנָּה, אֵין צָרִיךְ לוֹמַר בִּשְׁעַת עֲבוֹדָה, שֶׁצָּרִיךְ לַעֲבוֹד ה׳ בְּשִׂמְחָה וּבְטוּב לֵבָב, אֶלָּא אֲפִילוּ מִי שֶׁהוּא בַּעַל עֲסָקִים וְדֶרֶךְ אֶרֶץ, אִם נוֹפֵל לוֹ עֶצֶב וּדְאָגָה מִמִּילֵּי דִשְׁמַיָּא בִּשְׁעַת עֲסָקָיו, בְּיָדוּעַ שֶׁהוּא תַּחְבּוּלַת הַיֵּצֶר – כְּדֵי לְהַפִּילוֹ אַחַר כָּךְ בְּתַאֲווֹת חַס וְשָׁלוֹם, כַּנּוֹדָע, שֶׁאִם לֹא כֵן, מֵאַיִן בָּאָה לוֹ עַצְבוּת אֲמִיתִּית מֵחֲמַת אַהֲבַת ה׳ אוֹ יִרְאָתוֹ, בְּאֶמְצַע עֲסָקָיו."],"Tanya, Part I; Likkutei Amarim 27:1":["וְאִם הָעַצְבוּת אֵינָהּ מִדַּאֲגַת עֲוֹנוֹת, אֶלָּא מֵהִרְהוּרִים רָעִים וְתַאֲווֹת רָעוֹת שֶׁנּוֹפְלוֹת בְּמַחֲשַׁבְתּוֹ. הִנֵּה אִם נוֹפְלוֹת לוֹ שֶׁלֹּא בִּשְׁעַת הָעֲבוֹדָה, אֶלָּא בְּעֵת עָסְקוֹ בַּעֲסָקָיו וְדֶרֶךְ אֶרֶץ וּכְהַאי גַּוְונָא, אַדְּרַבָּה! יֵשׁ לוֹ לִשְׂמוֹחַ בְּחֶלְקוֹ, שֶׁאַף שֶׁנּוֹפְלוֹת לוֹ בְּמַחֲשַׁבְתּוֹ – הוּא מַסִּיחַ דַּעְתּוֹ מֵהֶן, לְקַיֵּים מַה שֶּׁנֶּאֱמַר: ״וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זוֹנִים אַחֲרֵיהֶם״."],"Tanya, Part I; Likkutei Amarim 27:11":["וְלֹא עוֹד, אֶלָּא אֲפִילוּ בִּדְבָרִים הַמּוּתָּרִים לְגַמְרֵי, כָּל מַה שֶּׁהָאָדָם זוֹבֵחַ יִצְרוֹ אֲפִילוּ שָׁעָה קַלָּה, וּמִתְכַּוֵין לְאַכֽפָּיָא לְסִטְרָא אָחֳרָא שֶׁבֶּחָלָל הַשְּׂמָאלִי, כְּגוֹן שֶׁחָפֵץ לֶאֱכוֹל, וּמְאַחֵר סְעוּדָּתוֹ עַד לְאַחַר שָׁעָה אוֹ פָּחוֹת, וְעוֹסֵק בַּתּוֹרָה בְּאוֹתָהּ שָׁעָה, כִּדְאִיתָא בַּגְּמָרָא: ״שָׁעָה רְבִיעִית מַאֲכַל כָּל אָדָם, שָׁעָה שִׁשִּׁית מַאֲכַל תַּלְמִידֵי חֲכָמִים״, וְהָיוּ מַרְעִיבִים עַצְמָם שְׁתֵּי שָׁעוֹת לְכַוָּונָה זוֹ, אַף שֶׁגַּם אַחַר הַסְּעוּדָּה הָיוּ לוֹמְדִים כָּל הַיּוֹם."],"Tanya, Part I; Likkutei Amarim 27:12":["וְכֵן אִם בּוֹלֵם פִּיו מִלְּדַבֵּר דְּבָרִים שֶׁלִּבּוֹ מִתְאַוֶּה מְאֹד לְדַבְּרָם מֵעִנְיְינֵי הָעוֹלָם, וְכֵן בְּהִרְהוּרֵי מַחֲשַׁבְתּוֹ, אֲפִילוּ בִּמְעַט מִזְּעֵיר, דְּאִתְכַּפְיָא סִטְרָא אָחֳרָא לְתַתָּא – אִסְתַּלֵּק יְקָרָא דְקוּדְשָׁא־בְּרִיךְ־הוּא וּקְדוּשָּׁתוֹ לְעֵילָּא הַרְבֵּה. וּמִקְּדוּשָּׁה זוֹ נִמְשֶׁכֶת קְדוּשָּׁה עֶלְיוֹנָה עַל הָאָדָם לְמַטָּה, לְסַיְּיעוֹ סִיּוּעַ רַב וְעָצוּם לַעֲבוֹדָתוֹ יִתְבָּרֵךְ."],"Tanya, Part I; Likkutei Amarim 27:3":["וְאַדְּרַבָּה, הָעַצְבוּת הִיא מִגַּסּוּת הָרוּחַ, שֶׁאֵינוֹ מַכִּיר מְקוֹמוֹ, וְעַל כֵּן יֵרַע לְבָבוֹ עַל שֶׁאֵינוֹ בְּמַדְרֵגַת צַדִּיק, שֶׁלְּצַדִּיקִים בְּוַדַּאי אֵין נוֹפְלִים לָהֶם הִרְהוּרֵי שְׁטוּת כָּאֵלּוּ, כִּי אִילּוּ הָיָה מַכִּיר מְקוֹמוֹ, שֶׁהוּא רָחוֹק מְאֹד מִמַּדְרֵגַת צַדִּיק, וְהַלְוַאי הָיָה בֵּינוֹנִי וְלֹא רָשָׁע כָּל יָמָיו, אֲפִילוּ שָׁעָה אַחַת, הֲרֵי זֹאת הִיא מִדַּת הַבֵּינוֹנִים וַעֲבוֹדָתָם – לִכְבּוֹשׁ הַיֵּצֶר וְהַהִרְהוּר הָעוֹלֶה מֵהַלֵּב לַמּוֹחַ, וּלְהַסִּיחַ דַּעְתּוֹ לְגַמְרֵי מִמֶּנּוּ, וְלִדְחוֹתוֹ בִּשְׁתֵּי יָדַיִם, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 27:4":["וּבְכָל דְּחִיָּה וּדְחִיָּה שֶׁמַּדְחֵהוּ מִמַּחֲשַׁבְתּוֹ, אִתְכַּפְיָא סִטְרָא אָחֳרָא לְתַתָּא, וּבְאִתְעָרוּתָא דִלְתַתָּא – אִתְעָרוּתָא דִלְעֵילָּא, וְאִתְכַּפְיָא סִטְרָא אָחֳרָא דִלְעֵילָּא הַמַּגְבִּיהַּ עַצְמָהּ כַּנֶּשֶׁר, לְקַיֵּים מַה שֶּׁנֶּאֱמַר: ״אִם תַּגְבִּיהַּ כַּנֶּשֶׁר וְגוֹ׳ מִשָּׁם אוֹרִידְךָ, נְאֻם ה׳״."],"Tanya, Part I; Likkutei Amarim 27:6":["וְלָכֵן, אַל יִפּוֹל לֵב אָדָם עָלָיו, וְלֹא יֵרַע לְבָבוֹ מְאֹד, גַּם אִם יִהְיֶה כֵּן כָּל יָמָיו בְּמִלְחָמָה זוֹ, כִּי אוּלַי לְכָךְ נִבְרָא, וְזֹאת עֲבוֹדָתוֹ לְאַכֽפָּיָא לְסִטְרָא אָחֳרָא תָּמִיד."],"Tanya, Part I; Likkutei Amarim 27:8":["וּשְׁנֵי מִינֵי נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ לְמַעְלָה: אֶחָד – מִבִּיטּוּל הַסִּטְרָא אָחֳרָא לְגַמְרֵי, וְאִתְהַפְּכָא מִמְּרִירוּ לְמִתְקָא וּמֵחֲשׁוֹכָא לִנְהוֹרָא, עַל יְדֵי הַצַּדִּיקִים. וְהַשֵּׁנִית – כַּד אִתְכַּפְיָא הַסִּטְרָא אָחֳרָא בְּעוֹדָהּ בְּתָקְפָּהּ וּגְבוּרָתָהּ וּמַגְבִּיהַּ עַצְמָהּ כַּנֶּשֶׁר, וּמִשָּׁם מוֹרִידָהּ ה׳ בְּאִתְעָרוּתָא דִלְתַתָּא עַל יְדֵי הַבֵּינוֹנִים."],"Tanya, Part I; Likkutei Amarim 28:1":["וַאֲפִילוּ אִם נוֹפְלִים לוֹ הִרְהוּרֵי תַּאֲווֹת וּשְׁאָר מַחֲשָׁבוֹת זָרוֹת בִּשְׁעַת הָעֲבוֹדָה בַּתּוֹרָה אוֹ בִּתְפִלָּה בְּכַוָּונָה, אַל יָשִׁית לֵב אֲלֵיהֶן, אֶלָּא יַסִּיחַ דַּעְתּוֹ מֵהֶן כְּרֶגַע."],"Tanya, Part I; Likkutei Amarim 28:5":["וְלֹא כְּטָעוּת הָעוֹלָם, שֶׁטּוֹעִים לְהוֹכִיחַ מִנְּפִילַת הַמַּחֲשָׁבָה זָרָה – מִכְּלָל שֶׁאֵין תְּפִלָּתָם כְּלוּם, שֶׁאִילּוּ הִתְפַּלֵּל כָּרָאוּי וְנָכוֹן – לֹא הָיוּ נוֹפְלִים לוֹ מַחֲשָׁבוֹת זָרוֹת. וְהָאֱמֶת הָיָה כְּדִבְרֵיהֶם, אִם הָיְתָה נֶפֶשׁ אַחַת לְבַדָּהּ, הִיא הַמִּתְפַּלֶּלֶת וְהִיא הַמְחַשֶּׁבֶת וּמְהַרְהֶרֶת הַמַּחֲשָׁבוֹת זָרוֹת."],"Tanya, Part I; Likkutei Amarim 29:1":["אַךְ עוֹד אַחַת צָרִיךְ לָשִׁית עֵצוֹת בְּנַפְשׁוֹת הַבֵּינוֹנִים, אֲשֶׁר לִפְעָמִים וְעִתִּים רַבִּים יֵשׁ לָהֶם טִמְטוּם הַלֵּב שֶׁנַּעֲשֶׂה כָּאֶבֶן, וְלֹא יָכוֹל לִפְתּוֹחַ לִבּוֹ בְּשׁוּם אוֹפֶן לַעֲבוֹדָה שֶׁבַּלֵּב זוֹ תְּפִלָּה."],"Tanya, Part I; Likkutei Amarim 29:12":["וּבִפְרָט כְּשֶׁיִּזְכּוֹר טוּמְאַת נַפְשׁוֹ בְּחַטַּאת נְעוּרִים, וְהַפְּגַם שֶׁעָשָׂה בָּעֶלְיוֹנִים, וְשָׁם הוּא לְמַעְלָה מֵהַזְּמַן, וּכְאִלּוּ פָּגַם וְנִטְמָא הַיּוֹם – חַס וְשָׁלוֹם – מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 29:15":["וְגַם מִי שֶׁהוּא נָקִי מֵחַטֹּאות נְעוּרִים הַחֲמוּרִים, יָשִׂים אֶל לִבּוֹ לְקַיֵּים מַאֲמַר זֹהַר הַקָּדוֹשׁ, לִהְיוֹת מִ״מָּארֵי דְחוּשְׁבָּנָא״, דְּהַיְינוּ, לַעֲשׂוֹת חֶשְׁבּוֹן עִם נַפְשׁוֹ, מִכָּל הַמַּחֲשָׁבוֹת וְהַדִּיבּוּרִים וְהַמַּעֲשִׂים שֶׁחָלְפוּ וְעָבְרוּ מִיּוֹם הֱיוֹתוֹ עַד הַיּוֹם הַזֶּה, אִם הָיוּ כּוּלָּם מִצַּד הַקְּדוּשָּׁה, אוֹ, מִצַּד הַטּוּמְאָה רַחֲמָנָא לִצְּלָן, דְּהַיְינוּ, כָּל הַמַּחֲשָׁבוֹת וְהַדִּיבּוּרִים וְהַמַּעֲשִׂים אֲשֶׁר לֹא לַה׳ הֵמָּה וְלִרְצוֹנוֹ וְלַעֲבוֹדָתוֹ, שֶׁזֶּהוּ פֵּירוּשׁ לְשׁוֹן ״סִטְרָא אָחֳרָא״, כַּנִּזְכָּר לְעֵיל [בְּפֶרֶק ו׳]."],"Tanya, Part I; Likkutei Amarim 29:17":["עוֹד יָשִׂים אֶל לִבּוֹ, רוֹב חֲלוֹמוֹתָיו, שֶׁהֵם הֶבֶל וּרְעוּת רוּחַ, מִשּׁוּם שֶׁאֵין נַפְשׁוֹ עוֹלָה לְמַעְלָה, וּכְמוֹ שֶׁכָּתוּב: ״מִי יַעֲלֶה בְּהַר ה׳, נְקִי כַפַּיִם וְגוֹ׳״, וְ״אִינוּן סִטְרִין בִּישִׁין אָתְיָין וּמִתְדַּבְּקָן בֵּיהּ וּמוֹדְעִין לֵיהּ בְּחֶלְמָא מִילִּין דְּעָלְמָא וְכוּ׳, וּלְזִמְנִין דְּחַיְיכָן בֵּיהּ וְאַחֲזִיאוּ לֵיהּ מִילֵּי שְׁקָר וְצַעֲרִין לֵיהּ בְּחֶלְמֵיהּ כוּ׳״, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר וַיִּקְרָא [דַּף כ״ה עַמּוּד א׳ וְעַמּוּד ב׳], עַיֵּין שָׁם בַּאֲרִיכוּת."],"Tanya, Part I; Likkutei Amarim 29:18":["וְהִנֵּה, כָּל מַה שֶּׁיַּאֲרִיךְ בְּעִנְיָינִים אֵלּוּ בְּמַחֲשַׁבְתּוֹ וְגַם בְּעִיּוּנוֹ בִּסְפָרִים, לִהְיוֹת לִבּוֹ נִשְׁבָּר בְּקִרְבּוֹ, וְ״נִבְזֶה בְעֵינָיו נִמְאָס״ כַּכָּתוּב, בְּתַכְלִית הַמִּיאוּס, וּלְמָאֵס חַיָּיו מַמָּשׁ, הֲרֵי בָּזֶה מְמָאֵס וּמְבַזֶּה הַסִּטְרָא אָחֳרָא וּמַשְׁפִּילָהּ לֶעָפָר, וּמוֹרִידָהּ מִגְּדוּלָּתָהּ וְגַסּוּת רוּחָהּ וְגַבְהוּתָהּ, שֶׁמַּגְבִּיהַּ אֶת עַצְמָהּ עַל אוֹר קְדוּשַּׁת נֶפֶשׁ הָאֱלֹהִית לְהַחֲשִׁיךְ אוֹרָהּ."],"Tanya, Part I; Likkutei Amarim 29:21":["וְהַטַּעַם, לְפִי שֶׁבֶּאֱמֶת אֵין שׁוּם מַמָּשׁוּת כְּלָל בַּסִטְרָא אָחֳרָא, שֶׁלָּכֵן נִמְשְׁלָה לְחֹשֶׁךְ שֶׁאֵין בּוֹ שׁוּם מַמָּשׁוּת כְּלָל, וּמִמֵּילָא נִדְחֶה מִפְּנֵי הָאוֹר, וְכָךְ הַסִּטְרָא אָחֳרָא, אַף שֶׁיֵּשׁ בָּהּ חַיּוּת הַרְבֵּה, לְהַחֲיוֹת כָּל בַּעֲלֵי חַיִּים הַטְּמֵאִים וְנַפְשׁוֹת אוּמּוֹת הָעוֹלָם, וְגַם נֶפֶשׁ הַבַּהֲמִית שֶׁבְּיִשְׂרָאֵל כַּנִּזְכָּר לְעֵיל, מִכָּל מָקוֹם, הֲרֵי כָּל חַיּוּתָהּ אֵינָהּ מִצַּד עַצְמָהּ חַס וְשָׁלוֹם, אֶלָּא מִצַּד הַקְּדוּשָּׁה כַּנִּזְכָּר לְעֵיל, וְלָכֵן הִיא בְּטֵלָה לְגַמְרֵי מִפְּנֵי הַקְּדוּשָּׁה, כְּבִיטּוּל הַחֹשֶׁךְ מִפְּנֵי הָאוֹר הַגַּשְׁמִי. רַק שֶׁלְּגַבֵּי קְדוּשַּׁת נֶפֶשׁ הָאֱלֹהִית שֶׁבָּאָדָם, נָתַן לָהּ הַקָּדוֹשׁ־בָּרוּךְ־הוּא רְשׁוּת וִיכוֹלֶת לְהַגְבִּיהַּ עַצְמָהּ כְּנֶגְדָּהּ, כְּדֵי שֶׁהָאָדָם יִתְעוֹרֵר לְהִתְגַּבֵּר עָלֶיהָ, לְהַשְׁפִּילָהּ עַל יְדֵי שִׁפְלוּת וּנְמִיכוּת רוּחוֹ, וְ״נִבְזֶה בְעֵינָיו נִמְאָס״."],"Tanya, Part I; Likkutei Amarim 29:5":["וְאַף שֶׁמֵּבִין וּמִתְבּוֹנֵן בְּשִׂכְלוֹ בִּגְדוּלַּת ה׳, אֵינוֹ נִתְפָּס וְנִדְבָּק בְּמוֹחוֹ כָּל כָּךְ שֶׁיּוּכַל לִמְשׁוֹל עַל חוּמְרִיּוּת הַלֵּב, מֵחֲמַת חוּמְרִיּוּתָן וְגַסּוּתָן. וְהַסִּיבָּה – הִיא גַסּוּת הַקְּלִיפָּה, שֶׁמַּגְבִּיהַּ עַצְמָהּ עַל אוֹר קְדוּשַּׁת נֶפֶשׁ הָאֱלֹהִית, וּמַסְתֶּרֶת וּמַחֲשִׁיכָה אוֹרָהּ."],"Tanya, Part I; Likkutei Amarim 29:8":["וּכְמַאֲמַר הִלֵּל הַזָּקֵן לְתַלְמִידָיו כְּשֶׁהָיָה הוֹלֵךְ לֶאֱכוֹל, הָיָה אוֹמֵר, שֶׁהוּא הוֹלֵךְ לִגְמוֹל חֶסֶד עִם הָעֲלוּבָה וַעֲנִיָּה – הוּא גוּפוֹ, כִּי כְּמוֹ זָר נֶחְשַׁב אֶצְלוֹ, וְלָכֵן אָמַר, שֶׁהוּא גּוֹמֵל חֶסֶד עִמּוֹ בְּמַה שֶּׁמַּאֲכִילוֹ, כִּי הוּא עַצְמוֹ אֵינוֹ רַק נֶפֶשׁ הָאֱלֹהִית לְבַד, כִּי הִיא לְבַדָּהּ מְחַיָּה גּוּפוֹ וּבְשָׂרוֹ, שֶׁהָרָע שֶׁהָיָה בַּנֶּפֶשׁ הַחִיּוּנִית הַמְלוּבֶּשֶׁת בְּדָמוֹ וּבְשָׂרוֹ – נִתְהַפֵּךְ לְטוֹב, וְנִכְלַל בִּקְדוּשַּׁת נֶפֶשׁ הָאֱלֹהִית מַמָּשׁ, בַּצַּדִּיקִים."],"Tanya, Part I; Likkutei Amarim 29:9":["אֲבָל בַּבֵּינוֹנִי, מֵאַחַר שֶׁמַּהוּתָהּ וְעַצְמוּתָהּ שֶׁל נֶפֶשׁ הַחִיּוּנִית הַבַּהֲמִית שֶׁמִּסִּטְרָא אָחֳרָא, הַמְלוּבֶּשֶׁת בְּדָמוֹ וּבְשָׂרוֹ, לֹא נֶהְפַּךְ לְטוֹב – הֲרֵי הִיא הִיא הָאָדָם עַצְמוֹ."],"Tanya, Part I; Likkutei Amarim 2:1":["וְנֶפֶשׁ הַשֵּׁנִית בְּיִשְׂרָאֵל, הִיא חֵלֶק אֱלוֹהַּ מִמַּעַל מַמָּשׁ, כְּמוֹ שֶׁכָּתוּב: ״וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים״, וְ״אַתָּה נָפַחְתָּ בִּי״, וּכְמוֹ שֶׁכָּתוּב בַּזֹּהַר, מַאן דְּנָפַח מִתּוֹכֵיהּ נָפַח, פֵּירוּשׁ, מִתּוֹכִיּוּתוֹ וּמִפְּנִימִיּוּתוֹ, שֶׁתּוֹכִיּוּת וּפְנִימִיּוּת הַחַיּוּת שֶׁבָּאָדָם מוֹצִיא בִּנְפִיחָתוֹ בְּכֹחַ:"],"Tanya, Part I; Likkutei Amarim 30:1":["עוֹד זֹאת יָשִׂים אֶל לִבּוֹ, לְקַיֵּים מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״וֶהֱוֵי שְׁפַל רוּחַ בִּפְנֵי כּל הָאָדָם״. וֶהֱוֵי – בֶּאֱמֶת לַאֲמִיתּוֹ, ״בִּפְנֵי כָל הָאָדָם״ – מַמָּשׁ, אֲפִילוּ בִּפְנֵי קַל שֶׁבְּקַלִּים. וְהַיְינוּ, עַל פִּי מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אַל תָּדִין אֶת חֲבֵירָךְ – עַד שֶׁתַּגִּיעַ לִמְקוֹמוֹ״."],"Tanya, Part I; Likkutei Amarim 30:14":["וַאֲפִילוּ בִּבְחִינַת ״סוּר מֵרָע״, יָכוֹל כָּל אִישׁ מַשְׂכִּיל לִמְצוֹא בְּנַפְשׁוֹ שֶׁאֵינוֹ סָר לְגַמְרֵי מֵהָרָע בַּכֹּל מִכֹּל כֹּל, בְּמָקוֹם שֶׁצָּרִיךְ לְמִלְחָמָה עֲצוּמָה כְּעֵרֶךְ הַנִּזְכָּר לְעֵיל, וַאֲפִילוּ פָּחוֹת מֵעֵרֶךְ הַנִּזְכָּר לְעֵיל, כְּגוֹן לְהַפְסִיק בְּאֶמְצַע שִׂיחָה נָאָה, אוֹ סִיפּוּר בִּגְנוּת חֲבֵירוֹ, וַאֲפִילוּ גְּנַאי קָטָן וְקַל מְאֹד, אַף שֶׁהוּא אֱמֶת, וַאֲפִילוּ כְּדֵי לְנַקּוֹת עַצְמוֹ, כַּנּוֹדָע מֵהָא דְּאָמַר רַבִּי שִׁמְעוֹן לְאָבִיו רַבֵּינוּ הַקָּדוֹשׁ: ״לָאו אֲנָא כַּתְבֵיהּ, אֶלָּא יְהוּדָא חַיָּיטָא כַּתְבֵיהּ״, וְאָמַר לוֹ: ״כַּלֵּךְ מִלָּשׁוֹן הָרָע״ [עַיֵּין שָׁם בַּגְּמָרָא רֵישׁ פֶּרֶק י׳ דְּבָבָא בַּתְרָא]."],"Tanya, Part I; Likkutei Amarim 30:17":["אֲבָל בֶּאֱמֶת, אִם הוּא יוֹדֵעַ סֵפֶר, וּמַחֲזִיק בְּתוֹרַת ה׳, וְקִרְבַת אֱלֹקִים יֶחְפָּץ – גָּדוֹל עֲוֹנוֹ מִנְּשׂוֹא, וְאַשְׁמָתוֹ גָדְלָה בְּכִפְלֵי כִפְלַיִים בְּמַה שֶּׁאֵינוֹ נִלְחָם וּמִתְגַּבֵּר עַל יִצְרוֹ בְּעֵרֶךְ וּבְחִינַת מִלְחָמָה עֲצוּמָה הַנִּזְכֶּרֶת לְעֵיל, מֵאַשְׁמַת קַל שֶׁבְּקַלִּים מִיּוֹשְׁבֵי קְרָנוֹת הָרְחוֹקִים מֵה׳ וְתוֹרָתוֹ, וְאֵין אַשְׁמָתָם גְּדוֹלָה כָּל כָּךְ בְּמַה שֶּׁאֵינָם כּוֹבְשִׁים יִצְרָם הַבּוֹעֵר כְּאֵשׁ לֶהָבָה, מִפְּנֵי פַּחַד ה׳ הַמֵּבִין וּמַבִּיט אֶל כָּל מַעֲשֵׂיהֶם, כְּאַשְׁמַת כָּל הַקָּרֵב הַקָּרֵב אֶל ה׳ וְאֶל תּוֹרָתוֹ וַעֲבוֹדָתוֹ, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה גַּבֵּי אַחֵר: ״שֶׁיָּדַע בִּכְבוֹדִי וְכוּ׳״."],"Tanya, Part I; Likkutei Amarim 30:4":["וְהִנֵּה, בֶּאֱמֶת, גַּם מִי שֶׁהוּא מְחוּמָּם מְאֹד בְּטִבְעוֹ, וּפַרְנָסָתוֹ הִיא לִהְיוֹת מִיּוֹשְׁבֵי קְרָנוֹת כָּל הַיּוֹם, אֵין לוֹ שׁוּם הִתְנַצְּלוּת עַל חֲטָאָיו, וּמִקְרֵי ״רָשָׁע גָּמוּר״ עַל אֲשֶׁר אֵין פַּחַד אֱלֹהִים לְנֶגֶד עֵינָיו."],"Tanya, Part I; Likkutei Amarim 30:6":["וְהִנֵּה, בֶּאֱמֶת, שֶׁהִיא מִלְחָמָה גְדוֹלָה וַעֲצוּמָה, לִשְׁבּוֹר הַיֵּצֶר הַבּוֹעֵר כְּאֵשׁ לֶהָבָה מִפְּנֵי פַּחַד ה׳, וּכְמוֹ נִסָּיוֹן מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 30:8":["וְכָל שֶׁלֹּא הִגִּיעַ לִידֵי מִדָּה זוֹ, לְהִלָּחֵם עִם גּוּפוֹ מִלְחָמָה עֲצוּמָה כָּזוֹ – עֲדַיִין לֹא הִגִּיעַ לִבְחִינַת וְעֵרֶךְ מִלְחֶמֶת הַיֵּצֶר הַבּוֹעֵר כְּאֵשׁ לֶהָבָה, לִהְיוֹת נִכְנָע וְנִשְׁבָּר מִפְּנֵי פַּחַד ה׳."],"Tanya, Part I; Likkutei Amarim 31:1":["וְהִנֵּה, אַף אִם כְּשֶׁיַּאֲרִיךְ הַרְבֵּה לְהַעֲמִיק בָּעִנְיָינִים הַנִּזְכָּרִים לְעֵיל כְּשָׁעָה וּשְׁתַּיִם, לִהְיוֹת בִּנְמִיכַת רוּחַ וְלֵב נִשְׁבָּר, יָבֹא לִידֵי עַצְבוּת גְּדוֹלָה – לֹא יָחוּשׁ."],"Tanya, Part I; Likkutei Amarim 31:11":["וְזֹאת תִּהְיֶה עֲבוֹדָתוֹ כָּל יָמָיו בְּשִׂמְחָה רַבָּה, הִיא שִׂמְחַת הַנֶּפֶשׁ בְּצֵאתָהּ מֵהַגּוּף הַמְתוֹעָב, ״וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ״, בִּשְׁעַת הַתּוֹרָה וְהָעֲבוֹדָה, וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: לִהְיוֹת כָּל יָמָיו בִּתְשׁוּבָה."],"Tanya, Part I; Likkutei Amarim 31:17":["וְלִהְיוֹת בְּחִינַת תְּשׁוּבָה זוֹ בְּיֶתֶר שְׂאֵת וְיֶתֶר עֹז מֵעוּמְקָא דְלִבָּא, וְגַם שִׂמְחַת הַנֶּפֶשׁ תִּהְיֶה בְּתוֹסֶפֶת אוֹרָה וְשִׂמְחָה – כַּאֲשֶׁר יָשִׁיב אֶל לִבּוֹ דַּעַת וּתְבוּנָה לְנַחֲמוֹ מֵעִצְּבוֹנוֹ וִיגוֹנוֹ, לֵאמֹר כַּנִּזְכָּר לְעֵיל: ״הֵן אֱמֶת כוּ׳״, ״אַךְ אֲנִי לֹא עָשִׂיתִי אֶת עַצְמִי. וְלָמָּה עָשָׂה ה׳ כָּזֹאת, לְהוֹרִיד חֵלֶק מֵאוֹרוֹ יִתְבָּרֵךְ, הַמְמַלֵּא וְסוֹבֵב כָּל עָלְמִין וְכוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיב, וְהִלְבִּישׁוֹ בְּ״מַשְׁכָּא דְחִוְיָא״ וְ״טִפָּה סְרוּחָה״? אֵין זֶה, כִּי אִם יְרִידָה זוֹ – הִיא צוֹרֶךְ עֲלִיָּה, לְהַעֲלוֹת לַה׳ כָּל נֶפֶשׁ הַחִיּוּנִית הַבַּהֲמִית שֶׁמִּקְּלִיפַּת נוֹגַהּ וְכָל לְבוּשֶׁיהָ, הֵן בְּחִינוֹת מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁלָּהּ, עַל יְדֵי הִתְלַבְּשׁוּתָן בְּמַעֲשֵׂה דִּבּוּר וּמַחֲשֶׁבֶת הַתּוֹרָה [וּכְמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן עִנְיַן הַעֲלָאָה זוֹ בַּאֲרִיכוּת, אֵיךְ שֶׁהִיא תַּכְלִית בְּרִיאַת הָעוֹלָם], וְאִם כֵּן אֵיפוֹא, זֹאת אֶעֱשֶׂה וְזֹאת תִּהְיֶה כָּל מְגַמָּתִי כָּל יְמֵי חֶלְדִּי – לְכָל בָּהֶן חַיֵּי רוּחִי וְנַפְשִׁי, וּכְמוֹ שֶׁכָּתוּב: ״אֵלֶיךָ ה׳ נַפְשִׁי אֶשָּׂא״, דְּהַיְינוּ, לְקַשֵּׁר מַחֲשַׁבְתִּי וְדִבּוּרִי – בְּמַחֲשַׁבְתּוֹ וְדִבּוּרוֹ יִתְבָּרֵךְ, וְהֵן הֵן גּוּפֵי הֲלָכוֹת הָעֲרוּכוֹת לְפָנֵינוּ, וְכֵן מַעֲשֶׂה – בְּמַעֲשֵׂה הַמִּצְוֹת."],"Tanya, Part I; Likkutei Amarim 31:9":["וְאַחַר כָּךְ יָבֹא לִידֵי שִׂמְחָה אֲמִיתִּית. דְּהַיְינוּ, שֶׁזֹּאת יָשִׁיב אֶל לִבּוֹ לְנַחֲמוֹ בְּכִפְלַיִים, אַחַר הַדְּבָרִים וְהָאֱמֶת הָאֵלֶּה הַנִּזְכָּרִים לְעֵיל, לֵאמֹר לְלִבּוֹ: ״אֱמֶת הוּא כֵּן בְּלִי סָפֵק, שֶׁאֲנִי רָחוֹק מְאֹד מֵה׳ בְּתַכְלִית, וּמְשׁוּקָּץ וּמְתוֹעָב כוּ׳, אַךְ כָּל זֶה הוּא אֲנִי לְבַדִּי, הוּא הַגּוּף עִם נֶפֶשׁ הַחִיּוּנִית שֶׁבּוֹ, אֲבָל מִכָּל מָקוֹם, יֵשׁ בְּקִרְבִּי ״חֵלֶק ה׳״ מַמָּשׁ, שֶׁיֶּשְׁנוֹ אֲפִילוּ בְּקַל שֶׁבְּקַלִּים, שֶׁהִיא נֶפֶשׁ הָאֱלֹהִית עִם נִיצוֹץ אֱלֹקוּת מַמָּשׁ הַמְלוּבָּשׁ בָּהּ לְהַחֲיוֹתָהּ, רַק שֶׁהִיא בִּבְחִינַת גָּלוּת, וְאִם כֵּן, אַדְּרַבָּה, כָּל מַה שֶּׁאֲנִי בְּתַכְלִית הָרִיחוּק מֵה׳ וְהַתִּיעוּב וְשִׁיקּוּץ הֲרֵי נֶפֶשׁ הָאֱלֹהִית שֶׁבִּי בְּגָלוּת גָּדוֹל יוֹתֵר, וְהָרַחֲמָנוּת עָלֶיהָ גְּדוֹלָה מְאֹד, וְלָזֶה אָשִׂים כָּל מְגַמָּתִי וְחֶפְצִי – לְהוֹצִיאָהּ וּלְהַעֲלוֹתָהּ מִגָּלוּת זֶה, לַהֲשִׁיבָהּ אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ, קוֹדֶם שֶׁנִּתְלַבְּשָׁה בְּגוּפִי, שֶׁהָיְתָה נִכְלֶלֶת בְּאוֹרוֹ יִתְבָּרֵךְ וּמְיוּחֶדֶת עִמּוֹ בְּתַכְלִית, וְגַם עַתָּה כֵּן – תְּהֵא כְּלוּלָה וּמְיוּחֶדֶת בּוֹ יִתְבָּרֵךְ, כְּשֶׁאָשִׂים כָּל מְגַמָּתִי בְּתוֹרָה וּמִצְוֹת, לְהַלְבִּישׁ בָּהֶן כָּל עֶשֶׂר בְּחִינוֹתֶיהָ כַּנִּזְכָּר לְעֵיל, וּבִפְרָט בְּמִצְוַת תְּפִלָּה, לִצְעוֹק אֶל ה׳ בַּצַּר לָהּ מִגָּלוּתָהּ בְּגוּפִי הַמְשׁוּקָּץ, לְהוֹצִיאָהּ מִמַּסְגֵּר, וּלְדָבְקָה בּוֹ יִתְבָּרֵךְ״."],"Tanya, Part I; Likkutei Amarim 32:1":["וְהִנֵּה, עַל יְדֵי קִיּוּם הַדְּבָרִים הַנִּזְכָּרִים לְעֵיל, לִהְיוֹת גּוּפוֹ נִבְזֶה וְנִמְאָס בְּעֵינָיו, רַק שִׂמְחָתוֹ תִּהְיֶה שִׂמְחַת הַנֶּפֶשׁ לְבַדָּהּ, הֲרֵי זוֹ דֶּרֶךְ יְשָׁרָה וְקַלָּה לָבֹא לִידֵי קִיּוּם מִצְוַת ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ לְכָל נֶפֶשׁ מִיִּשְׂרָאֵל – לְמִגָּדוֹל וְעַד קָטָן."],"Tanya, Part I; Likkutei Amarim 32:2":["כִּי מֵאַחַר שֶׁגּוּפוֹ נִמְאָס וּמְתוֹעָב אֶצְלוֹ, וְהַנֶּפֶשׁ וְהָרוּחַ מִי יוֹדֵעַ גְּדוּלָּתָן וּמַעֲלָתָן בְּשָׁרְשָׁן וּמְקוֹרָן בֵּאלֹקִים חַיִּים. בְּשֶׁגַּם שֶׁכּוּלָּן מַתְאִימוֹת, וְאָב אֶחָד לְכוּלָּנָה, וְלָכֵן נִקְרְאוּ כָּל יִשְׂרָאֵל ״אַחִים״ מַמָּשׁ, מִצַּד שׁוֹרֶשׁ נַפְשָׁם בַּה׳ אֶחָד רַק שֶׁהַגּוּפִים מְחוּלָּקִים. וְלָכֵן, הָעוֹשִׂים גּוּפָם עִיקָּר וְנַפְשָׁם טְפֵלָה – אִי אֶפְשָׁר לִהְיוֹת אַהֲבָה וְאַחֲוָה אֲמִיתִּית בֵּינֵיהֶם, אֶלָּא הַתְּלוּיָה בְדָבָר לְבַדָּהּ."],"Tanya, Part I; Likkutei Amarim 32:3":["וְזֶהוּ שֶׁאָמַר הִלֵּל הַזָּקֵן עַל קִיּוּם מִצְוָה זוֹ: ״זֶהוּ כָּל הַתּוֹרָה כוּלָּהּ, וְאִידָךְ פֵּירוּשָׁא הוּא כוּ׳״. כִּי יְסוֹד וְשׁוֹרֶשׁ כָּל הַתּוֹרָה – הוּא לְהַגְבִּיהַּ וּלְהַעֲלוֹת הַנֶּפֶשׁ עַל הַגּוּף מַעְלָה מַּעְלָה עַד עִיקָּרָא וְשָׁרְשָׁא דְּכָל עָלְמִין וְגַם, לְהַמְשִׁיךְ אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא בִּכְנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן, דְּהַיְינוּ, בִּמְקוֹר נִשְׁמוֹת כָּל יִשְׂרָאֵל, לְמֶהֱוֵי אֶחָד בְּאֶחָד דַּוְקָא, וְלֹא כְּשֶׁיֵּשׁ פֵּירוּד חַס וְשָׁלוֹם בַּנְּשָׁמוֹת, דְּ״קוּדְשָׁא־בְּרִיךְ־הוּא לָא שַׁרְיָא בַּאֲתַר פְּגִים״, וּכְמוֹ שֶׁאוֹמְרִים: ״בָּרְכֵנוּ אָבִינוּ כּוּלָּנוּ כְּאֶחָד בְּאוֹר פָּנֶיךָ״, וּכְמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר בַּאֲרִיכוּת:"],"Tanya, Part I; Likkutei Amarim 32:4":["וּמַה שֶּׁכָּתוּב בַּגְּמָרָא, שֶׁמִּי שֶׁרוֹאֶה בַּחֲבֵירוֹ שֶׁחָטָא – מִצְוָה לִשְׂנֹאותוֹ, וְגַם לוֹמַר לְרַבּוֹ שֶׁיִּשְׂנָאֵהוּ. הַיְינוּ – בַּחֲבֵירוֹ בְּתוֹרָה וּמִצְוֹת, וּכְבָר קִיֵּים בּוֹ מִצְוַת ״הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ״ – עַם שֶׁאִתְּךָ בְּתוֹרָה וּבְמִצְוֹת, וְאַף־עַל־פִּי־כֵן לֹא שָׁב מֵחֶטְאוֹ, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר חֲרֵדִים."],"Tanya, Part I; Likkutei Amarim 32:5":["אֲבָל מִי שֶׁאֵינוֹ חֲבֵירוֹ וְאֵינוֹ מְקוֹרָב אֶצְלוֹ, הִנֵּה עַל זֶה אָמַר הִלֵּל הַזָּקֵן: ״הֱוֵי מִתַּלְמִידָיו שֶׁל אַהֲרֹן, אוֹהֵב שָׁלוֹם וְכוּ׳, אוֹהֵב אֶת הַבְּרִיּוֹת וּמְקָרְבָן לַתּוֹרָה״. לוֹמַר, שֶׁאַף הָרְחוֹקִים מִתּוֹרַת ה׳ וַעֲבוֹדָתוֹ, וְלָכֵן נִקְרָאִים בְּשֵׁם ״בְּרִיּוֹת״ בְּעָלְמָא – צָרִיךְ לְמָשְׁכָן בְּחַבְלֵי עֲבוֹתוֹת אַהֲבָה, וְכוּלֵּי הַאי וְאוּלַי יוּכַל לְקָרְבָן לְתוֹרָה וַעֲבוֹדַת ה׳; וְהֵן לָא – לֹא הִפְסִיד שְׂכַר מִצְוַת אַהֲבַת רֵיעִים."],"Tanya, Part I; Likkutei Amarim 32:6":["וְגַם הַמְקוֹרָבִים אֵלָיו וְהוֹכִיחָם וְלֹא שָׁבוּ מֵעֲוֹנוֹתֵיהֶם שֶׁמִּצְוָה לִשְׂנֹאותָם – מִצְוָה לְאָהֳבָם גַּם כֵּן. וּשְׁתֵּיהֶן הֵן אֱמֶת: שִׂנְאָה – מִצַּד הָרָע שֶׁבָּהֶם, וְאַהֲבָה – מִצַּד בְּחִינַת הַטּוֹב הַגָּנוּז שֶׁבָּהֶם, שֶׁהוּא נִיצוֹץ אֱלֹקוּת שֶׁבְּתוֹכָם הַמְחַיֶּה נַפְשָׁם הָאֱלֹקִית. וְגַם, לְעוֹרֵר רַחֲמִים בְּלִבּוֹ עָלֶיהָ, כִּי הִיא בִּבְחִינַת גָּלוּת בְּתוֹךְ הָרָע מִסִּטְרָא אָחֳרָא הַגּוֹבֵר עָלֶיהָ בָּרְשָׁעִים, וְהָרַחֲמָנוּת – מְבַטֶּלֶת הַשִּׂנְאָה וּמְעוֹרֶרֶת הָאַהֲבָה, כַּנּוֹדָע מִמַּה שֶּׁכָּתוּב: לְ״יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם״."],"Tanya, Part I; Likkutei Amarim 33:1":["עוֹד זֹאת תִּהְיֶה שִׂמְחַת הַנֶּפֶשׁ הָאֲמִיתִּית, וּבִפְרָט כְּשֶׁרוֹאֶה בְּנַפְשׁוֹ בְּעִתִּים מְזוּמָּנִים שֶׁצָּרִיךְ לְזַכְּכָהּ וּלְהָאִירָהּ בְּשִׂמְחַת לֵבָב, אֲזַי יַעֲמִיק מַחֲשַׁבְתּוֹ וִיצַיֵּיר בְּשִׂכְלוֹ וּבִינָתוֹ עִנְיַן יִחוּדוֹ יִתְבָּרֵךְ הָאֲמִיתִּי, אֵיךְ הוּא מְמַלֵּא כָּל עָלְמִין עֶלְיוֹנִים וְתַחְתּוֹנִים, וַאֲפִילוּ מְלֹא כָּל הָאָרֶץ הַלֶּזוּ הוּא כְּבוֹדוֹ יִתְבָּרֵךְ, וְכוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיב מַמָּשׁ, וְהוּא לְבַדּוֹ הוּא בָּעֶלְיוֹנִים וְתַחְתּוֹנִים מַמָּשׁ, כְּמוֹ שֶׁהָיָה לְבַדּוֹ קוֹדֶם שֵׁשֶׁת יְמֵי בְרֵאשִׁית, וְגַם בַּמָּקוֹם הַזֶּה שֶׁנִּבְרָא בוֹ עוֹלָם הַזֶּה, הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם, הָיָה הוּא לְבַדּוֹ מְמַלֵּא הַמָּקוֹם הַזֶּה, וְגַם עַתָּה כֵּן, הוּא לְבַדּוֹ בְּלִי שׁוּם שִׁינּוּי כְּלָל."],"Tanya, Part I; Likkutei Amarim 33:6":["וְעַל זֶה תִּיקְּנוּ לִיתֵּן שֶׁבַח וְהוֹדָיָה לִשְׁמוֹ יִתְבָּרֵךְ בְּכָל בֹּקֶר, וְלוֹמַר: ״אַשְׁרֵינוּ מַה טּוֹב חֶלְקֵנוּ וְכוּ׳ וּמַה יָפָה יְרוּשָּׁתֵנוּ״, כְּלוֹמַר, כְּמוֹ שֶׁהָאָדָם שָׂשׂ וְשָׂמֵחַ בִּירוּשָּׁה שֶׁנָּפְלָה לוֹ הוֹן עָתֵק שֶׁלֹּא עָמַל בּוֹ, כֵּן וְיוֹתֵר מִכֵּן לְאֵין קֵץ, יֵשׁ לָנוּ לִשְׂמוֹחַ עַל יְרוּשָּׁתֵנוּ שֶׁהִנְחִילוּנוּ אֲבוֹתֵינוּ, הוּא יִחוּד ה׳ הָאֲמִיתִּי, אֲשֶׁר אֲפִילוּ בָּאָרֶץ מִתַּחַת – אֵין עוֹד מִלְּבַדּוֹ, וְזוֹ הִיא דִּירָתוֹ בַּתַּחְתּוֹנִים."],"Tanya, Part I; Likkutei Amarim 33:9":["וְזֶהוּ שֶׁאָמַר ״בֶּאֱמוּנָתוֹ יִחְיֶה״ – ״יִחְיֶה״ דַּיְיקָא, כִּתְחִיַּית הַמֵּתִים, דֶּרֶךְ מָשָׁל, כָּךְ תִּחְיֶה נַפְשׁוֹ בְּשִׂמְחָה רַבָּה זוֹ. וְהִיא שִׂמְחָה כְּפוּלָה וּמְכוּפֶּלֶת, כִּי מִלְּבַד שִׂמְחַת הַנֶּפֶשׁ הַמַּשְׂכֶּלֶת בְּקִרְבַת ה׳ וְדִירָתוֹ אִתּוֹ עִמּוֹ. עוֹד זֹאת יִשְׂמַח בְּכִפְלַיִים בְּשִׂמְחַת ה׳ וְגוֹדֶל נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ בֶּאֱמוּנָה זוֹ, דְּאִתְכַּפְיָא סִטְרָא אָחֳרָא מַמָּשׁ וְאִתְהַפֵּךְ חֲשׁוֹכָא לִנְהוֹרָא, שֶׁהוּא חֹשֶׁךְ הַקְּלִיפּוֹת שֶׁבָּעוֹלָם הַזֶּה הַחוּמְרִי הַמַּחֲשִׁיכִים וּמְכַסִּים עַל אוֹרוֹ יִתְבָּרֵךְ עַד עֵת קֵץ, כְּמוֹ שֶׁכָּתוּב: ״קֵץ שָׂם לַחֹשֶׁךְ״ [דְּהַיְינוּ, ״קֵץ הַיָּמִין״, שֶׁיַּעֲבִיר רוּחַ הַטּוּמְאָה מִן הָאָרֶץ, ״וְנִגְלָה כְּבוֹד ה׳, וְרָאוּ כָל בָּשָׂר יַחְדָּיו״, וּכְמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן]."],"Tanya, Part I; Likkutei Amarim 34:1":["וְהִנֵּה, מוּדַעַת זֹאת שֶׁ״הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה״, שֶׁכָּל יְמֵיהֶם לְעוֹלָם, לֹא הִפְסִיקוּ אֲפִילוּ שָׁעָה אַחַת מִלְּקַשֵּׁר דַּעְתָּם וְנִשְׁמָתָם לְרִבּוֹן הָעוֹלָמִים – בַּבִּיטּוּל הַנִּזְכָּר לְעֵיל לְיִחוּדוֹ יִתְבָּרֵךְ."],"Tanya, Part I; Likkutei Amarim 34:4":["וּמִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ – אֵין לְהַקָּדוֹשׁ־בָּרוּךְ־הוּא בְּעוֹלָמוֹ מִשְׁכָּן וּמָכוֹן לְשִׁבְתּוֹ, הוּא יִחוּדוֹ יִתְבָּרֵךְ, אֶלָּא אַרְבַּע אַמּוֹת שֶׁל הֲלָכָה, שֶׁהוּא רְצוֹנוֹ יִתְבָּרֵךְ וְחָכְמָתוֹ הַמְלוּבָּשִׁים בַּהֲלָכוֹת הָעֲרוּכוֹת לְפָנֵינוּ. וְלָכֵן, אַחַר שֶׁיַּעֲמִיק הָאָדָם מַחֲשַׁבְתּוֹ בְּעִנְיַן בִּיטּוּל הַנִּזְכָּר לְעֵיל כְּפִי יְכָלְתּוֹ, זֹאת יָשִׁיב אֶל לִבּוֹ: ״כִּי מִהְיוֹת קָטָן שִׂכְלִי וְשֹׁרֶשׁ נִשְׁמָתִי מֵהָכִיל, לִהְיוֹת מֶרְכָּבָה וּמִשְׁכָּן לְיִחוּדוֹ יִתְבָּרֵךְ בֶּאֱמֶת לַאֲמִיתּוֹ, מֵאַחַר דְּלֵית מַחֲשָׁבָה דִילִי תְּפִיסָא וּמַשֶּׂגֶת בּוֹ יִתְבָּרֵךְ כְּלָל וּכְלָל שׁוּם הַשָּׂגָה בָּעוֹלָם, וְלֹא שֶׁמֶץ מֶנְהוּ מֵהַשָּׂגַת הָאָבוֹת וְהַנְּבִיאִים, אֵי לָזֹאת, אֶעֱשֶׂה לוֹ מִשְׁכָּן וּמָכוֹן לְשִׁבְתּוֹ, הוּא הָעֵסֶק בְּתַלְמוּד תּוֹרָה כְּפִי הַפְּנַאי שֶׁלִּי, בִּקְבִיעוּת עִתִּים בַּיּוֹם וּבַלַּיְלָה, כְּדָת הַנִּיתְּנָה לְכָל אֶחָד וְאֶחָד בְּהִלְכוֹת תַּלְמוּד תּוֹרָה, וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ׳אֲפִילוּ פֶּרֶק אֶחָד שַׁחֲרִית כוּ׳׳״."],"Tanya, Part I; Likkutei Amarim 34:6":["וְאִם יַרְחִיב ה׳ לוֹ עוֹד, אֲזַי ״טְהוֹר יָדַיִם יוֹסִיף אוֹמֶץ״, וּ״מַחֲשָׁבָה טוֹבָה כוּ׳״, וְגַם שְׁאָר הַיּוֹם כּוּלּוֹ, שֶׁעוֹסֵק בְּמַשָּׂא וּמַתָּן, יִהְיֶה מָכוֹן לְשִׁבְתּוֹ יִתְבָּרֵךְ, בִּנְתִינַת הַצְּדָקָה שֶׁיִּתֵּן מִיגִיעוֹ, שֶׁהִיא מִמִּדּוֹתָיו שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא – ״מַה הוּא רַחוּם וְכוּ׳״, וּכְמוֹ שֶׁכָּתוּב בַּתִּיקּוּנִים: ״חֶסֶד דְּרוֹעָא יְמִינָא״."],"Tanya, Part I; Likkutei Amarim 35:1":["וְהִנֵּה, לְתוֹסֶפֶת בֵּיאוּר תֵּיבַת ״לַעֲשׂוֹתוֹ״, וְגַם לְהָבִין מְעַט מִזְּעֵיר תַּכְלִית בְּרִיאַת הַבֵּינוֹנִים וִירִידַת נִשְׁמוֹתֵיהֶם לָעוֹלָם הַזֶּה, לְהִתְלַבֵּשׁ בַּנֶּפֶשׁ הַבַּהֲמִית שֶׁמֵּהַקְּלִיפָּה וְסִטְרָא אָחֳרָא, מֵאַחַר שֶׁלֹּא יוּכְלוּ לְשַׁלְּחָהּ כָּל יְמֵיהֶם, וְלִדְחוֹתָהּ מִמְּקוֹמָהּ מֵחָלָל הַשְּׂמָאלִי שֶׁבַּלֵּב שֶׁלֹּא יַעֲלוּ מִמֶּנָּה הִרְהוּרִים אֶל הַמֹּחַ, כִּי מַהוּתָהּ וְעַצְמוּתָהּ שֶׁל נֶפֶשׁ הַבַּהֲמִית שֶׁמֵּהַקְּלִיפָּה – הִיא בְּתָקְפָּהּ וּבִגְבוּרָתָהּ אֶצְלָם כְּתוֹלַדְתָּהּ, רַק שֶׁלְּבוּשֶׁיהָ אֵינָם מִתְלַבְּשִׁים בְּגוּפָם כַּנִּזְכָּר לְעֵיל, וְאִם כֵּן, לָמָּה זֶּה יָרְדוּ נִשְׁמוֹתֵיהֶם לָעוֹלָם הַזֶּה לִיגַע לָרִיק חַס וְשָׁלוֹם, לְהִלָּחֵם כָּל יְמֵיהֶם עִם הַיֵּצֶר, וְלֹא יָכְלוּ לוֹ?"],"Tanya, Part I; Likkutei Amarim 35:11":["וְאַף שֶׁמַּהוּתָהּ וְעַצְמוּתָהּ שֶׁל נֶפֶשׁ הַבַּהֲמִית שֶׁבְּלִבּוֹ, שֶׁהֵן מִדּוֹתֶיהָ הָרָעוֹת, עֲדַיִין לֹא נִכְלְלוּ בִּקְדוּשָּׁה, מִכָּל מָקוֹם, מֵאַחַר דְּאִתְכַּפְיָן לִקְדוּשָּׁה, וּבְעַל כָּרְחָן עוֹנִין אָמֵן, וּמַסְכִּימִין וּמִתְרַצִּין לַעֲשִׂיַּית הַמִּצְוָה, עַל יְדֵי הִתְגַּבְּרוּת נַפְשׁוֹ הָאֱלֹהִית שֶׁבַּמּוֹחַ שֶׁשַּׁלִּיט עַל הַלֵּב, וְהֵן בְּשָׁעָה זוֹ בִּבְחִינַת גָּלוּת וְשֵׁינָה, כַּנִּזְכָּר לְעֵיל, וּלְכָךְ אֵין זוֹ מְנִיעָה מֵהַשְׁרָאַת הַשְּׁכִינָה עַל גּוּף הָאָדָם בְּשָׁעָה זוֹ."],"Tanya, Part I; Likkutei Amarim 35:3":["וְהוּא, בְּהַקְדִּים לְשׁוֹן הַיַּנּוּקָא [בַּזֹּהַר פָּרָשַׁת בָּלָק] עַל פָּסוּק: ״הֶחָכָם עֵינָיו בְּרֹאשׁוֹ״ – ״וְכִי בְּאָן אֲתַר עֵינוֹי דְּבַר נַשׁ כוּ׳, אֶלָּא קְרָא הָכֵי הוּא וַדַּאי, דִּתְנַן: לֹא יְהַךְ בַּר נַשׁ בְּגִילּוּיָא דְּרֵישָׁא אַרְבַּע אַמּוֹת, מַאי טַעֲמָא, דִּשְׁכִינְתָּא שַׁרְיָא עַל רֵישֵׁיהּ, וְכָל חָכָם עֵינוֹהִי וּמִילּוֹי בְּרֵישֵׁיהּ אִינּוּן, בְּהַהוּא דְּשַׁרְיָא וְקַיְּימָא עַל רֵישֵׁיהּ, וְכַד עֵינוֹי תַּמָּן, לִנְדַּע, דְּהַהוּא נְהוֹרָא דְּאַדְלִיק עַל רֵישֵׁיהּ – אִצְטְרִיךְ לְמִשְׁחָא, בְּגִין דְּגוּפָא דְבַר נַשׁ אִיהוּ פְּתִילָה, וּנְהוֹרָא אַדְלִיק לְעֵילָא, וּשְׁלֹמֹה מַלְכָּא צָוַח וְאָמַר: וְשֶׁמֶן עַל רֹאשְׁךָ אַל יֶחְסַר, דְּהָא נְהוֹרָא דִּבְרֹאשׁוֹ אִצְטְרִיךְ לְמִשְׁחָא, וְאִינּוּן עוֹבָדָאן טָבָאן, וְעַל דָּא הֶחָכָם עֵינָיו בְּרֹאשׁוֹ״, עַד כָּאן לְשׁוֹנוֹ."],"Tanya, Part I; Likkutei Amarim 35:4":["וְהִנֵּה, בֵּיאוּר מָשָׁל זֶה, שֶׁהִמְשִׁיל אוֹר הַשְּׁכִינָה לְאוֹר הַנֵּר שֶׁאֵינוֹ מֵאִיר וְנֶאֱחָז בַּפְּתִילָה בְּלִי שֶׁמֶן, וְכָךְ אֵין הַשְּׁכִינָה שׁוֹרָה עַל גּוּף הָאָדָם שֶׁנִּמְשָׁל לִפְתִילָה, אֶלָּא עַל יְדֵי מַעֲשִׂים טוֹבִים דַּוְוקָא, וְלֹא דַי לוֹ בְּנִשְׁמָתוֹ, שֶׁהִיא חֵלֶק אֱלוֹהַּ מִמַּעַל, לִהְיוֹת הִיא כְּשֶׁמֶן לַפְּתִילָה – מְבוֹאָר וּמוּבָן לְכָל מַשְׂכִּיל, כִּי הִנֵּה, נִשְׁמַת הָאָדָם, אֲפִילוּ הוּא צַדִּיק גָּמוּר עוֹבֵד ה׳ בְּיִרְאָה וְאַהֲבָה בְּתַּעֲנוּגִים, אַף־עַל־פִּי־כֵן, אֵינָהּ בְּטֵילָה בִּמְצִיאוּת לְגַמְרֵי לִיבָּטֵל וְלִיכָּלֵל בְּאוֹר ה׳ מַמָּשׁ, לִהְיוֹת לַאֲחָדִים וּמְיוּחָדִים בְּיִחוּד גָּמוּר, רַק הוּא דָּבָר בִּפְנֵי עַצְמוֹ – יְרֵא ה׳ וְאוֹהֲבוֹ; מַה שֶּׁאֵין כֵּן הַמִּצְוֹת וּמַעֲשִׂים טוֹבִים, שֶׁהֵן רְצוֹנוֹ יִתְבָּרֵךְ, וּרְצוֹנוֹ יִתְבָּרֵךְ הוּא מְקוֹר הַחַיִּים לְכָל הָעוֹלָמוֹת וְהַבְּרוּאִים, שֶׁיּוֹרֵד אֲלֵיהֶם עַל יְדֵי צִמְצוּמִים רַבִּים וְהֶסְתֵּר פָּנִים שֶׁל רָצוֹן הָעֶלְיוֹן בָּרוּךְ־הוּא וִירִידַת הַמַּדְרֵגוֹת, עַד שֶׁיּוּכְלוּ לְהִתְהַוּוֹת וּלְהִבָּרְאוֹת יֵשׁ מֵאַיִן וְדָבָר נִפְרָד בִּפְנֵי עַצְמוֹ, וְלֹא יִבָּטְלוּ בִּמְצִיאוּת כַּנִּזְכָּר לְעֵיל, מַה שֶּׁאֵין כֵּן הַמִּצְוֹת, שֶׁהֵן פְּנִימִית רְצוֹנוֹ יִתְבָּרֵךְ, וְאֵין שָׁם הֶסְתֵּר פָּנִים כְּלָל – אֵין הַחַיּוּת שֶׁבָּהֶם דָּבָר נִפְרָד בִּפְנֵי עַצְמוֹ כְּלָל, אֶלָּא הוּא מְיוּחָד וְנִכְלָל בִּרְצוֹנוֹ יִתְבָּרֵךְ, וְהָיוּ לַאֲחָדִים מַמָּשׁ בְּיִחוּד גָּמוּר."],"Tanya, Part I; Likkutei Amarim 35:5":["וְהִנֵּה, עִנְיַן הַשְׁרָאַת הַשְּׁכִינָה, הוּא גִּילּוּי אֱלֹהוּתוֹ יִתְבָּרֵךְ וְאוֹר אֵין־סוֹף בָּרוּךְ־הוּא בְּאֵיזֶה דָבָר, וְהַיְינוּ לוֹמַר, שֶׁאוֹתוֹ דָבָר נִכְלָל בְּאוֹר ה׳ וּבָטֵל לוֹ בִּמְצִיאוּת לְגַמְרֵי, שֶׁאָז הוּא שֶׁשּׁוֹרֶה וּמִתְגַּלֶּה בּוֹ ה׳ אֶחָד. אֲבָל כָּל מַה שֶּׁלֹּא בָטֵל אֵלָיו בִּמְצִיאוּת לְגַמְרֵי – אֵין אוֹר ה׳ שׁוֹרֶה וּמִתְגַּלֶּה בּוֹ. וְאַף צַדִּיק גָּמוּר שֶׁמִּתְדַּבֵּק בּוֹ בְּאַהֲבָה רַבָּה, הֲרֵי ״לֵית מַחֲשָׁבָה תְּפִיסָא בֵיהּ״ כְּלָל בֶּאֱמֶת, כִּי אֲמִיתַּת ״ה׳ אֱלֹהִים אֱמֶת״ – הוּא יִחוּדוֹ וְאַחְדוּתוֹ, שֶׁהוּא לְבַדּוֹ הוּא וְאֶפֶס בִּלְעָדוֹ מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 35:8":["וְהִנֵּה, כְּשֶׁהָאָדָם עוֹסֵק בַּתּוֹרָה, אֲזַי, נִשְׁמָתוֹ שֶׁהִיא נַפְשׁוֹ הָאֱלֹהִית, עִם שְׁנֵי לְבוּשֶׁיהָ הַפְּנִימִים לְבַדָּם, שֶׁהֵם, כֹּחַ הַדִּבּוּר וּמַחֲשָׁבָה, נִכְלָלוֹת בְּאוֹר ה׳ אֵין־סוֹף בָּרוּךְ־הוּא, וּמְיוּחָדוֹת בּוֹ בְּיִחוּד גָּמוּר. וְהִיא הַשְׁרָאַת הַשְּׁכִינָה עַל נַפְשׁוֹ הָאֱלֹהִית, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁאֲפִילוּ אֶחָד שֶׁיּוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה – שְׁכִינָה עִמּוֹ."],"Tanya, Part I; Likkutei Amarim 36:1":["וְהִנֵּה, מוּדַעַת זֹאת מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁתַּכְלִית בְּרִיאַת עוֹלָם הַזֶּה הוּא – שֶׁנִּתְאַוָּה הַקָּדוֹשׁ־בָּרוּךְ־הוּא לִהְיוֹת לוֹ דִּירָה בַּתַּחְתּוֹנִים."],"Tanya, Part I; Likkutei Amarim 36:11":["רַק שֶׁאַחַר כָּךְ גָּרַם הַחֵטְא וְנִתְגַּשְּׁמוּ הֵם וְהָעוֹלָם, עַד עֵת קֵץ הַיָּמִין, שֶׁאָז יִזְדַּכֵּךְ גַּשְׁמִיּוּת הַגּוּף וְהָעוֹלָם, וְיוּכְלוּ לְקַבֵּל גִּילּוּי אוֹר ה׳, שֶׁיָּאִיר לְיִשְׂרָאֵל עַל יְדֵי הַתּוֹרָה שֶׁנִּקְרֵאת ״עוֹז״. וּמִיִּתְרוֹן הַהֶאָרָה לְיִשְׂרָאֵל – יַגִּיהַּ חשֶׁךְ הָאוּמּוֹת גַּם כֵּן, כְּדִכְתִיב: ״וְהָלְכוּ גוֹיִם לְאוֹרֵךְ וְגוֹ׳״, וּכְתִיב: ״בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר ה׳״, וּכְתִיב: ״וְנִגְלָה כְּבוֹד ה׳, וְרָאוּ כָל בָּשָׂר יַחְדָּיו וְגוֹ׳״, וּכְתִיב: ״לָבוֹא בְּנִקְרֹת הַצּוּרִים וּבִסְעִיפֵי הַסְּלָעִים מִפְּנֵי פַּחַד ה׳ וַהֲדַר גְּאוֹנוֹ וְגוֹ׳״, וּכְמוֹ שֶׁאוֹמְרִים: ״וְהוֹפַע בַּהֲדַר גְּאוֹן עוּזֶּךָ עַל כָּל יוֹשְׁבֵי תֵבֵל אַרְצֶךָ וְגוֹ׳״:"],"Tanya, Part I; Likkutei Amarim 36:5":["וְהִנֵּה, תַּכְלִית הִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת וִירִידָתָם מִמַּדְרֵגָה לְמַדְרֵגָה – אֵינוֹ בִּשְׁבִיל עוֹלָמוֹת הָעֶלְיוֹנִים, הוֹאִיל וְלָהֶם יְרִידָה מֵאוֹר פָּנָיו יִתְבָּרֵךְ, אֶלָּא הַתַּכְלִית הוּא עוֹלָם הַזֶּה הַתַּחְתּוֹן, שֶׁכָּךְ עָלָה בִּרְצוֹנוֹ יִתְבָּרֵךְ, לִהְיוֹת נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ, כַּד אִתְכַּפְיָא סִטְרָא אָחֳרָא וְאִתְהַפֵּךְ חֲשׁוֹכָא לִנְהוֹרָא – שֶׁיָּאִיר אוֹר ה׳ אֵין־סוֹף בָּרוּךְ־הוּא בִּמְקוֹם הַחֹשֶׁךְ וְהַסִּטְרָא אָחֳרָא שֶׁל כָּל עוֹלָם הַזֶּה כּוּלּוֹ, בְּיֶתֶר שְׂאֵת וְיֶתֶר עֹז וְיִתְרוֹן אוֹר מִן הַחֹשֶׁךְ, מֵהֶאָרָתוֹ בְּעוֹלָמוֹת עֶלְיוֹנִים, שֶׁמֵּאִיר שָׁם עַל יְדֵי לְבוּשִׁים וְהֶסְתֵּר פָּנִים, הַמַּסְתִּירִים וּמַעֲלִימִים אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא שֶׁלֹּא יִבָּטְלוּ בִּמְצִיאוּת."],"Tanya, Part I; Likkutei Amarim 36:6":["וְלָזֶה נָתַן הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְיִשְׂרָאֵל אֶת הַתּוֹרָה, שֶׁנִּקְרֵאת עוֹז וְכֹחַ, וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא נוֹתֵן כֹּחַ בַּצַּדִּיקִים לְקַבֵּל שְׂכָרָם לֶעָתִיד לָבֹא, שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּת מַמָּשׁ בְּאוֹר ה׳ הַנִּגְלֶה לֶעָתִיד בְּלִי שׁוּם לְבוּשׁ, כְּדִכְתִיב: ״וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ [פֵּירוּשׁ, שֶׁלֹּא יִתְכַּסֶּה מִמְּךָ בְּכָנָף וּלְבוּשׁ], וְהָיוּ עֵינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ״, וּכְתִיב: ״כִּי עַיִן בְּעַיִן יִרְאוּ וְגוֹ׳״, וּכְתִיב: ״לֹא יִהְיֶה לָּךְ עוֹד הַשֶּׁמֶשׁ לְאוֹר יוֹמָם וְגוֹ׳, כִּי ה׳ יִהְיֶה לָּךְ לְאוֹר עוֹלָם וְגוֹ׳״."],"Tanya, Part I; Likkutei Amarim 36:9":["וְגַם כְּבָר הָיָה לְעוֹלָמִים מֵעֵין זֶה, בִּשְׁעַת מַתַּן תּוֹרָה, כְּדִכְתִיב: ״אַתָּה הָרְאֵתָ לָדַעַת כִּי ה׳ הוּא הָאֱלֹהִים אֵין עוֹד מִלְּבַדּוֹ״ – ״הָרְאֵתָ״ מַמָּשׁ, בִּרְאִיָּה חוּשִׁיִּית, כְּדִכְתִיב: ״וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת״ – ״רוֹאִים אֶת הַנִּשְׁמָע״, וּפֵירְשׁוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: מִסְתַּכְּלִים לַמִּזְרָח וְשׁוֹמְעִין אֶת הַדִּבּוּר יוֹצֵא אָנֹכִי כוּ׳. וְכֵן לְאַרְבַּע רוּחוֹת וּלְמַעְלָה וּלְמַטָּה, וְכִדְפֵירְשׁוּ בַּתִּיקּוּנִים ״דְּלֵית אֲתַר דְּלָא מַלֵּיל מִינֵּיהּ עִמְּהוֹן כוּ׳״."],"Tanya, Part I; Likkutei Amarim 37:1":["וְהִנֵּה, תַּכְלִית הַשְּׁלֵימוּת הַזֶּה שֶׁל יְמוֹת הַמָּשִׁיחַ וּתְחִיַּית הַמֵּתִים, שֶׁהוּא גִּילּוּי אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא בָּעוֹלָם הַזֶּה הַגַּשְׁמִי – תָּלוּי בְּמַעֲשֵׂינוּ וַעֲבוֹדָתֵנוּ כָּל זְמַן מֶשֶׁךְ הַגָּלוּת."],"Tanya, Part I; Likkutei Amarim 37:10":["וְעַל יְדֵי זֶה, תַּעֲלֶה גַם כֵּן כְּלָלוּת קְלִיפַּת נוֹגַהּ, שֶׁהִיא כְּלָלוּת הַחַיּוּת שֶׁל עוֹלָם הַזֶּה הַגַּשְׁמִי וְהַחוּמְרִי, כַּאֲשֶׁר כָּל הַנְּשָׁמָה וְנֶפֶשׁ הָאֱלֹהִית שֶׁבְּכָל יִשְׂרָאֵל, הַמִּתְחַלֶּקֶת בִּפְרָטוּת לְשִׁשִּׁים רִבּוֹא, תְּקַיֵּים כָּל נֶפֶשׁ פְּרָטִית כָּל תַּרְיַ״ג מִצְוֹת הַתּוֹרָה:"],"Tanya, Part I; Likkutei Amarim 37:12":["וּמֵאַחַר שֶׁכְּלָלוּת נֶפֶשׁ הַחִיּוּנִית שֶׁבִּכְלָלוּת יִשְׂרָאֵל תִּהְיֶה מֶרְכָּבָה קְדוֹשָׁה לַה׳ – אֲזַי גַּם כְּלָלוּת הַחַיּוּת שֶׁל עוֹלָם הַזֶּה, שֶׁהִיא קְלִיפַּת נוֹגַהּ עַכְשָׁיו, תֵּצֵא אָז מִטּוּמְאָתָהּ וְחֶלְאָתָהּ, וְתַעֲלֶה לִקְדוּשָּׁה לִהְיוֹת מֶרְכָּבָה לַה׳, בְּהִתְגַּלּוּת כְּבוֹדוֹ, ״וְרָאוּ כָל בָּשָׂר יַחְדָּיו״, וְיוֹפִיעַ עֲלֵיהֶם בַּהֲדַר גְּאוֹן עוּזּוֹ, ״וְיִמָּלֵא כְבוֹד ה׳ אֶת כָּל הָאָרֶץ״, וְיִשְׂרָאֵל יִרְאוּ עַיִן בְּעַיִן כִּבְמַתַּן תּוֹרָה, דִּכְתִיב: ״אַתָּה הָרְאֵתָ לָדַעַת כִּי ה׳ הוּא הָאֱלֹהִים אֵין עוֹד מִלְּבַדּוֹ״."],"Tanya, Part I; Likkutei Amarim 37:14":["וְנִמְצָא, כִּי כָּל תַּכְלִית שֶׁל יְמוֹת הַמָּשִׁיחַ וּתְחִיַּית הַמֵּתִים – שֶׁהוּא גִילּוּי כְּבוֹדוֹ וֵאלֹהוּתוֹ יִתְבָּרֵךְ, וּלְהַעֲבִיר רוּחַ הַטּוּמְאָה מִן הָאָרֶץ – תָּלוּי בְּהַמְשָׁכַת אֱלֹהוּתוֹ וְאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא לַנֶּפֶשׁ הַחִיּוּנִית שֶׁבִּכְלָלוּת יִשְׂרָאֵל בְּכָל רַמַ״ח אֵבָרֶיהָ, עַל יְדֵי קִיּוּמָהּ כָּל רַמַ״ח מִצְוֹת עֲשֵׂה, וּלְהַעֲבִיר רוּחַ הַטּוּמְאָה מִמֶּנָּה, בִּשְׁמִירָתָהּ כָּל שַׁסַ״ה מִצְוֹת לֹא תַעֲשֶׂה, שֶׁלֹּא יִינְקוּ מִמֶּנָּה שַׁסַ״ה גִידֶיהָ."],"Tanya, Part I; Likkutei Amarim 37:15":["כִּי כְּלָלוּת יִשְׂרָאֵל, שֶׁהֵם שִׁשִּׁים רִבּוֹא נְשָׁמוֹת פְּרָטִיּוֹת, הֵם כְּלָלוּת הַחַיּוּת שֶׁל כְּלָלוּת הָעוֹלָם, כִּי בִּשְׁבִילָם נִבְרָא, וְכָל פְּרָט מֵהֶם הוּא כּוֹלֵל וְשַׁיָּיךְ לוֹ הַחַיּוּת שֶׁל חֵלֶק אֶחָד מִשִּׁשִּׁים רִבּוֹא מִכְּלָלוּת הָעוֹלָם הַתָּלוּי בְּנַפְשׁוֹ הַחִיּוּנִית, לְהַעֲלוֹתוֹ לַה׳ בַּעֲלִיָּיתָהּ, דְּהַיְינוּ, בְּמַה שֶּׁמִּשְׁתַּמֵּשׁ מֵעוֹלָם הַזֶּה לְצוֹרֶךְ גּוּפוֹ וְנַפְשׁוֹ הַחִיּוּנִית לַעֲבוֹדַת ה׳, כְּגוֹן, אֲכִילָה וּשְׁתִיָּה וְדוֹמֵיהֶם, וְדִירָה וְכָל כְּלֵי תַּשְׁמִישָׁיו."],"Tanya, Part I; Likkutei Amarim 37:17":["וְכָל נִיצוֹץ, לֹא יָרַד לָעוֹלָם הַזֶּה, אַף שֶׁהִיא יְרִידָה גְדוֹלָה וּבְחִינַת גָּלוּת מַמָּשׁ, כִּי גַם שֶׁיִּהְיֶה צַדִּיק גָּמוּר עוֹבֵד ה׳ בְּיִרְאָה וְאַהֲבָה רַבָּה בְּתַעֲנוּגִים לֹא יַגִּיעַ לְמַעֲלוֹת דְּבֵיקוּתוֹ בַּה׳ בִּדְחִילוּ וּרְחִימוּ בְּטֶרֶם יְרִידָתוֹ לָעוֹלָם הַזֶּה הַחוּמְרִי, לֹא מִינָּהּ וְלֹא מִקְצָתָהּ, וְאֵין עֵרֶךְ וְדִמְיוֹן בֵּינֵיהֶם כְּלָל, כַּנּוֹדָע לְכָל מַשְׂכִּיל, שֶׁהַגּוּף אֵינוֹ יָכוֹל לִסְבּוֹל כוּ׳, אֶלָּא יְרִידָתוֹ לָעוֹלָם הַזֶּה לְהִתְלַבֵּשׁ בַּגּוּף וְנֶפֶשׁ הַחִיּוּנִית, הוּא כְּדֵי לְתַקְּנָם בִּלְבָד, וּלְהַפְרִידָם מֵהָרָע שֶׁל שָׁלשׁ קְלִיפּוֹת הַטְּמֵאוֹת, עַל יְדֵי שְׁמִירַת שַׁסַ״ה לֹא תַעֲשֶׂה וְעַנְפֵיהֶן, וּלְהַעֲלוֹת נַפְשׁוֹ הַחִיּוּנִית עִם חֶלְקָהּ הַשַּׁיָּיךְ לָהּ מִכְּלָלוּת עוֹלָם הַזֶּה, וּלְקַשְּׁרָם וּלְיַיחֲדָם בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, אֲשֶׁר יַמְשִׁיךְ בָּהֶם עַל יְדֵי קִיּוּמוֹ כָּל רַמַ״ח מִצְוֹת עֲשֵׂה בְּנַפְשׁוֹ הַחִיּוּנִית, שֶׁהִיא הִיא הַמְקַיֶּימֶת כָּל מִצְוֹת מַעֲשִׂיּוֹת כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 37:19":["וּבָזֶה יוּבַן מַה שֶּׁהִפְלִיגוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה בִּמְאֹד מְאֹד בְּמַעֲלַת הַצְּדָקָה, וְאָמְרוּ שֶׁ״שְּׁקוּלָה כְּנֶגֶד כָּל הַמִצְוֹת״, וּבְכָל תַּלְמוּד יְרוּשַׁלְמִי הִיא נִקְרֵאת בְּשֵׁם ״מִצְוָה״ סְתָם, כִּי כָּךְ הָיָה הֶרְגֵּל הַלָּשׁוֹן לִקְרוֹא צְדָקָה בְּשֵׁם ״מִצְוָה״ סְתָם, מִפְּנֵי שֶׁהִיא עִיקַּר הַמִּצְוֹת מַעֲשִׂיּוֹת, וְעוֹלָה עַל כּוּלָּנָה, שֶׁכּוּלָּן הֵן רַק לְהַעֲלוֹת נֶפֶשׁ הַחִיּוּנִית לַה׳, שֶׁהִיא הִיא הַמְקַיֶּימֶת אוֹתָן, וּמִתְלַבֶּשֶׁת בָּהֶן לִיכָּלֵל בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא הַמְלוּבָּשׁ בָּהֶן, וְאֵין לְךָ מִצְוָה שֶׁנֶּפֶשׁ הַחִיּוּנִית מִתְלַבֶּשֶׁת בָּהּ כָּל כָּךְ כִּבְמִצְוַת הַצְּדָקָה, שֶׁבְּכָל הַמִּצְוֹת אֵין מִתְלַבֵּשׁ בָּהֶן רַק כֹּחַ אֶחָד מִנֶּפֶשׁ הַחִיּוּנִית בִּשְׁעַת מַעֲשֵׂה הַמִּצְוָה לְבַד, אֲבָל בִּצְדָקָה, שֶׁאָדָם נוֹתֵן מִיגִיעַ כַּפָּיו, הֲרֵי כָּל כֹּחַ נַפְשׁוֹ הַחִיּוּנִית מְלוּבָּשׁ בַּעֲשִׂיַּית מְלַאכְתּוֹ אוֹ עֵסֶק אַחֵר שֶׁנִּשְׂתַּכֵּר בּוֹ מָעוֹת אֵלּוּ, וּכְשֶׁנּוֹתְנָן לִצְדָקָה – הֲרֵי כָּל נַפְשׁוֹ הַחִיּוּנִית עוֹלָה לַה׳."],"Tanya, Part I; Likkutei Amarim 37:22":["וּמַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁ״תַּלְמוּד תּוֹרָה כְּנֶגֶד כּוּלָּם״, הַיְינוּ, מִפְּנֵי שֶׁתַּלְמוּד תּוֹרָה הִיא בְּדִבּוּר וּמַחֲשָׁבָה, שֶׁהֵם לְבוּשִׁים הַפְּנִימִים שֶׁל נֶפֶשׁ הַחִיּוּנִית. וְגַם מַהוּתָן וְעַצְמוּתָן שֶׁל בְּחִינוֹת חָכְמָה־בִּינָה־דַּעַת מִקְּלִיפַּת נוֹגַהּ שֶׁבַּנֶּפֶשׁ הַחִיּוּנִית – נִכְלָלוֹת בִּקְדוּשָּׁה מַמָּשׁ כְּשֶׁעוֹסֵק בַּתּוֹרָה בְּעִיּוּן וְשֵׂכֶל."],"Tanya, Part I; Likkutei Amarim 37:26":["וְאַף־עַל־פִּי־כֵן, אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״לֹא הַמִּדְרָשׁ עִיקָּר אֶלָּא הַמַּעֲשֶׂה״, וְ״הַיּוֹם לַעֲשׂוֹתָם״ כְּתִיב, וּמְבַטְּלִין תַּלְמוּד תּוֹרָה לְקִיּוּם מִצְוָה מַעֲשִׂיית כְּשֶׁאִי אֶפְשָׁר לַעֲשׂוֹתָהּ עַל יְדֵי אֲחֵרִים, מִשּׁוּם, ״כִּי זֶה כָּל הָאָדָם״ וְתַכְלִית בְּרִיאָתוֹ וִירִידָתוֹ לָעוֹלָם הַזֶּה, לִהְיוֹת לוֹ יִתְבָּרֵךְ דִּירָה בַּתַּחְתּוֹנִים דַּוְקָא, לְאַהֲפָכָא חֲשׁוֹכָא לִנְהוֹרָא, ״וְיִמָּלֵא כְבוֹד ה׳ אֶת כָּל הָאָרֶץ״ הַגַּשְׁמִית דַּיְיקָא, ״וְרָאוּ כָל בָּשָׂר יַחְדָּיו״, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 37:28":["וְהִנֵּה, הַמְשָׁכָה וְהֶאָרָה זוֹ שֶׁהָאָדָם מַמְשִׁיךְ וּמֵאִיר מֵהֶאָרַת אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא עַל נַפְשׁוֹ, וְעַל נַפְשׁוֹת כָּל יִשְׂרָאֵל, הִיא הַשְּׁכִינָה, כְּנֶסֶת יִשְׂרָאֵל, מְקוֹר כָּל נִשְׁמוֹת יִשְׂרָאֵל כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן, עַל יְדֵי עֵסֶק הַתּוֹרָה – נִקְרֵאת בִּלְשׁוֹן ״קְרִיאָה״ – ״קוֹרֵא בַּתּוֹרָה״, פֵּירוּשׁ, שֶׁעַל יְדֵי עֵסֶק הַתּוֹרָה קוֹרֵא לְהַקָּדוֹשׁ־בָּרוּךְ־הוּא לָבוֹא אֵלָיו, כִּבְיָכוֹל, כְּאָדָם הַקּוֹרֵא לַחֲבֵירוֹ שֶׁיָּבֹא אֵלָיו, וּכְבֵן קָטָן הַקּוֹרֵא לְאָבִיו לָבֹא אֵלָיו לִהְיוֹת עִמּוֹ בְּצַוְותָּא חֲדָא, וְלֹא לִיפָּרֵד מִמֶּנּוּ וְלִישָּׁאֵר יְחִידִי חַס וְשָׁלוֹם."],"Tanya, Part I; Likkutei Amarim 37:4":["וּמָעוֹת הַצְּדָקָה שֶׁאֵינָן גֶּזֶל, וְכַיּוֹצֵא בָהֶם."],"Tanya, Part I; Likkutei Amarim 37:9":["זֹאת וְעוֹד אַחֶרֶת, שֶׁכֹּחַ נֶפֶשׁ הַחִיּוּנִית הַמִּתְלַבֶּשֶׁת בְּאוֹתִיּוֹת הַדִּבּוּר בְּתַלְמוּד תּוֹרָה אוֹ תְּפִלָּה וְכַיּוֹצֵא בָהֶן, אוֹ מִצְוֹת מַעֲשִׂיּוֹת – הֲרֵי כָּל גִּידּוּלוֹ וְחַיּוּתוֹ מֵהַדָּם, שֶׁהוּא מִקְּלִיפַּת נוֹגַהּ מַמָּשׁ, שֶׁהֵן כָּל אוֹכָלִין וּמַשְׁקִין שֶׁאָכַל וְשָׁתָה וְנַעֲשׂוּ דָם, שֶׁהָיוּ תַּחַת מֶמְשַׁלְתָּהּ וְיָנְקוּ חַיּוּתָם מִמֶּנָּה, וְעַתָּה הִיא מִתְהַפֶּכֶת מֵרָע לְטוֹב וְנִכְלֶלֶת בִּקְדוּשָּׁה, עַל יְדֵי כֹּחַ נֶפֶשׁ הַחִיּוּנִית הַגָּדֵל מִמֶּנָּה, שֶׁנִּתְלַבֵּשׁ בְּאוֹתִיּוֹת אֵלּוּ אוֹ בַּעֲשִׂיָּה זוֹ, אֲשֶׁר הֵן הֵן פְּנִימִיּוּת רְצוֹנוֹ יִתְבָּרֵךְ בְּלִי שׁוּם הֶסְתֵּר פָּנִים, וְחַיּוּתָן נִכְלָל גַּם כֵּן בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא שֶׁהוּא רְצוֹנוֹ יִתְבָּרֵךְ, וּבְחַיּוּתָן נִכְלָל וְעוֹלֶה גַם כֵּן כֹּחַ נֶפֶשׁ הַחִיּוּנִית."],"Tanya, Part I; Likkutei Amarim 38:1":["וְהִנֵּה, עִם כָּל הַנִּכְתָּב לְעֵיל, יוּבַן הֵיטֵב פְּסַק הַהֲלָכָה הָעֲרוּכָה בַּתַּלְמוּד וּפוֹסְקִים דְּ״הִרְהוּר לָאו כְּדִבּוּר דָּמֵי״, וְאִם קָרָא קְרִיאַת שְׁמַע בְּמַחֲשַׁבְתּוֹ וּבְלִבּוֹ לְבַד, בְּכָל כֹּחַ כַּוָּונָתוֹ – לֹא יָצָא יְדֵי חוֹבָתוֹ וְצָרִיךְ לַחֲזוֹר וְלִקְרוֹת, וְכֵן בְּבִרְכַּת הַמָּזוֹן דְּאוֹרַיְיתָא, וּבִשְׁאָר בְּרָכוֹת דְּרַבָּנָן, וּבִתְפִלָּה; וְאִם הוֹצִיא בִּשְׂפָתָיו וְלֹא כִּיוֵּן לִבּוֹ – יָצָא יְדֵי חוֹבָתוֹ בְּדִיעֲבַד, וְאֵין צָרִיךְ לַחֲזוֹר, לְבַד מִפָּסוּק רִאשׁוֹן שֶׁל קְרִיאַת שְׁמַע וּבְרָכָה רִאשׁוֹנָה שֶׁל תְּפִלַּת שְׁמוֹנֶה עֶשְׂרֵה, וְכִדְאִיתָא [בְּרֵישׁ פֶּרֶק ב׳ דִּבְרָכוֹת]: ״עַד כָּאן מִצְוַת כַּוָּונָה, מִכָּאן וְאֵילַךְ מִצְוַת קְרִיאָה וְכוּ׳״."],"Tanya, Part I; Likkutei Amarim 38:10":["וְלֹא שֶׁדְּבֵיקוּת הַמַּחֲשָׁבָה וְשֵׂכֶל הָאָדָם בּוֹ יִתְבָּרֵךְ, הִיא מִצַּד עַצְמָהּ לְמַעְלָה מִדְּבֵיקוּת קִיּוּם הַמִּצְוֹת מַעֲשִׂיּוֹת בְּפוֹעַל מַמָּשׁ, כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן, אֶלָּא, מִפְּנֵי שֶׁזֶּהוּ גַם כֵּן רְצוֹנוֹ יִתְבָּרֵךְ – לְדָבְקָה בְּשֵׂכֶל וּמַחֲשָׁבָה וְכַוָּונַת הַמִּצְוֹת מַעֲשִׂיּוֹת וּבְכַוָּונַת קְרִיאַת שְׁמַע וּתְפִלָּה וּשְׁאָר בְּרָכוֹת, וְהֶאָרַת רָצוֹן הָעֶלְיוֹן הַזֶּה, הַמְּאִירָה וּמְלוּבֶּשֶׁת בְּכַוָּונָה זוֹ, הִיא גְדוֹלָה לְאֵין קֵץ, לְמַעְלָה מַּעְלָה מֵהֶאָרַת רָצוֹן הָעֶלְיוֹן הַמְּאִירָה וּמְלוּבֶּשֶׁת בְּקִיּוּם הַמִּצְוֹת עַצְמָן בְּמַעֲשֶׂה וּבְדִבּוּר בְּלִי כַוָּונָה – כְּגוֹדֶל מַעֲלַת אוֹר הַנְּשָׁמָה עַל הַגּוּף, שֶׁהוּא כְּלִי וּמַלְבּוּשׁ הַנְּשָׁמָה, כְּמוֹ גּוּף הַמִּצְוָה עַצְמָהּ שֶׁהוּא כְּלִי וּמַלְבּוּשׁ לְכַוָּונָתָהּ."],"Tanya, Part I; Likkutei Amarim 38:14":["כִּי, מִי שֶׁדַּעְתּוֹ יָפָה לָדַעַת אֶת ה׳ וּלְהִתְבּוֹנֵן בִּגְדוּלָּתוֹ יִתְבָּרֵךְ, וּלְהוֹלִיד מִבִּינָתוֹ יִרְאָה עִילָּאָה בְּמוֹחוֹ וְאַהֲבַת ה׳ בֶּחָלָל הַיְמָנִי שֶׁבְּלִבּוֹ, לִהְיוֹת נַפְשׁוֹ צְמֵאָה לַה׳, לְדָבְקָה בוֹ עַל יְדֵי קִיּוּם הַתּוֹרָה וְהַמִּצְוֹת, שֶׁהֵן הַמְשָׁכַת וְהֶאָרַת אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא עַל נַפְשׁוֹ – לְדָבְקָה בוֹ, וּבְכַוָּונָה זוֹ – הוּא לוֹמֵד וּמְקַיֵּים הַמִּצְוֹת, וְכֵן בְּכַוָּונָה זוֹ – מִתְפַּלֵּל וּמְבָרֵךְ, הֲרֵי כַּוָּונָה זוֹ, עַל דֶּרֶךְ מָשָׁל, כְּמוֹ נִשְׁמַת הַמְדַבֵּר, שֶׁהוּא בַּעַל שֵׂכֶל וּבְחִירָה וּבְדַעַת יְדַבֵּר."],"Tanya, Part I; Likkutei Amarim 38:3":["אַךְ אַף־עַל־פִּי־כֵן, אָמְרוּ: תְּפִלָּה אוֹ שְׁאָר בְּרָכָה בְּלֹא כַוָּונָה – הֵן כְּגוּף בְּלֹא נְשָׁמָה, פֵּירוּשׁ, כִּי כְּמוֹ שֶׁכָּל הַבְּרוּאִים שֶׁבָּעוֹלָם הַזֶּה שֶׁיֵּשׁ לָהֶם גּוּף וּנְשָׁמָה, שֶׁהֵם: ״נֶפֶשׁ כָּל חַי וְרוּחַ כָּל בְּשַׂר אִישׁ״, וְ״נִשְׁמַת כָּל אֲשֶׁר רוּחַ חַיִּים בְּאַפָּיו״ מִכָּל בַּעֲלֵי חַיִּים, וַה׳ ״מְחַיֶּה אֶת כּוּלָּם״ וּמְהַוֶּה אוֹתָם מֵאַיִן לְיֵשׁ תָּמִיד בְּאוֹר וְחַיּוּת שֶׁמַּשְׁפִּיעַ בָּהֶם, שֶׁגַּם הַגּוּף הַחוּמְרִי, וַאֲפִילוּ אֲבָנִים וְעָפָר הַדּוֹמֵם מַמָּשׁ – יֵשׁ בּוֹ אוֹר וְחַיּוּת מִמֶּנּוּ יִתְבָּרֵךְ, שֶׁלֹּא יַחֲזוֹר לִהְיוֹת אַיִן וָאֶפֶס כְּשֶׁהָיָה, וְאַף־עַל־פִּי־כֵן, אֵין עֵרֶךְ וְדִמְיוֹן כְּלָל בֵּין בְּחִינַת אוֹר וְחַיּוּת הַמֵּאִיר בַּגּוּף, לְגַבֵּי בְּחִינַת אוֹר וְחַיּוּת הַמֵּאִיר בַּנְּשָׁמָה, שֶׁהִיא נֶפֶשׁ כָּל חַי."],"Tanya, Part I; Likkutei Amarim 38:4":["וְאַף שֶׁבִּשְׁנֵיהֶם אוֹר אֶחָד שָׁוֶה, בִּבְחִינַת הֶסְתֵּר פָּנִים וּלְבוּשִׁים שָׁוִים שֶׁהָאוֹר מִסְתַּתֵּר וּמִתְעַלֵּם וּמִתְלַבֵּשׁ בּוֹ, כִּי שְׁנֵיהֶם הֵם מֵעוֹלָם הַזֶּה, שֶׁבִּכְלָלוּתוֹ מִסְתַּתֵּר בְּשָׁוֶה הָאוֹר וְהַחַיּוּת שֶׁמֵּרוּחַ פִּיו יִתְבָּרַךְ, בִּבְחִינַת הֶסְתֵּר פָּנִים וִירִידַת הַמַּדְרֵגוֹת בְּהִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת מִמַּדְרֵגָה לְמַדְרֵגָה בְּצִמְצוּמִים רַבִּים וַעֲצוּמִים, עַד שֶׁנִּתְלַבֵּשׁ בִּקְלִיפַּת נוֹגַהּ לְהַחֲיוֹת כְּלָלוּת עוֹלָם הַזֶּה הַחוּמְרִי, דְּהַיְינוּ, כָּל דְּבָרִים הַמּוּתָּרִים וְהַטְּהוֹרִים שֶׁבָּעוֹלָם הַזֶּה, וּמִמֶּנָּה וְעַל יָדָהּ מוּשְׁפָּעִים דְּבָרִים הַטְּמֵאִים, כִּי הִיא בְּחִינָה מְמוּצַּעַת כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 38:6":["כִּי בַּגּוּף הַגַּשְׁמִי, וְהַדּוֹמֵם מַמָּשׁ כַּאֲבָנִים וְעָפָר – הַהֶאָרָה הִיא בִּבְחִינַת צִמְצוּם גָּדוֹל אֲשֶׁר אֵין כָּמוֹהוּ, וְהַחַיּוּת שֶׁבּוֹ מוּעֶטֶת כָּל כָּךְ, עַד שֶׁאֵין בּוֹ אֲפִילוּ כֹּחַ הַצּוֹמֵחַ, וּבַצּוֹמֵחַ – הַהֶאָרָה אֵינָהּ בְּצִמְצוּם גָּדוֹל כָּל כָּךְ."],"Tanya, Part I; Likkutei Amarim 39:1":["וּמִפְּנֵי זֶה גַם כֵּן, נִקְרָאִים הַמַּלְאָכִים בְּשֵׁם חַיּוֹת וּבְהֵמוֹת, כְּדִכְתִיב: ״וּפְנֵי אַרְיֵה אֶל הַיָּמִין וְגוֹ׳ וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל וְגוֹ׳״, לְפִי שֶׁאֵינָם בַּעֲלֵי בְחִירָה, וְיִרְאָתָם וְאַהֲבָתָם הִיא טִבְעִית לָהֶם, כְּמוֹ שֶׁכָּתוּב בְּ״רַעְיָא מְהֵימְנָא״ פָּרָשַׁת פִּנְחָס. וְלָכֵן מַעֲלַת הַצַּדִּיקִים גְּדוֹלָה מֵהֶם, כִּי, מְדוֹר נִשְׁמוֹת הַצַּדִּיקִים – הוּא בְּעוֹלַם הַבְּרִיאָה, וּמְדוֹר הַמַּלְאָכִים – בְּעוֹלַם הַיְצִירָה."],"Tanya, Part I; Likkutei Amarim 39:10":["וְעוֹלַם הָאֲצִילוּת שֶׁהוּא לְמַעְלָה מֵהַשֵּׂכֶל וְהַהַשָּׂגָה וְהַהֲבָנָה לְשֵׂכֶל נִבְרָא, כִּי חָכְמָתוֹ וּבִינָתוֹ וְדַעְתּוֹ שֶׁל אֵין־סוֹף בָּרוּךְ־הוּא מְיוּחָדוֹת שָׁם בּוֹ בְּתַכְלִית הַיִּחוּד, בְּיִחוּד עָצוּם וְנִפְלָא, בְּיֶתֶר שְׂאֵת וְיֶתֶר עֹז לְאֵין קֵץ מִבְּעוֹלַם הַבְּרִיאָה, כִּי שָׁם יָרְדוּ לְהָאִיר בִּבְחִינַת צִמְצוּם, כְּדֵי שֶׁיּוּכְלוּ שְׂכָלִים נִבְרָאִים לְקַבֵּל מֵהֶן חָכְמָה־בִּינָה־דַּעַת, לֵידַע אֶת ה׳, וּלְהָבִין וּלְהַשִּׂיג אֵיזוֹ הַשָּׂגָה בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, כְּפִי כֹּחַ שְׂכָלִים הַנִּבְרָאִים, שֶׁהֵם בַּעֲלֵי גְבוּל וְתַכְלִית, שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּתָם, וְלֹא יִהְיוּ בְּגֶדֶר נִבְרָאִים כְּלָל, רַק יַחְזְרוּ לִמְקוֹרָם וְשָׁרְשָׁם שֶׁהוּא בְּחִינַת אֱלֹהוּת מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 39:11":["וְהִנֵּה, צִמְצוּם זֶה, הִיא סִבַּת הַהֶאָרָה שֶׁמְּאִירוֹת שָׁם חָכְמָה־בִּינָה־דַּעַת שֶׁל אֵין־סוֹף בָּרוּךְ־הוּא לִנְשָׁמוֹת אֵלּוּ בְּעוֹלַם הַבְּרִיאָה."],"Tanya, Part I; Likkutei Amarim 39:14":["אַךְ מִי שֶׁשֹּׁרֶשׁ נִשְׁמָתוֹ קָטָן מֵהָכִיל עֲבוֹדָה תַמָּה זוֹ, לִיבָּטֵל וְלִיכָּלֵל בְּאוֹרוֹ יִתְבָּרֵךְ בַּעֲבוֹדָתוֹ בִּקְבִיעוּת, רַק לִפְרָקִים וְעִתִּים שֶׁהֵם עֵת רָצוֹן לְמַעְלָה, וּכְמוֹ בִּתְפִלַּת שְׁמוֹנֶה עֶשְׂרֵה שֶׁהִיא בַּאֲצִילוּת, וּבִפְרָט בְּהִשְׁתַּחֲוָואוֹת שֶׁבָּהּ, שֶׁכָּל הִשְׁתַּחֲוָואָה הִיא בִּבְחִינַת אֲצִילוּת [כְּמוֹ שֶׁכָּתוּב בִּפְרִי עֵץ חַיִּים בְּקַבָּלַת שַׁבָּת], כִּי הִיא עִנְיַן בִּיטּוּל בְּאוֹרוֹ יִתְבָּרֵךְ, לִהְיוֹת חֲשִׁיב קַמֵּיהּ כְּלָא מַמָּשׁ, אֲזַי גַּם כֵּן עִיקַּר קְבִיעוּת נִשְׁמָתוֹ הוּא בְּעוֹלַם הַבְּרִיאָה [רַק לִפְרָקִים בְּעֵת רָצוֹן תַּעֲלֶה נִשְׁמָתוֹ לַאֲצִילוּת בִּבְחִינַת ״מַיִּין נוּקְבִין״, כַּיָּדוּעַ לְיוֹדְעֵי חֵן]:"],"Tanya, Part I; Likkutei Amarim 39:15":["וְהִנֵּה, ״שְׂכַר מִצְוָה – מִצְוָה״, פֵּירוּשׁ, שֶׁמִּשְּׂכָרָהּ נֵדַע מַהוּתָהּ וּמַדְרֵגָתָהּ, וְאֵין לָנוּ עֵסֶק בַּנִּסְתָּרוֹת שֶׁהֵם צַדִּיקִים הַגְּדוֹלִים, שֶׁהֵם בִּבְחִינַת מֶרְכָּבָה, רַק הַנִּגְלוֹת לָנוּ, שֶׁאַחֲרֵיהֶם כָּל אָדָם יִמְשׁוֹךְ, לֵידַע נֶאֱמָנָה מַהוּת וּמַדְרֵגַת עֲבוֹדַת ה׳ בִּדְחִילוּ וּרְחִימוּ בְּהִתְגַּלּוּת לִבּוֹ, הַנִּמְשָׁכוֹת מִן הַבִּינָה וָדַעַת בִּגְדוּלַּת אֵין־סוֹף בָּרוּךְ־הוּא – מְקוֹמָהּ בְּי׳ סְפִירוֹת דִּבְרִיאָה, וַעֲבוֹדָה בִּדְחִילוּ וּרְחִימוּ הַטִּבְעִיִּים שֶׁבְּמוֹחוֹ – בְּי׳ סְפִירוֹת דִּיצִירָה."],"Tanya, Part I; Likkutei Amarim 39:17":["וְהַיְינוּ, אֲפִילוּ אִם אֵינוֹ עוֹסֵק שֶׁלֹּא לִשְׁמָהּ מַמָּשׁ, לְשׁוּם אֵיזוֹ פְּנִיָּה חַס וְשָׁלוֹם, אֶלָּא כְּמוֹ שֶׁכָּתוּב: ״וַתְּהִי יִרְאָתָם אוֹתִי מִצְוַת אֲנָשִׁים מְלוּמָּדָה״, פֵּירוּשׁ, מֵחֲמַת הֶרְגֵּל שֶׁהוּרְגַּל מִקַּטְנוּתוֹ, שֶׁהִרְגִּילוֹ וְלִימְּדוֹ אָבִיו וְרַבּוֹ לִירֹא אֶת ה׳ וּלְעָבְדוֹ, וְאֵינוֹ עוֹסֵק לִשְׁמָהּ מַמָּשׁ, כִּי, לִשְׁמָהּ מַמָּשׁ אִי אֶפְשָׁר בְּלֹא הִתְעוֹרְרוּת דְּחִילוּ וּרְחִימוּ הַטִּבְעִיִּים עַל כָּל פָּנִים, לְהוֹצִיאָן מֵהֶסְתֵּר הַלֵּב אֶל הַגִּילּוּי בַּמּוֹחַ וְתַעֲלוּמוֹת לִבּוֹ עַל כָּל פָּנִים, כִּי, כְּמוֹ שֶׁאֵין אָדָם עוֹשֶׂה דָבָר בִּשְׁבִיל חֲבֵירוֹ לְמַלֹּאת רְצוֹנוֹ, אֶלָּא אִם כֵּן אוֹהֲבוֹ אוֹ יָרֵא מִמֶּנּוּ, כָּךְ, אִי אֶפְשָׁר לַעֲשׂוֹת לִשְׁמוֹ יִתְבָּרֵךְ בֶּאֱמֶת לְמַלֹּאת רְצוֹנוֹ לְבַד בְּלִי זִכְרוֹן וְהִתְעוֹרְרוּת אַהֲבָתוֹ וְיִרְאָתוֹ כְּלָל בְּמוֹחוֹ וּמַחֲשַׁבְתּוֹ וְתַעֲלוּמוֹת לִבּוֹ עַל כָּל פָּנִים."],"Tanya, Part I; Likkutei Amarim 39:19":["וּכְשֶׁעוֹסֵק שֶׁלֹּא לִשְׁמָהּ מַמָּשׁ, לְשׁוּם אֵיזוֹ פְּנִיָּה לִכְבוֹד עַצְמוֹ, כְּגוֹן, לִהְיוֹת תַּלְמִיד חָכָם וּכְהַאי גַּוְונָא, אֲזַי, אוֹתָהּ פְּנִיָּה שֶׁמִּצַּד הַקְּלִיפָּה דְנוֹגַהּ – מִתְלַבֶּשֶׁת בְּתוֹרָתוֹ, וְהַתּוֹרָה הִיא בִּבְחִינַת גָּלוּת בְּתוֹךְ הַקְּלִיפָּה לְפִי שָׁעָה, עַד אֲשֶׁר יַעֲשֶׂה תְּשׁוּבָה שֶׁמְּבִיאָה רְפוּאָה לָעוֹלָם, שֶׁבְּשׁוּבוֹ אֶל ה׳ – גַּם תּוֹרָתוֹ שָׁבָה עִמּוֹ."],"Tanya, Part I; Likkutei Amarim 39:6":["אַךְ הַיְינוּ דַּוְוקָא נְשָׁמוֹת מַמָּשׁ, שֶׁהֵן בְּחִינַת מוֹחִין דְּגַדְלוּת אֵין־סוֹף בָּרוּךְ־הוּא, אֲבָל בְּחִינַת הָרוּחַ שֶׁל הַצַּדִּיקִים, וְכֵן שְׁאָר כָּל נִשְׁמוֹת יִשְׂרָאֵל שֶׁעָבְדוּ אֶת ה׳ בִּדְחִילוּ וּרְחִימוּ הַמְסוּתָּרוֹת בְּלֵב כְּלָלוּת יִשְׂרָאֵל, אֵין עוֹלוֹת לְשָׁם, רַק בְּשַׁבָּת וְרֹאשׁ־חֹדֶשׁ לְבַד, דֶּרֶךְ הָעַמּוּד שֶׁמִּגַּן עֵדֶן הַתַּחְתּוֹן לְגַן עֵדֶן הָעֶלְיוֹן, שֶׁהוּא עוֹלַם הַבְּרִיאָה הַנִּקְרָא גַּן עֵדֶן הָעֶלְיוֹן, לְהִתְעַנֵּג עַל ה׳ וְלֵיהָנוֹת מִזִּיו הַשְּׁכִינָה, כִּי אֵין הֲנָאָה וְתַעֲנוּג לְשֵׂכֶל נִבְרָא, אֶלָּא בְּמַה שֶּׁמַּשְׂכִּיל וּמֵבִין וְיוֹדֵעַ וּמַשִּׂיג בְּשִׂכְלוֹ וּבִינָתוֹ, מַה שֶּׁאֶפְשָׁר לוֹ לְהָבִין וּלְהַשִּׂיג מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, עַל יְדֵי חָכְמָתוֹ וּבִינָתוֹ יִתְבָּרֵךְ, הַמְּאִירוֹת שָׁם בְּעוֹלַם הַבְּרִיאָה."],"Tanya, Part I; Likkutei Amarim 3:1":["וְהִנֵּה, כָּל בְּחִינָה וּמַדְרֵגָה מִשָּׁלֹשׁ אֵלּוּ: נֶפֶשׁ רוּחַ וּנְשָׁמָה – כְּלוּלָה מֵעֶשֶׂר בְּחִינוֹת, כְּנֶגֶד עֶשֶׂר סְפִירוֹת עֶלְיוֹנוֹת שֶׁנִּשְׁתַּלְשְׁלוּ מֵהֶן, הַנֶּחְלָקוֹת לִשְׁתַּיִם, שֶׁהֵן: שָׁלֹשׁ אִמּוֹת וְשֶׁבַע כְּפוּלוֹת; פֵּירוּשׁ, חָכְמָה בִּינָה וָדַעַת, וְשִׁבְעַת יְמֵי הַבִּנְיָן: חֶסֶד גְּבוּרָה תִּפְאֶרֶת כוּ׳."],"Tanya, Part I; Likkutei Amarim 3:8":["כִּי הַשֵּׂכֶל שֶׁבַּנֶּפֶשׁ הַמַּשְׂכֶּלֶת, כְּשֶׁמִּתְבּוֹנֵן וּמַעֲמִיק מְאֹד בִּגְדוּלַּת ה׳, אֵיךְ הוּא ״מְמַלֵּא כָּל עָלְמִין״ וְ״סוֹבֵב כָּל עָלְמִין״ וְ״כוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיב״ נוֹלְדָה וְנִתְעוֹרְרָה מִדַּת יִרְאַת הָרוֹמְמוּת בְּמוֹחוֹ וּמַחֲשַׁבְתּוֹ, לִירֹא וּלְהִתְבּוֹשֵׁשׁ מִגְּדוּלָּתוֹ יִתְבָּרֵךְ שֶׁאֵין לָהּ סוֹף וְתַכְלִית, וּפַחַד ה׳ בְּלִבּוֹ."],"Tanya, Part I; Likkutei Amarim 40:1":["אַךְ כָּל זְמַן שֶׁלֹּא חָזַר וְלָמַד דָּבָר זֶה לִשְׁמָהּ, אֵין לִימּוּדוֹ עוֹלֶה אֲפִילוּ בְּי׳ סְפִירוֹת הַמְּאִירוֹת בְּעוֹלַם הַיְצִירָה וְהָעֲשִׂיָּה, כִּי הַסְּפִירוֹת הֵן בְּחִינַת אֱלֹהוּת, וּבָהֶן מִתְלַבֵּשׁ וּמִתְיַיחֵד אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא מַמָּשׁ, ״וּבְלָא דְּחִילוּ וּרְחִימוּ לָא יָכְלָא לְסָלְקָא וּלְמֵיקַם קֳדָם ה׳״, כְּמוֹ שֶׁכָּתוּב בַּתִּיקּוּנִים, רַק לִימּוּדוֹ עוֹלֶה לְהֵיכָלוֹת וּמְדוֹרִין שֶׁהֵן חִיצוֹנִיּוּת הָעוֹלָמוֹת שֶׁבָּהֶן עוֹמְדִים הַמַּלְאָכִים; וּכְמוֹ שֶׁכָּתַב הָרַב חַיִּים וִיטַאל זִכְרוֹנוֹ לִבְרָכָה בְּשַׁעַר הַנְּבוּאָה פֶּרֶק ב׳, שֶׁמֵּהַתּוֹרָה שֶׁלֹּא בְכַוָּונָה – נִבְרָאִים מַלְאָכִים בְּעוֹלַם הַיְצִירָה, וּמֵהַמִּצְוֹת בְּלִי כַוָּונָה – נִבְרָאִים מַלְאָכִים בְּעוֹלַם הָעֲשִׂיָּיה, וְכָל הַמַּלְאָכִים, הֵם בַּעֲלֵי חוֹמֶר וְצוּרָה."],"Tanya, Part I; Likkutei Amarim 40:10":["וּבָזֶה יוּבַן הֵיטֵב, הָא דִּדְחִילוּ וּרְחִימוּ נִקְרָאִין ״גַּדְפִין״ דֶּרֶךְ מָשָׁל, כְּדִכְתִיב: ״וּבִשְׁתַּיִם יְעוֹפֵף״ [וּכְמוֹ שֶׁכָּתַב הָרַב חַיִּים וִיטַאל זִכְרוֹנוֹ לִבְרָכָה בְּשַׁעַר הַיִּחוּדִים פֶּרֶק י״א], שֶׁהַכְּנָפַיִם בָּעוֹף הֵן זְרוֹעוֹת הָאָדָם כוּ׳; וּבַתִּיקּוּנִים פֵּירְשׁוּ, שֶׁהָעוֹסְקִים בְּתוֹרָה וּמִצְוֹת בִּדְחִילוּ וּרְחִימוּ – נִקְרָאִים ״בָּנִים״, וְאִם לָאו – נִקְרָאִים ״אֶפְרוֹחִים״, דְּלָא יָכְלִין לְפָרְחָא."],"Tanya, Part I; Likkutei Amarim 40:12":["כִּי, כְּמוֹ שֶׁכַּנְפֵי הָעוֹף אֵינָם עִיקַּר הָעוֹף, וְאֵין חַיּוּתוֹ תָּלוּי בָּהֶם כְּלָל, כְּדִתְנַן: ״נִיטְּלוּ אֲגַפֶּיהָ – כְּשֵׁרָה״, וְהָעִיקָּר, הוּא רֹאשׁוֹ וְכָל גּוּפוֹ, וְהַכְּנָפַיִים אֵינָם רַק מְשַׁמְּשִׁים לְרֹאשׁוֹ וְגוּפוֹ לְפָרְחָא בְּהוֹן; וְכָךְ דֶּרֶךְ מָשָׁל, הַתּוֹרָה וּמִצְוֹת הֵן עִיקַּר הַיִּחוּד הָעֶלְיוֹן, עַל יְדֵי גִילּוּי רָצוֹן הָעֶלְיוֹן הַמִּתְגַּלֶּה עַל יְדֵיהֶן, וְהַדְּחִילוּ וּרְחִימוּ – הֵם מַעֲלִים אוֹתָן לְמָקוֹם שֶׁיִּתְגַּלֶּה בּוֹ הָרָצוֹן אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא וְהַיִּחוּד, שֶׁהֵן יְצִירָה וּבְרִיאָה."],"Tanya, Part I; Likkutei Amarim 40:14":["וְהִנֵּה, אַף דִּדְחִילוּ וּרְחִימוּ הֵם גַּם כֵּן מִתַּרְיַ״ג מִצְוֹת, אַף עַל פִּי כֵן, נִקְרָאִין ״גַּדְפִין״, לִהְיוֹת, כִּי תַּכְלִית הָאַהֲבָה הִיא הָעֲבוֹדָה מֵאַהֲבָה, וְאַהֲבָה בְּלִי עֲבוֹדָה, הִיא ״אַהֲבָה בְּתַּעֲנוּגִים״, לְהִתְעַנֵּג עַל ה׳ מֵעֵין עוֹלָם הַבָּא וְקַבָּלַת שָׂכָר, וְ״הַיּוֹם לַעֲשׂוֹתָם״, כְּתִיב, וּ״לְמָחָר לְקַבֵּל שְׂכָרָם״."],"Tanya, Part I; Likkutei Amarim 40:5":["וְאַף דְּאוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד, שֶׁהוּא וּרְצוֹנוֹ אֶחָד, הֲרֵי קוּדְשָׁא־בְּרִיךְ־הוּא אִיהוּ מְמַלֵּא כָּל עָלְמִין בְּשָׁוֶה, וְאַף־עַל־פִּי־כֵן, אֵין הָעוֹלָמוֹת שָׁוִים בְּמַעֲלָתָם; וְהַשִּׁינּוּי הוּא מֵהַמְקַבְּלִים, בְּב׳ בְּחִינוֹת: הָאֶחָד, שֶׁהָעֶלְיוֹנִים מְקַבְּלִים הֶאָרָה יוֹתֵר גְּדוֹלָה לְאֵין קֵץ מֵהַתַּחְתּוֹנִים; וְהַשֵּׁנִית, שֶׁמְּקַבְּלִים בְּלִי לְבוּשִׁים וּמָסָכִים רַבִּים כָּל כָּךְ כְּבַתַּחְתּוֹנִים; וְעוֹלָם הַזֶּה הוּא עוֹלָם הַשָּׁפָל בְּב׳ בְּחִינוֹת: כִּי הַהֶאָרָה שֶׁבּוֹ מְצוּמְצֶמֶת מְאֹד עַד קָצֶה הָאַחֲרוֹן, וְלָכֵן הוּא חוּמְרִי וְגַשְׁמִי, וְגַם זֹאת, הִיא בִּלְבוּשִׁים וּמָסָכִים רַבִּים, עַד שֶׁנִּתְלַבְּשָׁה בִּקְלִיפַּת נוֹגַהּ לְהַחֲיוֹת כָּל דְּבָרִים הַטְּהוֹרִים שֶׁבָּעוֹלָם הַזֶּה, וּבִכְלָלָם – הוּא נֶפֶשׁ הַחִיּוּנִית הַמְדַבֶּרֶת שֶׁבָּאָדָם."],"Tanya, Part I; Likkutei Amarim 40:7":["אֲבָל בִּתְפִלָּה בְּכַוָּונָה וְתוֹרָה בְּכַוָּונָה לִשְׁמָהּ, הֲרֵי הַכַּוָּונָה מִתְלַבֶּשֶׁת בְּאוֹתִיּוֹת הַדִּבּוּר, הוֹאִיל וְהִיא מָקוֹר וְשֹׁרֶשׁ לָהֶן, שֶׁמֵּחֲמָתָהּ וּבְסִיבָּתָהּ הוּא מְדַבֵּר אוֹתִיּוֹת אֵלּוּ, לָכֵן הִיא מַעֲלָה אוֹתָן עַד מְקוֹמָהּ בְּי׳ סְפִירוֹת דִּיצִירָה אוֹ דִבְרִיאָה, לְפִי מַה שֶּׁהִיא הַכַּוָּונָה בִּדְחִילוּ וּרְחִימוּ שִׂכְלִיִּים אוֹ טִבְעִיִּים כוּ׳, כַּנִּכְתָּב לְעֵיל."],"Tanya, Part I; Likkutei Amarim 40:9":["הגההוְשָׁם מֵאִיר וּמִתְגַּלֶּה גַּם כֵּן הַיִּחוּד הָﬠֶלְיוֹן הַנַּﬠֲשֶׂה בְּכָל מִצְוָה וְתַלְמוּד תּוֹרָה, שֶׁהוּא יִחוּד מִדּוֹתָיו יִתְבָּרֵךְ, שֶׁנִּכְלָלוֹת זוֹ בָּזוֹ, וְנִמְתָּקוֹת הַגְּבוּרוֹת בַּחֲסָדִים, ﬠַל יְדֵי ﬠֵת רָצוֹן הָﬠֶלְיוֹן אֵין־סוֹף בָּרוּךְ־הוּא, הַמֵּאִיר וּמִתְגַּלֶּה בִּבְחִינַת גִּילּוּי רַב וְﬠָצוּם, בְּאִתְﬠָרוּתָא דִלְתַתָּא הִיא ﬠֲשִׂיַּית הַמִּצְוָה אוֹ ﬠֵסֶק הַתּוֹרָה, שֶׁבָּהֶן מְלוּבָּשׁ רָצוֹן הָﬠֶלְיוֹן אֵין־סוֹף בָּרוּךְ־הוּא. אַךְ ﬠִיקַּר הַיִּחוּד הוּא לְמַﬠְלָה מַּﬠְלָה בְּעוֹלַם הָאֲצִילוּת, שֶׁשָּׁם הוּא מַהוּת וְﬠַצְמוּת מִדּוֹתָיו יִתְבָּרֵךְ, מְיוּחָדוֹת בְּמַאֲצִילָן אֵין־סוֹף בָּרוּךְ־הוּא, וְשָׁם הוּא מַהוּת וְﬠַצְמוּת רָצוֹן הָﬠֶלְיוֹן אֵין־סוֹף בָּרוּךְ־הוּא, וְהֶאָרָתָן לְבַד הִיא מְאִירָה בִּבְרִיאָה יְצִירָה ﬠֲשִׂיָּה, בְּכָל עוֹלָם מֵהֶן לְפִי מַﬠֲלָתוֹ. וְאַף שֶׁנֶּפֶשׁ הָאָדָם הָעוֹסֵק בְּתוֹרָה וּמִצְוָה זוֹ אֵינָהּ מֵאֲצִילוּת, מִכָּל מָקוֹם הֲרֵי רָצוֹן הָﬠֶלְיוֹן הַמְלוּבָּשׁ בְּמִצְוָה זוֹ, וְהוּא הוּא ﬠַצְמוֹ הַדְּבַר הֲלָכָה וְהַתּוֹרָה שֶׁעוֹסֵק בָּהּ, הוּא אֱלֹהוּת וְאוֹר־אֵין־סוֹף הַמַּאֲצִיל בָּרוּךְ־הוּא, שֶׁהוּא וּרְצוֹנוֹ אֶחָד, וּבִרְצוֹנוֹ יִתְבָּרֵךְ הֶאֱצִיל מִדּוֹתָיו הַמְיוּחָדוֹת בּוֹ יִתְבָּרֵךְ, וְﬠַל יְדֵי גִּילּוּי רְצוֹנוֹ הַמִּתְגַּלֶּה ﬠַל יְדֵי ﬠֵסֶק תּוֹרָה וּמִצְוָה זוֹ, הֵן נִכְלָלוֹת זוֹ בָּזוֹ וְנִמְתָּקוֹת הַגְּבוּרוֹת בַּחֲסָדִים, בְּﬠֵת רָצוֹן זוֹ:"],"Tanya, Part I; Likkutei Amarim 41:1":["בְּרַם, צָרִיךְ לִהְיוֹת לְזִכָּרוֹן תָּמִיד רֵאשִׁית הָעֲבוֹדָה וְעִיקָּרָהּ וְשָׁרְשָׁהּ. וְהוּא, כִּי אַף שֶׁהַיִּרְאָה הִיא שֹׁרֶשׁ לְ״סוּר מֵרָע״ וְהָאַהֲבָה לְ״וַעֲשֵׂה טוֹב״, אַף־עַל־פִּי־כֵן, לֹא דַי לְעוֹרֵר הָאַהֲבָה לְבַדָּהּ לְ״וַעֲשֵׂה טוֹב״, וּלְפָחוֹת צָרִיךְ לְעוֹרֵר תְּחִלָּה הַיִּרְאָה הַטִּבְעִית הַמְסוּתֶּרֶת בְּלֵב כָּל יִשְׂרָאֵל, שֶׁלֹּא לִמְרוֹד בְּמֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ־בָּרוּךְ־הוּא, כַּנִּזְכָּר לְעֵיל, שֶׁתְּהֵא בְּהִתְגַּלּוּת לִבּוֹ אוֹ מוֹחוֹ עַל כָּל פָּנִים."],"Tanya, Part I; Likkutei Amarim 41:11":["וְהִנֵּה, אַף מִי שֶׁגַּם בְּמוֹחוֹ וּבְמַחֲשַׁבְתּוֹ אֵינוֹ מַרְגִּישׁ שׁוּם יִרְאָה וּבוּשָׁה, מִפְּנֵי פְּחִיתוּת עֵרֶךְ נַפְשׁוֹ מִמְּקוֹר חוּצְבָּהּ, מִמַּדְרֵגוֹת תַּחְתּוֹנוֹת דְּי׳ סְפִירוֹת דַּעֲשִׂיָּה, אַף־עַל־פִּי־כֵן, מֵאַחַר שֶׁמִּתְכַּוֵּין בַּעֲבוֹדָתוֹ כְּדֵי לַעֲבוֹד אֶת הַמֶּלֶךְ, הֲרֵי זוֹ עֲבוֹדָה גְמוּרָה, כִּי הַיִּרְאָה וְהָעֲבוֹדָה נֶחְשָׁבוֹת לִשְׁתֵּי מִצְוֹת בְּמִנְיַן תַּרְיַ״ג, וְאֵינָן מְעַכְּבוֹת זוֹ אֶת זוֹ."],"Tanya, Part I; Likkutei Amarim 41:16":["אַךְ אָמְנָם, אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״לְעוֹלָם אַל יוֹצִיא אָדָם עַצְמוֹ מִן הַכְּלָל״, לָכֵן יִתְכַּוֵּין לְיַחֵד וּלְדָבְקָה בּוֹ יִתְבָּרֵךְ, מְקוֹר נַפְשׁוֹ הָאֱלֹהִית וּמְקוֹר נַפְשׁוֹת כָּל יִשְׂרָאֵל, שֶׁהוּא רוּחַ פִּיו יִתְבָּרֵךְ, הַנִּקְרָא בְּשֵׁם ״שְׁכִינָה״, עַל שֵׁם שֶׁשּׁוֹכֶנֶת וּמִתְלַבֶּשֶׁת תּוֹךְ כָּל עָלְמִין לְהַחֲיוֹתָן וּלְקַיְּימָן, וְהִיא הִיא – הַמַּשְׁפַּעַת בּוֹ כֹּחַ הַדִּבּוּר הַזֶּה שֶׁמְּדַבֵּר בְּדִבְרֵי תוֹרָה, אוֹ כֹּחַ הַמַּעֲשֶׂה הַזֶּה לַעֲשׂוֹת מִצְוָה זוֹ."],"Tanya, Part I; Likkutei Amarim 41:20":["וְאַף שֶׁלִּהְיוֹת כַּוָּונָה זוֹ אֲמִיתִּית בְּלִבּוֹ, שֶׁיִּהְיֶה לִבּוֹ חָפֵץ בֶּאֱמֶת יִחוּד הָעֶלְיוֹן הַזֶּה, צָרִיךְ לִהְיוֹת בְּלִבּוֹ אַהֲבָה רַבָּה לַה׳ לְבַדּוֹ, לַעֲשׂוֹת נַחַת רוּחַ לְפָנָיו לְבַד, וְלֹא לְרַוּוֹת נַפְשׁוֹ הַצְּמֵאָה לַה׳, אֶלָּא כִּבְרָא דְּאִשְׁתַּדֵּל בָּתַר אֲבוֹי וְאִמֵּיהּ, דְּרָחִים לוֹן יַתִּיר מִגַּרְמֵיהּ וְנַפְשֵׁיהּ כוּ׳ [כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל בְּשֵׁם רַעְיָא מְהֵימְנָא], מִכָּל מָקוֹם, יֵשׁ לְכָל אָדָם לְהַרְגִּיל עַצְמוֹ בְּכַוָּונָה זוֹ."],"Tanya, Part I; Likkutei Amarim 41:22":["אֲבָל יִחוּד נַפְשׁוֹ וְהִתְכַּלְלוּתָהּ בְּאוֹר ה׳ – לִהְיוֹת לַאֲחָדִים, בָּזֶה חָפֵץ כָּל אָדָם מִיִּשְׂרָאֵל בֶּאֱמֶת לַאֲמִיתּוֹ לְגַמְרֵי בְּכָל לֵב וּבְכָל נֶפֶשׁ, מֵאַהֲבָה הַטִּבְעִית הַמְסוּתֶּרֶת בְּלֵב כָּל יִשְׂרָאֵל לְדָבְקָה בַּה׳, וְלֹא לִיפָּרֵד וְלִהְיוֹת נִכְרָת וְנִבְדָּל חַס וְשָׁלוֹם מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ בְּשׁוּם אוֹפֶן, אֲפִילוּ בִּמְסִירַת נֶפֶשׁ מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 41:25":["וְהִנֵּה, בַּהֲכָנָה זוֹ שֶׁל מְסִירַת נַפְשׁוֹ לַה׳, יַתְחִיל בִּרְכוֹת הַשַּׁחַר, ״בָּרוּךְ אַתָּה כוּ׳״, וְכֵן בַּהֲכָנָה זוֹ יַתְחִיל לִלְמוֹד שִׁיעוּר קָבוּעַ מִיָּד אַחַר הַתְּפִלָּה, וְכֵן בְּאֶמְצַע הַיּוֹם, קוֹדֶם שֶׁיַּתְחִיל לִלְמוֹד, צְרִיכָה הֲכָנָה זוֹ לְפָחוֹת, כַּנּוֹדָע, שֶׁעִיקַּר הַהֲכָנָה לִשְׁמָהּ לְעַכֵּב – הוּא בִּתְחִלַּת הַלִּימּוּד בַּבֵּינוֹנִים, וּכְמוֹ בְּגֵט וְסֵפֶר תּוֹרָה, שֶׁצְּרִיכִים לִשְׁמָהּ לְעַכֵּב, וְדַיּוֹ שֶׁיֹּאמַר בִּתְחִלַּת הַכְּתִיבָה: ״הֲרֵינִי כּוֹתֵב לְשֵׁם קְדוּשַּׁת סֵפֶר תּוֹרָה״, אוֹ ״לִשְׁמוֹ וְלִשְׁמָהּ״ כוּ׳."],"Tanya, Part I; Likkutei Amarim 41:27":["וְהִנֵּה, כָּל כַּוָּונָתוֹ בִּמְסִירַת נַפְשׁוֹ לַה׳ עַל יְדֵי הַתּוֹרָה וְהַתְּפִלָּה, לְהַעֲלוֹת נִיצוֹץ אֱלֹהוּת שֶׁבְּתוֹכָהּ לִמְקוֹרוֹ, תְּהֵא רַק כְּדֵי לַעֲשׂוֹת נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ, כִּמְשַׁל שִׂמְחַת הַמֶּלֶךְ בְּבוֹא אֵלָיו בְּנוֹ יְחִידוֹ, בְּצֵאתוֹ מִן הַשִּׁבְיָה וּבֵית הָאֲסוּרִים, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 41:3":["וְהִנֵּה ה׳ נִצָּב עָלָיו, וּ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״, וּמַבִּיט עָלָיו, וּבוֹחֵן כְּלָיוֹת וָלֵב אִם עוֹבְדוֹ כָּרָאוּי. וְעַל כֵּן צָרִיךְ לַעֲבוֹד לְפָנָיו בְּאֵימָה וּבְיִרְאָה, כְּעוֹמֵד לִפְנֵי הַמֶּלֶךְ."],"Tanya, Part I; Likkutei Amarim 41:5":["וְגַם יִתְבּוֹנֵן, אֵיךְ שֶׁאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, הַ״סּוֹבֵב כָּל עָלְמִין״ וּ״מְמַלֵּא כָּל עָלְמִין״, הוּא רָצוֹן הָעֶלְיוֹן, הוּא מְלוּבָּשׁ בְּאוֹתִיּוֹת וְחָכְמַת הַתּוֹרָה, אוֹ בְּצִיצִית וּתְפִלִּין אֵלּוּ, וּבִקְרִיאָתוֹ אוֹ בִּלְבִישָׁתוֹ הוּא מַמְשִׁיךְ אוֹרוֹ יִתְבָּרֵךְ עָלָיו, דְּהַיְינוּ עַל ״חֵלֶק אֱלוֹהַּ מִמַּעַל״ שֶׁבְּתוֹךְ גּוּפוֹ, לִיכָּלֵל וְלִיבָּטֵל בְּאוֹרוֹ יִתְבָּרֵךְ."],"Tanya, Part I; Likkutei Amarim 41:7":["וּבַעֲטִיפַת צִיצִית, יְכַוֵּין כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר: לְהַמְשִׁיךְ עָלָיו מַלְכוּתוֹ יִתְבָּרֵךְ, אֲשֶׁר הִיא ״מַלְכוּת כָּל עוֹלָמִים״ וְכוּ׳, לְיַיחֲדָהּ עָלֵינוּ עַל יְדֵי מִצְוָה זוֹ, וְהוּא כְּעִנְיַן ״שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ״."],"Tanya, Part I; Likkutei Amarim 41:9":["מַה שֶּׁאֵין כֵּן אִם לוֹמֵד וּמְקַיֵּים הַמִּצְוָה בְּאַהֲבָה לְבַדָּהּ, כְּדֵי לְדָבְקָה בוֹ עַל יְדֵי תּוֹרָתוֹ וּמִצְוֹתָיו – אֵינָהּ נִקְרֵאת בְּשֵׁם עֲבוֹדַת הָעֶבֶד, וְהַתּוֹרָה אָמְרָה: ״וַעֲבַדְתֶּם אֵת ה׳ אֱלֹהֵיכֶם וְגוֹ׳״, ״וְאוֹתוֹ תַעֲבוֹדוּ וְגוֹ׳״; וּכְמוֹ שֶׁכָּתוּב בַּזֹּהַר [פָּרָשַׁת בְּהַר]: ״כְּהַאי תּוֹרָא דְּיָהֲבִין עֲלֵיהּ עוֹל בְּקַדְמֵיתָא בְּגִין לְאַפָּקָא מִינֵּיהּ טַב לְעָלְמָא כוּ׳, הָכֵי נַמֵי אִצְטְרִיךְ לְבַר נַשׁ לְקַבָּלָא עֲלֵיהּ עוֹל מַלְכוּת שָׁמַיִם בְּקַדְמֵיתָא כוּ׳, וְאִי הַאי לָא אִשְׁתְּכַח גַּבֵּיהּ – לָא שַׁרְיָא בֵּיהּ קְדוּשָּׁה כוּ׳״; [וּבְרַעְיָא מְהֵימְנָא שָׁם דַּף קי״א עַמּוּד ב׳] שֶׁכָּל אָדָם צָרִיךְ לִהְיוֹת בִּשְׁתֵּי בְּחִינוֹת וּמַדְרֵגוֹת, וְהֵן: בְּחִינַת ״עֶבֶד״ וּבְחִינַת ״בֵּן״."],"Tanya, Part I; Likkutei Amarim 42:1":["וְהִנֵּה, בְּמַה שֶּׁנִּתְבָּאֵר לְעֵיל בְּעִנְיַן יִרְאָה תַּתָּאָה, יוּבַן הֵיטֵב מַה שֶּׁכָּתוּב בַּגְּמָרָא עַל פָּסוּק ״וְעַתָּה יִשְׂרָאֵל מָה ה׳ אֱלֹהֶיךָ שׁוֹאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה אֶת ה׳ אֱלֹהֶיךָ״: ״אָטוּ יִרְאָה מִילְּתָא זוּטַרְתִּי הִיא״? אִין, לְגַבֵּי מֹשֶׁה מִילְּתָא זוּטַרְתִּי הִיא וְכוּ׳."],"Tanya, Part I; Likkutei Amarim 42:10":["וְגַם כִּי אֵין לוֹ דְמוּת הַגּוּף, הֲרֵי אַדְּרַבָּה – הַכֹּל גָּלוּי וְיָדוּעַ לְפָנָיו, בְּיֶתֶר שְׂאֵת לְאֵין קֵץ מֵרְאִיַּית הָעַיִן וּשְׁמִיעַת הָאֹזֶן עַל דֶּרֶךְ מָשָׁל, רַק הוּא עַל דֶּרֶךְ מָשָׁל, כְּמוֹ אָדָם הַיּוֹדֵעַ וּמַרְגִּישׁ בְּעַצְמוֹ כָּל מַה שֶּׁנַּעֲשֶׂה וְנִפְעָל בְּאֶחָד מִכָּל רַמַ״ח אֵיבָרָיו, כְּמוֹ קוֹר אוֹ חוֹם, וַאֲפִילוּ חוֹם שֶׁבְּצִפָּרְנֵי רַגְלָיו עַל דֶּרֶךְ מָשָׁל – אִם נִכְוָה בָּאוּר, וְכֵן מַהוּתָם וְעַצְמוּתָם וְכָל מַה שֶּׁמִּתְפָּעֵל בָּהֶם, יוֹדֵעַ וּמַרְגִּישׁ בְּמוֹחוֹ."],"Tanya, Part I; Likkutei Amarim 42:14":["וְהִנֵּה, כָּל אָדָם מִיִּשְׂרָאֵל, יִהְיֶה מִי שֶׁיִּהְיֶה, כְּשֶׁיִּתְבּוֹנֵן בָּזֶה שָׁעָה גְדוֹלָה בְּכָל יוֹם, אֵיךְ שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא מָלֵא מַמָּשׁ אֶת הָעֶלְיוֹנִים וְאֶת הַתַּחְתּוֹנִים, וְאֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ מַמָּשׁ, ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״ מַמָּשׁ, וְצוֹפֶה וּמַבִּיט וּבוֹחֵן כִּלְיוֹתָיו וְלִבּוֹ וְכָל מַעֲשָׂיו וְדִיבּוּרָיו, וְכָל צְעָדָיו יִסְפּוֹר, אֲזַי, תִּקָּבַע בְּלִבּוֹ הַיִּרְאָה לְכָל הַיּוֹם כּוּלּוֹ, כְּשֶׁיַּחֲזוֹר וְיִתְבּוֹנֵן בָּזֶה אֲפִילוּ בְּהִתְבּוֹנְנוּת קַלָּה, בְּכָל עֵת וּבְכָל שָׁעָה – יִהְיֶה ״סוּר מֵרָע וַעֲשֵׂה טוֹב״ בְּמַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה, שֶׁלֹּא לַמְרוֹת חַס וְשָׁלוֹם עֵינֵי כְבוֹדוֹ, אֲשֶׁר מָלֵא כָל הָאָרֶץ, וּכְמַאֲמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי לְתַלְמִידָיו כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 42:16":["וְעוֹד זֹאת יִזְכּוֹר, כִּי, כְּמוֹ שֶׁבְּמֶלֶךְ בָּשָׂר וָדָם עִיקַּר הַיִּרְאָה הִיא מִפְּנִימִיּוּתוֹ וְחַיּוּתוֹ וְלֹא מִגּוּפוֹ, שֶׁהֲרֵי כְּשֶׁיָּשֵׁן – אֵין שׁוּם יִרְאָה מִמֶּנּוּ, וְהִנֵּה, פְּנִימִיּוּתוֹ וְחַיּוּתוֹ, אֵין נִרְאֶה לְעֵינֵי בָשָׂר, רַק בְּעֵינֵי הַשֵּׂכֶל – עַל יְדֵי רְאִיַּית עֵינֵי בָשָׂר בְּגוּפוֹ וּלְבוּשָׁיו, שֶׁיּוֹדֵעַ שֶׁחַיּוּתוֹ מְלוּבָּשׁ בְּתוֹכָם, וְאִם כֵּן, כָּכָה מַמָּשׁ יֵשׁ לוֹ לִירֹא אֶת ה׳, עַל יְדֵי רְאִיַּית עֵינֵי בָשָׂר בַּשָּׁמַיִם וָאָרֶץ וְכָל צְבָאָם, אֲשֶׁר אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא מְלוּבָּשׁ בָּהֶם לְהַחֲיוֹתָם."],"Tanya, Part I; Likkutei Amarim 42:20":["וְגַם לִהְיוֹת לְזִכָּרוֹן תָּמִיד – לְשׁוֹן חֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה, ״קַבָּלַת עוֹל מַלְכוּת שָׁמַיִם״, שֶׁהוּא כְּעִנְיַן ״שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ״, כְּמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר וְכוּ׳, כִּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא מַנִּיחַ אֶת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וּמְיַיחֵד מַלְכוּתוֹ עָלֵינוּ וְכוּ׳, וַאֲנַחְנוּ מְקַבְּלִים וְכוּ׳, וְזֶהוּ עִנְיַן הַהִשְׁתַּחֲוָואוֹת שֶׁבִּתְפִלַּת י״ח, אַחַר קַבָּלַת עוֹל מַלְכוּת שָׁמַיִם בְּדִבּוּר בִּקְרִיאַת שְׁמַע, לַחֲזוֹר וּלְקַבֵּל בְּפוֹעַל מַמָּשׁ, בְּמַעֲשֶׂה וְכוּ׳, כְּמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר:"],"Tanya, Part I; Likkutei Amarim 42:5":["וְכֹחַ זֶה וּמִדָּה זוֹ לְקַשֵּׁר דַּעְתּוֹ בַּה׳, יֵשׁ בְּכָל נֶפֶשׁ מִבֵּית יִשְׂרָאֵל, בִּינִיקָתָהּ מִנִּשְׁמַת מֹשֶׁה רַבֵּינוּ עָלָיו הַשָּׁלום. רַק מֵאַחַר שֶׁנִּתְלַבְּשָׁה הַנֶּפֶשׁ בַּגּוּף, צְרִיכָה לִיגִיעָה רַבָּה וַעֲצוּמָה כְּפוּלָה וּמְכוּפֶּלֶת. הָאַחַת – הִיא יְגִיעַת בָּשָׂר, לְבַטֵּשׁ אֶת הַגּוּף וּלְהַכְנִיעוֹ שֶׁלֹּא יַחְשִׁיךְ עַל אוֹר הַנֶּפֶשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל בְּשֵׁם הַזֹּהַר, דְּ״גוּפָא דְּלָא סָלִיק בֵּיהּ נְהוֹרָא דְנִשְׁמְתָא מְבַטְּשִׁין לֵיהּ״, וְהַיְינוּ, עַל יְדֵי הִרְהוּרֵי תְשׁוּבָה מֵעוֹמֶק הַלֵּב, כְּמוֹ שֶׁנִּתְבָּאֵר שָׁם."],"Tanya, Part I; Likkutei Amarim 42:6":["וְהַשֵּׁנִית – הִיא יְגִיעַת הַנֶּפֶשׁ, שֶׁלֹּא תִכְבַּד עָלֶיהָ הָעֲבוֹדָה לְיַגֵּעַ מַחֲשַׁבְתָּהּ לְהַעֲמִיק וּלְהִתְבּוֹנֵן בִּגְדוּלַּת ה׳ שָׁעָה גְדוֹלָה רְצוּפָה. כִּי שִׁיעוּר שָׁעָה זוֹ – אֵינוֹ שָׁוֶה בְּכָל נֶפֶשׁ, יֵשׁ נֶפֶשׁ זַכָּה בְּטִבְעָהּ, שֶׁמִּיָּד שֶׁמִּתְבּוֹנֶנֶת בִּגְדוּלַּת ה׳ – יַגִּיעַ אֵלֶיהָ הַיִּרְאָה וּפַחַד ה׳, כְּמוֹ שֶׁכָּתוּב בְּשֻׁלְחָן עָרוּךְ אוֹרַח חַיִּים סִימָן א׳: ״כְּשֶׁיִּתְבּוֹנֵן הָאָדָם שֶׁהַמֶּלֶךְ הַגָּדוֹל מֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ־בָּרוּךְ־הוּא, אֲשֶׁר ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״, עוֹמֵד עָלָיו וְרוֹאֶה בְּמַעֲשָׂיו – מִיָּד יַגִּיעַ אֵלָיו הַיִּרְאָה וכוּ׳״."],"Tanya, Part I; Likkutei Amarim 43:1":["וְהִנֵּה עַל יִרְאָה תַּתָּאָה זוֹ, שֶׁהִיא לְקִיּוּם מִצְוֹתָיו יִתְבָּרֵךְ בִּבְחִינַת ״סוּר מֵרָע וַעֲשֵׂה טוֹב״, אָמְרוּ: ״אִם אֵין יִרְאָה אֵין חָכְמָה״."],"Tanya, Part I; Likkutei Amarim 43:6":["וְהִנֵּה, בְּאַהֲבָה יֵשׁ גַּם כֵּן שְׁתֵּי מַדְרֵגוֹת: ״אַהֲבָה רַבָּה״ וְ״אַהֲבַת עוֹלָם״, ״אַהֲבָה רַבָּה״ – הִיא ״אַהֲבָה בְּתַּעֲנוּגִים״, וְהִיא שַׁלְהֶבֶת הָעוֹלָה מֵאֵלֶיהָ, וּבָאָה מִלְמַעְלָה בִּבְחִינַת מַתָּנָה לְמִי שֶׁהוּא שָׁלֵם בְּיִרְאָה, כַּנּוֹדָע עַל מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״דַּרְכּוֹ שֶׁל אִישׁ לְחַזֵּר אַחַר אִשָּׁה״, שֶׁאַהֲבָה נִקְרֵאת ״אִישׁ״ וְ״זָכָר״, כְּמוֹ שֶׁכָּתוּב: ״זָכַר חַסְדּוֹ״, וְ״אִשָּׁה – יִרְאַת ה׳״, כַּנּוֹדָע; וּבְלִי קְדִימַת הַיִּרְאָה, אִי אֶפְשָׁר לְהַגִּיעַ לְאַהֲבָה רַבָּה זוֹ, כִּי אַהֲבָה זוֹ הִיא מִבְּחִינַת אֲצִילוּת, דְּלֵית תַּמָּן קִיצּוּץ וּפֵירוּד חַס וְשָׁלוֹם."],"Tanya, Part I; Likkutei Amarim 43:9":["וְהִנֵּה, בְּחִינַת אַהֲבָה זוֹ, פְּעָמִים שֶׁקּוֹדֶמֶת לְיִרְאָה, כְּפִי בְּחִינַת הַדַּעַת הַמּוֹלִידָהּ, כַּנּוֹדָע [שֶׁהַדַּעַת כּוֹלֵל חֲסָדִים וּגְבוּרוֹת, שֶׁהֵם אַהֲבָה וְיִרְאָה, וּפְעָמִים שֶׁהַחֲסָדִים קוֹדְמִים לֵירֵד וּלְהִתְגַּלּוֹת], וְלָכֵן אֶפְשָׁר לְרָשָׁע וּבַעַל עֲבֵירוֹת שֶׁיַּעֲשֶׂה תְּשׁוּבָה מֵאַהֲבָה הַנּוֹלְדָה בְּלִבּוֹ, בְּזָכְרוֹ אֶת ה׳ אֱלֹהָיו."],"Tanya, Part I; Likkutei Amarim 44:1":["וְהִנֵּה, כָּל מַדְרֵגַת אַהֲבָה מִבּ׳ מַדְרֵגוֹת אֵלּוּ: ״אַהֲבָה רַבָּה״ וְ״אַהֲבַת עוֹלָם״ – נֶחְלֶקֶת לְכַמָּה בְּחִינוֹת וּמַדְרֵגוֹת לְאֵין קֵץ, כָּל חַד לְפוּם שִׁיעוּרָא דִילֵיהּ, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר הַקָּדוֹשׁ עַל פָּסוּק: ״נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ״ – ״דָּא קוּדְשָׁא־בְּרִיךְ־הוּא, דְּאִיהוּ אִתְיְדַע וְאִתְדַּבֵּק לְכָל חַד לְפוּם מַה דִמְשַׁעֵר בְּלִבֵּיהּ וְכוּ׳״."],"Tanya, Part I; Likkutei Amarim 44:13":["וְהִנֵּה, בּ׳ בְּחִינוֹת אֲהָבוֹת אֵלּוּ, אַף שֶׁהֵן יְרוּשָּׁה לָנוּ מֵאֲבוֹתֵינוּ וּכְמוֹ טֶבַע בְּנַפְשׁוֹתֵינוּ, וְכֵן הַיִּרְאָה הַכְּלוּלָה בָּהֶן, שֶׁהִיא, לִירֹא מִלִּיפָּרֵד חַס וְשָׁלוֹם מִמְּקוֹר חַיֵּינוּ וְאָבִינוּ הָאֲמִיתִּי בָּרוּךְ־הוּא, אַף־עַל־פִּי־כֵן, אֵינָן נִקְרָאוֹת בְּשֵׁם ״דְּחִילוּ וּרְחִימוּ טִבְעִיִּים״, אֶלָּא כְּשֶׁהֵן בְּמוֹחוֹ וּמַחֲשַׁבְתּוֹ לְבַד וְתַעֲלוּמוֹת לִבּוֹ, וְאָז, מְקוֹמָן בְּי׳ סְפִירוֹת דִּיצִירָה, וּלְשָׁם הֵן מַעֲלוֹת עִמָּהֶן הַתּוֹרָה וְהַמִּצְוֹת הַבָּאוֹת מֵחֲמָתָן וּבְסִיבָּתָן."],"Tanya, Part I; Likkutei Amarim 44:17":["רַק שֶׁאַף־עַל־פִּי־כֵן, צָרִיךְ לִטְרוֹחַ בְּשִׂכְלוֹ לְהַשִּׂיג וּלְהַגִּיעַ גַּם לִבְחִינַת ״אַהֲבַת עוֹלָם״ הַנִּזְכֶּרֶת לְעֵיל, הַבָּאָה מֵהַתְּבוּנָה וָדַעַת בִּגְדוּלַּת ה׳, כְּדֵי לְהַגְדִּיל מְדוּרַת אֵשׁ הָאַהֲבָה בְּרִשְׁפֵּי אֵשׁ וְשַׁלְהֶבֶת עַזָּה וְלַהַב הָעוֹלֶה הַשָּׁמַיְמָה, עַד שֶׁ״מַּיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת וְכוּ׳ וּנְהָרוֹת לֹא יִשְׁטְפוּהָ וְכוּ׳״. כִּי יֵשׁ יִתְרוֹן וּמַעֲלָה לִבְחִינַת אַהֲבָה כְּרִשְׁפֵּי אֵשׁ וְשַׁלְהֶבֶת עַזָּה וְכוּ׳, הַבָּאָה מֵהַתְּבוּנָה וָדַעַת בִּגְדוּלַּת אֵין־סוֹף בָּרוּךְ־הוּא, עַל שְׁתֵּי בְּחִינוֹת אַהֲבָה הַנִּזְכָּרוֹת לְעֵיל – כַּאֲשֶׁר אֵינָן כְּרִשְׁפֵּי אֵשׁ וְשַׁלְהֶבֶת כוּ׳, כְּיִתְרוֹן וּמַעֲלַת הַזָּהָב עַל הַכֶּסֶף וְכוּ׳, כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן."],"Tanya, Part I; Likkutei Amarim 44:6":["וְאַהֲבָה רַבָּה וּגְדוֹלָה מִזּוֹ, וְהִיא מְסוּתֶּרֶת גַּם כֵּן בְּכָל נֶפֶשׁ מִיִּשְׂרָאֵל בִּירוּשָּׁה מֵאֲבוֹתֵינוּ, הִיא, מַה שֶּׁכָּתוּב בְּרַעְיָא מְהֵימְנָא: ״כִּבְרָא דְּאִשְׁתַּדֵּל בָּתַר אֲבוֹי וְאִימֵּיהּ, דְּרָחִים לוֹן יַתִּיר מִגַּרְמֵיהּ וְנַפְשֵׁיהּ וְרוּחֵיהּ כוּ׳״, כִּי הֲלֹא אָב אֶחָד לְכוּלָּנוּ."],"Tanya, Part I; Likkutei Amarim 44:9":["וְאַף אִם נִדְמֶה לוֹ לִכְאוֹרָה, שֶׁהוּא כֹּחַ דִּמְיוֹנִי – לֹא יָחוּשׁ, מֵאַחַר שֶׁהוּא אֱמֶת לַאֲמִיתּוֹ מִצַּד עַצְמוֹ בִּבְחִינַת ״אַהֲבָה מְסוּתֶּרֶת״. רַק שֶׁתּוֹעֶלֶת יְצִיאָתָהּ אֶל הַגִּילּוּי כְּדֵי לַהֲבִיאָהּ לִידֵי מַעֲשֶׂה, שֶׁהוּא עֵסֶק הַתּוֹרָה וְהַמִּצְוֹת שֶׁלּוֹמֵד וּמְקַיֵּים עַל יְדֵי זֶה, כְּדֵי לַעֲשׂוֹת נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ כְּבֵן הָעוֹבֵד אֶת אָבִיו."],"Tanya, Part I; Likkutei Amarim 45:1":["עוֹד יֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ, לַעֲסוֹק בַּתּוֹרָה וּמִצְוֹת לִשְׁמָן, עַל יְדֵי מִדָּתוֹ שֶׁל יַעֲקֹב אָבִינוּ עָלָיו הַשָּׁלוֹם, שֶׁהִיא מִדַּת הָרַחֲמִים, לְעוֹרֵר בְּמַחֲשַׁבְתּוֹ תְּחִלָּה רַחֲמִים רַבִּים לִפְנֵי ה׳ עַל נִיצוֹץ אֱלֹהוּת הַמְחַיֶּה נַפְשׁוֹ, אֲשֶׁר יָרַד מִמְּקוֹרוֹ – חַיֵּי הַחַיִּים אֵין־סוֹף בָּרוּךְ־הוּא, הַמְמַלֵּא כָּל עָלְמִין, וְסוֹבֵב כָּל עָלְמִין, וְכוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיב, וְנִתְלַבֵּשׁ בְּ״מַשְׁכָּא דְחִוְיָא״, הָרָחוֹק מֵאוֹר פְּנֵי הַמֶּלֶךְ בְּתַכְלִית הַהֶרְחֵק – כִּי הָעוֹלָם הַזֶּה הוּא תַּכְלִית הַקְּלִיפּוֹת הַגַּסּוֹת כוּ׳."],"Tanya, Part I; Likkutei Amarim 45:3":["וְזֶהוּ שֶׁאָמַר הַכָּתוּב: ״וַיִּשַּׁק יַעֲקֹב לְרָחֵל, וַיִּשָּׂא אֶת קוֹלוֹ וַיֵּבְךְּ״. כִּי רָחֵל הִיא כְּנֶסֶת יִשְׂרָאֵל, מְקוֹר כָּל הַנְּשָׁמוֹת. וְיַעֲקֹב בְּמִדָּתוֹ הָעֶלְיוֹנָה, שֶׁהִיא מִדַּת הָרַחֲמִים שֶׁבַּאֲצִילוּת, הוּא הַמְּעוֹרֵר רַחֲמִים רַבִּים עָלֶיהָ. וַיִּשָּׂא אֶת קוֹלוֹ – לְמַעְלָה, לִמְקוֹר הָרַחֲמִים הָעֶלְיוֹנִים, הַנִּקְרָא ״אַב הָרַחֲמִים״ וּמְקוֹרָם. וַיֵּבְךְּ – לְעוֹרֵר וּלְהַמְשִׁיךְ מִשָּׁם רַחֲמִים רַבִּים עַל כָּל הַנְּשָׁמוֹת וְעַל מְקוֹר כְּנֶסֶת יִשְׂרָאֵל, לְהַעֲלוֹתָן מִגָּלוּתָן, וּלְיַיחֲדָן בַּיִּחוּד הָעֶלְיוֹן אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, בִּבְחִינַת נְשִׁיקִין, שֶׁהִיא – אִתְדַּבְּקוּת רוּחָא בְּרוּחָא, כְּמוֹ שֶׁכָּתוּב: ״יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ״, דְּהַיְינוּ, הִתְקַשְּׁרוּת דִּבּוּר הָאָדָם בִּ״דְבַר ה׳ זוֹ הֲלָכָה״, וְכֵן מַחֲשָׁבָה בְּמַחֲשָׁבָה, וּמַעֲשֶׂה בְּמַעֲשֶׂה, שֶׁהוּא מַעֲשֵׂה הַמִּצְוֹת, וּבִפְרָט מַעֲשֵׂה הַצְּדָקָה וָחֶסֶד. דְּ״חֶסֶד דְּרוֹעָא יְמִינָא״, וְהוּא בְּחִינַת חִיבּוּק מַמָּשׁ, כְּמוֹ שֶׁכָּתוּב: ״וִימִינוֹ תְּחַבְּקֵנִי״. וְעֵסֶק הַתּוֹרָה בְּדִבּוּר וּמַחֲשֶׁבֶת הָעִיּוּן – הֵן בְּחִינַת נְשִׁיקִין מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 46:1":["וְיֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ, שָׁוֶה לְכָל נֶפֶשׁ, וְקָרוֹב הַדָּבָר מְאֹד מְאֹד, לְעוֹרֵר וּלְהָאִיר אוֹר הָאַהֲבָה הַתְּקוּעָה וּמְסוּתֶּרֶת בְּלִבּוֹ, לִהְיוֹת מְאִירָה בְּתוֹקֶף אוֹרָהּ כְּאֵשׁ בּוֹעֲרָה בְּהִתְגַּלּוּת לִבּוֹ וּמוֹחוֹ, לִמְסוֹר נַפְשׁוֹ לַה׳ וְגוּפוֹ וּמְאוֹדוֹ בְּכָל לֵב וּבְכָל נֶפֶשׁ וּמְאֹד, מֵעוּמְקָא דְלִבָּא בֶּאֱמֶת לַאֲמִיתּוֹ, וּבִפְרָט בִּשְׁעַת קְרִיאַת שְׁמַע וּבִרְכוֹתֶיהָ, כְּמוֹ שֶׁיִּתְבָּאֵר."],"Tanya, Part I; Likkutei Amarim 46:11":["וְזֶהוּ שֶׁאָמַר אָסָף בְּרוּחַ הַקֹּדֶשׁ בְּעַד כָּל כְּנֶסֶת יִשְׂרָאֵל שֶׁבַּגּוֹלָה: ״וַאֲנִי בַעַר וְלֹא אֵדָע, בְּהֵמוֹת הָיִיתִי עִמָּךְ, וַאֲנִי תָּמִיד עִמָּךְ״. כְּלוֹמַר שֶׁאַף עַל פִּי שֶׁאֲנִי כִּבְהֵמָה בִּהְיוֹתִי עִמְּךָ, וְלֹא אֵדַע וְלֹא אַרְגִּישׁ בְּנַפְשִׁי יִחוּד זֶה – שֶׁתִּפּוֹל עָלֶיהָ אֵימָתָה וָפַחַד תְּחִלָּה, וְאַחַר כָּךְ אַהֲבָה רַבָּה בְּתַּעֲנוּגִים אוֹ כְּרִשְׁפֵּי אֵשׁ, כְּמִדַּת הַצַּדִּיקִים שֶׁנִּזְדַּכֵּךְ חוּמְרָם; וְכַנּוֹדָע, שֶׁדַּעַת הוּא לְשׁוֹן הַרְגָּשָׁה בַּנֶּפֶשׁ, וְהוּא כּוֹלֵל חֶסֶד וּגְבוּרָה – אַף־עַל־פִּי־כֵן, ״אֲנִי תָּמִיד עִמָּךְ״, כִּי אֵין הַחוֹמֶר מוֹנֵעַ יִחוּד הַנֶּפֶשׁ בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא הַמְמַלֵּא כָּל עָלְמִין, וּכְמוֹ שֶׁכָּתוּב: ״גַּם חוֹשֶׁךְ לֹא יַחְשִׁיךְ מִמֶּךָּ״."],"Tanya, Part I; Likkutei Amarim 46:3":["וְהִנֵּה, זֶהוּ טֶבַע הַנָּהוּג בְּמִדַּת כָּל אָדָם, אַף אִם שְׁנֵיהֶם שָׁוִים בְּמַעֲלָה. וְעַל אַחַת כַּמָּה וְכַמָּה, אִם מֶלֶךְ גָּדוֹל וְרַב, מַרְאֶה אַהֲבָתוֹ הַגְּדוֹלָה וְהָעֲצוּמָה לְאִישׁ הֶדְיוֹט וְנִבְזֶה וּשְׁפַל אֲנָשִׁים וּמְנֻוָּול הַמּוּטָּל בְּאַשְׁפָּה, וְיוֹרֵד אֵלָיו מִמְּקוֹם כְּבוֹדוֹ עִם כָּל שָׂרָיו יַחְדָּיו, וּמְקִימוֹ וּמְרִימוֹ מֵאַשְׁפָּתוֹ, וּמַכְנִיסוֹ לְהֵיכָלוֹ הֵיכַל הַמֶּלֶךְ, חֶדֶר לִפְנִים מֵחֶדֶר, מָקוֹם שֶׁאֵין כָּל עֶבֶד וְשַׂר נִכְנָס לְשָׁם, וּמִתְיַיחֵד עִמּוֹ שָׁם בְּיִחוּד וְקֵירוּב אֲמִיתִּי וְחִיבּוּק וְנִישּׁוּק וְאִתְדַּבְּקוּת רוּחָא בְּרוּחָא בְּכָל לֵב וָנֶפֶשׁ – עַל אַחַת כַּמָּה וְכַמָּה, שֶׁתִּתְעוֹרֵר מִמֵּילָא הָאַהֲבָה כְּפוּלָה וּמְכוּפֶּלֶת בְּלֵב הַהֶדְיוֹט וּשְׁפַל אֲנָשִׁים הַזֶּה אֶל נֶפֶשׁ הַמֶּלֶךְ, בְּהִתְקַשְּׁרוּת הַנֶּפֶשׁ מַמָּשׁ מִלֵּב וָנֶפֶשׁ מֵעוּמְקָא דְלִבָּא לְאֵין קֵץ, וְאַף אִם לִבּוֹ כְּלֵב הָאֶבֶן – הִמֵּס יִמַּס וְהָיָה לְמַיִם, וְתִשְׁתַּפֵּךְ נַפְשׁוֹ כַּמַּיִם – בִּכְלוֹת הַנֶּפֶשׁ מַמָּשׁ לְאַהֲבַת הַמֶּלֶךְ:"],"Tanya, Part I; Likkutei Amarim 46:4":["וְהִנֵּה, כְּכָל הַדְּבָרִים הָאֵלֶּה וּכְכָל הַחִזָּיוֹן הַזֶּה, וְגָדוֹל יָתֵר מְאֹד בְּכִפְלֵי כִפְלַיִים לְאֵין קֵץ, עָשָׂה לָנוּ אֱלֹהֵינוּ. כִּי לִגְדוּלָּתוֹ אֵין חֵקֶר, וְ״אִיהוּ מְמַלֵּא כָּל עָלְמִין״ וְ״סוֹבֵב כָּל עָלְמִין״, וְנוֹדָע מִזֹּהַר הַקָּדוֹשׁ וְהָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה, רִיבּוּי הַהֵיכָלוֹת וְהָעוֹלָמוֹת עַד אֵין מִסְפָּר, וּבְכָל עוֹלָם וְהֵיכָל רִיבּוֹא רִבְבוֹת מַלְאָכִים לְאֵין קֵץ וְתַכְלִית, וּכְמוֹ שֶׁכָּתוּב בַּגְּמָרָא: כְּתִיב, ״הֲיֵשׁ מִסְפָּר לִגְדוּדָיו״, וּכְתִיב, ״אֶלֶף אַלְפִין יְשַׁמְּשׁוּנֵּיהּ, וְרִיבּוֹ רִבְבָן קָדָמוֹהִי כוּ׳״, וּמְשַׁנֵּי: ״אֶלֶף אַלְפִין וְכוּ׳ – מִסְפַּר גְּדוּד אֶחָד, אֲבָל לִגְדוּדָיו – אֵין מִסְפָּר״, וְכוּלָּם קַמֵּיהּ כְּלָא מַמָּשׁ חֲשִׁיבֵי, וּבְטֵלִים בִּמְצִיאוּת מַמָּשׁ, כְּבִיטּוּל דִּבּוּר אֶחָד מַמָּשׁ לְגַבֵּי מַהוּת הַנֶּפֶשׁ הַמְדַבֶּרֶת וְעַצְמוּתָהּ, בְּעוֹד שֶׁהָיָה דִיבּוּרָהּ עֲדַיִין בְּמַחֲשַׁבְתָּהּ אוֹ בִּרְצוֹן וְחֶמְדַּת הַלֵּב, כַּנִּזְכָּר לְעֵיל בַּאֲרִיכוּת:"],"Tanya, Part I; Likkutei Amarim 46:5":["וְכוּלָּם שׁוֹאֲלִים: ״אַיֵּה מְקוֹם כְּבוֹדוֹ״, וְעוֹנִים: ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״ – הֵם יִשְׂרָאֵל עַמּוֹ, כִּי הִנִּיחַ הַקָּדוֹשׁ־בָּרוּךְ־הוּא אֶת הָעֶלְיוֹנִים וְאֶת הַתַּחְתּוֹנִים, וְלֹא בָחַר בְּכוּלָּם כִּי אִם בְּיִשְׂרָאֵל עַמּוֹ, וְהוֹצִיאָם מִמִּצְרַיִם, עֶרְוַת הָאָרֶץ, מְקוֹם הַזּוּהֲמָא וְהַטּוּמְאָה, לֹא עַל יְדֵי מַלְאָךְ וְלֹא עַל יְדֵי כוּ׳, אֶלָּא הַקָּדוֹשׁ־בָּרוּךְ־הוּא בִּכְבוֹדוֹ וּבְעַצְמוֹ יָרַד לְשָׁם, כְּמוֹ שֶׁכָּתוּב: ״וָאֵרֵד לְהַצִּילוֹ וְגוֹ׳״, כְּדֵי לְקָרְבָם אֵלָיו בְּקֵירוּב וְיִחוּד אֲמִיתִּי, בְּהִתְקַשְּׁרוּת הַנֶּפֶשׁ מַמָּשׁ בִּבְחִינַת נְשִׁיקִין פֶּה לַפֶה – לְדַבֵּר דְבַר ה׳ זוֹ הֲלָכָה, וְאִתְדַּבְּקוּת רוּחָא בְּרוּחָא – הִיא הַשָּׂגַת הַתּוֹרָה וִידִיעַת רְצוֹנוֹ וְחָכְמָתוֹ, דְּכוּלָּא חַד מַמָּשׁ, וְגַם בִּבְחִינַת חִיבּוּק – הוּא קִיּוּם הַמִּצְוֹת מַעֲשִׂיּוֹת בְּרַמַ״ח אֵבָרִים, דְּרַמַ״ח פִּיקּוּדִין הֵן רַמַ״ח אֵבָרִין דְּמַלְכָּא כַּנִּזְכָּר לְעֵיל, וְדֶרֶךְ כְּלָל, נֶחְלָקִין לְשָׁלֹשׁ בְּחִינוֹת: יָמִין וּשְׂמֹאל וְאֶמְצַע, שֶׁהֵן: חֶסֶד דִּין רַחֲמִים – תְּרֵין דְּרוֹעִין וְגוּפָא וְכוּ׳."],"Tanya, Part I; Likkutei Amarim 46:6":["וְזֶהוּ שֶׁאוֹמְרִים: ״אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו״, כְּאָדָם הַמְקַדֵּשׁ אִשָּׁה לִהְיוֹת מְיוּחֶדֶת עִמּוֹ בְּיִחוּד גָּמוּר, כְּמוֹ שֶׁכָּתוּב: ״וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד״. – כָּכָה מַמָּשׁ וְיֶתֶר עַל כֵּן לְאֵין קֵץ, הוּא יִחוּד נֶפֶשׁ הָאֱלֹהִית הָעוֹסֶקֶת בַּתּוֹרָה וּמִצְוֹת וְנֶפֶשׁ הַחִיּוּנִית וּלְבוּשֵׁיהֶן – הַנִּזְכָּרִים לְעֵיל – בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא."],"Tanya, Part I; Likkutei Amarim 46:7":["וְלָכֵן הִמְשִׁיל שְׁלֹמֹה עָלָיו הַשָּׁלוֹם בְּ״שִׁיר הַשִּׁירִים״, יִחוּד זֶה לְיִחוּד חָתָן וְכַלָּה, בִּדְבִיקָה חֲשִׁיקָה וַחֲפִיצָה בְּחִיבּוּק וְנִישּׁוּק."],"Tanya, Part I; Likkutei Amarim 47:1":["וְהִנֵּה, ״בְּכָל דּוֹר וָדוֹר, – וְכָל יוֹם וָיוֹם – חַיָּיב אָדָם לִרְאוֹת עַצְמוֹ כְּאִילּוּ הוּא יָצָא הַיּוֹם מִמִּצְרָיִם״. וְהִיא יְצִיאַת נֶפֶשׁ הָאֱלֹהִית מִמַּאֲסַר הַגּוּף, ״מַשְׁכָּא דְחִוְיָא״, לִיכָּלֵל בְּיִחוּד אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, עַל יְדֵי עֵסֶק הַתּוֹרָה וְהַמִּצְוֹת בִּכְלָל, וּבִפְרָט בְּקַבָּלַת מַלְכוּת שָׁמַיִם בִּקְרִיאַת שְׁמַע, שֶׁבָּהּ מְקַבֵּל וּמַמְשִׁיךְ עָלָיו יִחוּדוֹ יִתְבָּרֵךְ בְּפֵירוּשׁ, בְּאָמְרוֹ: ״ה׳ אֱלֹהֵינוּ ה׳ אֶחָד״."],"Tanya, Part I; Likkutei Amarim 48:1":["וְהִנֵּה, כַּאֲשֶׁר יִתְבּוֹנֵן הַמַּשְׂכִּיל בִּגְדוּלַּת אֵין־סוֹף בָּרוּךְ־הוּא, כִּי כִּשְׁמוֹ כֵּן הוּא – אֵין־סוֹף וְאֵין קֵץ וְתַכְלִית כְּלָל, לְאוֹר וְחַיּוּת הַמִּתְפַּשֵּׁט מִמֶּנּוּ יִתְבָּרֵךְ בִּרְצוֹנוֹ הַפָּשׁוּט וּמְיוּחָד בְּמַהוּתוֹ וְעַצְמוּתוֹ יִתְבָּרֵךְ בְּתַכְלִית הַיִּחוּד. וְאִילּוּ הָיְתָה הִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא בְּלִי צִמְצוּמִים, רַק כְּסֵדֶר הַמַּדְרֵגוֹת מִמַּדְרֵגָה לְמַדְרֵגָה בְּדֶרֶךְ עִלָּה וְעָלוּל – לֹא הָיָה הָעוֹלָם הַזֶּה נִבְרָא כְּלָל כְּמוֹ שֶׁהוּא עַתָּה בִּבְחִינַת גְּבוּל וְתַכְלִית, ״מֵהָאָרֶץ לָרָקִיעַ מַהֲלַךְ תּ״ק שָׁנָה״, וְכֵן בֵּין כָּל רָקִיעַ לְרָקִיעַ, וְכֵן עוֹבִי כָּל רָקִיעַ וְרָקִיעַ."],"Tanya, Part I; Likkutei Amarim 48:10":["לְמָשָׁל, כַּדּוּר הָאָרֶץ הַלֵּזוּ, הֲרֵי יְדִיעָתוֹ יִתְבָּרֵךְ מַקֶּפֶת כָּל עוֹבִי כַּדּוּר הָאָרֶץ וְכָל אֲשֶׁר בְּתוֹכוֹ וְתוֹךְ תּוֹכוֹ עַד תַּחְתִּיתוֹ, הַכֹּל בְּפוֹעַל מַמָּשׁ, שֶׁהֲרֵי, יְדִיעָה זוֹ, הִיא חַיּוּת כָּל עוֹבִי כַּדּוּר הָאָרֶץ כּוּלּוֹ, וְהִתְהַוּוּתוֹ מֵאַיִן לְיֵשׁ. רַק שֶׁלֹּא הָיָה מִתְהַוֶּה כְּמוֹת שֶׁהוּא עַתָּה, בַּעַל גְּבוּל וְתַכְלִית וְחַיּוּת מוּעֶטֶת מְאֹד, כְּדֵי בְּחִינוֹת דּוֹמֵם וְצוֹמֵחַ. אִם לֹא, עַל יְדֵי צִמְצוּמִים רַבִּים וַעֲצוּמִים, שֶׁצִּמְצְמוּ הָאוֹר וְהַחַיּוּת שֶׁנִּתְלַבֵּשׁ בְּכַדּוּר הָאָרֶץ לְהַחֲיוֹתוֹ וּלְקַיְּימוֹ בִּבְחִינַת גְּבוּל וְתַכְלִית, וּבִבְחִינוֹת דּוֹמֵם וְצוֹמֵחַ בִּלְבָד."],"Tanya, Part I; Likkutei Amarim 48:11":["אַךְ יְדִיעָתוֹ יִתְבָּרֵךְ הַמְיוּחֶדֶת בְּמַהוּתוֹ וְעַצְמוּתוֹ – כִּי ״הוּא הַמַּדָּע וְהוּא הַיּוֹדֵעַ וְהוּא הַיָּדוּעַ, וּבִידִיעַת עַצְמוֹ כִּבְיָכוֹל יוֹדֵעַ כָּל הַנִּבְרָאִים, וְלֹא בִּידִיעָה שֶׁחוּץ מִמֶּנּוּ כִּידִיעַת הָאָדָם, כִּי כּוּלָּם נִמְצָאִים מֵאֲמִיתָּתוֹ יִתְבָּרֵךְ, וְדָבָר זֶה אֵין בִּיכוֹלֶת הָאָדָם לְהַשִּׂיגוֹ עַל בּוּרְיוֹ וְכוּ׳״"],"Tanya, Part I; Likkutei Amarim 48:3":["וְהִנֵּה, פְּרָטִיּוּת הַצִּמְצוּמִים, אֵיךְ וּמָה – אֵין כָּאן מְקוֹם בֵּיאוּרָם. אַךְ דֶּרֶךְ כְּלָל, הֵן הֵם בְּחִינַת הֶסְתֵּר וְהֶעְלֵם הַמְשָׁכַת הָאוֹר וְהַחַיּוּת, שֶׁלֹּא יָאִיר וְיוּמְשַׁךְ לַתַּחְתּוֹנִים בִּבְחִינַת גִּילּוּי, לְהִתְלַבֵּשׁ וּלְהַשְׁפִּיעַ בָּהֶן וּלְהַחֲיוֹתָם לִהְיוֹת יֵשׁ מֵאַיִן – כִּי אִם, מְעַט מִזְּעֵר אוֹר וְחַיּוּת, בִּכְדֵי שֶׁיִּהְיוּ בִּבְחִינַת גְּבוּל וְתַכְלִית, שֶׁהִיא הֶאָרָה מוּעֶטֶת מְאֹד וּמַמָּשׁ כְּלָא חֲשִׁיבֵי לְגַבֵּי בְּחִינַת הֶאָרָה בְּלִי גְבוּל וְתַכְלִית, וְאֵין בֵּינֵיהֶם עֵרֶךְ וְיַחַס כְּלָל, כַּנּוֹדָע פֵּירוּשׁ מִלַּת ‘עֵרֶךְ׳ בְּמִסְפָּרִים, שֶׁאֶחָד בְּמִסְפָּר, יֵשׁ לוֹ עֵרֶךְ לְגַבֵּי מִסְפָּר אֶלֶף אֲלָפִים, שֶׁהוּא חֵלֶק אֶחָד מִנִּי אֶלֶף אֲלָפִים, אֲבָל לְגַבֵּי דָּבָר שֶׁהוּא בִּבְחִינַת בְּלִי גְבוּל וּמִסְפָּר כְּלָל – אֵין כְּנֶגְדּוֹ שׁוּם עֵרֶךְ בְּמִסְפָּרִים, שֶׁאֲפִילוּ אֶלֶף אַלְפֵי אֲלָפִים וְרִיבּוֹא רְבָבוֹת, אֵינָן אֲפִילוּ כְּעֵרֶךְ מִסְפָּר אֶחָד לְגַבֵּי אֶלֶף אַלְפֵי אֲלָפִים וְרִבּוֹא רְבָבוֹת, אֶלָּא כְּלָא מַמָּשׁ חֲשִׁיבֵי."],"Tanya, Part I; Likkutei Amarim 48:4":["וְכָכָה מַמָּשׁ הִיא בְּחִינַת הַהֶאָרָה מוּעֶטֶת זוֹ, הַמִּתְלַבֶּשֶׁת בְּעוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים לְהַשְׁפִּיעַ בָּהֶם לְהַחֲיוֹתָם, לְגַבֵּי עֵרֶךְ אוֹר הַגָּנוּז וְנֶעְלָם, שֶׁהוּא בִּבְחִינַת ״אֵין־סוֹף״, וְאֵינוֹ מִתְלַבֵּשׁ וּמַשְׁפִּיעַ בָּעוֹלָמוֹת בִּבְחִינַת גִּילּוּי לְהַחֲיוֹתָם, אֶלָּא מַקִּיף עֲלֵיהֶם מִלְמַעְלָה, וְנִקְרָא – ״סוֹבֵב כָּל עָלְמִין״."],"Tanya, Part I; Likkutei Amarim 48:7":["וְהַמָּשָׁל בָּזֶה, הִנֵּה הָאָרֶץ הַלֵּזוּ הַגַּשְׁמִיּוּת, אַף שֶׁ״מְּלֹא כָל הָאָרֶץ כְּבוֹדוֹ״, וְהַיְינוּ אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, כְּמוֹ שֶׁכָּתוּב: ״הֲלֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא, נְאֻם ה׳״. אַף־עַל־פִּי־כֵן, אֵין מִתְלַבֵּשׁ בְּתוֹכָהּ בִּבְחִינַת גִּילּוּי הַהַשְׁפָּעָה, רַק חַיּוּת מְעַט מִזְּעֵר, בְּחִינוֹת דּוֹמֵם וְצוֹמֵחַ לְבַד. וְכָל אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא נִקְרָא סוֹבֵב עָלֶיהָ, אַף שֶׁהוּא בְּתוֹכָהּ מַמָּשׁ. מֵאַחַר שֶׁאֵין הַשְׁפָּעָתוֹ מִתְגַּלֵּית בָּהּ יוֹתֵר, רַק מַשְׁפִּיעַ בָּהּ בִּבְחִינַת הֶסְתֵּר וְהֶעְלֵם, וְכָל הַשְׁפָּעָה שֶׁבִּבְחִינַת הֶסְתֵּר, נִקְרָא מַקִּיף מִלְמַעְלָה, כִּי, ״עָלְמָא דְאִתְכַּסְיָא״ הוּא לְמַעְלָה בְּמַדְרֵגָה מֵ״עָלְמָא דְאִתְגַּלְיָא״."],"Tanya, Part I; Likkutei Amarim 48:9":["אֲבָל הַקָּדוֹשׁ־בָּרוּךְ־הוּא דִּכְתִיב בֵּיהּ: ״כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיכֶם כוּ׳״, הֲרֵי מַחֲשַׁבְתּוֹ וְדַעְתּוֹ שֶׁיּוֹדֵעַ כָּל הַנִּבְרָאִים, מַקֶּפֶת כָּל נִבְרָא וְנִבְרָא מֵרֹאשׁוֹ וְעַד תַּחְתִּיתוֹ, וְתוֹכוֹ וְתוֹךְ תּוֹכוֹ, הַכֹּל בְּפוֹעַל מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 49:1":["וְהִנֵּה, אַף כִּי פְּרָטֵי בְּחִינוֹת הַהֶסְתֵּר וְהַהֶעְלֵם אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, בְּהִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת עַד שֶׁנִּבְרָא עוֹלָם הַזֶּה הַגַּשְׁמִי עָצְמוּ מִסְפֹר, וּמִינִים מִמִּינִים שׁוֹנִים, כַּיָּדוּעַ לַטּוֹעֲמִים מֵעֵץ הַחַיִּים, אַךְ דֶּרֶךְ כְּלָל, הֵם שְׁלֹשָׁה מִינֵי צִמְצוּמִים עֲצוּמִים כְּלָלִיִּים. לִשְׁלֹשָׁה מִינֵי עוֹלָמוֹת כְּלָלִיִּים. וּבְכָל כְּלָל יֵשׁ רִבּוֹא רִבְבוֹת פְּרָטִיים, וְהֵם שְׁלֹשָׁה עוֹלָמוֹת בְּרִיאָה, יְצִירָה, עֲשִׂיָּה. כִּי עוֹלַם הָאֲצִילוּת – הוּא אֱלֹהוּת מַמָּשׁ."],"Tanya, Part I; Likkutei Amarim 49:10":["וְאַחַר־כָּךְ בְּרָכָה שְׁנִיָּה: – ״אַהֲבַת עוֹלָם אֲהַבְתָּנוּ ה׳ אֱלֹהֵינוּ״, כְּלוֹמַר, שֶׁהִנִּיחַ כָּל צְבָא מַעְלָה הַקְּדוֹשִׁים, וְהִשְׁרָה שְׁכִינָתוֹ עָלֵינוּ, לִהְיוֹת נִקְרָא ״אֱלֹהֵינוּ״, כְּמוֹ ״אֱלֹהֵי אַבְרָהָם כוּ׳״ כַּנִּזְכָּר לְעֵיל. וְהַיְינוּ, כִּי אַהֲבָה דּוֹחֶקֶת הַבָּשָׂר, וְלָכֵן נִקְרָא ״אַהֲבַת עוֹלָם״ – שֶׁהִיא בְּחִינַת צִמְצוּם אוֹרוֹ הַגָּדוֹל הַבִּלְתִּי תַכְלִית, לְהִתְלַבֵּשׁ בִּבְחִינַת גְּבוּל הַנִּקְרָא ״עוֹלָם״, בַּעֲבוּר אַהֲבַת עַמּוֹ יִשְׂרָאֵל, כְּדֵי לְקָרְבָם אֵלָיו, לִיכָּלֵל בְּיִחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ."],"Tanya, Part I; Likkutei Amarim 49:12":["וְהִנֵּה, כַּאֲשֶׁר יָשִׂים הַמַּשְׂכִּיל אֵלֶּה הַדְּבָרִים אֶל עוּמְקָא דְּלִבָּא וּמוֹחָא, אֲזַי מִמֵּילָא, ״כַּמַּיִם הַפָּנִים לַפָּנִים״ – תִּתְלַהֵט נַפְשׁוֹ וְתִתְלַבֵּשׁ בְּרוּחַ נְדִיבָה, לְהִתְנַדֵּב לְהַנִּיחַ וְלַעֲזוֹב כָּל אֲשֶׁר לוֹ מִנֶּגֶד, וְרַק לְדָבְקָה בּוֹ יִתְבָּרֵךְ וְלִיכָּלֵל בְּאוֹרוֹ בִּדְבִיקָה חֲשִׁיקָה וְכוּ׳, בִּבְחִינַת נְשִׁיקִין וְ״אִתְדַּבְּקוּת רוּחָא בְּרוּחָא״ כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 49:13":["אַךְ אֵיךְ הִיא בְּחִינַת ״אִתְדַּבְּקוּת רוּחָא בְּרוּחָא״? לָזֶה אָמַר: ״וְהָיוּ הַדְּבָרִים הָאֵלֶּה כוּ׳ עַל לְבָבֶךָ, וְדִבַּרְתָּ בָּם כוּ׳״, וּכְמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים, שֶׁיִּחוּד הַנְּשִׁיקִין, עִיקָּרוֹ הוּא יִחוּד חָכְמָה־בִּינָה־דַּעַת בְּחָכְמָה־בִּינָה־דַּעַת, וְהוּא – עִיּוּן הַתּוֹרָה; וְהַפֶּה – הוּא מוֹצָא הָרוּחַ וְגִילּוּיוֹ בִּבְחִינַת גִּילּוּי, וְהַיְינוּ – בְּחִינַת הַדִּבּוּר בְּדִבְרֵי תוֹרָה, ״כִּי עַל מוֹצָא פִי ה׳ יִחְיֶה הָאָדָם״."],"Tanya, Part I; Likkutei Amarim 49:6":["וּבָזֶה יוּבַן טוּב טַעַם וָדַעַת לְתַקָּנַת חֲכָמִים, שֶׁתִּקְּנוּ בִּרְכוֹת קְרִיאַת שְׁמַע ״שְׁתַּיִם לְפָנֶיהָ כוּ׳״, דְּלִכְאוֹרָה, אֵין לָהֶם שַׁיָּיכוּת כְּלָל עִם קְרִיאַת שְׁמַע, כְּמוֹ שֶׁכָּתְבוּ הָרַשְׁבָּ״א וּשְׁאָר פּוֹסְקִים, וְלָמָּה קָרְאוּ אוֹתָן ״בִּרְכוֹת קְרִיאַת שְׁמַע״? וְלָמָּה תִּקְּנוּ אוֹתָן לְפָנֶיהָ דַוְוקָא?"],"Tanya, Part I; Likkutei Amarim 49:8":["וְאֵיךְ יָבֹא הָאָדָם הַחוּמְרִי לְמִדָּה זוֹ? לְכָךְ, סִידְּרוּ תְּחִלָּה – בִּרְכַּת ״יוֹצֵר אוֹר״, וְשָׁם נֶאֱמַר וְנִשְׁנָה בַּאֲרִיכוּת עִנְיַן וְסֵדֶר הַמַּלְאָכִים ״הָעוֹמְדִים בְּרוּם עוֹלָם״, לְהוֹדִיעַ גְּדוּלָּתוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא, אֵיךְ שֶׁכּוּלָּם בְּטֵלִים לְאוֹרוֹ יִתְבָּרֵךְ, ״וּמַשְׁמִיעִים בְּיִרְאָה כוּ׳, וּמַקְדִּישִׁים כוּ׳, וְאוֹמְרִים בְּיִרְאָה קָדוֹשׁ כוּ׳״, כְּלוֹמַר, שֶׁהוּא מוּבְדָּל מֵהֶן וְאֵינוֹ מִתְלַבֵּשׁ בָּהֶן בִּבְחִינַת גִּילּוּי, אֶלָּא, ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״ – הִיא כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה וְיִשְׂרָאֵל לְמַטָּה, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part I; Likkutei Amarim 4:1":["וְעוֹד יֵשׁ לְכָל נֶפֶשׁ אֱלֹהִית שְׁלֹשָׁה לְבוּשִׁים, שֶׁהֵם מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁל תַּרְיַ״ג מִצְוֹת הַתּוֹרָה; שֶׁכְּשֶׁהָאָדָם מְקַיֵּים בְּמַעֲשֶׂה כָּל מִצְוֹת מַעֲשִׂיּוֹת, וּבְדִבּוּר הוּא עוֹסֵק בְּפֵירוּשׁ כָּל תַּרְיַ״ג מִצְוֹת וְהִלְכוֹתֵיהֶן, וּבְמַחֲשָׁבָה הוּא מַשִּׂיג כָּל מַה שֶּׁאֶפְשָׁר לוֹ לְהַשִּׂיג בִּפְשַׁט־רֶמֶז־דְּרוּשׁ־סוֹד הַתּוֹרָה – הֲרֵי כְּלָלוּת תַּרְיַ״ג אֵבְרֵי נַפְשׁוֹ מְלוּבָּשִׁים בְּתַרְיַ״ג מִצְוֹת הַתּוֹרָה."],"Tanya, Part I; Likkutei Amarim 4:11":["וּמֵאַחַר שֶׁהַתּוֹרָה וּמִצְוֹתֶיהָ מַלְבִּישִׁים כָּל עֶשֶׂר בְּחִינוֹת הַנֶּפֶשׁ וְכָל תַּרְיַ״ג אֵבָרֶיהָ מֵרֹאשָׁהּ וְעַד רַגְלָהּ, הֲרֵי כּוּלָּהּ צְרוּרָה בִּצְרוֹר הַחַיִּים אֶת ה׳ מַמָּשׁ, וְאוֹר ה׳ מַמָּשׁ מַקִּיפָהּ וּמַלְבִּישָׁהּ מֵרֹאשָׁהּ וְעַד רַגְלָהּ, כְּמוֹ שֶׁכָּתוּב: ״צוּרִי אֶחֱסֶה בּוֹ״, וּכְתִיב: ״כַּצִּנָּה רָצוֹן תַּעְטְרֶנּוּ״, שֶׁהוּא רְצוֹנוֹ וְחָכְמָתוֹ יִתְבָּרֵךְ הַמְלוּבָּשִׁים בְּתוֹרָתוֹ וּמִצְוֹתֶיהָ."],"Tanya, Part I; Likkutei Amarim 4:12":["וְלָכֵן אָמְרוּ: ״יָפָה שָׁעָה אַחַת בִּתְשׁוּבָה וּמַעֲשִׂים טוֹבִים בָּעוֹלָם הַזֶּה מִכָּל חַיֵּי עוֹלָם הַבָּא״, כִּי עוֹלָם הַבָּא הוּא שֶׁנֶּהֱנִין מִזִּיו הַשְּׁכִינָה, שֶׁהוּא תַּעֲנוּג הַהַשָּׂגָה, וְאִי אֶפְשָׁר לְשׁוּם נִבְרָא, אֲפִילוּ מֵהָעֶלְיוֹנִים, לְהַשִּׂיג, כִּי אִם אֵיזוֹ הֶאָרָה מֵאוֹר ה׳, וְלָכֵן נִקְרָא בְּשֵׁם ״זִיו הַשְּׁכִינָה״; אֲבָל הַקָּדוֹשׁ־בָּרוּךְ־הוּא בִּכְבוֹדוֹ וּבְעַצְמוֹ – לֵית מַחֲשָׁבָה תְּפִיסָא בֵיהּ כְּלָל, כִּי אִם כַּאֲשֶׁר תְּפִיסָא וּמִתְלַבֶּשֶׁת בַּתּוֹרָה וּמִצְוֹתֶיהָ, אֲזַי הִיא תְּפִיסָא וּמִתְלַבֶּשֶׁת בְּהַקָּדוֹשׁ־בָּרוּךְ־הוּא מַמָּשׁ, דְּאוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד."],"Tanya, Part I; Likkutei Amarim 4:2":["וּבִפְרָטוּת, בְּחִינוֹת חָכְמָה־בִּינָה־דַּעַת שֶׁבְּנַפְשׁוֹ, מְלוּבָּשׁוֹת בְּהַשָּׂגַת הַתּוֹרָה שֶׁהוּא מַשִּׂיג בִּפְשַׁט־רֶמֶז־דְּרוּשׁ־סוֹד כְּפִי יְכוֹלֶת הַשָּׂגָתוֹ וְשֹׁרֶשׁ נַפְשׁוֹ לְמַעְלָה; וְהַמִּדּוֹת, שֶׁהֵן יִרְאָה וְאַהֲבָה וְעַנְפֵיהֶן וְתוֹלְדוֹתֵיהֶן – מְלוּבָּשׁוֹת בְּקִיּוּם הַמִּצְוֹת בְּמַעֲשֶׂה וּבְדִבּוּר, שֶׁהוּא תַּלְמוּד תּוֹרָה שֶׁכְּנֶגֶד כּוּלָּן."],"Tanya, Part I; Likkutei Amarim 4:5":["וְהִנֵּה, שְׁלֹשָׁה לְבוּשִׁים אֵלּוּ מֵהַתּוֹרָה וּמִצְוֹתֶיהָ, אַף שֶׁנִּקְרָאִים לְבוּשִׁים לְנֶפֶשׁ רוּחַ וּנְשָׁמָה עִם כָּל זֶה, גָּבְהָה וְגָדְלָה מַעֲלָתָם לְאֵין קֵץ וְסוֹף עַל מַעֲלַת נֶפֶשׁ רוּחַ וּנְשָׁמָה עַצְמָן, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר, דְּאוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד, פֵּירוּשׁ: דְּאוֹרַיְיתָא, הִיא חָכְמָתוֹ וּרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וְהַקָּדוֹשׁ־בָּרוּךְ־הוּא בִּכְבוֹדוֹ וּבְעַצְמוֹ – כּוּלָּא חַד, כִּי הוּא הַיּוֹדֵעַ וְהוּא הַמַּדָּע וְכוּ׳, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל בְּשֵׁם הָרַמְבַּ״ם."],"Tanya, Part I; Likkutei Amarim 4:9":["וְלָכֵן נִמְשְׁלָה הַתּוֹרָה לְמַיִם; מַה מַּיִם יוֹרְדִים מִמָּקוֹם גָּבוֹהַּ לְמָקוֹם נָמוּךְ, כָּךְ הַתּוֹרָה יָרְדָה מִמְּקוֹם כְּבוֹדָהּ, שֶׁהִיא רְצוֹנוֹ וְחָכְמָתוֹ יִתְבָּרֵךְ, וְאוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד, וְלֵית מַחֲשָׁבָה תְּפִיסָא בֵיהּ כְּלָל."],"Tanya, Part I; Likkutei Amarim 50:1":["וְהִנֵּה, כָּל בְּחִינוֹת וּמַדְרֵגוֹת אַהֲבָה הַנִּזְכָּרוֹת לְעֵיל – הֵן מִסִּטְרָא דְיַמִּינָא וּבְחִינַת ״כֹּהֵן אִישׁ חֶסֶד״, וְנִקְרָאוֹת ״כֶּסֶף הַקֳּדָשִׁים״, מִלְּשׁוֹן ״נִכְסוֹף נִכְסַפְתָּ לְבֵית אָבִיךָ״."],"Tanya, Part I; Likkutei Amarim 50:6":["וְהִנֵּה, סֵדֶר הָעֲבוֹדָה בְּעֵסֶק הַתּוֹרָה וְהַמִּצְוֹת הַנִּמְשֶׁכֶת מִבְּחִינַת אַהֲבָה עַזָּה זוֹ, הִיא בִּבְחִינַת ״שׁוֹב״ לְבַד, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יְצִירָה: ״וְאִם רָץ לִבְּךָ – שׁוּב לְאֶחָד״, פֵּירוּשׁ ״וְאִם רָץ לִבְּךָ״ – הִיא תְּשׁוּקַת הַנֶּפֶשׁ שֶׁבַּלֵּב בֶּחָלָל הַיְמָנִי, כְּשֶׁמִּתְגַּבֶּרֶת וּמִתְלַהֶבֶת וּמִתְלַהֶטֶת בִּמְאֹד מְאֹד עַד כְּלוֹת הַנֶּפֶשׁ מַמָּשׁ, לְהִשְׁתַּפֵּךְ אֶל חֵיק אָבִיהָ חַיֵּי הַחַיִּים בָּרוּךְ־הוּא, וְלָצֵאת מִמַּאֲסָרָהּ בַּגּוּף הַגּוּפָנִי וְגַשְׁמִי לְדָבְקָה בּוֹ יִתְבָּרֵךְ – אֲזַי, זֹאת יָשִׁיב אֶל לִבּוֹ: מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, כִּי ״עַל כָּרְחָךְ אַתָּה חַי״ בַּגּוּף הַזֶּה לְהַחֲיוֹתוֹ, כְּדֵי לְהַמְשִׁיךְ חַיִּים עֶלְיוֹנִים מֵחַיֵּי הַחַיִּים בָּרוּךְ־הוּא לְמַטָּה, עַל יְדֵי תּוֹרַת חַיִּים, לִהְיוֹת דִּירָה בַּתַּחְתּוֹנִים לְאַחְדּוּתוֹ יִתְבָּרֵךְ בִּבְחִינַת גִּילּוּי, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל, וּכְמוֹ שֶׁכָּתוּב בַּזֹּהַר הַקָּדוֹשׁ: ״לְמֶהֱוֵי אֶחָד בְּאֶחָד״, פֵּירוּשׁ, שֶׁהַיִּחוּד הַנֶּעְלָם יִהְיֶה בִּבְחִינַת ״עָלְמָא דְאִתְגַּלְיָא״."],"Tanya, Part I; Likkutei Amarim 51:1":["וְהִנֵּה, לְתוֹסֶפֶת בֵּיאוּר לְשׁוֹן הַיַּנּוּקָא דִלְעֵיל, צָרִיךְ לְבָאֵר תְּחִלָּה, לְהָבִין קְצָת עִנְיַן הַשְׁרָאַת הַשְּׁכִינָה שֶׁהָיְתָה שׁוֹרָה בְּבֵית קָדְשֵׁי קָדָשִׁים, וְכֵן כָּל מְקוֹם הַשְׁרָאַת הַשְּׁכִינָה, מָה עִנְיָינוֹ? הֲלֹא ״מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ״, וְ״לֵית אֲתַר פָּנוּי מִינֵּיהּ״!"],"Tanya, Part I; Likkutei Amarim 51:4":["וְהִנֵּה, עַל הַמְשָׁכַת כָּל הַתַּרְיַ״ג מִינֵי כֹּחוֹת וְחַיּוּת מֵהֶעְלֵם הַנְּשָׁמָה אֶל הַגּוּף לְהַחֲיוֹתוֹ – עָלֶיהָ אָמְרוּ, שֶׁעִיקַּר מִשְׁכָּנָהּ וְהַשְׁרָאָתָהּ שֶׁל הַמְשָׁכָה זוֹ וְגִילּוּי זֶה – הוּא כּוּלּוֹ בַּמּוֹחִין שֶׁבָּרֹאשׁ, וְלָכֵן הֵם מְקַבְּלִים תְּחִלָּה הַכֹּחַ וְהַחַיּוּת הָרָאוּי לָהֶם לְפִי מִזְגָּם וּתְכוּנָתָם, שֶׁהֵן חָכְמָה־בִּינָה־דַּעַת וְכֹחַ הַמַּחֲשָׁבָה וְכָל הַשַּׁיָּיךְ לַמּוֹחִין. וְלֹא זוֹ בִּלְבָד, אֶלָּא גַּם כְּלָלוּת כָּל הַמְשָׁכוֹת הַחַיּוּת לִשְׁאָר הָאֵבָרִים, גַּם כֵּן כְּלוּלָה וּמְלוּבֶּשֶׁת בַּמּוֹחִין שֶׁבָּרֹאשׁ, וְשָׁם הוּא עִיקָּרָהּ וְשָׁרְשָׁהּ שֶׁל הַמְשָׁכָה זוֹ, בִּבְחִינַת גִּילּוּי הָאוֹר וְהַחַיּוּת שֶׁל כָּל הַנְּשָׁמָה כוּלָּהּ, וּמִשָּׁם מִתְפַּשֶּׁטֶת הֶאָרָה לִשְׁאָר כָּל הָאֵבָרִים, וּמְקַבֵּל כָּל אֶחָד כֹּחַ וְחַיוּת הָרָאוּי לוֹ כְּפִי מִזְגּוֹ וּתְכוּנָתוֹ: כֹּחַ הָרְאִיָּה מִתְגַּלֶּה בָּעַיִן, וְכֹחַ הַשְּׁמִיעָה בָּאוֹזֶן וְכוּ׳. וְכָל הַכֹּחוֹת מִתְפַּשְּׁטִים מֵהַמּוֹחַ כַּנּוֹדָע, כִּי שָׁם הוּא עִיקַּר מִשְׁכַּן הַנְּשָׁמָה כוּלָּהּ בִּבְחִינַת גִּילּוּי, שֶׁנִּגְלֵית שָׁם כְּלָלוּת הַחַיּוּת הַמִּתְפַּשֵּׁט מִמֶּנָּה. רַק כֹּחוֹתֶיהָ שֶׁל כְּלָלוּת הַחַיּוּת מְאִירִים וּמִתְפַּשְּׁטִים מִשָּׁם לְכָל אֵבְרֵי הַגּוּף, כְּדִמְיוֹן הָאוֹר הַמִּתְפַּשֵּׁט וּמֵאִיר מֵהַשֶּׁמֶשׁ לְחַדְרֵי חֲדָרִים. [וַאֲפִילוּ הַלֵּב – מְקַבֵּל מֵהַמּוֹחַ, וְלָכֵן הַמּוֹחַ שַׁלִּיט עָלָיו בְּתוֹלַדְתּוֹ, כַּנִּזְכָּר לְעֵיל]."],"Tanya, Part I; Likkutei Amarim 51:5":["וְכָכָה מַמָּשׁ, עַל דֶּרֶךְ מָשָׁל, אֵין־סוֹף בָּרוּךְ־הוּא מְמַלֵּא כָּל עָלְמִין לְהַחֲיוֹתָם, וּבְכָל עוֹלָם יֵשׁ בְּרוּאִים לְאֵין קֵץ וְתַכְלִית, רִבּוֹא רְבָבוֹת מִינֵי מַדְרֵגוֹת מַלְאָכִים וּנְשָׁמוֹת כוּ׳, וְכֵן רִיבּוּי הָעוֹלָמוֹת אֵין לוֹ קֵץ וּגְבוּל, גָּבוֹהַּ עַל גָּבוֹהַּ כוּ׳."],"Tanya, Part I; Likkutei Amarim 51:7":["וְהַהֶבְדֵּל שֶׁבֵּין עוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, הוּא מִצַּד הַמְשָׁכַת הַחַיּוּת אֲשֶׁר אֵין־סוֹף בָּרוּךְ־הוּא מַמְשִׁיךְ וּמֵאִיר בִּבְחִינַת גִּילּוּי מֵהַהֶעְלֵם [שֶׁזֶּה אֶחָד מֵהַטְּעָמִים שֶׁהַהַשְׁפָּעָה וְהַמְשָׁכַת הַחַיּוּת מְכוּנָּה בְּשֵׁם ״אוֹר״ עַל דֶּרֶךְ מָשָׁל], לְהַחֲיוֹת הָעוֹלָמוֹת וְהַבְּרוּאִים שֶׁבָּהֶם, שֶׁהָעוֹלָמוֹת הָעֶלְיוֹנִים מְקַבְּלִים בִּבְחִינַת גִּילּוּי קְצָת יוֹתֵר מֵהַתַּחְתּוֹנִים, וְכָל הַבְּרוּאִים שֶׁבָּהֶם מְקַבְּלִים כָּל אֶחָד כְּפִי כֹּחוֹ וּתְכוּנָתוֹ, שֶׁהִיא תְּכוּנַת וּבְחִינַת הַמְשָׁכָה הַפְּרָטִית אֲשֶׁר אֵין־סוֹף בָּרוּךְ־הוּא מַמְשִׁיךְ וּמֵאִיר לוֹ."],"Tanya, Part I; Likkutei Amarim 51:9":["וְכָל כָּךְ עָצְמוּ וְגָבְרוּ הַלְּבוּשִׁים אֲשֶׁר אֵין־סוֹף בָּרוּךְ־הוּא מַלְבִּישׁ וּמַסְתִּיר בָּהֶם הָאוֹר וְהַחַיּוּת, עַד אֲשֶׁר בָּרָא בוֹ עוֹלָם הַזֶּה הַחוּמְרִי וְהַגַּשְׁמִי מַמָּשׁ, וּמְהַוֵּוהוּ וּמְחַיֵּיהוּ בְּחַיּוּת וְאוֹר אֲשֶׁר מַמְשִׁיךְ וּמֵאִיר לוֹ, אוֹר הַמְלוּבָּשׁ וּמְכוּסֶּה וּמוּסְתָּר בְּתוֹךְ הַלְּבוּשִׁים הָרַבִּים וְהָעֲצוּמִים הַמַּעֲלִימִים וּמַסְתִּירִים הָאוֹר וְהַחַיּוּת, עַד שֶׁאֵין נִרְאֶה וְנִגְלֶה שׁוּם אוֹר וְחַיּוּת רַק דְּבָרִים חוּמְרִיִּים וְגַשְׁמִיִּים, וְנִרְאִים מֵתִים, אַךְ בְּתוֹכָם – יֵשׁ אוֹר וְחַיּוּת הַמְהַוֶּה אוֹתָם מֵאַיִן לְיֵשׁ תָּמִיד, שֶׁלֹּא יַחְזְרוּ לִהְיוֹת אַיִן וָאֶפֶס כְּשֶׁהָיוּ, וְאוֹר זֶה הוּא מֵאֵין־סוֹף בָּרוּךְ־הוּא, רַק שֶׁנִּתְלַבֵּשׁ בִּלְבוּשִׁים רַבִּים, וּכְמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים, שֶׁאוֹר וְחַיּוּת כַּדּוּר הָאָרֶץ הַחוּמְרִי הַנִּרְאֶה לְעֵינֵי בָשָׂר, הוּא מִמַּלְכוּת דְּמַלְכוּת דַּעֲשִׂיָּה, וּבְתוֹכָהּ – מַלְכוּת דִּיצִירָה וְכוּ׳, עַד שֶׁבְּתוֹךְ כּוּלָּן – י׳ סְפִירוֹת דַּאֲצִילוּת הַמְיוּחָדוֹת בְּמַאֲצִילָן אֵין־סוֹף בָּרוּךְ־הוּא:"],"Tanya, Part I; Likkutei Amarim 52:1":["וּכְמוֹ שֶׁבְּנִשְׁמַת הָאָדָם עִיקַּר גִּילּוּי כְּלָלוּת הַחַיּוּת – הוּא בַּמּוֹחִין, וְכָל הָאֵבָרִים, מְקַבְּלִים אוֹר וְכֹחַ לְבַד, הַמֵּאִיר לָהֶם מִמְּקוֹר גִּילּוּי הַחַיּוּת שֶׁבַּמּוֹחִין – כָּכָה מַמָּשׁ, עַל דֶּרֶךְ מָשָׁל, עִיקַּר גִּילּוּי כְּלָלוּת הַמְשָׁכַת הַחַיּוּת, לְהַחֲיוֹת הָעוֹלָמוֹת וְהַבְּרוּאִים שֶׁבָּהֶם – הוּא מְלוּבָּשׁ וְנִכְלָל בִּרְצוֹנוֹ וְחָכְמָתוֹ וּבִינָתוֹ וְדַעְתּוֹ יִתְבָּרֵךְ, הַנִּקְרָאִין בְּשֵׁם ״מוֹחִין״, וְהֵן הֵן הַמְלוּבָּשִׁים בַּתּוֹרָה וּמִצְוֹתֶיהָ."],"Tanya, Part I; Likkutei Amarim 52:5":["אֲבָל הַשְּׁכִינָה עַצְמָהּ, שֶׁהִיא רֵאשִׁית הַגִּילּוּי וְעִיקָּרוֹ, מַה שֶּׁאֵין־סוֹף בָּרוּךְ־הוּא מֵאִיר לָעוֹלָמוֹת בִּבְחִינַת גִּילּוּי, וְהִיא מְקוֹר כָּל הַמְשָׁכוֹת הַחַיּוּת שֶׁבְּכָל הָעוֹלָמוֹת [שֶׁכָּל הַחַיּוּת שֶׁבָּהֶם, אֵינוֹ רַק אוֹר הַמִּתְפַּשֵּׁט מִמֶּנָּה – כָּאוֹר הַמִּתְפַּשֵּׁט מֵהַשֶּׁמֶשׁ] – אִי אֶפְשָׁר לָעוֹלָמוֹת לִסְבּוֹל וּלְקַבֵּל אוֹר שְׁכִינָתָהּ, שֶׁתִּשְׁכּוֹן וְתִתְלַבֵּשׁ בְּתוֹכָם מַמָּשׁ, בְּלֹא לְבוּשׁ הַמַּעֲלִים וּמַסְתִּיר אוֹרָהּ מֵהֶם, שֶׁלֹּא יִתְבַּטְּלוּ בִּמְצִיאוּת לְגַמְרֵי בִּמְקוֹרָם, כְּבִיטּוּל אוֹר הַשֶּׁמֶשׁ בִּמְקוֹרוֹ בְּגוּף הַשֶּׁמֶשׁ, שֶׁאֵין נִרְאֶה שָׁם אוֹר זֶה, רַק עֶצֶם גּוּף הַשֶּׁמֶשׁ בִּלְבָד."],"Tanya, Part I; Likkutei Amarim 52:7":["וּבִירִידָתָהּ בְּהִשְׁתַּלְשְׁלוּת מֵעוֹלָם לְעוֹלָם – גַּם הַשְּׁכִינָה יָרְדָה וְנִתְלַבְּשָׁה בָּהּ בְּכָל עוֹלָם וְעוֹלָם, וְזֶהוּ הֵיכַל קָדְשֵׁי קָדָשִׁים שֶׁבְּכָל עוֹלָם וְעוֹלָם, וּכְמוֹ שֶׁכָּתוּב בַּזֹּהַר וְעֵץ חַיִּים, שֶׁהַשְּׁכִינָה, שֶׁהִיא מַלְכוּת דַּאֲצִילוּת [שֶׁהִיא בְּחִינַת גִּילּוּי אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא וְחַיּוּת שֶׁמֵּאִיר לָעוֹלָמוֹת, וְלָכֵן הִיא נִקְרֵאת ״דְּבַר ה׳״ וְ״רוּחַ פִּיו״, כִּבְיָכוֹל עַל דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁבָּאָדָם הַדִּבּוּר הוּא מְגַלֶּה מַחֲשַׁבְתּוֹ הַסְּתוּמָה וְנֶעְלָמָה לְהַשּׁוֹמְעִים] – הִיא מִתְלַבֶּשֶׁת בְּהֵיכַל קָדְשֵׁי קָדָשִׁים דִּבְרִיאָה, שֶׁהִיא חָכְמָה־בִּינָה־דַּעַת דִּבְרִיאָה, וּבְהִתְלַבְּשׁוּתָן בְּמַלְכוּת דִּבְרִיאָה – נִבְרְאוּ הַנְּשָׁמוֹת וְהַמַּלְאָכִים שֶׁבַּבְּרִיאָה."],"Tanya, Part I; Likkutei Amarim 52:9":["וּבְהִתְלַבְּשׁוּת מַלְכוּת דַּאֲצִילוּת בְּמַלְכוּת דִּבְרִיאָה, מִתְלַבֶּשֶׁת בְּהֵיכַל קָדְשֵׁי קָדָשִׁים דִּיצִירָה שֶׁהוּא חָכְמָה־בִּינָה־דַּעַת דִּיצִירָה. וּבְהִתְלַבְּשׁוּתָן בְּמַלְכוּת דִּיצִירָה – נוֹצְרוּ הָרוּחוֹת וְהַמַּלְאָכִים שֶׁבִּיצִירָה."],"Tanya, Part I; Likkutei Amarim 53:1":["וְהִנֵּה, כְּשֶׁהָיָה בַּיִת רִאשׁוֹן קַיָּים, שֶׁבּוֹ הָיָה הָאָרוֹן וְהַלּוּחוֹת בְּבֵית קָדְשֵׁי קָדָשִׁים – הָיְתָה הַשְּׁכִינָה, שֶׁהִיא מַלְכוּת דַּאֲצִילוּת, שֶׁהִיא בְּחִינַת גִּילּוּי אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, שׁוֹרָה שָׁם, וּמְלוּבֶּשֶׁת בַּעֲשֶׂרֶת הַדִּבְּרוֹת, בְּיֶתֶר שְׂאֵת וְיֶתֶר עֹז, בְּגִילּוּי רַב וְעָצוּם יוֹתֵר מִגִּילּוּיָהּ בְּהֵיכְלוֹת קָדְשֵׁי קָדָשִׁים שֶׁלְּמַעְלָה בְּעוֹלָמוֹת עֶלְיוֹנִים."],"Tanya, Part I; Likkutei Amarim 53:3":["וּבְבַיִת שֵׁנִי שֶׁלֹּא הָיָה בוֹ הָאָרוֹן וְהַלּוּחוֹת, אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁלֹּא הָיְתָה שְׁכִינָה שׁוֹרָה בּוֹ, פֵּירוּשׁ, מַדְרֵגַת שְׁכִינָה שֶׁהָיְתָה שׁוֹרָה בְּבַיִת רִאשׁוֹן שֶׁלֹּא כְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת. אֶלָּא, בְּבַיִת שֵׁנִי, הָיְתָה שׁוֹרָה כְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וְהִתְלַבְּשׁוּת מַלְכוּת דַּאֲצִילוּת בְּמַלְכוּת דִּבְרִיאָה, וְדִבְרִיאָה בְּמַלְכוּת דִּיצִירָה, וְדִיצִירָה בְּהֵיכַל קָדְשֵׁי קָדָשִׁים דַּעֲשִׂיָּה, וְקָדְשֵׁי קָדָשִׁים דַּעֲשִׂיָּה הָיָה מִתְלַבֵּשׁ בְּקָדְשֵׁי קָדָשִׁים שֶׁבְּבֵית הַמִּקְדָּשׁ שֶׁלְּמַטָּה, וְשָׁרְתָה בּוֹ הַשְּׁכִינָה – מַלְכוּת דִּיצִירָה הַמְלוּבֶּשֶׁת בְּקָדְשֵׁי קָדָשִׁים דַּעֲשִׂיָּה, וְלָכֵן לֹא הָיָה רַשַּׁאי שׁוּם אָדָם לִיכָּנֵס שָׁם, לְבַד כֹּהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים. – וּ״מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ אֵין לוֹ לְהַקָּדוֹשׁ־בָּרוּךְ־הוּא בְּעוֹלָמוֹ אֶלָּא ד׳ אַמּוֹת שֶׁל הֲלָכָה בִּלְבָד״, וַ״אֲפִילוּ אֶחָד שֶׁיּוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה – שְׁכִינָה עִמּוֹ״, כִּדְאִיתָא בִּבְרָכוֹת פֶּרֶק קַמָּא, פֵּירוּשׁ ״שְׁכִינָה עִמּוֹ״ – כְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וְהִתְלַבְּשׁוּת מַלְכוּת דַּאֲצִילוּת בְּמַלְכוּת דִּבְרִיאָה וִיצִירָה וַעֲשִׂיָּה."],"Tanya, Part I; Likkutei Amarim 53:6":["וְזֶהוּ שֶׁאָמַר הַיַּנּוּקָא: ״דִּנְהוֹרָא עִילָּאָה דְּאַדְלִיק עַל רֵישֵׁיהּ״ הִיא שְׁכִינְתָּא – ״אִצְטְרִיךְ לְמִשְׁחָא״, פֵּירוּשׁ, לְהִתְלַבֵּשׁ בְּחָכְמָה, הַנִּקְרֵאת ״שֶׁמֶן מִשְׁחַת קֹדֶשׁ״, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר, וְ״אִינוּן עוֹבָדִין טָבִין״ – הֵן תַּרְיַ״ג מִצְוֹת הַנִּמְשָׁכוֹת מֵחָכְמָתוֹ יִתְבָּרֵךְ, כְּדֵי לֶאֱחוֹז אוֹר הַשְּׁכִינָה בַּפְּתִילָה, הִיא נֶפֶשׁ הַחִיּוּנִית שֶׁבַּגּוּף, הַנִּקְרֵאת פְּתִילָה עַל דֶּרֶךְ מָשָׁל. כִּי, כְּמוֹ שֶׁבַּנֵּר הַגַּשְׁמִי, הָאוֹר מֵאִיר עַל יְדֵי כִּלְיוֹן וּשְׂרֵיפַת הַפְּתִילָה הַנֶּהְפֶּכֶת לְאֵשׁ, כָּךְ, אוֹר הַשְּׁכִינָה שׁוֹרֶה עַל נֶפֶשׁ הָאֱלֹהִית עַל יְדֵי כִּלְיוֹן נֶפֶשׁ הַבַּהֲמִית וְהִתְהַפְּכוּתָהּ מֵחֲשׁוֹכָא לִנְהוֹרָא וּמִמְּרִירוּ לְמִתְקָא – בַּצַּדִּיקִים, אוֹ לְפָחוֹת, עַל יְדֵי כִּלְיוֹן לְבוּשֶׁיהָ שֶׁהֵן מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה, וְהִתְהַפְּכוּתָן מֵחֹשֶׁךְ הַקְּלִיפּוֹת לְאוֹר ה׳ אֵין־סוֹף בָּרוּךְ־הוּא הַמְלוּבָּש וּמְיוּחָד בְּמַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה שֶׁל תַּרְיַ״ג מִצְוֹת הַתּוֹרָה – בַּבֵּינוֹנִים."],"Tanya, Part I; Likkutei Amarim 5:1":["וּלְתוֹסֶפֶת בֵּיאוּר, בַּאֵר הֵיטֵב לְשׁוֹן ״תְּפִיסָא״ שֶׁאָמַר אֵלִיָּהוּ: ״לֵית מַחֲשָׁבָה תְּפִיסָא בָךְ כוּ׳״."],"Tanya, Part I; Likkutei Amarim 5:7":["וְזֹאת מַעֲלָה יְתֵרָה גְּדוֹלָה וְנִפְלָאָה לְאֵין קֵץ אֲשֶׁר בְּמִצְוַת יְדִיעַת הַתּוֹרָה וְהַשָּׂגָתָהּ עַל כָּל הַמִּצְוֹת מַעֲשִׂיּוֹת, וַאֲפִילוּ עַל מִצְוֹת הַתְּלוּיוֹת בְּדִבּוּר, וַאֲפִילוּ עַל מִצְוַת תַּלְמוּד תּוֹרָה שֶׁבְּדִבּוּר."],"Tanya, Part I; Likkutei Amarim 6:1":["וְהִנֵּה, זֶה לְעוּמַּת זֶה עָשָׂה אֱלֹהִים."],"Tanya, Part I; Likkutei Amarim 6:4":["וְהֵן הֵם כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשִׂים תַּחַת הַשֶּׁמֶשׁ, אֲשֶׁר ״הַכֹּל הֶבֶל וּרְעוּת רוּחַ״, וּכְמוֹ שֶׁכָּתוּב בַּזֹּהַר בְּשַׁלַּח, שֶׁהֵן ״תְּבִירוּ דְרוּחָא כוּ׳״, וְכֵן כָּל הַדִּבּוּרִים וְכָל הַמַּחֲשָׁבוֹת אֲשֶׁר לֹא לַה׳ הֵמָּה וְלִרְצוֹנוֹ וְלַעֲבוֹדָתוֹ, שֶׁזֶּהוּ פֵּירוּשׁ לְשׁוֹן ״סִטְרָא אָחֳרָא״, פֵּירוּשׁ – צַד אַחֵר, שֶׁאֵינוֹ צַד הַקְּדוּשָּׁה."],"Tanya, Part I; Likkutei Amarim 6:7":["אֲבָל כָּל מַה שֶּׁאֵינוֹ בָּטֵל אֶצְלוֹ יִתְבָּרֵךְ, אֶלָּא הוּא דָּבָר נִפְרָד בִּפְנֵי עַצְמוֹ, אֵינוֹ מְקַבֵּל חַיּוּת מִקְּדוּשָּׁתוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא מִבְּחִינַת פְּנִימִית הַקְּדוּשָּׁה וּמַהוּתָהּ וְעַצְמוּתָהּ בִּכְבוֹדָהּ וּבְעַצְמָהּ, אֶלָּא מִבְּחִינַת אֲחוֹרַיִים, שֶׁיּוֹרְדִים מִמַּדְרֵגָה לְמַדְרֵגָה רִבְבוֹת מַדְרֵגוֹת, בְּהִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת דֶּרֶךְ עִלָּה וְעָלוּל וְצִמְצוּמִים רַבִּים, עַד שֶׁנִּתְמַעֵט כָּל כָּךְ הָאוֹר וְהַחַיּוּת, מִיעוּט אַחַר מִיעוּט, עַד שֶׁיָּכוֹל לְהִתְצַמְצֵם וּלְהִתְלַבֵּשׁ בִּבְחִינַת גָּלוּת תּוֹךְ אוֹתוֹ דָּבָר הַנִּפְרָד, לְהַחֲיוֹתוֹ וּלְקַיְּימוֹ מֵאַיִן לְיֵשׁ, שֶׁלֹּא יַחֲזוֹר לִהְיוֹת אַיִן וָאֶפֶס כְּבַתְּחִלָּה מִקּוֹדֶם שֶׁנִּבְרָא."],"Tanya, Part I; Likkutei Amarim 6:8":["וְלָכֵן נִקְרָא עוֹלָם הַזֶּה וּמְלוֹאוֹ, עוֹלַם הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא. וְלָכֵן כָּל מַעֲשֵׂה עוֹלָם הַזֶּה קָשִׁים וְרָעִים, וְהָרְשָׁעִים גּוֹבְרִים בּוֹ, כְּמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים שַׁעַר מ״ב סוֹף פֶּרֶק ד׳."],"Tanya, Part I; Likkutei Amarim 7:1":["אַךְ נֶפֶשׁ הַחִיּוּנִית הַבַּהֲמִית שֶׁבְּיִשְׂרָאֵל שֶׁמִּצַּד הַקְּלִיפָּה, הַמְלוּבֶּשֶׁת בְּדַם הָאָדָם כַּנִּזְכָּר לְעֵיל, וְנַפְשׁוֹת בְּהֵמוֹת וְחַיּוֹת וְעוֹפוֹת וְדָגִים טְהוֹרִים וּמוּתָּרִים בַּאֲכִילָה, וְקִיּוּם וְחַיּוּת כָּל הַדּוֹמֵם וְכָל הַצּוֹמֵחַ הַמּוּתָּר בַּאֲכִילָה, וְכֵן קִיּוּם וְחַיּוּת כָּל הַמַּעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה בְּעִנְיְינֵי עוֹלָם הַזֶּה שֶׁאֵין בָּהֶם צַד אִיסּוּר, לֹא שֹׁרֶשׁ וְלֹא עָנָף מִשַּׁסַ״ה מִצְוֹת לֹא תַעֲשֶׂה וְעַנְפֵיהֶן דְּאוֹרַיְיתָא וּדְרַבָּנָן, רַק שֶׁאֵינָן לְשֵׁם שָׁמַיִם – אֶלָּא רְצוֹן הַגּוּף וְחֶפְצוֹ וְתַאֲוָתוֹ, וַאֲפִילוּ הוּא צוֹרֶךְ הַגּוּף וְקִיּוּמוֹ וְחַיּוּתוֹ מַמָּשׁ, אֶלָּא שֶׁכַּוָּונָתוֹ אֵינָהּ לְשֵׁם שָׁמַיִם כְּדֵי לַעֲבוֹד אֶת ה׳ בְּגוּפוֹ – לָא עֲדִיפֵי מַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבוֹת אֵלּוּ מִנֶּפֶשׁ הַחִיּוּנִית הַבַּהֲמִית בְּעַצְמָהּ, וְהַכֹּל כַּאֲשֶׁר לַכֹּל, נִשְׁפָּע וְנִמְשָׁךְ מִמַּדְרֵגָה הַשֵּׁנִית שֶׁבִּקְלִיפּוֹת וְסִטְרָא אָחֳרָא, שֶׁהִיא קְלִיפָּה רְבִיעִית הַנִּקְרֵאת ״קְלִיפַּת נוֹגַהּ״, שֶׁבָּעוֹלָם הַזֶּה, הַנִּקְרָא ״עוֹלַם הָעֲשִׂיָּה״, רוּבּוֹ כְּכוּלּוֹ רָע, רַק מְעַט טוֹב מְעוֹרָב בְּתוֹכָהּ [שֶׁמִּמֶּנָּה בָּאוֹת מִדּוֹת טוֹבוֹת שֶׁבַּנֶּפֶשׁ הַבַּהֲמִית שֶׁבְּיִשְׂרָאֵל, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל]."],"Tanya, Part I; Likkutei Amarim 7:12":["אַךְ הַחַיּוּת שֶׁבְּטִפּוֹת זֶרַע שֶׁיָּצְאוּ מִמֶּנּוּ לְבַטָּלָה, אַף שֶׁיָּרְדָה וְנִכְלְלָה בְּשָׁלשׁ קְלִיפּוֹת הַטְּמֵאוֹת – הֲרֵי זוֹ עוֹלָה מִשָּׁם בִּתְשׁוּבָה נְכוֹנָה, וּבְכַוָּונָה עֲצוּמָה בִּקְרִיאַת־שְׁמַע־שֶׁעַל־הַמִּטָּה, כַּנּוֹדָע מֵהָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה, וּמְרוּמָּז בַּגְּמָרָא: ״כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע עַל מִטָּתוֹ כְּאִלּוּ אוֹחֵז חֶרֶב שֶׁל שְׁתֵּי פִיּוֹת כוּ׳״, לַהֲרוֹג גּוּפוֹת הַחִיצוֹנִים שֶׁנַּעֲשׂוּ לְבוּשׁ לַחַיּוּת שֶׁבַּטִּפּוֹת, וְעוֹלָה הַחַיּוּת מֵהֶם, כַּיָּדוּעַ לְיוֹדְעֵי חֵן."],"Tanya, Part I; Likkutei Amarim 7:6":["אַךְ מִי שֶׁהוּא בְּזוֹלְלֵי בָּשָׂר וְסוֹבְאֵי יַיִן, לְמַלֹּאת תַּאֲוַת גּוּפוֹ וְנַפְשׁוֹ הַבַּהֲמִית, שֶׁהוּא בְּחִינַת יְסוֹד הַמַּיִם מֵאַרְבַּע יְסוֹדוֹת הָרָעִים שֶׁבָּהּ שֶׁמִּמֶּנּוּ מִדַּת הַתַּאֲוָה, הִנֵּה עַל יְדֵי זֶה יוֹרֵד חַיּוּת הַבָּשָׂר וְהַיַּיִן שֶׁבְּקִרְבּוֹ, וְנִכְלָל לְפִי שָׁעָה בְּרַע גָּמוּר שֶׁבְּשָׁלֹשׁ קְלִיפּוֹת הַטְּמֵאוֹת, וְגוּפוֹ נַעֲשֶׂה לָהֶן לְבוּשׁ וּמֶרְכָּבָה לְפִי שָׁעָה. עַד אֲשֶׁר יָשׁוּב הָאָדָם וְיַחֲזוֹר לַעֲבוֹדַת ה׳ וּלְתוֹרָתוֹ, כִּי לְפִי שֶׁהָיָה בְּשַׂר הֶיתֵּר וְיַיִן כָּשֵׁר, לְכָךְ יְכוֹלִים לַחֲזוֹר וְלַעֲלוֹת עִמּוֹ בְּשׁוּבוֹ לַעֲבוֹדַת ה׳, שֶׁזֶּהוּ לְשׁוֹן ״הֶיתֵּר״ וּ״מוּתָּר״, כְּלוֹמַר שֶׁאֵינוֹ קָשׁוּר וְאָסוּר בִּידֵי הַחִיצוֹנִים שֶׁלֹּא יוּכַל לַחֲזוֹר וְלַעֲלוֹת לַה׳."],"Tanya, Part I; Likkutei Amarim 8:1":["וְעוֹד זֹאת בְּמַאֲכָלוֹת אֲסוּרוֹת, שֶׁלְּכָךְ נִקְרָאִים בְּשֵׁם ״אִיסּוּר״, מִפְּנֵי שֶׁאַף מִי שֶׁאָכַל מַאֲכַל אִיסּוּר בְּלֹא הוֹדַע – לְשֵׁם שָׁמַיִם, לַעֲבוֹד ה׳ בְּכֹחַ אֲכִילָה הַהִיא, וְגַם פָּעַל וְעָשָׂה כֵּן, וְקָרָא וְהִתְפַּלֵּל בְּכֹחַ אֲכִילָה הַהִיא, אֵין הַחַיּוּת שֶׁבָּהּ עוֹלָה וּמִתְלַבֶּשֶׁת בְּתֵיבוֹת הַתּוֹרָה וְהַתְּפִלָּה כְּמוֹ הַהֶיתֵּר, מִפְּנֵי אִיסּוּרָהּ בִּידֵי הַסִּטְרָא אָחֳרָא מִשָּׁלֹשׁ קְלִיפּוֹת הַטְּמֵאוֹת. וַאֲפִילוּ הוּא אִיסּוּר דְּרַבָּנָן, שֶׁחֲמוּרִים דִּבְרֵי סוֹפְרִים יוֹתֵר מִדִּבְרֵי תוֹרָה כוּ׳."],"Tanya, Part I; Likkutei Amarim 8:5":["וְעַל דְּבָרִים בְּטֵלִים בְּהֶיתֵּר, כְּגוֹן עַם הָאָרֶץ שֶׁאֵינוֹ יָכוֹל לִלְמוֹד, צָרִיךְ לְטַהֵר נַפְשׁוֹ מִטּוּמְאָה זוֹ דִּקְלִיפָּה זוֹ, עַל יְדֵי גִּלְגּוּלָהּ בְּכַף הַקֶּלַע, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר פָּרָשַׁת בְּשַׁלַּח דַּף נ״ט."],"Tanya, Part I; Likkutei Amarim 9:1":["וְהִנֵּה, מְקוֹם מִשְׁכַּן נֶפֶשׁ הַבַּהֲמִית שֶׁמִּקְּלִיפַּת נוֹגַהּ בְּכָל אִישׁ יִשְׂרָאֵל, הוּא בַּלֵּב בְּחָלָל שְׂמָאלִי שֶׁהוּא מָלֵא דָם, וּכְתִיב: ״כִּי הַדָּם הוּא הַנָּפֶשׁ״."],"Tanya, Part I; Likkutei Amarim 9:5":["אַךְ הִנֵּה כְּתִיב: ״וּלְאוֹם מִלְאוֹם יֶאֱמָץ״, כִּי הַגּוּף נִקְרָא ״עִיר קְטַנָּה״, וּכְמוֹ שֶׁשְּׁנֵי מְלָכִים נִלְחָמִים עַל עִיר אַחַת, שֶׁכָּל אֶחָד רוֹצֶה לְכָבְשָׁהּ וְלִמְלוֹךְ עָלֶיהָ, דְּהַיְינוּ, לְהַנְהִיג יוֹשְׁבֶיהָ כִּרְצוֹנוֹ וְשֶׁיִּהְיוּ סָרִים לְמִשְׁמַעְתּוֹ בְּכָל אֲשֶׁר יִגְזוֹר עֲלֵיהֶם, כָּךְ שְׁתֵּי הַנְּפָשׁוֹת, הָאֱלֹהִית וְהַחִיּוּנִית הַבַּהֲמִית שֶׁמֵּהַקְּלִיפָּה, נִלְחָמוֹת זוֹ עִם זוֹ עַל הַגּוּף וְכָל אֵבָרָיו, שֶׁהָאֱלֹהִית – חֶפְצָהּ וּרְצוֹנָהּ שֶׁתְּהֵא הִיא לְבַדָּהּ הַמּוֹשֶׁלֶת עָלָיו וּמַנְהִיגָתוֹ, וְכָל הָאֵבָרִים יִהְיוּ סָרִים לְמִשְׁמַעְתָּהּ וּבְטֵלִים אֶצְלָהּ לְגַמְרֵי, וּמֶרְכָּבָה אֵלֶיהָ, וְיִהְיוּ לְבוּשׁ לְעֶשֶׂר בְּחִינוֹתֶיהָ וְג׳ לְבוּשֶׁיהָ הַנִּזְכָּרִים לְעֵיל, שֶׁיִּתְלַבְּשׁוּ כוּלָּם בְּאֵבְרֵי הַגּוּף, וְיִהְיֶה הַגּוּף כּוּלּוֹ מָלֵא מֵהֶם לְבַדָּם, וְלֹא יַעֲבוֹר זָר בְּתוֹכָם חַס וְשָׁלוֹם, דְּהַיְינוּ, תְּלַת מוֹחִין שֶׁבָּרֹאשׁ יִהְיוּ מְמוּלָּאִים מֵחָכְמָה־בִּינָה־דַּעַת שֶׁבַּנֶּפֶשׁ הָאֱלֹהִית, שֶׁהִיא חָכְמַת ה׳ וּבִינָתוֹ, לְהִתְבּוֹנֵן בִּגְדוּלָּתוֹ אֲשֶׁר עַד אֵין חֵקֶר וְאֵין סוֹף, וּלְהוֹלִיד מֵהֶן – עַל יְדֵי הַדַּעַת, הַיִּרְאָה בְּמוֹחוֹ וּפַחַד ה׳ בְּלִבּוֹ, וְאַהֲבַת ה׳ כְּאֵשׁ בּוֹעֲרָה בְּלִבּוֹ כְּרִשְׁפֵּי שַׁלְהֶבֶת, לִהְיוֹת נִכְסְפָה וְגַם כָּלְתָה נַפְשׁוֹ בַּחֲשִׁיקָה וַחֲפִיצָה לְדָבְקָה בוֹ בְּאֵין־סוֹף בָּרוּךְ־הוּא בְּכָל לֵב וְנֶפֶשׁ וּמְאֹד מֵעוּמְקָא דְלִבָּא שֶׁבֶּחָלָל הַיְמָנִי, שֶׁיִּהְיֶה תּוֹכוֹ רָצוּף אַהֲבָה מָלֵא וְגָדוּשׁ עַד שֶׁתִּתְפַּשֵּׁט גַּם לֶחָלָל הַשְּׂמָאלִי לְאַכְפָּיָא לְסִטְרָא אָחֳרָא יְסוֹד הַמַּיִם הָרָעִים שֶׁבָּהּ, שֶׁהִיא הַתַּאֲוָה שֶׁמִּקְּלִיפַּת נוֹגַהּ, לְשַׁנּוֹתָהּ וּלְהַפְּכָהּ מִתַּעֲנוּגֵי עוֹלָם הַזֶּה לְאַהֲבַת ה׳, כְּמוֹ שֶׁכָּתוּב: ״בְּכָל לְבָבְךָ״ – ״בִּשְׁנֵי יְצָרֶיךָ״."],"Tanya, Part I; Likkutei Amarim 9:6":["וְהַיְינוּ, שֶׁיַּעֲלֶה וְיָבֹא וְיַגִּיעַ לְמַדְרֵגַת אַהֲבָה רַבָּה וְחִיבָּה יְתֵרָה מִמַּדְרֵגַת אַהֲבָה עַזָּה כְּרִשְׁפֵּי אֵשׁ, וְהִיא הַנִּקְרֵאת בַּכָּתוּב: ״אַהֲבָה בְּתַּעֲנוּגִים״, לְהִתְעַנֵּג עַל ה׳ מֵעֵין עוֹלָם הַבָּא; וְהָעֹנֶג – הוּא בְּמוֹחַ חָכְמָה וָשֵׂכֶל, הַמִּתְעַנֵּג בְּהַשְׂכָּלַת ה׳ וִידִיעָתוֹ, כְּפִי הַשָּׂגַת שִׂכְלוֹ וְחָכְמָתוֹ; וְהוּא בְּחִינַת הַמַּיִם וְזֶרַע אוֹר זָרוּעַ שֶׁבִּקְדוּשַּׁת נֶפֶשׁ הָאֱלֹהִית, הַמְהַפֶּכֶת לְטוֹב אֶת בְּחִינַת הַמַּיִם שֶׁבַּנֶּפֶשׁ הַבַּהֲמִית, שֶׁמֵּהֶם בָּאוּ תַּאֲוֹת תַּעֲנוּגֵי עוֹלָם הַזֶּה מִתְּחִלָּה; וּכְמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים שַׁעַר נ׳ פֶּרֶק ג׳ בְּשֵׁם הַזֹּהַר, שֶׁהָרָע נֶהְפָּךְ לִהְיוֹת טוֹב גָּמוּר כְּמוֹ יֵצֶר טוֹב מַמָּשׁ, בְּהָסִיר ״הַבְּגָדִים הַצּוֹאִים״ מִמֶּנּוּ, שֶׁהֵם תַּעֲנוּגֵי עוֹלָם הַזֶּה שֶׁהוּא מְלוּבָּשׁ בָּהֶם."],"Tanya, Part I; Likkutei Amarim, Compiler's Foreword 1":["וְהִיא אִגֶּרֶת הַשְּׁלוּחָה לִכְלָלוּת אַנְשֵׁי שְׁלוֹמֵינוּ, יְבָרְכֵם צוּרֵנוּ וְיִשְׁמְרֵם:"],"Tanya, Part I; Likkutei Amarim, Compiler's Foreword 13":["וְהִנֵּה, אַחַר שֶׁנִּתְפַּשְּׁטוּ הַקּוּנְטְרֵיסִים הַנִּזְכָּרִים לְעֵיל, בְּקֶרֶב כָּל אַנְשֵׁי שְׁלוֹמֵנוּ הַנִּזְכָּרִים לְעֵיל, בְּהַעְתָּקוֹת רַבּוֹת מִידֵי סוֹפְרִים שׁוֹנִים וּמְשׁוּנִּים, הִנֵּה עַל יְדֵי רִיבּוּי הַהַעְתָּקוֹת שׁוֹנוֹת, רַבּוּ כְּמוֹ רַבּוּ הַטָּעוּיּוֹת־סוֹפְרִים בִּמְאוֹד מְאוֹד, וְלָזֹאת, נָדְבָה רוּחָם שֶׁל אֲנָשִׁים אֶפְרָתִים הַנְּקוּבִים הַנִּזְכָּרִים לְעֵיל מֵעֵבֶר לַדַּף, לִטְרוֹחַ בְּגוּפָם וּמְאוֹדָם לְהָבִיא אֶת קוּנְטְרֵיסִים הַנִּזְכָּרִים לְעֵיל לְבֵית הַדְּפוּס מְנוּקִּים מִכָּל סִיג וְטָעוּיּוֹת־סוֹפְרִים וּמוּגָּהִים הֵיטֵב, וְאֲמִינָא לְפָעֲלָא טָבָא יִישַׁר חֵילָא."],"Tanya, Part I; Likkutei Amarim, Compiler's Foreword 9":["אַךְ בְּיוֹדְעַיי וּמַכִּירַיי קָאֲמִינָא, הֵם כָּל אֶחָד וְאֶחָד מֵאַנְשֵׁי שְׁלוֹמֵנוּ שֶׁבִּמְדִינָתֵינוּ וְסָמוֹכוֹת שֶׁלָּהּ, אֲשֶׁר הָיָה הַדִּבּוּר שֶׁל חִיבָּה מָצוּי בֵּינֵינוּ, וְגִילּוּ לְפָנַי כָּל תַּעֲלוּמוֹת לִבָּם וּמוֹחָם בַּעֲבוֹדַת ה׳ הַתְּלוּיָה בַּלֵּב, אֲלֵיהֶם תִּטּוֹף מִלָּתִי וּלְשׁוֹנִי עֵט סוֹפֵר – בְּקוּנְטְרֵיסִים אֵלּוּ הַנִּקְרָאִים בְּשֵׁם ״לִקּוּטֵי אֲמָרִים״, מְלוּקָּטִים מִפִּי סְפָרִים וּמִפִּי סוֹפְרִים קְדוֹשֵׁי עֶלְיוֹן נִשְׁמָתָם עֵדֶן הַמְפוּרְסָמִים אֶצְלֵינוּ."],"Tanya, Part I; Likkutei Amarim, Title Page 1":["סֵפֶרלִקּוּטֵי אֲמָרִים"],"Tanya, Part II; Shaar HaYichud VehaEmunah 10:1":["אַךְ מִכָּל מָקוֹם, הוֹאִיל ״וְדִבְּרָה תוֹרָה כִּלְשׁוֹן בְּנֵי אָדָם״, ״לְשַׁכֵּךְ אֶת הָאֹזֶן מַה שֶּׁהִיא יְכוֹלָה לִשְׁמוֹעַ״, לְכָךְ נִיתַּן רְשׁוּת לְחַכְמֵי הָאֱמֶת לְדַבֵּר בִּסְפִירוֹת בְּדֶרֶךְ מָשָׁל, וְקָרְאוּ אוֹתָן ״אוֹרוֹת״, כְּדֵי שֶׁעַל יְדֵי הַמָּשָׁל הַזֶּה יוּבַן לָנוּ קְצָת עִנְיַן הַיִּחוּד שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא וּמִדּוֹתָיו, שֶׁהוּא בְּדֶרֶךְ מָשָׁל, כְּעֵין יִחוּד אוֹר הַשֶּׁמֶשׁ שֶׁבְּתוֹךְ גּוּף כַּדּוּר הַשֶּׁמֶשׁ עִם גּוּף הַשֶּׁמֶשׁ – שֶׁנִּקְרָא ״מָאוֹר״, כְּמוֹ שֶׁכָּתוּב: ״אֶת הַמָּאוֹר הַגָּדוֹל וְגוֹ׳״, וְהַזִּיו וְהַנִּיצוֹץ הַמִּתְפַּשֵּׁט וּמֵאִיר מִמֶּנּוּ – נִקְרָא ״אוֹר״, כְּמוֹ שֶׁכָּתוּב: ״וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם״, וּכְשֶׁהָאוֹר הוּא בִּמְקוֹרוֹ בְּגוּף הַשֶּׁמֶשׁ – הוּא מְיוּחָד עִמּוֹ בְּתַכְלִית הַיִּחוּד, כִּי אֵין שָׁם, רַק עֶצֶם אֶחָד שֶׁהוּא גּוּף הַמָּאוֹר הַמֵּאִיר, כִּי הַזִּיו וְהָאוֹר שָׁם – עֶצֶם אֶחָד מַמָּשׁ עִם גּוּף הַמָּאוֹר הַמֵּאִיר, וְאֵין לוֹ שׁוּם מְצִיאוּת כְּלָל בִּפְנֵי עַצְמוֹ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 10:3":["וּמִכָּל מָקוֹם, לְשַׁכֵּךְ הָאֹזֶן, נִשְׁמַע וְנִתְבּוֹנֵן מִמְּשַׁל אוֹר הַשֶּׁמֶשׁ, הַמְיוּחָד וּבָטֵל בִּמְקוֹרוֹ וְאֵינוֹ עוֹלֶה בְּשֵׁם כְּלָל בִּפְנֵי עַצְמוֹ, רַק שֵׁם הַמָּקוֹר לְבַדּוֹ – כָּךְ כָּל מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא וּרְצוֹנוֹ וְחָכְמָתוֹ, אֵינָן עוֹלוֹת וְנִקְרָאוֹת בְּשֵׁמוֹת אֵלּוּ כְּלָל, אֶלָּא לְגַבֵּי הַנִּבְרָאִים עֶלְיוֹנִים וְתַחְתּוֹנִים, שֶׁהֲוָויָיתָם וְחַיּוּתָם וְהַנְהָגָתָם, שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא מְהַוֶּה וּמְחַיֶּה אוֹתָם וּמַנְהִיגָם, הוּא בִּרְצוֹנוֹ וְחָכְמָתוֹ וּבִינָתוֹ וְדַעְתּוֹ הַמִּתְלַבְּשׁוֹת בְּמִדּוֹתָיו הַקְּדוֹשׁוֹת, כִּדְאִיתָא בַּמִּדְרָשׁ: ״בַּעֲשָׂרָה דְבָרִים נִבְרָא הָעוֹלָם: בְּחָכְמָה, בִּתְבוּנָה וּבְדַעַת וְכוּ׳, דִּכְתִיב, ׳ה׳ בְּחָכְמָה יָסַד אָרֶץ, כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ וְגוֹ׳״. וּכְמַאֲמַר אֵלִיָּהוּ: ״דְּאַפִּיקַת עֲשַׂר תִּיקּוּנִין, וְקָרִינָן לְהוֹן עֲשַׂר סְפִירָן, לְאַנְהָגָא בְהוֹן עָלְמִין סְתִימִין דְּלָא אִתְגַּלְיָין וְעָלְמִין דְּאִתְגַּלְיָין, וּבְהוֹן אִתְכְּסִיאַת כוּ׳״."],"Tanya, Part II; Shaar HaYichud VehaEmunah 10:4":["עַל דֶּרֶךְ מָשָׁל, בְּיוֹם רִאשׁוֹן מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית – נִגְלֵית מִדַּת הַחֶסֶד, כְּלוּלָה מִכָּל מִדּוֹתָיו הַקְּדוֹשׁוֹת, וּרְצוֹנוֹ וְחָכְמָתוֹ וּבִינָתוֹ וְדַעְתּוֹ מְלוּבָּשִׁין בָּהּ, וּבָרָא בָהּ אֶת הָאוֹר – בְּמַאֲמַר ״יְהִי אוֹר״, שֶׁהִיא בְּחִינַת הִתְפַּשְּׁטוּת וְהַמְשָׁכַת הָאוֹר לָעוֹלָם מִלְמַעְלָה, וְהִתְפַּשְּׁטוּתוֹ בָּעוֹלָם מִסּוֹף הָעוֹלָם עַד סוֹפוֹ, שֶׁהִיא בְּחִינַת מִדַּת חֶסֶד; רַק מִפְּנֵי שֶׁכְּלוּלָה גַּם מִמִּדַּת גְּבוּרָה, לָכֵן לֹא הָיָה רוּחָנִי כְּאוֹר שֶׁל מַעְלָה מַמָּשׁ, וְגַם נִתְלַבֵּשׁ בָּעוֹלָם הַזֶּה שֶׁהוּא בִּבְחִינַת גְּבוּל וְתַכְלִית, שֶׁהוּא מַהֲלַךְ תּ״ק שָׁנָה מֵהָאָרֶץ לָרָקִיעַ וּמִמִּזְרָח לְמַעֲרָב."],"Tanya, Part II; Shaar HaYichud VehaEmunah 11:1":["וְהִנֵּה, גַּם עֲשָׂרָה מַאֲמָרוֹת, גַּם כֵּן נִקְרְאוּ בְּשֵׁם ״מַאֲמָרוֹת״ לְגַבֵּי הַנִּבְרָאִים בִּלְבָד. כִּי כְּמוֹ שֶׁהַמִּדּוֹת שֶׁבְּנִשְׁמַת הָאָדָם, כְּשֶׁבָּאוֹת לְהִתְגַּלּוֹת בְּמַעֲשֶׂה, הֵן בָּאוֹת מְלוּבָּשׁוֹת בְּאוֹתִיּוֹת הַמַּחֲשָׁבָה, כְּגוֹן, מִדַּת חֶסֶד וְרַחֲמִים שֶׁבַּנְּשָׁמָה, אִי אֶפְשָׁר לָבֹא לִידֵי הִתְגַּלּוּת בְּפוֹעַל מַמָּשׁ, כִּי אִם עַל יְדֵי שֶׁמְּחַשֵּׁב בְּדַעְתּוֹ וּמְהַרְהֵר מַעֲשֵׂה הַצְּדָקָה וָחֶסֶד לַעֲשׂוֹתָהּ בְּפוֹעַל מַמָּשׁ, כִּי אִי אֶפְשָׁר לַעֲשׂוֹת בְּלִי מַחֲשָׁבָה, וְאִם מְצַוֶּה לַאֲחֵרִים לַעֲשׂוֹת, כְּמוֹ הַמֶּלֶךְ, אֲזַי מִתְלַבֶּשֶׁת מִדַּת הַחֶסֶד וְגַם אוֹתִיּוֹת הַמַּחֲשָׁבָה – בְּאוֹתִיּוֹת הַדִּבּוּר [וְכֵן כְּשֶׁמְּדַבֵּר דִּבְרֵי חֶסֶד וְרַחֲמִים לְרֵעֵהוּ]"],"Tanya, Part II; Shaar HaYichud VehaEmunah 11:6":["אֲבָל בֶּאֱמֶת, בְּחִינַת אוֹתִיּוֹת הַדִּבּוּר שֶׁל מַעְלָה – הִיא לְמַעְלָה מַּעְלָה מִמַּדְרֵגַת וּמַהוּת חָכְמָה וְשֵׂכֶל הַנִּבְרָאִים, שֶׁהֲרֵי בְּמַאֲמַר וְאוֹתִיּוֹת ״נַעֲשֶׂה אָדָם בְּצַלְמֵינוּ וְגוֹ׳״ – נִבְרָא הָאָדָם בַּעַל חָכְמָה וָשֵׂכֶל, אוֹ אֲפִילוּ בַּהֶבֶל הָעֶלְיוֹן לְבַד, כְּדִכְתִיב: ״וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים״, וְאִם כֵּן, הַדִּבּוּר וְהֶבֶל הָעֶלְיוֹן, הוּא מְקוֹר הַחָכְמָה וְהַשֵּׂכֶל שֶׁבְּנִשְׁמַת אָדָם הָרִאשׁוֹן, הַכּוֹלֶלֶת כָּל נִשְׁמוֹת הַצַּדִּיקִים, שֶׁהֵם גְּדוֹלִים מִמַּלְאֲכֵי הַשָּׁרֵת."],"Tanya, Part II; Shaar HaYichud VehaEmunah 12:1":["רַק שֶׁהַבְּרוּאִים מִתְחַלְּקִים לְמִינֵיהֶם בִּכְלָלוּת וּבִפְרָטוּת, עַל יְדֵי שִׁינּוּיֵי הַצֵּירוּפִים וְחִילּוּפִים וּתְמוּרוֹת, כַּנִּזְכָּר לְעֵיל. כִּי כָּל אוֹת, הִיא הַמְשָׁכַת חַיּוּת וְכֹחַ מְיוּחָד פְּרָטִי, וּכְשֶׁנִּצְטָרְפוּ אוֹתִיּוֹת הַרְבֵּה – לִהְיוֹת תֵּיבָה, אֲזַי, מִלְּבַד רִיבּוּי מִינֵי כֹּחוֹת וְחַיּוּת הַנִּמְשָׁכִים כְּפִי מִסְפַּר הָאוֹתִיּוֹת שֶׁבַּתֵּיבָה, עוֹד זֹאת הָעוֹלָה עַל כּוּלָּנָה – הַמְשָׁכַת כֹּחַ עֶלְיוֹן וְחַיּוּת כְּלָלִית הַכּוֹלֶלֶת וּשְׁקוּלָה כְּנֶגֶד כָּל מִינֵי הַכֹּחוֹת וְהַחַיּוּת פְּרָטִיּוֹת שֶׁל הָאוֹתִיּוֹת וְעוֹלָה עַל גַּבֵּיהֶן, וְהִיא מְחַבַּרְתָּן וּמְצָרַפְתָּן יַחַד, לְהַשְׁפִּיעַ כֹּחַ וְחַיּוּת לָעוֹלָם הַנִּבְרָא בְּתֵיבָה זוֹ, לִכְלָלוֹ וְלִפְרָטָיו."],"Tanya, Part II; Shaar HaYichud VehaEmunah 12:5":["כִּי הֵן דֶּרֶךְ מָשָׁל, דּוּגְמַת אוֹר הַמֵּאִיר בַּלַּיְלָה בָּאָרֶץ מִן הַיָּרֵחַ, וְאוֹר הַיָּרֵחַ הוּא מֵהַשֶּׁמֶשׁ, וְנִמְצָא – אוֹר שֶׁעַל הָאָרֶץ הוּא אוֹר הָאוֹר שֶׁל הַשֶּׁמֶשׁ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 1:1":["לְהָבִין מְעַט מִזְּעֵר מַה שֶּׁכָּתוּב בַּזֹּהַר, דִּ״שְׁמַע יִשְׂרָאֵל כוּ׳״ – הוּא ״יִחוּדָא עִילָּאָה״, וּ״בָרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד״ – הוּא ״יִחוּדָא תַּתָּאָה״:"],"Tanya, Part II; Shaar HaYichud VehaEmunah 1:6":["וְאַף שֶׁלֹּא הוּזְכַּר שֵׁם ״אֶבֶן״ בַּעֲשָׂרָה מַאֲמָרוֹת שֶׁבַּתּוֹרָה, אַף־עַל־פִּי־כֵן, נִמְשָׁךְ חַיּוּת לָאֶבֶן עַל יְדֵי צֵירוּפִים וְחִילּוּפֵי אוֹתִיּוֹת, הַמִּתְגַּלְגְּלוֹת בְּרל״א שְׁעָרִים פָּנִים וְאָחוֹר, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יְצִירָה, עַד שֶׁמִּשְׁתַּלְשֵׁל מֵעֲשָׂרָה מַאֲמָרוֹת וְנִמְשָׁךְ מֵהֶן צֵירוּף שֵׁם ״אֶבֶן״, וְהוּא חַיּוּתוֹ שֶׁל הָאֶבֶן."],"Tanya, Part II; Shaar HaYichud VehaEmunah 2:1":["וְהִנֵּה, מִכָּאן תְּשׁוּבַת הַמִּינִים וְגִילּוּי שׁוֹרֶשׁ טָעוּתָם, הַכּוֹפְרִים בְּהַשְׁגָּחָה פְרָטִית וּבְאוֹתוֹת וּמוֹפְתֵי הַתּוֹרָה, שֶׁטּוֹעִים בְּדִמְיוֹנָם הַכּוֹזֵב, שֶׁמְּדַמִין מַעֲשֵׂה ה׳ – ״עוֹשֵׂה שָׁמַיִם וָאָרֶץ״ לְמַעֲשֵׂה אֱנוֹשׁ וְתַחְבּוּלוֹתָיו, כִּי כַּאֲשֶׁר יָצָא לַצּוֹרֵף כְּלִי – שׁוּב אֵין הַכְּלִי צָרִיךְ לִידֵי הַצּוֹרֵף, כִּי אַף שֶׁיָּדָיו מְסוּלָּקוֹת הֵימֶנּוּ וְהוֹלֵךְ לוֹ בַּשּׁוּק – הַכְּלִי קַיָּים בְּתַבְנִיתוֹ וְצַלְמוֹ מַמָּשׁ כַּאֲשֶׁר יָצָא מִידֵי הַצּוֹרֵף, כָּךְ מְדַמִּין הַסְּכָלִים הָאֵלּוּ מַעֲשֵׂה שָׁמַיִם וָאָרֶץ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 2:4":["וְכָל שֶׁכֵּן וְקַל וָחוֹמֶר בִּבְרִיאַת יֵשׁ מֵאַיִן, שֶׁהִיא לְמַעְלָה מֵהַטֶּבַע, וְהַפְלֵא וָפֶלֶא יוֹתֵר מִקְּרִיעַת יַם סוּף, עַל אַחַת כַּמָּה וְכַמָּה שֶׁבְּהִסְתַּלְּקוּת כֹּחַ הַבּוֹרֵא מִן הַנִּבְרָא חַס וְשָׁלוֹם – יָשׁוּב הַנִּבְרָא לְאַיִן וָאֶפֶס מַמָּשׁ. אֶלָּא צָרִיךְ לִהְיוֹת כֹּחַ הַפּוֹעֵל בַּנִּפְעָל תָּמִיד, לְהַחֲיוֹתוֹ וּלְקַיְּימוֹ. וְהֵן הֵן בְּחִינוֹת אוֹתִיּוֹת הַדִּבּוּר מֵעֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרְאוּ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 3:1":["וְהִנֵּה, אַחֲרֵי הַדְּבָרִים וְהָאֱמֶת הָאֵלֶּה, כָּל מַשְׂכִּיל עַל דָּבָר יָבִין לַאֲשׁוּרוֹ, אֵיךְ שֶׁכָּל נִבְרָא וָיֵשׁ הוּא בֶּאֱמֶת נֶחְשָׁב לְאַיִן וָאֶפֶס מַמָּשׁ לְגַבֵּי כֹּחַ הַפּוֹעֵל וְרוּחַ פִּיו שֶׁבַּנִּפְעָל, הַמְהַוֶּה אוֹתוֹ תָּמִיד וּמוֹצִיאוֹ מֵאַיִן מַמָּשׁ לְיֵשׁ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 3:3":["וְהַמָּשָׁל לָזֶה הוּא, אוֹר הַשֶּׁמֶשׁ ״הַמֵּאִיר לָאָרֶץ וְלַדָּרִים״, שֶׁהוּא זִיו וְאוֹר הַמִּתְפַּשֵּׁט מִגּוּף הַשֶּׁמֶשׁ וְנִרְאֶה לְעֵין כֹּל, מֵאִיר עַל הָאָרֶץ וּבַחֲלַל הָעוֹלָם, וְהִנֵּה, זֶה פָּשׁוּט, שֶׁאוֹר וְזִיו הַזֶּה יֶשְׁנוֹ גַּם כֵּן בְּגוּף וְחוֹמֶר כַּדּוּר הַשֶּׁמֶשׁ עַצְמוֹ שֶׁבַּשָּׁמַיִם, שֶׁאִם מִתְפַּשֵּׁט וּמֵאִיר לְמֵרָחוֹק כָּל כָּךְ, כָּל שֶׁכֵּן שֶׁיּוּכַל לְהָאִיר בִּמְקוֹמוֹ מַמָּשׁ, רַק שֶׁשָּׁם, בִּמְקוֹמוֹ מַמָּשׁ, נֶחְשָׁב הַזִּיו הַזֶּה לְאַיִן וָאֶפֶס מַמָּשׁ, כִּי בָּטֵל מַמָּשׁ בִּמְצִיאוּת לְגַבֵּי גּוּף כַּדּוּר הַשֶּׁמֶשׁ, שֶׁהוּא מְקוֹר הָאוֹר וְהַזִּיו הַזֶּה, שֶׁהַזִּיו וְהָאוֹר הַזֶּה, אֵינוֹ רַק הֶאָרָה מְאִירָה מִגּוּף וְעֶצֶם כַּדּוּר הַשֶּׁמֶשׁ; רַק בַּחֲלַל הָעוֹלָם, תַּחַת כָּל הַשָּׁמַיִם וְעַל הָאָרֶץ, שֶׁאֵין כָּאן גּוּף כַּדּוּר הַשֶּׁמֶשׁ בִּמְצִיאוּת – נִרְאֶה כָּאן הָאוֹר וְהַזִּיו הַזֶּה לְיֵשׁ מַמָּשׁ לְעֵין כֹּל, וְנוֹפֵל עָלָיו כָּאן שֵׁם ״יֵשׁ״ בֶּאֱמֶת, מַה־שֶּׁאֵין־כֵּן כְּשֶׁהוּא בִּמְקוֹרוֹ בְּגוּף הַשֶּׁמֶשׁ – אֵין נוֹפֵל עָלָיו שֵׁם ״יֵשׁ״ כְּלָל, רַק שֵׁם ״אַיִן״ וָ״אֶפֶס״, כִּי בֶּאֱמֶת, הוּא שָׁם לְאַיִן וָאֶפֶס מַמָּשׁ, שֶׁאֵין מֵאִיר שָׁם רַק מְקוֹרוֹ לְבַדּוֹ, שֶׁהוּא גּוּף הַשֶּׁמֶשׁ הַמֵּאִיר, וְאֶפֶס בִּלְעָדוֹ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 3:4":["וְכַדְּבָרִים הָאֵלֶּה מַמָּשׁ, בִּדְמוּתָם כְּצַלְמָם, הֵם כָּל הַבְּרוּאִים – לְגַבֵּי שֶׁפַע הָאֱלֹהִי מֵרוּחַ פִּיו, הַשּׁוֹפֵעַ עֲלֵיהֶם וּמְהַוֶּה אוֹתָם, וְהוּא מְקוֹרָם, וְהֵם עַצְמָם, אֵינָם, רַק כְּמוֹ אוֹר וְזִיו מִתְפַּשֵּׁט מִן הַשֶּׁפַע וְרוּחַ ה׳ הַשּׁוֹפֵעַ וּמִתְלַבֵּשׁ בְּתוֹכָם וּמוֹצִיאָם מֵאַיִן לְיֵשׁ, וְלָכֵן הֵם בְּטֵלִים בִּמְצִיאוּת לְגַבֵּי מְקוֹרָם, כְּמוֹ אוֹר הַשֶּׁמֶשׁ שֶׁבָּטֵל בִּמְצִיאוּת וְנֶחְשָׁב לְאַיִן וָאֶפֶס מַמָּשׁ, וְאֵינוֹ נִקְרָא בְּשֵׁם ״יֵשׁ״ כְּלָל כְּשֶׁהוּא בִּמְקוֹרוֹ, רַק תַּחַת הַשָּׁמַיִם – שֶׁאֵין שָׁם מְקוֹרוֹ, כָּךְ כָּל הַבְּרוּאִים, אֵין נוֹפֵל עֲלֵיהֶם שֵׁם ״יֵשׁ״ כְּלָל, אֶלָּא לְעֵינֵי בָשָׂר שֶׁלָּנוּ, שֶׁאֵין אָנוּ רוֹאִים וּמַשִּׂיגִים כְּלָל אֶת הַמָּקוֹר, שֶׁהוּא רוּחַ ה׳ הַמְהַוֶּה אוֹתָם, וְלָכֵן נִרְאֶה לְעֵינֵינוּ גַּשְׁמִיּוּת הַנִּבְרָאִים וְחוּמְרָם וּמַמָּשָׁם שֶׁהֵם יֵשׁ גָּמוּר, כְּמוֹ שֶׁנִּרְאֶה אוֹר הַשֶּׁמֶשׁ יֵשׁ גָּמוּר כְּשֶׁאֵינוֹ בִּמְקוֹרוֹ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 4:1":["כִּי הִנֵּה כְּתִיב: ״כִּי שֶׁמֶשׁ וּמָגֵן ה׳ אֱלֹהִים״, פֵּירוּשׁ, ״מָגֵן״ – הוּא נַרְתֵּק לַשֶּׁמֶשׁ, לְהָגֵן שֶׁיּוּכְלוּ הַבְּרִיּוֹת לְסָבְלוֹ, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״לֶעָתִיד לָבֹא הַקָּדוֹשׁ־בָּרוּךְ־הוּא מוֹצִיא חַמָּה מִנַּרְתֵּקָהּ, רְשָׁעִים נִידּוֹנִין בָּהּ כוּ׳״. וּכְמוֹ שֶׁהַנַּרְתֵּק מֵגִין בְּעַד הַשֶּׁמֶשׁ, כָּךְ שֵׁם ״אֱלֹהִים״ מֵגִין לְשֵׁם הֲוָיָ״ה בָּרוּךְ־הוּא."],"Tanya, Part II; Shaar HaYichud VehaEmunah 4:4":["וְהִנֵּה, כְּמוֹ שֶׁמִּדָּה זוֹ הִיא שְׁבְָחוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְבַדּוֹ, שֶׁאֵין בִּיכוֹלֶת שׁוּם נִבְרָא לִבְרוֹא יֵשׁ מֵאַיִן וּלְהַחֲיוֹתוֹ, וְגַם, מִדָּה זוֹ הִיא לְמַעְלָה מֵהַשְׂכָּלַת כָּל הַבְּרוּאִים וְהַשָּׂגָתָם, שֶׁאֵין כֹּחַ בְּשֵׂכֶל שׁוּם נִבְרָא לְהַשְׂכִּיל וּלְהַשִּׂיג מִדָּה זוֹ וִיכָלְתָּהּ לִבְרוֹא יֵשׁ מֵאַיִן וּלְהַחֲיוֹתוֹ, כִּי הַבְּרִיאָה יֵשׁ מֵאַיִן הוּא דָּבָר שֶׁלְּמַעְלָה מִשֵּׂכֶל הַנִּבְרָאִים, כִּי הִיא מִמִּדַּת גְּדוּלָּתוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וְהַקָּדוֹשׁ־בָּרוּךְ־הוּא וּמִדּוֹתָיו – אַחְדּוּת פָּשׁוּט, כִּדְאִיתָא בַּזֹּהַר הַקָּדוֹשׁ דְּ״אִיהוּ וְגַרְמוֹהִי חַד״, וּכְשֵׁם שֶׁאֵין בִּיכוֹלֶת שׁוּם שֵׂכֶל נִבְרָא לְהַשִּׂיג בּוֹרְאוֹ, כָּךְ אֵינוֹ יָכוֹל לְהַשִּׂיג מִדּוֹתָיו."],"Tanya, Part II; Shaar HaYichud VehaEmunah 4:8":["[וְהִנֵּה, בְּחִינַת הַצִּמְצוּם וְהֶסְתֵּר הַחַיּוּת – נִקְרָא בְּשֵׁם ״כֵּלִים״, וְהַחַיּוּת עַצְמוֹ – נִקְרָא בְּשֵׁם ״אוֹר״, שֶׁכְּמוֹ שֶׁהַכְּלִי מְכַסֶּה עַל מַה שֶּׁבְּתוֹכוֹ, כָּךְ בְּחִינַת הַצִּמְצוּם מְכַסֶּה וּמַסְתִּיר הָאוֹר וְהַחַיּוּת הַשּׁוֹפֵעַ; וְהַכֵּלִים – הֵן הֵן הָאוֹתִיּוֹת, שֶׁשָּׁרְשָׁן ה׳ אוֹתִיּוֹת מנצפ״ך, שֶׁהֵן ה׳ גְּבוּרוֹת הַמְחַלְּקוֹת וּמַפְרִידוֹת הַהֶבֶל וְהַקּוֹל בְּה׳ מוֹצָאוֹת הַפֶּה לְהִתְהַוּוֹת כ״ב אוֹתִיּוֹת, וְשֹׁרֶשׁ הַה׳ גְּבוּרוֹת – הוּא ״בּוּצִינָא דְקַרְדּוּנִיתָא״, שֶׁהִיא גְּבוּרָה עִילָּאָה דְּ״עַתִּיק יוֹמִין״, וְשֹׁרֶשׁ הַחֲסָדִים – הוּא גַּם כֵּן חֶסֶד דְּ״עַתִּיק יוֹמִין״, כַּיָּדוּעַ לְיוֹדְעֵי חֵן]:"],"Tanya, Part II; Shaar HaYichud VehaEmunah 5:1":["וְהִנֵּה, עַל זֶה אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״בִּתְחִלָּה עָלָה בְּמַחֲשָׁבָה לִבְרוֹא אֶת הָעוֹלָם בְּמִדַּת הַדִּין, רָאָה שֶׁאֵין הָעוֹלָם מִתְקַיֵּים – שִׁתֵּף בּוֹ מִדַּת רַחֲמִים״, דְּהַיְינוּ, הִתְגַּלּוּת אֱלֹהוּת עַל יְדֵי צַדִּיקִים וְאוֹתוֹת וּמוֹפְתִים שֶׁבַּתּוֹרָה."],"Tanya, Part II; Shaar HaYichud VehaEmunah 6:1":["וְהִנֵּה, שֵׁם ״אֱלֹהִים״, הוּא שֵׁם מִדַּת הַגְּבוּרָה וְהַצִּמְצוּם, וְלָכֵן הוּא גַּם כֵּן בְּגִימַטְרִיָּא ״הַטֶּבַע״, לְפִי שֶׁמַּסְתִּיר הָאוֹר שֶׁלְּמַעְלָה – הַמְהַוֶּה וּמְחַיֶּה הָעוֹלָם, וְנִרְאֶה, כְּאִילּוּ הָעוֹלָם עוֹמֵד וּמִתְנַהֵג בְּדֶרֶךְ הַטֶּבַע. וְשֵׁם ״אֱלֹהִים״ זֶה, הוּא מָגֵן וְנַרְתֵּק לְשֵׁם הֲוָיָ״ה, לְהַעֲלִים הָאוֹר וְהַחַיּוּת הַנִּמְשָׁךְ מִשֵּׁם הֲוָיָ״ה וּמְהַוֶּה מֵאַיִן לְיֵשׁ, שֶׁלֹּא יִתְגַּלֶּה לַנִּבְרָאִים וִיבָּטְלוּ בִּמְצִיאוּת."],"Tanya, Part II; Shaar HaYichud VehaEmunah 6:3":["וְהִנֵּה, מֵהִתְכַּלְלוּת הַמִּדּוֹת זוֹ בָּזוֹ, נִרְאֶה לָעַיִן דְּ״אִיהוּ וְגַרְמוֹהִי חַד״, שֶׁהֵן מִדּוֹתָיו, כִּי מֵאַחַר שֶׁהֵן בְּיִחוּד גָּמוּר עִמּוֹ, לָכֵן הֵן מִתְיַיחֲדוֹת זוֹ בָּזוֹ וּכְלוּלוֹת זוֹ מִזּוֹ, כְּמַאֲמַר אֵלִיָּהוּ: ״וְאַנְתְּ הוּא דְּקָשִׁיר לוֹן וּמְיַחֵד לוֹן וְכוּ׳, וּבַר מִינָּךְ לֵית יִחוּדָא בְּעִילָּאֵי כוּ׳״."],"Tanya, Part II; Shaar HaYichud VehaEmunah 6:6":["וְלָכֵן הוּצְרַךְ הַכָּתוּב לְהַזְהִיר ״וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ וְגוֹ׳״, שֶׁלֹּא תַעֲלֶה עַל דַּעְתְּךָ שֶׁהַשָּׁמַיִם וְכָל צְבָאָם וְהָאָרֶץ וּמְלוֹאָהּ הֵם דָּבָר נִפְרָד בִּפְנֵי עַצְמוֹ, וְהַקָּדוֹשׁ־בָּרוּךְ־הוּא מְמַלֵּא כָּל הָעוֹלָם כְּהִתְלַבְּשׁוּת הַנְּשָׁמָה בַּגּוּף, וּמַשְׁפִּיעַ כֹּחַ הַצּוֹמֵחַ בָּאָרֶץ, וְכֹחַ הַתְּנוּעָה בַּגַּלְגַּלִּים, וּמְנִיעָם וּמַנְהִיגָם כִּרְצוֹנוֹ, כְּמוֹ שֶׁהַנְּשָׁמָה מְנִיעָה אֶת הַגּוּף וּמַנְהִיגָתוֹ כִּרְצוֹנָהּ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:1":["וּבָזֶה יוּבַן מַה שֶּׁכָּתוּב בַּזֹּהַר הַקָּדוֹשׁ, דְּפָסוּק ״שְׁמַע יִשְׂרָאֵל״ – הוּא ״יִחוּדָא עִילָּאָה״, וּ״בָרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד״ – הוּא ״יִחוּדָא תַּתָּאָה״, כִּי ״וָעֶד״ הוּא ״אֶחָד״ בְּחִלּוּפֵי אַתְוָון."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:10":["וְהִנֵּה, בְּמַה שֶּׁנִּתְבָּאֵר, יוּבַן מַה שֶּׁכָּתוּב: ״אֲנִי ה׳ לֹא שָׁנִיתִי״, פֵּירוּשׁ, שֶׁאֵין שׁוּם שִׁינּוּי כְּלָל, כְּמוֹ שֶׁהָיָה לְבַדּוֹ קוֹדֶם בְּרִיאַת הָעוֹלָם – כָּךְ הוּא לְבַדּוֹ אַחַר שֶׁנִּבְרָא. וְזֶהוּ שֶׁאוֹמְרִים: ״אַתָּה הוּא עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, אַתָּה הוּא כוּ׳״, בְּלִי שׁוּם שִׁינּוּי בְּעַצְמוּתוֹ, וְלֹא בְּדַעְתּוֹ, כִּי בִּידִיעַת עַצְמוֹ יוֹדֵעַ כָּל הַנִּבְרָאִים, שֶׁהַכֹּל מִמֶּנּוּ וּבָטֵל בִּמְצִיאוּת אֶצְלוֹ, וּכְמוֹ שֶׁכָּתַב הָרַמְבַּ״ם זִכְרוֹנוֹ לִבְרָכָה, שֶׁ״הוּא הַיּוֹדֵעַ, וְהוּא הַיָּדוּעַ, וְהוּא הַדֵּיעָה עַצְמָהּ – הַכֹּל אֶחָד, וְדָבָר זֶה אֵין כֹּחַ בַּפֶּה לְאָמְרוֹ, וְלֹא בָּאֹזֶן לְשָׁמְעוֹ, וְלֹא בְּלֵב הָאָדָם לְהַכִּירוֹ עַל בּוּרְיוֹ״."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:15":["וְהִנֵּה, מִכָּאן יֵשׁ לְהָבִין שִׁגְגַת מִקְצָת חֲכָמִים בְּעֵינֵיהֶם, ה׳ יְכַפֵּר בַּעֲדָם, שֶׁשָּׁגוּ וְטָעוּ בְּעִיּוּנָם בְּכִתְבֵי הָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה, וְהֵבִינוּ עִנְיַן הַצִּמְצוּם הַמּוּזְכָּר שָׁם כִּפְשׁוּטוֹ, שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא סִילֵּק עַצְמוֹ וּמַהוּתוֹ חַס וְשָׁלוֹם מֵעוֹלָם הַזֶּה, רַק שֶׁמַּשְׁגִּיחַ מִלְמַעְלָה בְּהַשְׁגָּחָה פְרָטִית עַל כָּל הַיְצוּרִים כּוּלָּם, אֲשֶׁר בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:17":["וְזֶהוּ שֶׁכָּתוּב בַּתִּקּוּנִים תִּיקּוּן נ״ז: ״דְּלֵית אֲתַר פָּנוּי מִינֵיהּ, לָא בְּעִילָּאִין וְלָא בְּתַתָּאִין״; וּבְרַעְיָא מְהֵימְנָא פָּרָשַׁת פִּינְחָס: ״אִיהוּ תָּפִיס בְּכוּלָּא וְלֵית מַאן דְּתָפִיס בֵּיהּ כוּ׳, אִיהוּ סוֹבֵב כָּל עָלְמִין כוּ׳, וְלֵית מַאן דְּנָפִיק מֵרְשׁוּתֵיהּ לְבַר, אִיהוּ מְמַלֵּא כָּל עָלְמִין כוּ׳, אִיהוּ מְקַשֵּׁר וּמְיַחֵד זִינָא לְזִינֵיהּ עֵילָּא וְתַתָּא, וְלֵית קוּרְבָא בְּד׳ יְסוֹדִין, אֶלָּא בְּקוּדְשָׁא־בְּרִיךְ־הוּא כַּד אִיהוּ בֵּינַיְיהוּ״, עַד כָּאן לְשׁוֹנוֹ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:19":["וְזֶהוּ גַּם כֵּן עִנְיַן ״סוֹבֵב כָּל עָלְמִין״, פֵּירוּשׁ, דֶּרֶךְ מָשָׁל, כְּשֶׁאָדָם מִתְבּוֹנֵן בְּאֵיזֶה דְּבַר חָכְמָה בְּשִׂכְלוֹ אוֹ דָּבָר גַּשְׁמִי בְּמַחֲשַׁבְתּוֹ, אֲזַי, שִׂכְלוֹ וּמַחֲשַׁבְתּוֹ מַקִּיפִים עַל הַדָּבָר הַהוּא הַמְצוּיָּר בְּמַחֲשַׁבְתּוֹ אוֹ בְּשִׂכְלוֹ, אַךְ אֵין מַקִּיפִים עַל הַדָּבָר הַהוּא מַמָּשׁ – בְּפוֹעַל מַמָּשׁ; אֲבָל הַקָּדוֹשׁ־בָּרוּךְ־הוּא דִּכְתִיב בֵּיהּ ״כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיכֶם וְגוֹ׳״, מַחֲשַׁבְתּוֹ וִידִיעָתוֹ שֶׁיּוֹדֵעַ כָּל הַנִּבְרָאִים, מַקֶּפֶת כָּל נִבְרָא וְנִבְרָא בְּפוֹעַל מַמָּשׁ, שֶׁהֲרֵי, הִיא הִיא חַיּוּתוֹ וְהִתְהַוּוּתוֹ מֵאַיִן לְיֵשׁ בְּפוֹעַל מַמָּשׁ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:20":["וּ״מְמַלֵּא כָּל עָלְמִין״ – הִיא בְּחִינַת הַחַיּוּת הַמִּתְלַבֶּשֶׁת תּוֹךְ עֶצֶם הַנִּבְרָא, שֶׁהִיא מְצוּמְצֶמֶת בְּתוֹכוֹ בְּצִמְצוּם רַב, כְּפִי עֵרֶךְ מַהוּת הַנִּבְרָא, שֶׁהוּא בַּעַל גְּבוּל וְתַכְלִית בְּכַמּוּתוֹ וְאֵיכוּתוֹ, דְּהַיְינוּ – מַעֲלָתוֹ וַחֲשִׁיבוּתוֹ. כְּגוֹן הַשֶּׁמֶשׁ, שֶׁגּוּפוֹ יֵשׁ לוֹ גְּבוּל וְתַכְלִית בְּכַמּוּתוֹ, שֶׁהוּא כְּמוֹ קס״ז פְּעָמִים כְּגוֹדֶל כַּדּוּר הָאָרֶץ, וְאֵיכוּתוֹ וּמַעֲלָתוֹ, הוּא אוֹרוֹ, גַּם כֵּן יֵשׁ לוֹ גְּבוּל עַד כַּמָּה יוּכַל לְהָאִיר, כִּי לֹא יָאִיר לְבִלְתִּי תַכְלִית, מֵאַחַר שֶׁהוּא נִבְרָא, וְכֵן כָּל הַנִּבְרָאִים הֵם בַּעֲלֵי גְבוּל וְתַכְלִית, כִּי מֵהָאָרֶץ לָרָקִיעַ מַהֲלַךְ תּ״ק שָׁנָה כוּ׳."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:22":["כִּי מְקוֹר הַחַיּוּת – הוּא רוּחַ פִּיו שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא הַמִּתְלַבֵּשׁ בַּעֲשָׂרָה מַאֲמָרוֹת שֶׁבַּתּוֹרָה, וְרוּחַ פִּיו יִתְבָּרֵךְ, הָיָה יָכוֹל לְהִתְפַּשֵּׁט לְאֵין קֵץ וְתַכְלִית, וְלִבְרוֹא עוֹלָמוֹת אֵין קֵץ וְתַכְלִית לְכַמּוּתָם וְאֵיכוּתָם, וּלְהַחֲיוֹתָם עֲדֵי עַד, וְלֹא הָיָה נִבְרָא עוֹלָם הַזֶּה כְּלָל (שֶׁכְּמוֹ שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא נִקְרָא ״אֵין־סוֹף״, כָּךְ כָּל מִדּוֹתָיו וּפְעוּלּוֹתָיו, דְּ״אִיהוּ וְגַרְמוֹהִי חַד״, הַיְינוּ הַחַיּוּת הַנִּמְשֶׁכֶת מִמִּדּוֹתָיו, שֶׁהֵן חֶסֶד וְרַחֲמִים וּשְׁאָר מִדּוֹתָיו הַקְּדוֹשׁוֹת, עַל יְדֵי הִתְלַבְּשׁוּתָן שֶׁמִּתְלַבְּשׁוֹת בְּרוּחַ פִּיו – ״כִּי הוּא אָמַר וַיֶּהִי״, וְ״עוֹלָם״ – עַל יְדֵי – ״חֶסֶד יִבָּנֶה״ בִּדְבַר ה׳ וְרוּחַ פִּיו, הַנַּעֲשֶׂה כְּלִי וּלְבוּשׁ לְחֶסֶד זֶה, כְּ״הָדֵין קַמְצָא דִּלְבוּשֵׁיהּ מִינֵּיהּ וּבֵיהּ״)."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:23":["אֶלָּא שֶׁצִּמְצֵם הַקָּדוֹשׁ־בָּרוּךְ־הוּא הָאוֹר וְהַחַיּוּת, שֶׁיּוּכַל לְהִתְפַּשֵּׁט מֵרוּחַ פִּיו, וְהִלְבִּישׁוֹ תּוֹךְ צֵירוּפֵי אוֹתִיּוֹת שֶׁל עֲשָׂרָה מַאֲמָרוֹת וְצֵירוּפֵי צֵירוּפֵיהֶן בְּחִילּוּפֵי וּתְמוּרוֹת הָאוֹתִיּוֹת עַצְמָן וּבְחֶשְׁבּוֹנָן וּמִסְפָּרָן. שֶׁכָּל חִילּוּף וּתְמוּרָה, מוֹרֶה עַל יְרִידַת הָאוֹר וְהַחַיּוּת מִמַּדְרֵגָה לְמַדְרֵגָה, דְּהַיְינוּ, שֶׁיּוּכַל לִבְרוֹא וּלְהַחֲיוֹת בְּרוּאִים שֶׁמַדְרֵגוֹת אֵיכוּתָם וּמַעֲלָתָם הִיא פְּחוּתָה מִמַּדְרֵגוֹת אֵיכוּת וּמַעֲלַת הַבְּרוּאִים הַנִּבְרָאִים מֵאוֹתִיּוֹת וְתֵיבוֹת עַצְמָן שֶׁבַּעֲשָׂרָה מַאֲמָרוֹת, שֶׁבָּהֶן מִתְלַבֵּשׁ הַקָּדוֹשׁ־בָּרוּךְ־הוּא בִּכְבוֹדוֹ וּבְעַצְמוֹ – שֶׁהֵן מִדּוֹתָיו."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:4":["וְהִנֵּה, גֶּדֶר וּבְחִינַת שֵׁם ״עוֹלָם״ נוֹפֵל עַל בְּחִינַת מָקוֹם וּבְחִינַת זְמַן דַּוְקָא. בְּחִינַת מָקוֹם – הוּא: מִזְרָח וּמַעֲרָב, צָפוֹן, דָּרוֹם, מַעְלָה וּמַטָּה. בְּחִינַת זְמַן – עָבָר, הֹוֶה וְעָתִיד."],"Tanya, Part II; Shaar HaYichud VehaEmunah 7:8":["וְהִנֵּה, אַף־עַל־פִּי שֶׁהוּא יִתְבָּרֵךְ לְמַעְלָה מֵהַמָּקוֹם וְהַזְּמַן, אַף־עַל־פִּי־כֵן – הוּא נִמְצָא גַּם לְמַטָּה בְּמָקוֹם וּזְמַן, דְּהַיְינוּ, שֶׁמִּתְיַיחֵד בְּמִדַּת מַלְכוּתוֹ שֶׁמִּמֶּנָּה נִמְשָׁךְ וְנִתְהַוֶּוה הַמָּקוֹם וְהַזְּמַן, וְזֶהוּ יִחוּדָא תַּתָּאָה [שִׁילּוּב הֲוָיָ״ה בְּאַדְנוּת בָּרוּךְ־הוּא], דְּהַיְינוּ, שֶׁמַּהוּתוֹ וְעַצְמוּתוֹ יִתְבָּרֵךְ, הַנִּקְרָא בְּשֵׁם ״אֵין־סוֹף״ בָּרוּךְ־הוּא – מָלֵא אֶת כָּל הָאָרֶץ מַמָּשׁ בִּזְמַן וּמָקוֹם, כִּי בַּשָּׁמַיִם מִמַּעַל וּבָאָרֶץ וּלְד׳ סִטְרִין, הַכֹּל מָלֵא מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא בְּשָׁוֶה מַמָּשׁ, כִּי כָּךְ הוּא בָּאָרֶץ מִתַּחַת כְּמוֹ בַּשָּׁמַיִם מִמַּעַל מַמָּשׁ, כִּי הַכֹּל הוּא בְּחִינַת מָקוֹם – הַבָּטֵל בִּמְצִיאוּת בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, הַמִּתְלַבֵּשׁ בּוֹ עַל יְדֵי מִדַּת מַלְכוּתוֹ הַמְיוּחֶדֶת בּוֹ יִתְבָּרֵךְ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 8:1":["וְהִנֵּה, מַה שֶּׁכָּתַב הָרַמְבַּ״ם זִכְרוֹנוֹ לִבְרָכָה שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא מַהוּתוֹ וְעַצְמוּתוֹ וְדַעְתּוֹ הַכֹּל אֶחָד מַמָּשׁ, אַחְדּוּת פְּשׁוּטָה וְלֹא מוּרְכֶּבֶת כְּלָל – כֵּן הָעִנְיָן מַמָּשׁ בְּכָל מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וּבְכָל שְׁמוֹתָיו הַקְּדוֹשִׁים וְהַכִּינּוּיִים שֶׁכִּינּוּ לוֹ הַנְּבִיאִים וַחֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה, כְּגוֹן ״חַנּוּן״ וְ״רַחוּם״ וְ״חָסִיד״ וְכַיּוֹצֵא בָהֶן, וְכֵן מַה שֶּׁנִּקְרָא ״חָכָם״, דִּכְתִיב: ״וְגַם הוּא חָכָם וְגוֹ׳״, וְכֵן רְצוֹנוֹ ״כִּי רוֹצֶה ה׳ אֶת יְרֵאָיו״ וְ״חָפֵץ חֶסֶד הוּא״ וְ״רוֹצֶה בִּתְשׁוּבָתָם שֶׁל רְשָׁעִים וְאֵינוֹ חָפֵץ בְּמִיתָתָם וּבְרִשְׁעָתָם״ וּ״טְהוֹר עֵינַיִם מֵרְאוֹת בְּרָע״, אֵין רְצוֹנוֹ וְחָכְמָתוֹ וּמִדַּת חַסְדּוֹ וְרַחֲמָנוּתוֹ וּשְׁאָר מִדּוֹתָיו מוֹסִיפִים בּוֹ רִיבּוּי וְהַרְכָּבָה חַס וְשָׁלוֹם בְּמַהוּתוֹ וְעַצְמוּתוֹ, אֶלָּא עַצְמוּתוֹ וּמַהוּתוֹ וּרְצוֹנוֹ וְחָכְמָתוֹ וּבִינָתוֹ וְדַעְתּוֹ, וּמִדַּת חַסְדּוֹ וּגְבוּרָתוֹ, וְרַחֲמָנוּתוֹ וְתִפְאַרְתּוֹ הַכְּלוּלָה מֵחַסְדּוֹ וּגְבוּרָתוֹ, וְכֵן שְׁאָר מִדּוֹתָיו הַקְּדוֹשׁוֹת – הַכֹּל אַחְדּוּת פְּשׁוּטָה מַמָּשׁ, שֶׁהִיא הִיא עַצְמוּתוֹ וּמַהוּתוֹ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 8:3":["כִּי הַמַּעֲלָה וּמַדְרֵגָה הָרִאשׁוֹנָה אֵצֶל הַנִּבְרָאִים הִיא הַחָכְמָה, שֶׁלָּכֵן נִקְרֵאת ״רֵאשִׁית״, כִּי בֶּאֱמֶת הִיא רֵאשִׁית וּמְקוֹר כָּל הַחַיּוּת בַּנִּבְרָאִים, כִּי מֵהַחָכְמָה נִמְשָׁכוֹת בִּינָה וָדַעַת, וּמֵהֶן נִמְשָׁכוֹת כָּל הַמִּדּוֹת שֶׁבַּנֶּפֶשׁ הַמַּשְׂכֶּלֶת, כְּמוֹ אַהֲבָה וָחֶסֶד וְרַחֲמִים וְכַיּוֹצֵא בָּהֶן, וְכַנִּרְאֶה בְּחוּשׁ, שֶׁהַקָּטָן שֶׁאֵין בּוֹ דַּעַת, הוּא בְּכַעַס תָּמִיד וְאַכְזָרִי, וְגַם אַהֲבָתוֹ, הִיא לִדְבָרִים קְטַנִּים שֶׁאֵין רָאוּי לְאַָהֳבָם, מִפְּנֵי שֶׁאֵין בּוֹ דַּעַת לֶאֱהוֹב דְּבָרִים הָרְאוּיִים לְאָהֳבָם, שֶׁהָאַהֲבָה כְּפִי הַדַּעַת."],"Tanya, Part II; Shaar HaYichud VehaEmunah 9:1":["אֲבָל לְגַבֵּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא, מַדְרֵגַת הַחָכְמָה, שֶׁהִיא תְּחִלַּת מַחֲשָׁבָה וְרֵאשִׁיתָהּ – הִיא סוֹף מַעֲשֶׂה אֶצְלוֹ, דְּהַיְינוּ, שֶׁנֶּחְשֶׁבֶת כְּאִילּוּ הִיא בְּחִינַת וּמַדְרֵגַת עֲשִׂיָּיה לְגַבֵּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא, כְּדִכְתִיב: ״כּוּלָּם בְּחָכְמָה עָשִׂיתָ״."],"Tanya, Part II; Shaar HaYichud VehaEmunah 9:3":["רַק מִפְּנֵי שֶׁאֵין בַּנִּבְרָאִים כֹּחַ לְהַשִּׂיג רַק הַהִשְׁתַּלְשְׁלוּת מִמַּדְרֵגַת חָכְמָה, שֶׁהִיא רֵאשִׁיתָם, לְמַדְרֵגַת עֲשִׂיָּה הַשְּׁפֵלָה, לְכָךְ אָנוּ אוֹמְרִים, שֶׁלְּגַבֵּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא, נֶחְשֶׁבֶת מַדְרֵגַת הַחָכְמָה כְּמַדְרֵגַת עֲשִׂיָּה מַמָּשׁ."],"Tanya, Part II; Shaar HaYichud VehaEmunah 9:6":["הגההסוֹד הַצִּמְצוּם בְּאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, וְצִמְצוּם אָדָם קַדְמוֹן, וְסוֹד הַדִּיקְנָא, שֶׁסּוֹד כָּל הַצִּמְצוּמִים לְצַמְצֵם הָאוֹר שֶׁיִּתְלַבֵּשׁ בִּבְחִינוֹת כֵּלִים דְּי׳ סְפִירוֹת. וְהִנֵּה, אַחַר שֶׁנִּתְלַבֵּשׁ אוֹר־אֵין־סוֹף בִּבְחִינוֹת כֵּלִים דְּחָכְמָה־בִּינָה־דַּעַת, אָז שַׁיָּיךְ לוֹמַר מַה שֶּׁכָּתַב הָרַמְבַּ״ם: ״הוּא הַיּוֹדֵעַ, וְהוּא הַמַּדָּע, וְהוּא הַיָּדוּעַ, וּבִידִיעַת עַצְמוֹ וְכוּ׳״, לְפִי שֶׁבְּחִינוֹת כֵּלִים דַּאֲצִילוּת נַﬠֲשִׂים נְשָׁמָה וְחַיּוּת לִבְרִיאָה־יְצִירָה־ﬠֲשִׂיָּה וּלְכָל אֲשֶׁר בָּהֶם. אֲבָל בְּלִי צִמְצוּם וְהַלְבָּשָׁה הַנִּזְכָּר לְﬠֵיל לֹא שַׁיָּיךְ כְּלָל לוֹמַר ״הוּא הַיּוֹדֵﬠַ, וְהוּא הַמַּדָּע וְכוּ׳״, כִּי אֵינוֹ בִּבְחִינַת וְגֶדֶר דַּﬠַת וּמַדָּע כְּלָל חַס וְשָׁלוֹם, אֶלָּא לְמַﬠְלָה מַּﬠְלָה ﬠִילּוּי רַב ﬠַד אֵין קֵץ אֲפִילוּ מִבְּחִינַת וְגֶדֶר חָכְמָה, ﬠַד שֶׁבְּחִינַת חָכְמָה נֶחְשֶׁבֶת אֶצְלוֹ יִתְבָּרֵךְ כִּבְחִינַת ﬠֲשִׂיָּה גַשְׁמִית:"],"Tanya, Part II; Shaar HaYichud VehaEmunah, Chinukh Katan 1":["לִקּוּטֵי אֲמָרִים חֵלֶק שֵׁנִי"],"Tanya, Part II; Shaar HaYichud VehaEmunah, Chinukh Katan 10":["וְהִנֵּה, עִנְיַן אַהֲבָה זוֹ רָצָה מֹשֶׁה רַבֵּינוּ עָלָיו־הַשָּׁלוֹם לִיטַּע בְּלֵב כָּל יִשְׂרָאֵל, בְּפָרָשָׁה: ״וְעַתָּה יִשְׂרָאֵל וְגוֹ׳״, בַּפָּסוּק: ״הֵן לַה׳ אֱלֹהֶיךָ הַשָּׁמַיִם וְגוֹ׳, רַק בַּאֲבוֹתֶיךָ חָשַׁק וְגוֹ׳, וּמַלְתֶּם וְגוֹ׳, בְּשִׁבְעִים נֶפֶשׁ וְגוֹ׳, וְאָהַבְתָּ וְגוֹ׳״. וְלָכֵן סִיֵּים דְּבָרָיו עַל אַהֲבָה זוֹ: ״אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם לַעֲשׂוֹתָהּ״, שֶׁהִיא אַהֲבָה עֲשׂוּיָה בַּלֵּב, עַל יְדֵי הַבִּינָה וְהַדַּעַת בִּדְבָרִים הַמְּעוֹרְרִים אֶת הָאַהֲבָה. וְעַל זֶה צִוָּה כְּבָר תְּחִלָּה: ״וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם עַל לְבָבֶךָ״, כְּדֵי שֶׁעַל יְדֵי זֶה תָּבֹא לְאַהֲבָה אֶת ה׳, כִּדְאִיתָא בְּסִפְרֵי עַל פָּסוּק זֶה."],"Tanya, Part II; Shaar HaYichud VehaEmunah, Chinukh Katan 12":["אַךְ הִנֵּה יָדוּעַ לַיּוֹדְעִים, טַעֲמָא דִקְרָא מַאי דִּכְתִיב: ״כִּי שֶׁבַע יִפּוֹל צַדִּיק וָקָם״, וּבִפְרָט שֶׁהָאָדָם נִקְרָא ״מְהַלֵּךְ״ וְלֹא ״עוֹמֵד״, וְצָרִיךְ לֵילֵךְ מִמַּדְרֵגָה לְמַדְרֵגָה, וְלֹא לַעֲמוֹד בְּמַדְרֵגָה אַחַת לְעוֹלָם, וּבֵין מַדְרֵגָה לְמַדְרֵגָה, טֶרֶם שֶׁיַּגִּיעַ לְמַדְרֵגָה עֶלְיוֹנָה מִמֶּנָּה, הוּא בִּבְחִינַת ״נְפִילָה״ מִמַּדְרֵגָה הָרִאשׁוֹנָה. אַךְ, ״כִּי יִפּוֹל – לֹא יוּטָל״ כְּתִיב, וְאֵינָהּ נִקְרֵאת נְפִילָה, אֶלָּא לְגַבֵּי מַדְרֵיגָתוֹ הָרִאשׁוֹנָה, וְלֹא לְגַבֵּי שְׁאָר כָּל אָדָם חַס וְשָׁלוֹם, שֶׁאַף־עַל־פִּי־כֵן, הוּא לְמַעְלָה מִכָּל הָאָדָם בַּעֲבוֹדָתוֹ, כִּי נִשְׁאַר בָּהּ בְּחִינַת רְשִׁימוּ מִמַּדְרֵיגָתוֹ הָרִאשׁוֹנָה. אַךְ עִיקָּרָהּ, מֵאַהֲבָה שֶׁנִּתְחַנֵּךְ וְהוּרְגַּל בָּהּ מִנְּעוּרָיו, בְּטֶרֶם שֶׁהִגִּיעַ לְמַדְרֵגַת צַדִּיק. וְזֶהוּ שֶׁכָּתוּב: ״גַּם כִּי יַזְקִין וְגוֹ׳״. וְהִנֵּה, רֵאשִׁית הַדְּבָרִים הַמְּעוֹרְרִים הָאַהֲבָה וְהַיִּרְאָה וִיסוֹדָן – הִיא הָאֱמוּנָה הַטְּהוֹרָה וְנֶאֱמָנָה בְּיִחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ וְיִתְעַלֶּה:"],"Tanya, Part III; Iggeret HaTeshuvah 10:1":["וְהִנֵּה, תְּשׁוּבָה עִילָּאָה זוֹ, דְּאִתְדַּבְּקוּתָא דְרוּחָא בְּרוּחָא עַל־יְדֵי תּוֹרָה וּגְמִילוּת חֲסָדִים, הִיא בִּבְחִינַת הַמְשָׁכָה מִלְמַעְלָה לְמַטָּה, לִהְיוֹת דְּבַר ה׳ מַמָּשׁ בְּפִיו, וּכְמוֹ שֶׁכָּתוּב: ״וָאָשִׂים דְּבָרַי בְּפִיךָ״, ״וִימִינוֹ תְּחַבְּקֵנִי״ בִּגְמִילוּת חֲסָדִים, דְּ״חֶסֶד דְּרוֹעָא יְמִינָא וְכוּ׳״."],"Tanya, Part III; Iggeret HaTeshuvah 10:5":["וּמֵאַחַר שֶׁהַתְּפִלָּה הִיא בְּחִינַת תְּשׁוּבָה עִילָּאָה – צָרִיךְ לְהַקְדִּים לְפָנֶיהָ בְּחִינַת תְּשׁוּבָה תַּתָּאָה. וְזֶהוּ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה בַּמִּשְׁנָה: ״אֵין עוֹמְדִין לְהִתְפַּלֵּל אֶלָּא מִתּוֹךְ כּוֹבֶד רֹאשׁ״, וּפֵירֵשׁ רַשִׁ״י: ״הַכְנָעָה״, וְהִיא בְּחִינַת תְּשׁוּבָה תַּתָּאָה לְעוֹרֵר רַחֲמִים כַּנִּזְכָּר לְעֵיל, וְכִדְיָלִיף הָתָם בַּגְּמָרָא מִקְּרָא, דִּכְתִיב: וְהִיא מָרַת נָפֶשׁ."],"Tanya, Part III; Iggeret HaTeshuvah 11:1":["וְאָמְנָם, לִהְיוֹת בְּלִבּוֹ הַהַכְנָעָה, הִיא בְּחִינַת תְּשׁוּבָה תַּתָּאָה כַּנִּזְכָּר לְעֵיל, וְגַם הַשִּׂמְחָה בַּה׳, שְׁתֵּיהֶן בְּיַחַד – כְּבָר מִילְּתָא אֲמוּרָה בְּלִקּוּטֵי־אֲמָרִים סוֹף פֶּרֶק ל״ד, כְּמוֹ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ ״חֶדְוָה תְּקִיעָא בְּלִבַּאי מִסִּטְרָא דָא וְכוּ׳״. וּבְצֵירוּף עוֹד הָאֱמוּנָה וְהַבִּטָּחוֹן, לִהְיוֹת נָכוֹן לִבּוֹ בָּטוּחַ בַּה׳, כִּי חָפֵץ חֶסֶד הוּא, וְחַנּוּן וְרַחוּם וְרַב לִסְלוֹחַ, תֵּיכֶף וּמִיָּד שֶׁמְּבַקֵּשׁ מְחִילָה וּסְלִיחָה מֵאִתּוֹ יִתְבָּרֵךְ (״כְּרוֹב רַחֲמֶיךָ מְחֵה פְשָׁעָי״ ״כַּבְּסֵנִי טַהֲרֵנִי״, וְכָל עֲווֹנוֹתַי מְחֵה״ וְכוּ׳), בְּלִי שׁוּם סָפֵק וּסְפֵק סְפֵיקָא בָּעוֹלָם."],"Tanya, Part III; Iggeret HaTeshuvah 11:12":["וּמַה שֶּׁכָּתוּב ״וְחַטָּאתִי נֶגְדִּי תָמִיד״ – אֵין הַמְכֻוָּון לִהְיוֹת תָּמִיד עָצֵב נִבְזֶה חַס וְשָׁלוֹם, דְּהָא כְּתִיב בַּתְרֵיהּ: ״תַּשְׁמִיעֵנִי שָׂשׂוֹן וְשִׂמְחָה וְגוֹ׳ וְרוּחַ נְדִיבָה תִסְמְכֵנִי וְגוֹ׳״, וּמִשּׁוּם שֶׁצָּרִיךְ לִהְיוֹת כָּל יָמָיו בִּתְשׁוּבָה עִילָּאָה, שֶׁהִיא בְּשִׂמְחָה רַבָּה כַּנִּזְכָּר לְעֵיל. אֶלָּא ״נֶגְדִּי״ דַיְיקָא, כְּמוֹ: ״וְאַתָּה תִּתְיַצֵּב מִנֶּגֶד״, ״מִנֶּגֶד סָבִיב לְאֹהֶל מוֹעֵד יַחֲנוּ״, וּפֵירֵשׁ רַשִׁ״י ״מֵרָחוֹק״. וְהַמְכֻוָּון, רַק לְבִלְתִּי רוּם לְבָבוֹ, וְלִהְיוֹת שְׁפַל רוּחַ בִּפְנֵי כָל הָאָדָם, כְּשֶׁיִּהְיֶה לְזִכָּרוֹן בֵּין עֵינָיו שֶׁחָטָא נֶגֶד ה׳."],"Tanya, Part III; Iggeret HaTeshuvah 11:6":["וּמַה שֶּׁמְּשַׁבְּחִים וּמְבָרְכִים אֶת ה׳ ״חַנּוּן הַמַּרְבֶּה לִסְלוֹחַ״ – ״הַמַּרְבֶּה״ דַּיְיקָא, וּכְמוֹ שֶׁכָּתוּב בְּעֶזְרָא ״וְרַב לִסְלוֹחַ״, דְהַיְינוּ, שֶׁבְּמִדַּת בָּשָׂר וָדָם, אִם יֶחֱטָא אִישׁ לְאִישׁ וּבִיקֵּשׁ מִמֶּנּוּ מְחִילָה וּמָחַל לוֹ וְאַחַר כָּךְ חָזַר לְסוּרוֹ – קָשֶׁה מְאֹד שֶׁיִּמְחוֹל לוֹ שֵׁנִית, וּמִכָּל שֶׁכֵּן בִּשְׁלִישִׁית וּרְבִיעִית."],"Tanya, Part III; Iggeret HaTeshuvah 12:1":["וְטַעַם הַשִּׂמְחָה בְּיִסּוּרֵי הַגּוּף, לְפִי שֶׁהִיא טוֹבָה גְדוֹלָה וַעֲצוּמָה לַנֶּפֶשׁ הַחוֹטֵאת, לְמָרְקָהּ בָּעוֹלָם הַזֶּה וּלְהַצִּילָהּ מֵהַמֵּירוּק בְּגֵּיהִנֹּם (בִּפְרָט בְּדוֹרוֹתֵינוּ אֵלֶּה, שֶׁאֵין בִּיכוֹלֶת לְהִתְעַנּוֹת כְּפִי מִסְפַּר כָּל הַצּוֹמוֹת שֶׁבְּתִיקּוּנֵי תְּשׁוּבָה מֵהָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה, הַצְּרִיכוֹת לְמֵירוּק הַנֶּפֶשׁ לְהַצִּילָהּ מִמֵּירוּק בְּגֵּיהִנֹּם)."],"Tanya, Part III; Iggeret HaTeshuvah 1:1":["תַּנְיָא בְּסוֹף יוֹמָא: שְׁלֹשָׁה חִלּוּקֵי כַפָּרָה הֵם, וּתְשׁוּבָה עִם כָּל אֶחָד; עָבַר עַל מִצְוַת עֲשֵׂה וְשָׁב – אֵינוֹ זָז מִשָּׁם עַד שֶׁמּוֹחֲלִין לוֹ; עָבַר עַל מִצְוַת לֹא תַעֲשֶׂה וְשָׁב – תְּשׁוּבָה תּוֹלָה, וְיוֹם הַכִּפּוּרִים מְכַפֵּר."],"Tanya, Part III; Iggeret HaTeshuvah 1:7":["וְהִנֵּה, מִצְוַת הַתְּשׁוּבָה מִן הַתּוֹרָה, הִיא עֲזִיבַת הַחֵטְא בִּלְבַד (כִּדְאִיתָא בַּגְּמָרָא פֶּרֶק ג׳ דְּסַנְהֶדְרִין וּבְחֹשֶׁן־מִשְׁפָּט סוֹף סִימָן ל״ד לְעִנְיַן עֵדוּת), דְּהַיְינוּ, שֶׁיִּגְמוֹר בְּלִבּוֹ בְּלֵב שָׁלֵם, לְבַל יָשׁוּב עוֹד לְכִסְלָה, לִמְרוֹד בְּמַלְכוּתוֹ יִתְבָּרֵךְ, וְלֹא יַעֲבוֹר עוֹד מִצְוֹת הַמֶּלֶךְ חַס וְשָׁלוֹם, הֵן בְּמִצְוֹת עֲשֵׂה הֵן בְּמִצְוֹת לֹא תַעֲשֶׂה."],"Tanya, Part III; Iggeret HaTeshuvah 2:1":["אַךְ כָּל זֶה לְעִנְיַן כַּפָּרָה וּמְחִילַת הֶעָוֹן, שֶׁנִּמְחָל לוֹ לְגַמְרֵי מַה שֶּׁעָבַר עַל מִצְוֹת הַמֶּלֶךְ כְּשֶׁעָשָׂה תְּשׁוּבָה שְׁלֵימָה, וְאֵין מַזְכִּירִין לוֹ דָּבָר וַחֲצִי דָּבָר בְּיוֹם הַדִּין לְעָנְשׁוֹ עַל זֶה חַס וְשָׁלוֹם בָּעוֹלָם־הַבָּא, וְנִפְטָר לְגַמְרֵי מִן הַדִּין בָּעוֹלָם־הַבָּא."],"Tanya, Part III; Iggeret HaTeshuvah 3:1":["וְהִנֵּה, חַכְמֵי הַמּוּסָר הָאַחֲרוֹנִים נֶחְלְקוּ בְּמִי שֶׁחָטָא חֵטְא אֶחָד פְּעָמִים רַבּוֹת; דְּיֵשׁ אוֹמְרִים, שֶׁצָּרִיךְ לְהִתְעַנּוֹת מִסְפַּר הַצּוֹמוֹת לְאוֹתוֹ חֵטְא פְּעָמִים רַבּוֹת כְּפִי הַמִּסְפָּר אֲשֶׁר חָטָא; כְּגוֹן הַמּוֹצִיא זֶרַע לְבַטָּלָה, שֶׁמִּסְפַּר הַצּוֹמוֹת הַמְפוֹרָשׁ בְּתִיקּוּנֵי תְּשׁוּבָה מֵהָאֲרִיזַ״ל הֵן פ״ד תַּעֲנִיּוֹת, וְאִם חָטָא בָּזֶה עֶשֶׂר אוֹ עֶשְׂרִים פְּעָמִים, עַל דֶּרֶךְ מָשָׁל – צָרִיךְ לְהִתְעַנוֹת עֶשֶׂר אוֹ עֶשְׂרִים פְּעָמִים פ״ד, וְכֵן לְעוֹלָם, דּוּמְיָא דְּקָרְבַּן חַטָּאת, שֶׁחַיָּיב לְהָבִיא עַל כָּל פַּעַם וּפַעַם."],"Tanya, Part III; Iggeret HaTeshuvah 3:11":["אָכֵן, מִסְפַּר הַצּוֹמוֹת הָעוֹדְפִים עַל רנ״ב וּכְהַאי גַּוְנָא, שֶׁהָיָה צָרִיךְ לְהִתְעַנּוֹת, לָחוּשׁ לְדַעַת הַמַּחְמִירִים לְהִתְעַנּוֹת מִסְפַּר הַצּוֹמוֹת שֶׁעַל כָּל חֵטְא וְחֵטְא כְּפִי מִסְפַּר הַפְּעָמִים שֶׁחָטָא כַּנִּזְכָּר לְעֵיל, יִפְדֶּה כוּלָּן בִּצְדָקָה עֵרֶךְ ח״י גְּדוֹלִים פּוֹלִישׁ בְּעַד כָּל יוֹם. וְכֵן שְׁאָר כָּל תַּעֲנִיּוֹת שֶׁצָּרִיךְ לְהִתְעַנּוֹת עַל עֲבֵירוֹת שֶׁאֵין בָּהֶן מִיתָה, וַאֲפִילוּ עַל בִּיטּוּל מִצְוֹת עֲשֵׂה דְּאוֹרַיְיתָא וּדְרַבָּנָן, וְתַלְמוּד תּוֹרָה כְּנֶגֶד כּוּלָּם, כְּפִי הַמִּסְפָּר הַמְפוֹרָשׁ בְּתִיקּוּנֵי הַתְּשׁוּבָה מֵהָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה (וְרוּבָּם נִזְכָּרִים בְּ״מִשְׁנַת חֲסִידִים״ בְּמַסֶּכֶת הַתְּשׁוּבָה) – הַכֹּל כַּאֲשֶׁר לַכֹּל, יִפְדֶּה בִּצְדָקָה כַּנִּזְכָּר לְעֵיל, אִי לָא מָצִי לְצַעוּרֵי נַפְשֵׁיהּ כַּנִּזְכָּר לְעֵיל."],"Tanya, Part III; Iggeret HaTeshuvah 3:4":["אָכֵן, כָּל זֶה בְּאָדָם חָזָק וּבָרִיא, שֶׁאֵין רִיבּוּי הַצּוֹמוֹת מַזִּיק לוֹ כְּלָל לִבְרִיאוּת גּוּפוֹ, וּכְמוֹ בַּדּוֹרוֹת הָרִאשׁוֹנִים. אֲבָל מִי שֶׁרִיבּוּי הַצּוֹמוֹת מַזִּיק לוֹ, שֶׁאֶפְשָׁר שֶׁיּוּכַל לָבֹא לִידֵי חוֹלִי אוֹ מֵיחוֹשׁ חַס וְשָׁלוֹם, כְּמוֹ בְּדוֹרוֹתֵינוּ אֵלֶּה, אָסוּר לוֹ לְהַרְבּוֹת בְּתַעֲנִיּוֹת אֲפִילוּ עַל כְּרֵיתוֹת וּמִיתוֹת בֵּית־דִּין, וּמִכָּל שֶׁכֵּן עַל מִצְוֹת עֲשֵׂה וּמִצְוֹת לֹא תַעֲשֶׂה שֶׁאֵין בָּהֶן כָּרֵת, אֶלָּא כְּפִי אֲשֶׁר יְשַׁעֵר בְּנַפְשׁוֹ שֶׁבְּוַדַּאי לֹא יַזִּיק לוֹ כְּלָל."],"Tanya, Part III; Iggeret HaTeshuvah 3:8":["וּמִכָּל מָקוֹם, כָּל בַּעַל נֶפֶשׁ הֶחָפֵץ קִרְבַת ה׳, לְתַקֵּן נַפְשׁוֹ לַהֲשִׁיבָהּ אֶל ה׳ בִּתְשׁוּבָה מְעוּלָּה מִן הַמּוּבְחָר – יַחְמִיר עַל עַצְמוֹ לְהַשְׁלִים עַל כָּל פָּנִים פַּעַם אַחַת כָּל יְמֵי חַיָּיו מִסְפַּר הַצּוֹמוֹת לְכָל עָוֹן וְעָוֹן מֵעֲוֹנוֹת הַחֲמוּרִים שֶׁחַיָּיבִין עֲלֵיהֶם מִיתָה עַל כָּל פָּנִים, וַאֲפִילוּ בִּידֵי שָׁמַיִם בִּלְבַד, כְּגוֹן לְהוֹצָאוֹת זֶרַע לְבַטָּלָה פ״ד צוֹמוֹת פַּעַם אַחַת בִּימֵי חַיָּיו."],"Tanya, Part III; Iggeret HaTeshuvah 4:1":["וְאוּלָם, כָּל הַנִּזְכָּר לְעֵיל, הוּא לִגְמַר הַכַּפָּרָה וּמֵירוּק הַנֶּפֶשׁ לַה׳ אַחַר הַתְּשׁוּבָה, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל מֵהַגְּמָרָא פֶּרֶק קַמָּא דִזְבָחִים, דְּעוֹלָה, דּוֹרוֹן הִיא לְאַחַר שֶׁרִיצָּה הַפְּרַקְלִיט וְכוּ׳. אָמְנָם, הַתְחָלַת מִצְוַת הַתְּשׁוּבָה וְעִיקָּרָהּ, לָשׁוּב עַד ה׳ בֶּאֱמֶת וּבְלֵב שָׁלֵם, הַהֶכְרֵחַ לְבָאֵר הֵיטֵב בְּהַרְחָבַת הַבֵּיאוּר."],"Tanya, Part III; Iggeret HaTeshuvah 4:16":["וְכָכָה מַמָּשׁ עַל דֶּרֶךְ מָשָׁל, הַמַּבְדִּיל הַבְדָּלוֹת לְאֵין קֵץ, בְּנִשְׁמַת הָאָדָם, שֶׁהִיא בְּחִינַת נֶפֶשׁ הָאֱלֹקִית – דְּמִתּוֹכֵיהּ נָפַח, יֵשׁ בָּהּ בְּחִינַת שֵׂכֶל הַנֶּעְלָם, הַמְרוּמָּז בְּאוֹת יוּ״ד, שֶׁבְּכֹחוֹ לָצֵאת אֶל הַגִּילּוּי, לְהָבִין וּלְהַשְׂכִּיל בַּאֲמִתָּתוֹ יִתְבָּרֵךְ וּבִגְדוּלָּתוֹ וְכוּ׳, כָּל חַד וְחַד לְפוּם שִׁיעוּרָא דִּילֵיהּ, לְפִי רוֹחַב שִׂכְלוֹ וּבִינָתוֹ."],"Tanya, Part III; Iggeret HaTeshuvah 4:4":["אַךְ הָעִנְיָן יוּבַן, עַל פִּי מַה שֶּׁכָּתוּב: ״כִּי חֵלֶק ה׳ עַמּוֹ וְגוֹ׳״, חֵלֶק מִשֵּׁם הַוָיָ׳ בָּרוּךְ־הוּא, כְּדִכְתִיב: ״וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים״, וּ״מַאן דְּנָפַח מִתּוֹכוֹ נָפַח וְכוּ׳״. וְאַף שֶׁ״אֵין לוֹ דְמוּת הַגּוּף וְכוּ׳״ חַס וְשָׁלוֹם, אַךְ ״דִּבְּרָה תוֹרָה כִּלְשׁוֹן בְּנֵי אָדָם״."],"Tanya, Part III; Iggeret HaTeshuvah 4:6":["כָּכָה מַמָּשׁ עַל דֶּרֶךְ מָשָׁל, הַמַּבְדִּיל הַבְדָּלוֹת לְאֵין קֵץ, יֵשׁ הֶפְרֵשׁ עָצוּם מְאֹד לְמַעְלָה, בֵּין כָּל צְבָא הַשָּׁמַיִם, וַאֲפִילוּ הַמַּלְאָכִים, שֶׁנִּבְרְאוּ מֵאַיִן לְיֵשׁ, וְחַיִּים וְקַיָּימִים מִבְּחִינַת חִיצוֹנִיּוּת הַחַיּוּת וְהַשֶּׁפַע שֶׁמַּשְׁפִּיעַ אֵין־סוֹף בָּרוּךְ־הוּא לְהַחֲיוֹת הָעוֹלָמוֹת, וּבְחִינָה זוֹ נִקְרֵאת בְּשֵׁם ״רוּחַ פִּיו״ עַל דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁכָּתוּב: ״וּבְרוּחַ פִּיו כָּל צְבָאָם״, וְהִיא בְּחִינַת חַיּוּת הַמְלוּבֶּשֶׁת בָּאוֹתִיּוֹת שֶׁבַּעֲשָׂרָה מַאֲמָרוֹת (שֶׁהֵן בְּחִינַת כֵּלִים וְהַמְשָׁכוֹת וְכוּ׳, כְּמוֹ שֶׁנִּתְבָּאֵר בְּלִקּוּטֵי־אֲמָרִים חֵלֶק ב׳ פֶּרֶק י״א); וּבֵין נִשְׁמַת הָאָדָם, שֶׁנִּמְשְׁכָה תְּחִלָּה מִבְּחִינַת פְּנִימִיּוּת הַחַיּוּת וְהַשֶּׁפַע שֶׁמַּשְׁפִּיעַ אֵין־סוֹף בָּרוּךְ־הוּא, כְּמוֹ שֶׁכָּתוּב: ״וַיִּפַּח וְכוּ׳״, וְאַחַר כָּךְ יָרְדָה בְּסֵתֶר הַמַּדְרֵגָה, גַּם כֵּן, עַל־יְדֵי בְּחִינַת הָאוֹתִיּוֹת שֶׁבְּמַאֲמַר ״נַעֲשֶׂה אָדָם״ וְכוּ׳ כְּדֵי לְהִתְלַבֵּשׁ בְּגוּף עוֹלָם הַזֶּה הַתַּחְתּוֹן."],"Tanya, Part III; Iggeret HaTeshuvah 4:9":["וּבֵיאוּר הָעִנְיָן, כַּנּוֹדָע מִמַּאֲמַר אֵלִיָּהוּ: ״אַנְתְּ הוּא דְאַפִּיקַת עֲשַׂר תִּיקּוּנִין, וְקָרִינָן לְהוֹן עֲשַׂר סְפִירָן, לְאַנְהָגָא בְהוֹן עָלְמִין סְתִימִין וְכוּ׳. וְכָל הַי׳ סְפִירוֹת נִכְלָלוֹת וְנִרְמָזוֹת בְּשֵׁם הַוָיָ׳ בָּרוּךְ־הוּא."],"Tanya, Part III; Iggeret HaTeshuvah 5:1":["וְהִנֵּה, הַמְשָׁכַת וִירִידַת הַנֶּפֶשׁ הָאֱלֹקִית לָעוֹלָם הַזֶּה לְהִתְלַבֵּשׁ בְּגוּף הָאָדָם, נִמְשְׁכָה מִבְּחִינַת פְּנִימִיּוּת וּמְקוֹר הַדִּיבּוּר, הוּא הֶבֶל הָעֶלְיוֹן, הַמְרוּמָּז בְּאוֹת הֵ״א תַּתָּאָה כַּנִּזְכָּר לְעֵיל, וּכְמוֹ שֶׁכָּתוּב: ״וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה״, וּ״מַאן דְּנָפַח וְכוּ׳״."],"Tanya, Part III; Iggeret HaTeshuvah 6:1":["אָמְנָם, זֶהוּ בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל בְּמַדְרֵגָה עֶלְיוֹנָה, כְּשֶׁהָיְתָה הַשְּׁכִינָה שׁוֹרָה בְּיִשְׂרָאֵל בְּבֵית הַמִּקְדָּשׁ, וְאָז, לֹא הָיוּ מְקַבְּלִים חַיּוּת לְגוּפָם, רַק – עַל־יְדֵי נֶפֶשׁ הָאֱלֹקִית לְבַדָּהּ, מִבְּחִינַת פְּנִימִיּוּת הַשֶּׁפַע שֶׁמַּשְׁפִּיעַ אֵין־סוֹף בָּרוּךְ־הוּא עַל־יְדֵי שֵׁם הַוָיָ׳ בָּרוּךְ־הוּא, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part III; Iggeret HaTeshuvah 6:7":["וְהִנֵּה, ״יַעֲקֹב חֶבֶל נַחֲלָתוֹ״ כְּתִיב: עַל דֶּרֶךְ מָשָׁל, כְּמוֹ הַחֶבֶל שֶׁרֹאשׁוֹ אֶחָד לְמַעְלָה וְרֹאשׁוֹ הַשֵּׁנִי לְמַטָּה, אִם יִמְשׁוֹךְ אָדָם בְּרֹאשׁוֹ הַשֵּׁנִי – יְנַעֲנֵעַ וְיִמָּשֵׁךְ אַחֲרָיו גַּם רֹאשׁוֹ הָרִאשׁוֹן כַּמָּה שֶׁאֶפְשָׁר לוֹ לְהִמָּשֵׁךְ."],"Tanya, Part III; Iggeret HaTeshuvah 7:1":["וְאוּלָם, דֶּרֶךְ הָאֱמֶת וְהַיָּשָׁר לִבְחִינַת תְּשׁוּבָה תַּתָּאָה, הֵ״א תַּתָּאָה הַנִּזְכֶּרֶת לְעֵיל – הֵם ב׳ דְּבָרִים דֶּרֶךְ כְּלָל."],"Tanya, Part III; Iggeret HaTeshuvah 7:11":["וְאַף מִי שֶׁלֹּא עָבַר עַל עֲוֹן כָּרֵת, וְגַם לֹא עַל עֲוֹן מִיתָה בִּידֵי שָׁמַיִם שֶׁהוּא הוֹצָאַת זֶרַע לְבַטָּלָה וּכְהַאי גַּוְנָא, אֶלָּא שְׁאָר עֲבֵירוֹת קַלּוֹת, אַף־עַל־פִּי־כֵן, מֵאַחַר שֶׁהֵן פּוֹגְמִים בַּנְּשָׁמָה וְנֶפֶשׁ הָאֱלֹקִית, וְכִמְשַׁל פְּגִימַת וּפְסִיקַת חֲבָלִים דַּקִּים כַּנִּזְכָּר לְעֵיל, הֲרֵי בְּרִיבּוּי הַחֲטָאִים יָכוֹל לִהְיוֹת פְּגַם כְּמוֹ בְּלָאו אֶחָד שֶׁיֵּשׁ בּוֹ כָּרֵת אוֹ מִיתָה, וַאֲפִילוּ בִּכְפִילַת חֵטְא אֶחָד פְּעָמִים רַבּוֹת מְאֹד."],"Tanya, Part III; Iggeret HaTeshuvah 7:8":["וְהַאֵיךְ נִשְׁבָּר הַלֵּב וְנִדְכֶּה? הִנֵּה, מְעַט מִזְּעֵיר הוּא עַל־יְדֵי סִיגּוּפִים וְתַעֲנִיּוֹת, בְּדוֹרוֹתֵינוּ אֵלֶּה שֶׁאֵין לָנוּ כֹּחַ לְהִתְעַנּוֹת הַרְבֵּה כְּדָוִד הַמֶּלֶךְ, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה עַל פָּסוּק: ״וְלִבִּי חָלַל בְּקִרְבִּי״ – שֶׁ״הֲרָגוֹ בְּתַעֲנִית״."],"Tanya, Part III; Iggeret HaTeshuvah 8:1":["וְהִנֵּה, אַחֲרֵי הַעֲמָקַת הַדַּעַת בְּכָל הַנִּזְכָּר לְעֵיל, יוּכַל לְבַקֵּשׁ בֶּאֱמֶת, מֵעוּמְקָא דְלִבָּא ״כְּרוֹב רַחֲמֶיךָ מְחֵה פְשָׁעָי וְגוֹ׳״. כִּי אֲזַי תִּקָּבַע בְּלִבּוֹ בֶּאֱמֶת גּוֹדֶל הָרַחֲמָנוּת עַל בְּחִינַת אֱלֹקוּת שֶׁבְּנַפְשׁוֹ וְשֶׁלְּמַעְלָה, כַּנִּזְכָּר לְעֵיל. וּבָזֶה – יְעוֹרֵר רַחֲמִים הָעֶלְיוֹנִים מִי״ג מִדּוֹת הָרַחֲמִים, הַנִּמְשָׁכוֹת מֵרָצוֹן הָעֶלְיוֹן בָּרוּךְ־הוּא, הַנִּרְמָז בְּקוֹצוֹ שֶׁל יוּ״ד, שֶׁלְּמַעְלָה מַּעְלָה מִבְּחִינַת הַהַשְׁפָּעָה הַנִּשְׁפַּעַת מֵאוֹתִיּוֹת שֵׁם הַוָיָ׳."],"Tanya, Part III; Iggeret HaTeshuvah 8:4":["וּמֵאַחַר שֶׁ״רוּחַ עָבְרָה וַתְּטַהֲרֵם״, אֲזַי תּוּכַל נַפְשָׁם לָשׁוּב עַד הַוָיָ׳ בָּרוּךְ־הוּא מַמָּשׁ, וְלַעֲלוֹת מַעְלָה מַּעְלָה לִמְקוֹרָהּ, וּלְדָבְקָה בּוֹ יִתְבָּרֵךְ בְּיִחוּד נִפְלָא, כְּמוֹ שֶׁהָיְתָה מְיוּחֶדֶת בּוֹ יִתְבָּרֵךְ בְּתַכְלִית הַיִּחוּד, בְּטֶרֶם שֶׁנְּפָחָהּ בְּרוּחַ פִּיו יִתְבָּרֵךְ לֵירֵד לְמַטָּה וּלְהִתְלַבֵּשׁ בְּגוּף הָאָדָם (וּכְמוֹ עַל דֶּרֶךְ מָשָׁל, בְּאָדָם הַנּוֹפֵחַ בְּרוּחַ פִּיו, בְּטֶרֶם שֶׁיּוֹצֵא הָרוּחַ מִפִּיו – הוּא מְיוּחָד בְּנַפְשׁוֹ). וְזוֹ הִיא תְּשׁוּבָה שְׁלֵימָה."],"Tanya, Part III; Iggeret HaTeshuvah 9:1":["וּבֵיאוּר הָעִנְיָן, כְּמוֹ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ וְתִיקּוּנִים בְּכַמָּה מְקוֹמוֹת, דְּבִינָה – אִיהִי תְּשׁוּבָה עִילָּאָה, ״וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים״ וְכוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 10:1":["אַחַר דְּרִישַׁת שְׁלוֹמָם וְחַיִּים, פֶּתַח דְּבָרַי יָעִיר אֹזֶן שׁוֹמַעַת תּוֹכַחַת חַיִּים, אֲשֶׁר הוֹכִיחַ ה׳ חַיִּים עַל־יְדֵי נְבִיאוֹ, וְאָמַר: חַסְדֵי ה׳ כִּי לֹא תָמְנוּ וְגוֹ׳, וַהֲוָה־לֵיהּ־לְמֵימַר ״כִּי לֹא תָמּוּ״, כְּמוֹ שֶׁאוֹמְרִים: ״כִּי לֹא תַמּוּ חֲסָדֶיךָ וְגוֹ׳״. וְיוּבַן עַל פִּי מַה שֶּׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ: ״אִית חֶסֶד וְאִית חֶסֶד, אִית חֶסֶד עוֹלָם כוּ׳ וְאִית חֶסֶד עִילָּאָה דְּהוּא רַב חֶסֶד כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 10:13":["וְהִנֵּה, מִדַּת חֶסֶד זוֹ בְּלִי גְבוּל וּמִדָּה נִקְרֵאת עַל שְׁמוֹ שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא – ״חַסְדֵי ה׳״, כְּדִכְתִיב: ״וְחֶסֶד ה׳ מֵעוֹלָם וְעַד עוֹלָם כוּ׳״. כִּי הֲגַם שֶׁכָּל יִשְׂרָאֵל הֵם רַחֲמָנִים וְגוֹמְלֵי חֲסָדִים, בְּרַם יֵשׁ גְּבוּל וּמִדָּה לְרַחֲמֵי הָאָדָם, אֲבָל הַקָּדוֹשׁ־בָּרוּךְ־הוּא נִקְרָא ״אֵין־סוֹף בָּרוּךְ־הוּא״, וּלְמִדּוֹתָיו אֵין סוֹף, כְּדִכְתִיב: ״כִּי לֹא כָלוּ רַחֲמָיו וְכוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 10:5":["וְהִנֵּה, לְפִי שֶׁהַמִּצְוֹת נִיתְּנוּ לָנוּ עַל־יְדֵי הִתְלַבְּשׁוּת בְּמִדַּת גְּבוּרָה וְצִמְצוּם הַהֶאָרָה כוּ׳, לָכֵן רוֹב הַמִּצְוֹת יֵשׁ לָהֶן שִׁיעוּר מְצוּמְצָם, כְּמוֹ: אוֹרֶךְ הַצִּיצִית י״בּ גּוּדָלִין, וְהַתְּפִילִּין אֶצְבָּעַיִם עַל אֶצְבָּעַיִם וּמְרוּבָּעוֹת דַּוְקָא, וְהַלּוּלָב ד׳ טְפָחִים, וְהַסּוּכָּה ז׳ טְפָחִים, וְהַשּׁוֹפָר טֶפַח, וְהַמִּקְוֶה מ׳ סְאָה, וְכֵן בְּקָרְבָּנוֹת יֵשׁ לָהֶן שִׁיעוּר מְצוּמְצָם לִזְמַן, כְּמוֹ כְּבָשִׂים בְּנֵי שָׁנָה, וְאֵילִים בְּנֵי שְׁתַּיִם, וּפָרִים כוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 10:8":["אַךְ, הַיְינוּ דַוְקָא לְשׁוֹמֵר הַתּוֹרָה וְלֹא סָר מִמֶּנָּה יָמִין וּשְׂמֹאל אֲפִילוּ כִּמְלֹא נִימָא; אֲבָל מִי שֶׁהֶעֱבִיר עָלָיו הַדֶּרֶךְ חַס וְשָׁלוֹם, מֵאַחַר שֶׁהֶעֱוָה דַרְכּוֹ, לָתֵת מִגְרָעוֹת בַּקֹּדֶשׁ הָעֶלְיוֹן, שֶׁגָּרַע עֶרְכּוֹ, בְּחִינַת הַמְשָׁכָתוֹ, מַה שֶּׁהָיָה יָכוֹל לְהַמְשִׁיךְ מִבְּחִינַת אֱלֹהוּתוֹ וְהֶאָרַת הָאוֹר מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא אִילּוּ הָיָה שׁוֹמֵר הַתּוֹרָה וּמְקַיְּימָהּ כְּהִלְכָתָהּ הֲרֵי מְעֻוָּות זֶה לֹא יוּכַל לִתְקֹן, כִּי אִם בְּהַמְשָׁכַת הָאוֹר הָעֶלְיוֹן שֶׁלְּמַעְלָה מֵהָעוֹלָמוֹת וְאֵינוֹ מִתְלַבֵּשׁ בָּהֶן, הַנִּקְרָא ״חֶסֶד עִילָּאָה״ וְ״רַב חֶסֶד״, לְפִי שֶׁמֵּאִיר וּמִתְפַּשֵּׁט בִּבְחִינַת אֵין־סוֹף בְּלִי גְבוּל וּמִדָּה, מֵאַחַר שֶׁאֵינֶנּוּ מְצוּמְצָם תּוֹךְ הָעוֹלָמוֹת אֶלָּא בִּבְחִינַת מַקִּיף עֲלֵיהֶן מִלְמַעְלָה, מֵרֵישׁ כָּל דַּרְגִין עַד סוֹף וְכוּ׳, וּכְשֶׁהָאָדָם מַמְשִׁיכוֹ לְמַטָּה בְּמַעֲשָׂיו וְ״אִתְעָרוּתָא דִלְתַתָּא״, אֲזַי, אוֹר עֶלְיוֹן זֶה מֵאִיר וּמִתְפַּשֵּׁט תּוֹךְ הָעוֹלָמוֹת וּמְתַקֵּן כָּל מְעֻוָּות וְכָל מִגְרָעוֹת שֶׁנִּיתְּנוּ בַּקֹּדֶשׁ הָעֶלְיוֹן, וּמְחַדֵּשׁ אוֹרָן וְטוּבָן בְּיֶתֶר שְׂאֵת וְיֶתֶר עֹז, בִּבְחִינַת אוֹר חָדָשׁ מַמָּשׁ. לָכֵן אָמְרוּ: ״בְּמָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹמְדִין וְכוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 10:9":["וְהִנֵּה, עִיקַּר הַתְּשׁוּבָה הוּא בַּלֵּב, כִּי עַל־יְדֵי הַחֲרָטָה מֵעוּמְקָא דְלִבָּא מְעוֹרֵר עוֹמֶק אוֹר הָעֶלְיוֹן הַזֶּה."],"Tanya, Part IV; Iggeret HaKodesh 11:1":["לְהַשְׂכִּילְךָ בִּינָה, כִּי לֹא זוֹ הַדֶּרֶךְ יִשְׁכּוֹן אוֹר ה׳ לִהְיוֹת חָפֵץ בְּחַיֵּי בְשָׂרִים וּבָנֵי וּמְזוֹנֵי, כִּי עַל זֶה אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה ״בַּטֵּל רְצוֹנְךָ כוּ׳״, דְּהַיְינוּ, שֶׁיִּהְיֶה רְצוֹנוֹ בָּטֵל בִּמְצִיאוּת, וְלֹא יִהְיֶה לוֹ שׁוּם רָצוֹן כְּלָל בְּעִנְיְנֵי עוֹלָם הַזֶּה כּוּלָּם, הַנִּכְלָלִים בְּבָנֵי חַיֵּי וּמְזוֹנֵי, וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁ״עַל כָּרְחָךְ אַתָּה חַי״;"],"Tanya, Part IV; Iggeret HaKodesh 11:4":["וְעַל כֵּן, רֵאשִׁית הַכֹּל, שֶׁיִּשְׂמַח הָאָדָם וְיָגֵל בְּכָל עֵת וְשָׁעָה, וְיִחְיֶה מַמָּשׁ בֶּאֱמוּנָתוֹ בַּה׳, הַמְחַיֶּה וּמֵטִיב עִמּוֹ בְּכָל רֶגַע. וּמִי שֶׁמִּתְעַצֵּב וּמִתְאוֹנֵן – מַרְאֶה בְּעַצְמוֹ שֶׁיֵּשׁ לוֹ מְעַט רַע וְיִסּוּרִין וְחָסֵר לוֹ אֵיזֶה טוֹבָה, וַהֲרֵי זֶה כְּכוֹפֵר חַס וְשָׁלוֹם. וְעַל כֵּן הִרְחִיקוּ מִדַּת הָעַצְבוּת בִּמְאֹד חַכְמֵי הָאֱמֶת."],"Tanya, Part IV; Iggeret HaKodesh 12:1":["וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם, וַעֲבוֹדַת הַצְּדָקָה הַשְׁקֵט וָבֶטַח עַד עוֹלָם. לְהָבִין הַהֶפְרֵשׁ שֶׁבֵּין ״מַעֲשֶׂה״ לַ״עֲבוֹדָה״ וּבֵין ״שָׁלוֹם״ לְ״הַשְׁקֵט וָבֶטַח״ כוּ׳. עַל פִּי מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה עַל פָּסוּק ״עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו״ – כִּי ״מִיכָאֵל שַׂר שֶׁל מַיִם וְגַבְרִיאֵל שַׂר שֶׁל אֵשׁ, וְאֵין מְכַבִּין זֶה אֶת זֶה״."],"Tanya, Part IV; Iggeret HaKodesh 12:10":["וּבֵירוּר זֶה יִהְיֶה גַם כֵּן עַל־יְדֵי גִּילּוּי אֱלֹקוּתוֹ לְמַטָּה בְּהֶאָרָה רַבָּה וְהַשְׁפָּעָה עֲצוּמָה, כְּמוֹ שֶׁכָּתוּב: ״כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה׳״, ״וְנִגְלָה כְּבוֹד ה׳ כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 12:13":["וְהִנֵּה מוּדַעַת זֹאת, שֶׁיִּשְׂרָאֵל בְּטִבְעָם הֵם רַחֲמָנִים וְגוֹמְלֵי חֲסָדִים, מִפְּנֵי הֱיוֹת נַפְשׁוֹתֵיהֶם נִמְשָׁכוֹת מִמִּדּוֹתָיו יִתְבָּרֵךְ, אֲשֶׁר הַחֶסֶד גּוֹבֵר בָּהֶן עַל מִדַּת הַדִּין וְהַגְּבוּרָה וְהַצִּמְצוּם, וּכְמוֹ שֶׁכָּתוּב: ״גָּבַר חַסְדּוֹ עַל יְרֵיאָיו״, שֶׁלָּכֵן נִקְרֵאת הַנְּשָׁמָה ״בַּת כֹּהֵן״ כְּמוֹ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ."],"Tanya, Part IV; Iggeret HaKodesh 12:16":["וְזֶהוּ שֶׁכָּתוּב ״וְהָיָה מַעֲשֵׂה הַצְּדָקָה״, שֶׁגַּם הַצְּדָקָה הַנִּקְרֵאת בְּשֵׁם ״מַעֲשֶׂה״ וְלֹא בְּשֵׁם ״עֲבוֹדָה״, אַף־עַל־פִּי־כֵן, בְּ״אִתְעָרוּתָא דִלְתַתָּא אִתְעָרוּתָא דִלְעֵילָּא״, מְעוֹרֵר גִּילּוּי אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא בְּהֶאָרָה רַבָּה וְהַשְׁפָּעָה עֲצוּמָה, וְנַעֲשֶׂה שָׁלוֹם בִּמְרוֹמָיו וְגַם בְּפָמַלְיָא שֶׁל מַטָּה."],"Tanya, Part IV; Iggeret HaKodesh 12:3":["אַךְ הַקָּדוֹשׁ־בָּרוּךְ־הוּא – עוֹשֶׂה שָׁלוֹם בֵּינֵיהֶם, דְּהַיְינוּ, עַל־יְדֵי גִּילּוּי שֶׁמִּתְגַּלֶּה בָּהֶן הֶאָרָה רַבָּה וְהַשְׁפָּעָה עֲצוּמָה מְאֹד מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, אֲשֶׁר כִּשְׁמוֹ כֵּן הוּא, שֶׁאֵינוֹ בִּבְחִינַת מִדָּה חַס וְשָׁלוֹם, אֶלָּא לְמַעְלָה מַּעְלָה עַד אֵין קֵץ, אֲפִילוּ מִבְּחִינַת חָכְמָה־בִּינָה־דַּעַת מְקוֹר הַמִּדּוֹת, וַאֲזַי, הַמִּדּוֹת נֶגְדִּיּוֹת שֶׁל מִיכָאֵל וְגַבְרִיאֵל נִכְלָלוֹת בִּמְקוֹרָן וְשָׁרְשָׁן, וְהָיוּ לַאֲחָדִים מַמָּשׁ, וּבְטֵלִים בְּאוֹרוֹ יִתְבָּרֵךְ הַמֵּאִיר לָהֶם בִּבְחִינַת גִּילּוּי."],"Tanya, Part IV; Iggeret HaKodesh 12:6":["וְהִנֵּה, אִתְעָרוּתָא דִלְעֵילָּא, לְעוֹרֵר גִּילּוּי הֶאָרָה רַבָּה וְהַשְׁפָּעָה עֲצוּמָה הַנִּזְכֶּרֶת לְעֵיל, מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, לַעֲשׂוֹת שָׁלוֹם הַנִּזְכָּר לְעֵיל, הִיא בְּאִתְעָרוּתָא דִלְתַתָּא, בְּמַעֲשֵׂה הַצְּדָקָה וְהַשְׁפָּעַת חַיִּים חֵן וָחֶסֶד וְרַחֲמִים לְמַאן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם, וּלְהַחֲיוֹת רוּחַ שְׁפָלִים כוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 13:1":["מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ וְגוֹ׳."],"Tanya, Part IV; Iggeret HaKodesh 13:10":["וְזֶהוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ עָלָיו־הַשָּׁלוֹם: ״מָה רַב טוּבְךָ וְגוֹ׳״. כְּלוֹמַר, שֶׁמִּדַּת הַטּוֹב וְהַחֶסֶד אֲשֶׁר הִיא בִּבְחִינַת הֶעְלֵם וְהֶסְתֵּר אֵצֶל כָּל מִי שֶׁשּׁוֹרֶשׁ נִשְׁמָתוֹ מִבְּחִינַת שְׂמֹאל, הַנִּקְרָא בְּשֵׁם ״יְרֵאֶיךָ״, כְּמִדַּת בֵּית שַׁמַּאי, הִנֵּה אַף שֶׁהוּא טוֹב הַגָּנוּז וְצָפוּן, אַף־עַל־פִּי־כֵן, הוּא רַב וְגָדוֹל מְאֹד כְּמוֹ מִדַּת הַגְּדוּלָּה וְהַחֶסֶד מַמָּשׁ שֶׁמִּבְּחִינַת יָמִין, וּשְׁתֵּיהֶן הֵן מִבְּחִינַת גִּילּוּי בְּלִי גְבוּל וּמִדָּה וְשִׁיעוּר."],"Tanya, Part IV; Iggeret HaKodesh 13:6":["וְהִנֵּה, כָּל אִישׁ יִשְׂרָאֵל צָרִיךְ לִהְיוֹת כָּלוּל מִב׳ בְּחִינוֹת אֵלּוּ, וְ״אֵין לְךָ דָבָר שֶׁאֵין לוֹ מָקוֹם״."],"Tanya, Part IV; Iggeret HaKodesh 14:1":["לְעוֹרֵר אֶת הָאַהֲבָה הַיְשָׁנָה וְחִבַּת אֶרֶץ הַקּוֹדֶשׁ, לִהְיוֹת בּוֹעֶרֶת כְּרִשְׁפֵּי אֵשׁ מִקֶּרֶב אִישׁ וְלֵב עָמוֹק, כְּאִלּוּ הַיּוֹם מַמָּשׁ נָתַן ה׳ רוּחוֹ עָלֵינוּ, רוּחַ נְדִיבָה, בְּהִתְנַדֵּב עָם לְמַלֹּאות יָדָם לַה׳, בְּיָד מְלֵאָה וּרְחָבָה, בְּרִיבּוּי אַחַר רִיבּוּי, מִדֵּי שָׁנָה בְּשָׁנָה, הוֹלֵךְ וְעוֹלֶה לְמַעְלָה רֹאשׁ, כְּמִדַּת ״קֹדֶשׁ הָעֶלְיוֹן״ הַמֵּאִיר לְאֶרֶץ הַקּוֹדֶשׁ, הַמִּתְחַדֵּשׁ וּמִתְרַבֶּה תָּמִיד, כְּדִכְתִיב: ״תָּמִיד עֵינֵי ה׳ אֱלֹהֶיךָ בָּהּ, מֵרֵשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה״;"],"Tanya, Part IV; Iggeret HaKodesh 14:5":["וּבְכָל שָׁנָה וְשָׁנָה יוֹרֵד וּמֵאִיר מֵחָכְמָה עִילָּאָה אוֹר חָדָשׁ וּמְחוּדָּשׁ, שֶׁלֹּא הָיָה מֵאִיר עֲדַיִין מֵעוֹלָם לָאָרֶץ הָעֶלְיוֹנָה, כִּי אוֹר כָּל שָׁנָה וְשָׁנָה מִסְתַּלֵּק לְשָׁרְשׁוֹ בְּכָל עֶרֶב רֹאשׁ־הַשָּׁנָה כְּשֶׁ״הַחֹדֶשׁ מִתְכַּסֶּה בּוֹ״, וְאַחַר כָּךְ, עַל־יְדֵי תְּקִיעַת שׁוֹפָר וְהַתְּפִלּוֹת, נִמְשָׁךְ אוֹר חָדָשׁ עֶלְיוֹן מִבְּחִינָה עֶלְיוֹנָה יוֹתֵר שֶׁבְּמַדְרֵגַת חָכְמָה עִילָּאָה, לְהָאִיר לָאָרֶץ עֶלְיוֹנָה וְלַדָּרִים עָלֶיהָ, הֵם כָּל הָעוֹלָמוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים הַמְקַבְּלִים חַיּוּתָם מִמֶּנָּה, דְּהַיְינוּ, מִן הָאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא וְחָכְמָתוֹ הַמְלוּבָּשׁ בָּהּ, כְּדִכְתִיב: ״כִּי עִמְּךָ מְקוֹר חַיִּים, בְּאוֹרְךָ נִרְאֶה אוֹר״, דְּהַיְינוּ, אוֹר הַמֵּאִיר מֵחָכְמָה עִילָּאָה מְקוֹר הַחַיִּים (וְכַנּוֹדָע לְיוֹדְעֵי חֵן, שֶׁבְּכָל רֹאשׁ־הַשָּׁנָה הִיא הַנְּסִירָה, וּמְקַבֶּלֶת מוֹחִין חֲדָשִׁים עֶלְיוֹנִים יוֹתֵר כוּ׳)."],"Tanya, Part IV; Iggeret HaKodesh 14:8":["וְזֶהוּ שֶׁכָּתוּב ״תָּמִיד עֵינֵי ה׳ אֱלֹהֶיךָ בָּהּ״, שֶׁהָ״עֵינַיִם״ הֵם כִּינּוּיִם לְהַמְשָׁכַת וְהֶאָרַת אוֹר הַחָכְמָה, שֶׁלָּכֵן נִקְרְאוּ חֲכָמִים ״עֵינֵי הָעֵדָה״, וַ״אֲוִירָא דְאֶרֶץ יִשְׂרָאֵל מַחְכִּים״."],"Tanya, Part IV; Iggeret HaKodesh 15:1":["לְהָבִין מָשָׁל וּמְלִיצָה דִּבְרֵי חֲכָמִים וְחִידוֹתָם בְּעִנְיַן הַסְּפִירוֹת, מוּדַעַת זֹאת בָּאָרֶץ מִפִּי קְדוֹשֵׁי עֶלְיוֹן נִשְׁמָתָם עֵדֶן."],"Tanya, Part IV; Iggeret HaKodesh 15:17":["וְהִנֵּה, מִדּוֹת אֵלּוּ הֵן בְּחִינוֹת חִיצוֹנִיּוֹת שֶׁבַּנֶּפֶשׁ, וּבְתוֹכָן מְלוּבָּשׁוֹת מִדּוֹת פְּנִימִיּוֹת, שֶׁהֵן בְּחִינוֹת אַהֲבָה וְיִרְאָה כוּ׳. דְּהַיְינוּ, עַל דֶּרֶךְ מָשָׁל, בָּאָב הַמַּשְׁפִּיעַ לִבְנוֹ מֵחֲמַת אַהֲבָתוֹ, וּמוֹנֵעַ הַשְׁפָּעָתוֹ מִפַּחְדּוֹ וְיִרְאָתוֹ, שֶׁלֹּא יָבֹא לִידֵי מִכְשׁוֹל, חַס וְשָׁלוֹם."],"Tanya, Part IV; Iggeret HaKodesh 15:21":["וְהִנֵּה, כָּל זֶה הוּא רַק עַל דֶּרֶךְ מָשָׁל לְבַד, כִּי כָּל זֶה הוּא בַּנֶּפֶשׁ הַשִּׂכְלִית הַתַּחְתּוֹנָה שֶׁבָּאָדָם, הַבָּאָה מִקְּלִיפַּת נוֹגַהּ. אַךְ בֶּאֱמֶת לַאֲמִיתּוֹ, בַּנֶּפֶשׁ הָעֶלְיוֹנָה הָאֱלֹהִית, שֶׁהִיא ״חֵלֶק אֱלוֹהַּ מִמַּעַל״, כָּל הַמִּדּוֹת, פְּנִימִיּוֹת וְחִיצוֹנִיּוֹת, הֵן לַה׳ לְבַדּוֹ."],"Tanya, Part IV; Iggeret HaKodesh 15:30":["וּמְקוֹר וְשׁוֹרֶשׁ כָּל הַמִּדּוֹת הֵן מֵחָכְמָה־בִּינָה־דַּעַת, דְּהַיְינוּ: הַחָכְמָה – הִיא מְקוֹר הַשֵּׂכֶל הַמַּשִּׂיג אֶת ה׳ וְחָכְמָתוֹ וּגְדוּלָּתוֹ וּמִדּוֹתָיו הַקְּדוֹשׁוֹת שֶׁמַּנְהִיג וּמְחַיֶּה בָּהֶן כָּל הָעוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, וּבִינָה – הִיא הַהִתְבּוֹנְנוּת בְּהַשָּׂגָה זוֹ בְּאוֹרֶךְ וְרוֹחַב וְעוֹמֶק בִּינָתוֹ, לְהָבִין דָּבָר מִתּוֹךְ דָּבָר, וּלְהוֹלִיד מֵהַשָּׂגָה זוֹ – תּוֹלְדוֹתֶיהָ, שֶׁהֵן מִדּוֹת אַהֲבָה וְיִרְאָה וּשְׁאָרֵי מִדּוֹת הַנּוֹלָדוֹת בַּנֶּפֶשׁ הָאֱלֹהִית, הַמַּשְׂכֶּלֶת וּמִתְבּוֹנֶנֶת בִּגְדוּלַּת ה׳. כִּי, ״לִגְדוּלָּתוֹ אֵין חֵקֶר״."],"Tanya, Part IV; Iggeret HaKodesh 15:4":["אַךְ צָרִיךְ לְהַקְדִּים, מַה שֶּׁשָּׁמַעְתִּי מִמּוֹרִי עָלָיו־הַשָּׁלוֹם עַל פָּסוּק ״וְאָנֹכִי עָפָר וָאֵפֶר״, שֶׁאָמַר אַבְרָהָם אָבִינוּ עָלָיו־הַשָּׁלוֹם עַל הֶאָרַת נִשְׁמָתוֹ הַמְּאִירָה בְּגוּפוֹ מֵאוֹר חֶסֶד עֶלְיוֹן, וְהִיא מִדָּתוֹ מִדַּת ״אַהֲבָה רַבָּה״, (נוסח אחר: שֶׁבָּהּ הָיָה) שֶׁהָיָה אוֹהֵב אֶת הַקָּדוֹשׁ־בָּרוּךְ־הוּא אַהֲבָה גְדוֹלָה וְעֶלְיוֹנָה כָּל כָּךְ, עַד שֶׁנַּעֲשָׂה ״מֶרְכָּבָה״ לְהַקָּדוֹשׁ־בָּרוּךְ־הוּא."],"Tanya, Part IV; Iggeret HaKodesh 15:9":["וְהִנֵּה, כְּלָלוּת הַי׳ סְפִירוֹת שֶׁבְּנִשְׁמַת הָאָדָם, נוֹדָע לַכֹּל [בְּדֶרֶךְ כְּלָל. בכתב יד ליתא], שֶׁהַמִּדּוֹת נֶחְלָקוֹת בְּדֶרֶךְ כְּלָל לְז׳ מִדּוֹת, וְכָל פְּרָטֵי הַמִּדּוֹת שֶׁבָּאָדָם – בָּאוֹת מֵאַחַת מִז׳ מִדּוֹת אֵלּוּ, שֶׁהֵן שׁוֹרֶשׁ כָּל הַמִּדּוֹת וּכְלָלוּתָן, שֶׁהֵן: מִדַּת הַחֶסֶד לְהַשְׁפִּיעַ בְּלִי גְבוּל, וּמִדַּת הַגְּבוּרָה – לְצַמְצֵם מִלְּהַשְׁפִּיעַ כָּל כָּךְ, אוֹ שֶׁלֹּא לְהַשְׁפִּיעַ [נוסח אחר: כָּל עִיקָּר] כְּלָל, וּמִדַּת הָרַחֲמִים – לְרַחֵם עַל מִי שֶׁשַּׁיָּיךְ לְשׁוֹן רַחֲמָנוּת עָלָיו, וְהִיא מִדָּה מְמוּצַּעַת בֵּין גְּבוּרָה לְחֶסֶד, שֶׁהִיא לְהַשְׁפִּיעַ לַכֹּל, גַּם לְמִי שֶׁלֹּא שַׁיָּיךְ לְשׁוֹן רַחֲמָנוּת עָלָיו כְּלָל, מִפְּנֵי שֶׁאֵינוֹ חָסֵר כְּלוּם וְאֵינוֹ שָׁרוּי בְּצַעַר כְּלָל."],"Tanya, Part IV; Iggeret HaKodesh 16:1":["לאנשי קהלת וכו׳"],"Tanya, Part IV; Iggeret HaKodesh 16:5":["וְהִנֵּה, זֶהוּ עַל פִּי שׁוּרַת הַדִּין גָּמוּר. אֲבָל בֶּאֱמֶת, גַּם אִם הוּא עִנְיָן דְּלֹא שַׁיָּיךְ כָּל כָּךְ הַאי טַעֲמָא רָאוּי לְכָל אָדָם שֶׁלֹּא לְדַקְדֵּק לְהַעֲמִיד עַל הַדִּין, רַק לִדְחוֹק חַיָּיו וְלִיכָּנֵס לִפְנַי וְלִפְנִים מִשּׁוּרַת הַדִּין, וְלִדְאוֹג לְעַצְמוֹ מִמַּאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁכָּל הַמְדַקְדֵּק בְּכָךְ – סוֹף בָּא לִידֵי כָךְ, חַס וְשָׁלוֹם."],"Tanya, Part IV; Iggeret HaKodesh 17:1":["נוֹדָע, דִּבְ״אִתְעָרוּתָא דִלְתַתָּא״, שֶׁהָאָדָם מְעוֹרֵר בְּלִבּוֹ מִדַּת הַחֶסֶד וְרַחֲמָנוּת עַל כָּל הַצְּרִיכִים לְרַחֲמִים – ״אִתְעָרוּתָא דִלְעֵילָּא״, לְעוֹרֵר עָלָיו רַחֲמִים רַבִּים מִמְּקוֹר הָרַחֲמִים, לְהַשְׁפִּיעַ לוֹ הַפֵּירוֹת בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן לָעוֹלָם־הַבָּא."],"Tanya, Part IV; Iggeret HaKodesh 17:10":["וְזֶהוּ ״רְחָבָה מִצְוָתְךָ מְאֹד״, הִיא מִצְוַת הַצְּדָקָה, שֶׁהִיא כְּלִי וְשֶׁטַח רָחָב מְאֹד, לְהִתְלַבֵּשׁ בָּהּ הֶאָרַת אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא (וּכְמוֹ שֶׁכָּתוּב: ״לְבוּשׁוֹ צְדָקָה״), אֲשֶׁר יָאִיר לֶעָתִיד בִּבְחִינַת בְּלִי גְבוּל וְתַכְלִית בְּחֶסֶד חִנָּם בְּ״אִתְעָרוּתָא דִלְתַתָּא״ זוֹ, הַנִּקְרֵאת ״דֶּרֶךְ ה׳״. וְזֶהוּ לְשׁוֹן ״מְאֹד״, שֶׁהוּא בְּלִי גְבוּל וְתַכְלִית."],"Tanya, Part IV; Iggeret HaKodesh 17:7":["וְזֶהוּ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם וְנֶהֱנִין כוּ׳״, ״עֲטָרָה״ הִיא בְּחִינַת מַקִּיף וְסוֹבֵב, וְנִקְרָא ״כֶּתֶר״ מִלְּשׁוֹן ״כּוֹתֶרֶת״, וְהוּא בְּחִינַת מְמוּצָּע הַמְחַבֵּר הֶאָרַת הַמַּאֲצִיל אֵין־סוֹף בָּרוּךְ־הוּא לְהַנֶּאֱצָלִים, וְלֶעָתִיד יָאִיר וְיִתְגַּלֶּה בָּעוֹלָם הַזֶּה לְכָל הַצַּדִּיקִים שֶׁיָּקוּמוּ בַּתְּחִיָּיה (״וְעַמֵּךְ כּוּלָּם צַדִּיקִים כוּ׳״)."],"Tanya, Part IV; Iggeret HaKodesh 18:1":["כְּתִיב: ״מַה יָּפִית וּמַה נָּעַמְתְּ, אַהֲבָה בַּתַּעֲנוּגִים״."],"Tanya, Part IV; Iggeret HaKodesh 18:5":["וְהַשֵּׁנִית – הִיא אַהֲבָה וְתַאֲוָה, שֶׁהַנֶּפֶשׁ מִתְאַוָּה וְאוֹהֶבֶת וַחֲפֵיצָה לְדָבְקָה בַּה׳, לִצְרוֹר בִּצְרוֹר הַחַיִּים, וְקִרְבַת אֱלֹהִים טוֹב לָהּ מְאֹד, וּבוֹ תַּחְפּוֹץ, וְרַע לָהּ מְאֹד לְהִתְרַחֵק מִמֶּנּוּ יִתְבָּרֵךְ חַס וְשָׁלוֹם, לִהְיוֹת מְחִיצָה שֶׁל בַּרְזֶל מֵהַחִיצוֹנִים מַפְסֶקֶת חַס וְשָׁלוֹם."],"Tanya, Part IV; Iggeret HaKodesh 19:1":["עוֹטֶה אוֹר כַּשַּׂלְמָה וְגוֹ׳. הִנֵּה, בְּ״לִקּוּטֵי תּוֹרָה״ שֶׁל הָאֲרִיזַ״ל פָּרָשַׁת כִּי תִשָּׂא וּפָרָשַׁת וַיִּקְרָא כָּתַב, כִּי הַשָּׂגַת מֹשֶׁה רַבֵּנוּ עָלָיו־הַשָּׁלוֹם לֹא הָיְתָה בִּבְחִינַת פְּנִימִיּוּת דְּחָכְמָה עִילָּאָה, הַנִּקְרָא ״אַבָּא דַאֲצִילוּת״, וְכָל שֶׁכֵּן בִּסְפִירַת הַכֶּתֶר שֶׁלְּמַעְלָה מִמֶּנָּה, הַנִּקְרָא ״אֲרִיךְ אַנְפִּין״, כִּי אִם בִּבְחִינַת אֲחוֹרַיִים דְּחָכְמָה הַמִּתְלַבְּשִׁים בְּבִינָה, הַמִּתְלַבֶּשֶׁת בְּז׳ סְפִירוֹת תַּחְתּוֹנוֹת שֶׁנִּקְרָאִים ״זְעֵיר אַנְפִּין״, סוֹד הַתּוֹרָה, וּמִתְפַּשֶּׁטֶת עַד סוֹף ד׳ סְפִירוֹת הַתַּחְתּוֹנוֹת, שֶׁהֵן נֶצַח־הוֹד־יְסוֹד־מַלְכוּת, וְשָׁם הָיְתָה הַשָּׂגַת נְבוּאָתוֹ בִּבְחִינַת פְּנִימִיּוּת, דְּהַיְינוּ מִבְּחִינַת פְּנִימִיּוּת דְּנֶצַח־הוֹד־יְסוֹד־מַלְכוּת."],"Tanya, Part IV; Iggeret HaKodesh 19:11":["וְהִנֵּה, בְּחִינַת חָכְמַת אֱלֹהוּת בָּרוּךְ־הוּא הַמְלוּבֶּשֶׁת בְּתַרְיַ״ג מִצְוֹת הַתּוֹרָה נִקְרֵאת בְּשֵׁם ״בְּחִינַת אֲחוֹרַיִים דְּחָכְמָה״, כִּי כָּל אֲחוֹרַיִים שֶׁבַּסְּפִירוֹת הֵן מַדְרֵגוֹת הַחִיצוֹנוֹת וְהַתַּחְתּוֹנוֹת בְּמַעֲלָה שֶׁבִּסְפִירָה זוֹ, מַה שֶּׁיּוּכְלוּ לֵירֵד וּלְהִתְפַּשֵּׁט לְמַטָּה לְהִתְלַבֵּשׁ בַּבְּרוּאִים לְהַחֲיוֹתָם; וּבְחִינַת הַפָּנִים, הִיא הַסְּפִירָה עַצְמָהּ הַמְיוּחֶדֶת בְּמַאֲצִילָהּ אֵין־סוֹף בָּרוּךְ־הוּא בְּתַכְלִית הַיִּחוּד."],"Tanya, Part IV; Iggeret HaKodesh 19:14":["כֵּן עַל דֶּרֶךְ זֶה מַמָּשׁ – הִיא בְּחִינַת חָכְמָתוֹ יִתְבָּרֵךְ, מַה שֶּׁיּוּכַל לְהִתְפַּשֵּׁט מִמֶּנָּה (לְהַשְׁפִּיעַ) [לְהִתְלַבֵּשׁ] בַּתַּחְתּוֹנִים כּוּלָּם, הֵם כְּאַיִן לְגַבֵּי בְּחִינַת פָּנִים הַמְיוּחָד בַּמַּאֲצִיל בָּרוּךְ־הוּא, דְּ״כוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיב״, וְהַהַשְׁפָּעָה לְכָל הַנִּבְרָאִים כּוּלָּם שֶׁהֵם בַּעֲלֵי גְבוּל וְתַכְלִית – נֶחְשֶׁבֶת יְרִידָה וְצִמְצוּם כִּבְיָכוֹל לְגַבֵּי הַמַּאֲצִיל אֵין־סוֹף בָּרוּךְ־הוּא, עַל דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁנֶּחְשֶׁבֶת יְרִידָה וְצִמְצוּם לְשֵׂכֶל הָאָדָם הַמַּשְׂכִּיל הַמְצוּמְצָם בְּאֵיזֶה עֲשִׂיָּה גַּשְׁמִיּוּת וְחוּמְרִית מַמָּשׁ."],"Tanya, Part IV; Iggeret HaKodesh 19:16":["הָאוֹתִיּוֹת הַנִּגְלוֹת לָנוּ, הֵן בְּמַעֲשֶׂה דִּבּוּר וּמַחֲשָׁבָה."],"Tanya, Part IV; Iggeret HaKodesh 19:4":["אַךְ הָעִנְיָן הוּא פָּשׁוּט וּמוּבָן לַכֹּל, שֶׁיֵּשׁ הֶפְרֵשׁ גָּדוֹל בֵּין הַשָּׂגַת חַכְמֵי הָאֱמֶת כְּרַשְׁבִּ״י וְהָאֲרִיזַ״ל, שֶׁהִיא הַשָּׂגַת חָכְמָה וָדַעַת, וּבֵין הַשָּׂגַת מֹשֶׁה רַבֵּינוּ עָלָיו־הַשָּׁלוֹם וּשְׁאָר הַנְּבִיאִים בִּנְבוּאָה, הַמְכוּנָּה בַּכָּתוּב בְּשֵׁם ״רְאִיָּה״ מַמָּשׁ; וְרָאִיתָ אֶת אֲחוֹרָי״, ״וָאֶרְאֶה אֶת ה׳״, ״וַיֵּרָא אֵלָיו ה׳״."],"Tanya, Part IV; Iggeret HaKodesh 1:1":["פּוֹתְחִין בִּבְרָכָה, לְבָרֵךְ וּלְהוֹדוֹת לַה׳ כִּי טוֹב. שְׁמוּעָה טוֹבָה שָׁמְעָה וַתְּחִי נַפְשִׁי, ״תּוֹרַת ה׳ תְּמִימָה״ – זוֹ הַשְׁלָמַת כָּל הַשַּׁ״ס כּוּלּוֹ בְּרוֹב עֲיָירוֹת וּמִנְיָנִים מֵאַנְשֵׁי שְׁלוֹמֵנוּ, הוֹדָאָה עַל הֶעָבָר וּבַקָּשָׁה עַל הֶעָתִיד, כֹּה יִתֵּן וְכֹה יוֹסִיף ה׳ לְאַמֵּץ לִבָּם בַּגִּבּוֹרִים מִדֵּי שָׁנָה בְּשָׁנָה, בִּגְבוּרָה שֶׁל תּוֹרָה. וּלְהוֹדִיעַ לִבְנֵי אָדָם גְּבוּרָתָהּ שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה וְכֹחָהּ עוֹז;"],"Tanya, Part IV; Iggeret HaKodesh 1:6":["אַךְ מִי הוּא הַנּוֹתֵן כֹּחַ וָעוֹז לִבְחִינַת ״מָתְנַיִם״, לְהַעֲמִיד וּלְקַיֵּים הָרֹאשׁ וְהַזְּרוֹעוֹת? – הוּא עֵסֶק וְלִימּוּד הֲלָכוֹת בַּתּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהִיא בְּחִינַת גִּילּוּי רָצוֹן הָעֶלְיוֹן, דְּאוֹרַיְיתָא – מֵחָכְמָה הִיא דְנָפְקַת, אֲבָל מְקוֹרָהּ וְשָׁרְשָׁהּ – הוּא לְמַעְלָה מַּעְלָה מִבְּחִינַת חָכְמָה, וְהוּא הַנִּקְרָא בְּשֵׁם ״רָצוֹן הָעֶלְיוֹן״ בָּרוּךְ־הוּא, וּכְמוֹ שֶׁכָּתוּב ״כַּצִּנָּה רָצוֹן תַּעְטְרֶנּוּ״ כַּעֲטָרָה שֶׁהִיא עַל הַמּוֹחִין שֶׁבָּרֹאשׁ, וְכַנּוֹדָע מִמַּה שֶּׁפֵּירְשׁוּ עַל פָּסוּק ״אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ״; וְ״כָל הַשּׁוֹנֶה הֲלָכוֹת בְּכָל יוֹם כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 1:9":["וְעַתָּה הַפַּעַם, הִנְּנִי יוֹסִיף שֵׁנִית יָדִי בְּתוֹסֶפֶת בֵּיאוּר, וּבַקָּשָׁה כְּפוּלָה, שְׁטוּחָה וּפְרוּשָׂה לִפְנֵי כָּל אַנְשֵׁי שְׁלוֹמִים הַקְּרוֹבִים וְהָרְחוֹקִים, לְקַיֵּים עֲלֵיהֶם."],"Tanya, Part IV; Iggeret HaKodesh 20:1":["אִיהוּ וְחַיּוֹהִי חַד, אִיהוּ וְגַרְמוֹהִי חַד בְּהוֹן. (פֵּירוּשׁ, עֶשֶׂר סְפִירוֹת דַּאֲצִילוּת; חַיּוֹהִי הֵן הָאוֹרוֹת, וְ״גַרְמוֹהִי״ הֵן הַכֵּלִים, שֶׁכּוּלָּן אֱלֹקוּת, מַה שֶּׁאֵין כֵּן בִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה כוּ׳). וְצָרִיךְ לְהָבִין הֵיטֵב, אֵיךְ הָ״אֵין־סוֹף״ חַד עִם ״גַּרְמוֹהִי״ הֵן הַכֵּלִים, הֲרֵי הַכֵּלִים הֵן בִּבְחִינַת גְּבוּל וְתַכְלִית, כְּמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים."],"Tanya, Part IV; Iggeret HaKodesh 20:13":["אָמְנָם מוּדַעַת זֹאת, שֶׁעִיקַּר הִתְהַוּוּת הַיֵּשׁ וְדָבָר נִפְרָד לְגַמְרֵי, הוּא מִמַּלְכוּת דַּאֲצִילוּת שֶׁנַּעֲשָׂה עַתִּיק דִּבְרִיאָה, כִּי ״אֵין מֶלֶךְ בְּלֹא עָם וְכוּ׳״. וְגַם רִיבּוּי הַנִּבְרָאִים וְהִתְחַלְּקוּתָן שֶׁנִּבְרְאוּ בְּכֹחַ הָ״אֵין־סוֹף״ יָחִיד וּמְיוּחָד בְּתַכְלִית – הוּא עַל־יְדֵי רִיבּוּי הָאוֹתִיּוֹת הַיּוֹצְאִין מִמַּלְכוּת, ״פִּי ה׳״, ״וּבְרוּחַ פִּיו כָּל צְבָאָם״, וְה׳ מוֹצָאוֹת הַפֶּה הֵן מֵה׳ גְּבוּרוֹת דְּנוּקְבָא."],"Tanya, Part IV; Iggeret HaKodesh 20:17":["וּבָזֶה יוּבַן, הֱיוֹת הַמִּצְוֹת בְּמַלְכוּת – ה׳ שֶׁל שֵׁם הַוָיָ׳, וְהַתּוֹרָה בִּ״זְעֵיר אַנְפִּין״ – וָא״ו שֶׁל שֵׁם הַוָיָ׳, הֲגַם שֶׁלְּמַעְלָה בַּ״אֲרִיךְ אַנְפִּין״ הַמִּצְוֹת הֵן בְּ״גוּלְגַּלְתָּא״, בְּ״לַבְנוּנִית״, הִיא הָ״אוּרְחָא״ דִּבְ״פַלְגוּתָא דְשַׂעֲרֵי״, דְּמִתְפַּלְגָא לְתַרְיַ״ג אוּרְחִין דְּאוֹרַיְיתָא שֶׁבִּ״זְעֵיר אַנְפִּין״, וְשֹׁרֶשׁ הַתּוֹרָה דְּנָפְקָא מֵ״חָכְמָה עִילָּאָה״ הוּא בְּ״מוֹחָא סְתִימָאָה״ דַּ״אֲרִיךְ אַנְפִּין״, וְהַיְינוּ, הַחָכְמָה דְּטַעֲמֵי הַמִּצְוֹת, אֶלָּא שֶׁהוּא כְּחוֹתָם הַמִּתְהַפֵּךְ."],"Tanya, Part IV; Iggeret HaKodesh 20:20":["וְהִנֵּה, כְּמוֹ כֵן מִזִּיוּוּג זְעֵיר אַנְפִּין וְנוּקְבָא דִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה נִבְרְאוּ מֵאַיִן לְיֵשׁ כָּל הַנִּבְרָאִים וְהַנּוֹצָרִים וְהַנַּעֲשִׂים, עַל־יְדֵי אוֹר הַנְּשָׁמָה שֶׁבְּתוֹכָן, שֶׁהִיא אֱלֹקוּת, מֵהַכֵּלִים דְּי׳ סְפִירוֹת דְּמַלְכוּת דַּאֲצִילוּת, וְגַם בְּתוֹכָהּ הֶאָרַת הַ״קַּו״ דְּאוֹר־אֵין־סוֹף הַמְלוּבָּשׁ בַּאֲצִילוּת עַד הַ״פַּרְסָא״, וְהֶאָרַת הַ״קַּו״ שֶׁהָיָה מֵאִיר בַּכֵּלִים דְּי׳ סְפִירוֹת דְּמַלְכוּת בָּקַע הַ״פַּרְסָא״ עִמָּהֶם, וּמֵאִיר בָּהֶם בִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה כְּמוֹ בַּאֲצִילוּת מַמָּשׁ."],"Tanya, Part IV; Iggeret HaKodesh 20:22":["וְכָל זֹאת בִּבְחִינַת הִתְפַּשְּׁטוּת הַחַיּוּת לְהַחֲיוֹתָם. אָמְנָם, מְצִיאוּתוֹ וּמַהוּתוֹ שֶׁל אוֹר הָאֵין־סוֹף – אֵינוֹ בְּגֶדֶר מָקוֹם כְּלָל, וְסוֹבֵב כָּל עָלְמִין בְּשָׁוֶה, וְ״אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא״ בְּהַשְׁוָואָה אַחַת, וְ״לֵית אֲתַר פָּנוּי מִינֵּיהּ״ אַף בָּאָרֶץ הַלֵּזוּ הַגַּשְׁמִית, רַק, שֶׁהוּא בִּבְחִינַת מַקִּיף וְסוֹבֵב, וּכְמוֹ שֶׁנִּתְבָּאֵר הַפֵּירוּשׁ בְּלִקּוּטֵי אֲמָרִים, וְלֹא הִתְפַּשְּׁטוּת וְהִתְלַבְּשׁוּת הַחַיּוּת לְהַחֲיוֹתָם וּלְהַוּוֹתָם מֵאַיִן לְיֵשׁ, כִּי אִם עַל־יְדֵי הֶאָרָה דְהֶאָרָה דְהֶאָרָה וְכוּ׳ מֵהַ״קַּו״, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part IV; Iggeret HaKodesh 20:25":["וְעוֹד זֹאת, יֶתֶר עַל כֵּן עַל כָּל הַנִּזְכָּר לְעֵיל, הֶאָרָה דְהֶאָרָה דְהֶאָרָה, וְכָל הַנִּזְכָּר לְעֵיל הִיא מַרְאָה כֹּחָהּ וִיכָלְתָּהּ בִּיסוֹד הֶעָפָר הַגַּשְׁמִי בְּגִילּוּי עָצוּם, בְּיֶתֶר עֹז מִיסוֹדוֹת הָעֶלְיוֹנִים מִמֶּנּוּ, וְגַם מִצְּבָא הַשָּׁמַיִם, שֶׁאֵין בְּכֹחָם וִיכָלְתָּם לְהוֹצִיא יֵשׁ מֵאַיִן תָּמִיד, כִּיסוֹד הֶעָפָר הַמַּצְמִיחַ תָּמִיד יֵשׁ מֵאַיִן, הֵם עֲשָׂבִים וְאִילָנוֹת (וְהַמַּזָּל הַמַּכֶּה וְאוֹמֵר ״גְּדַל״, הַיְינוּ לְאַחַר שֶׁכְּבָר צָמַח הָעֵשֶׂב, וְאֵינוֹ אוֹמֵר לוֹ לִצְמוֹחַ מֵאַיִן לְיֵשׁ אֶלָּא מִקּוֹטֶן לְגוֹדֶל, וְלָשֵׂאת פְּרִי כָּל מִין וּמִין בִּפְרָטֵי פְּרָטִיּוּת. אֲבָל בְּטֶרֶם יִצְמַח לְמִי יֹאמַר כָּל מַזָּל וּמַזָּל לְכָל עֵשֶׂב וְעֵשֶׂב בִּפְרָטֵי פְּרָטִיּוּת) מֵהַכֹּחַ הַצּוֹמֵחַ שֶׁבּוֹ, שֶׁהוּא אַיִן וְרוּחָנִי, וְהֵם גַּשְׁמִיִּים."],"Tanya, Part IV; Iggeret HaKodesh 20:29":["וּלְפִי מַה שֶּׁכָּתוּב בְּ״סֵפֶר הַגִּלְגּוּלִים״ פֶּרֶק כ׳, הוּבָא בְּלִקּוּטֵי אֲמָרִים – מִתְלַבֶּשֶׁת תְּחִלָּה הֶאָרָה זוֹ שֶׁל הַ״קַּו״ דְּאוֹר־אֵין־סוֹף בְּאוֹר הָאֲצִילוּת שֶׁבַּעֲשִׂיָּה, וּמִמֶּנָּה לִבְרִיאָה וִיצִירָה שֶׁבַּעֲשִׂיָּה, וּמֵהֶן לִבְחִינַת אוֹר הַנְּשָׁמָה דְּמַלְכוּת דְּמַלְכוּת דַּעֲשִׂיָּה, וְעַל־יְדֵי זֶה יֵשׁ כֹּחַ וָעוֹז בְּסִיּוּם הַכְּלִי דְּמַלְכוּת דְּמַלְכוּת דַּעֲשִׂיָּה שֶׁבִּיסוֹד הֶעָפָר, וְהוּא מַאֲמַר ״תַּדְשֵׁא הָאָרֶץ וְכוּ׳״, לִהְיוֹת פּוֹעֵל בְּקֶרֶב הָאָרֶץ תָּמִיד לְעוֹלָם וָעֶד –"],"Tanya, Part IV; Iggeret HaKodesh 20:34":["וּמִזֶּה יוּבַן הֵיטֵב בְּעִנְיַן סֵדֶר מַדְרֵגוֹת: דּוֹמֵם, צוֹמֵחַ, חַי, מְדַבֵּר, שֶׁהֵן בְּחִינוֹת עָפָר, מַיִם, אֵשׁ, רוּחַ, שֶׁאַף שֶׁהַחַי הוּא לְמַעְלָה מֵהַצּוֹמֵחַ, וְהַמְדַבֵּר – לְמַעְלָה מֵהַחַי, אַף־עַל־פִּי־כֵן, הַחַי נִיזּוֹן וְחַי מֵהַצּוֹמֵחַ, וְהַמְדַבֵּר מְקַבֵּל חַיּוּתוֹ מִשְּׁנֵיהֶם, וְגַם חָכְמָה וָדַעַת, שֶׁ״אֵין הַתִּינוֹק יוֹדֵעַ לִקְרוֹת ׳אַבָּא׳ וְ׳אִימָּא׳ עַד שֶׁיִּטְעוֹם טַעַם דָּגָן כוּ׳״, וַ״עֲדַיִין לָא אֲכִילְנָא בִּישְׂרָא דְתוֹרָא כוּ׳״, כִּי הוּא בְּחִינַת ״אוֹר חוֹזֵר״ מִמַּטָּה לְמַעְלָה, מִתַּחְתִּית הָעֲשִׂיָּה, שֶׁמִּתְגַּלֵּית שָׁם בְּיֶתֶר עֹז, הֶאָרָה דְהֶאָרָה כוּ׳ מֵאוֹר־אֵין־סוֹף הַסּוֹבֵב כָּל עָלְמִין, וּמֵהַ״קַּו״ אוֹר־אֵין־סוֹף שֶׁבְּסִיּוּם ״רַגְלֵי הַיּוֹשֶׁר״ דְּ״אָדָם קַדְמוֹן״ בִּבְחִינַת ״אוֹר חוֹזֵר״, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part IV; Iggeret HaKodesh 20:5":["וְ״יֵשׁ מֵאַיִן״ נִקְרָא ״בְּרִיאָה״ בִּלְשׁוֹן הַקֹּדֶשׁ. וַהֲגַם שֶׁהַיֵּשׁ הַנִּבְרָא הוּא גַּם כֵּן כְּלָא חֲשִׁיב קַמֵּיהּ, דְּהַיְינוּ, שֶׁבָּטֵל בִּמְצִיאוּת לְגַבֵּי הַכֹּחַ וְהָאוֹר הַשּׁוֹפֵעַ בּוֹ מֵהַכֵּלִים דְּי׳ סְפִירוֹת דַּאֲצִילוּת־בְּרִיאָה־יְצִירָה־עֲשִׂיָּה, שֶׁהַ״קַּו״ אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא מֵאִיר בָּהֶם, וּכְזִיו הַשֶּׁמֶשׁ בַּשֶּׁמֶשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר בְּלִקּוּטֵי אֲמָרִים חֵלֶק ב׳ – הַיְינוּ ״קַמֵּיהּ״ דַּוְקָא, שֶׁהִיא יְדִיעָתוֹ יִתְבָּרֵךְ מִלְמַעְלָה לְמַטָּה."],"Tanya, Part IV; Iggeret HaKodesh 20:7":["וְהִנֵּה, רֵאשִׁית הַיֵּשׁ הַנִּבְרָא וּתְחִילָּתוֹ, הֵן הַכֵּלִים דְּי׳ סְפִירוֹת דִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה, וְגַם הָאוֹרוֹת נֶפֶשׁ־רוּחַ, וְנִבְרְאוּ מִבְּחִינַת הַנְּשָׁמָה דְּי׳ סְפִירוֹת דִבְרִיאָה־יְצִירָה־עֲשִׂיָּה שֶׁהוּא אֱלֹקוּת, וְהֵן הַלַּמֶ״ד כֵּלִים דְּמַלְכוּת דַּאֲצִילוּת. וְכֵן בַּאֲצִילוּת, מֵחִיצוֹנִיּוּת הַכֵּלִים דְּי׳ סְפִירוֹת דַּאֲצִילוּת שֶׁהֵן אֱלֹקוּת, נִבְרְאוּ הַהֵיכָלוֹת דַּאֲצִילוּת שֶׁמִּתְלַבֵּשׁ בָּהֶן בְּחִינַת הָעִיגּוּלִים דְּי׳ סְפִירוֹת, וְגַם גּוּפוֹת הַמַּלְאָכִים דַּאֲצִילוּת שֶׁהֵן בְּחִינַת יֵשׁ, וּכְמוֹ שֶׁכָּתוּב: ״וּבְמַלְאָכָיו יָשִׂים תָּהֳלָה״, שֶׁאֵינָן בִּבְחִינַת בִּיטּוּל לְגַמְרֵי כְּעָלוּל לְגַבֵּי עִילָּתוֹ."],"Tanya, Part IV; Iggeret HaKodesh 20:8":["אַךְ נִשְׁמוֹת הַמַּלְאָכִים שֶׁיָּצְאוּ מִ״זִּיוּוּג הַנְּשִׁיקִין״, וְכֵן נִשְׁמוֹת הָאָדָם שֶׁיָּצְאוּ מִזִּיוּוּג דְּזָ״א וְנוּקְבָא דַּאֲצִילוּת קוֹדֶם שֶׁיָּרְדוּ לִבְרִיאָה־יְצִירָה־עֲשִׂיָּה אֵינָן בִּכְלַל ״יֵשׁ״ וְדָבָר נִפְרָד בִּפְנֵי עַצְמָן, אֶלָּא הֵן מֵעֵין בְּחִינַת אֱלֹקוּת בְּצִמְצוּם עָצוּם, וּכְעֵין הַכֵּלִים דְּי׳ סְפִירוֹת דַּאֲצִילוּת, שֶׁהֵן בִּבְחִינַת גְּבוּל עַל־יְדֵי צִמְצוּם אוֹר הָאֵין־סוֹף, הוּא הַ״קַּו״ הַמְלוּבָּשׁ בְּנֶפֶשׁ־רוּחַ־נְשָׁמָה שֶׁלָּהֶם, וּכְמוֹ צִמְצוּם הָרִאשׁוֹן לִהְיוֹת חָלָל וְכוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 21:1":["אַחַר דְּרִישַׁת שְׁלוֹמָם, כְּמִשְׁפָּט לְאוֹהֲבֵי שְׁמוֹ, אֶל הַמִּתְנַדְּבִים בָּעָם, לַעֲשׂוֹת צִדְקַת ה׳ עִם אַרְצוֹ הַקְּדוֹשָׁה, לָתֵת מִדֵּי שָׁנָה בְּשָׁנָה חוֹק הַקָּצוּב מָעוֹת אֶרֶץ הַקּוֹדֶשׁ, תִּבָּנֶה וְתִכּוֹנֵן בִּמְהֵרָה בְיָמֵינוּ, אֲלֵיהֶם תִּטּוֹף מִלָּתִי, וְתִזַּל כַּטַּל אִמְרָתִי, לְזָרֵז לִזְרִיזִים, וּלְחַזֵּק יָדַיִם רָפוֹת בְּמַתַּן דָּמִים מָעוֹת אֶרֶץ יִשְׂרָאֵל מִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ, וּלְפָחוֹת מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ, מֵעֶרְכּוֹ הַקָּצוּב לְעֵרֶךְ שָׁנָה, וְכָל כֶּסֶף הַקֳּדָשִׁים אֲשֶׁר עָלָה עַל לֵב אִישׁ לְהִתְנַדֵּב בְּלִי נֶדֶר לְפַרְנָסַת אַחֵינוּ יוֹשְׁבֵי אֶרֶץ הַקּוֹדֶשׁ, מִדֵּי שָׁנָה בְּשָׁנָה."],"Tanya, Part IV; Iggeret HaKodesh 21:5":["אַךְ גַּם זֹאת מָצָאנוּ רָאִינוּ בַּעֲבוֹדַת הַצְּדָקָה, מַעֲלָה פְּרָטִיּוּת גְּדוֹלָה וְנִפְלָאָה אֵין עֲרוֹךְ אֵלֶיהָ, לִהְיוֹת מַעֲשֵׂה הַצְּדָקָה נַעֲשֵׂית בִּפְעָמִים רַבּוֹת, וְכָל הַמַּרְבֶּה – הֲרֵי זֶה מְשׁוּבָּח, וְלֹא בְּפַעַם אַחַת וּבְבַת אַחַת, גַּם כִּי הַסַּךְ הַכּוֹלֵל אֶחָד הוּא, כְּמוֹ שֶׁכָּתַב הָרַמְבַּ״ם זִכְרוֹנוֹ לִבְרָכָה בְּפֵירוּשׁ הַמִּשְׁנָה שֶׁשָּׁנוּ חֲכָמִים זִכְרוֹנָם לִבְרָכָה: ״וְהַכֹּל לְפִי רוֹב הַמַּעֲשֶׂה״:"],"Tanya, Part IV; Iggeret HaKodesh 22:1":["אֲהוּבַיי, אַחַיי וְרֵעַיי!"],"Tanya, Part IV; Iggeret HaKodesh 22:10":["וְעֵצָה הַיְּעוּצָה לְקַבֵּל בְּאַהֲבָה, הִיא עֲצַת ה׳ בְּפִי חֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״לְפַשְׁפֵּשׁ בְּמַעֲשָׂיו״, וְיִמְצָא לוֹ עֲוֹנוֹת הַצְּרִיכִין מֵירוּק יִסּוּרִים, וְיִרְאֶה לָעַיִן גּוֹדֶל אַהֲבָתוֹ אֵלָיו, הַמְקַלְקֶלֶת הַשּׁוּרָה, כִּמְשַׁל מֶלֶךְ גָּדוֹל וְנוֹרָא הָרוֹחֵץ בִּכְבוֹדוֹ וּבְעַצְמוֹ צוֹאַת בְּנוֹ יְחִידוֹ, מֵרוֹב אַהֲבָתוֹ, כְּמוֹ שֶׁכָּתוּב: ״אִם רָחַץ ה׳ צוֹאַת בְּנוֹת צִיּוֹן כוּ׳, בְּרוּחַ מִשְׁפָּט כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 22:13":["אֲהוּבַיי, אַחַיי וְרֵעַיי!"],"Tanya, Part IV; Iggeret HaKodesh 22:17":["וְעוֹד זֹאת אֶדְרוֹשׁ מִמַּעֲלַתְכֶם, שֶׁלֹּא לְהַשְׁלִיךְ דְּבָרַי אַחֲרֵיכֶם, אֲשֶׁר עָרַכְתִּי שִׂיחַ, לִהְיוֹת כָּל אִישׁ יָשָׁר וְהוֹלֵךְ בְּתוּמּוֹ, כַּאֲשֶׁר ״עָשָׂה הָאֱלֹקִים אֶת הָאָדָם יָשָׁר״, וְלֹא לְבַקֵּשׁ ״חֶשְׁבּוֹנוֹת רַבִּים״, מֵ״עֲלִילוֹת מִצְעֲדֵי גָבֶר וּמַחְשְׁבוֹת אָדָם וְתַחְבּוּלוֹתָיו״. כִּי זוֹ, מְלֶאכֶת שָׁמַיִם הִיא וְלֹא מְלֶאכֶת בָּשָׂר וָדָם."],"Tanya, Part IV; Iggeret HaKodesh 22:5":["אַךְ הָאֱמֶת אַגִּיד לַשּׁוֹמְעִים לִי, כִּי ״אַהֲבָה מְקַלְקֶלֶת הַשּׁוּרָה״, וְ״הִנֵּה הִיא כְּסוּת עֵינַיִם״ שֶׁלֹּא לִרְאוֹת הָאֱמֶת, מֵרוֹב אַהֲבָתָם לְחַיֵּי הַגּוּף לְשֵׁם שָׁמַיִם, לַעֲבוֹד בּוֹ אֶת ה׳, בְּרִשְׁפֵּי אֵשׁ וְשַׁלְהֶבֶת גְּדוֹלָה מֵאַהֲבַת נַפְשָׁם אֶת ה׳, וְעַל כֵּן, הֵיטֵב חָרָה לָהֶם בְּצַעַר הַגּוּף חַס וְשָׁלוֹם ה׳ יְרַחֵם, וְאֵין יְכוֹלִין לְקַבֵּל כְּלָל, עַד שֶׁמַּעֲבִירָם עַל דַּעְתָּם, לְכַתֵּת רַגְלֵיהֶם מֵעִיר לְעִיר, לִשְׁאוֹל עֵצוֹת מֵרָחוֹק, וְלֹא שָׁעוּ אֶל ה׳ לָשׁוּב אֵלָיו בְּרוּחַ נְמוּכָה וְהַכְנָעַת הַגּוּף, לְקַבֵּל תּוֹכַחְתּוֹ בְּאַהֲבָה, ״כִּי אֶת אֲשֶׁר יֶאֱהַב ה׳ וְכוּ׳״:"],"Tanya, Part IV; Iggeret HaKodesh 22:6":["וּכְמוֹ אָב רַחֲמָן חָכָם וְצַדִּיק הַמַּכֶּה בְּנוֹ, שֶׁאֵין לְבֵן חָכָם לַהֲפוֹךְ עוֹרֶף לָנוּס, לִמְצוֹא לוֹ עֶזְרָה, אוֹ אֲפִילוּ מֵלִיץ יוֹשֶׁר, לִפְנֵי אָבִיו הָרַחֲמָן וְהַצַּדִּיק וְחָסִיד, רַק לִהְיוֹת ״יָשָׁר יֶחֱזוּ פָנֵימוֹ״ עִם אָבִיו פָּנִים בְּפָנִים, לִסְבּוֹל הַכָּאוֹתָיו בְּאַהֲבָה, לְטוֹב לוֹ כָּל הַיָּמִים."],"Tanya, Part IV; Iggeret HaKodesh 23:1":["בִּגְזֵירַת עִירִין פִּתְגָמָא וּמַאֲמַר קַדִּישִׁין, חַכְמֵי הַמִּשְׁנָה עֲלֵיהֶם־הַשָּׁלוֹם, שֶׁשָּׁנוּ בְּמִשְׁנָתָם: ״עֲשָׂרָה שֶׁיּוֹשְׁבִין וְעוֹסְקִין בַּתּוֹרָה שְׁכִינָה שְׁרוּיָה בֵינֵיהֶם״, ״כִּי זֶה כָּל הָאָדָם״. וְאַף גַּם זֹאת הָיְתָה כָּל יְרִידָתוֹ בָּעוֹלָם הַזֶּה לְצוֹרֶךְ עֲלִיָּה זוֹ, אֲשֶׁר אֵין עֲלִיָּה לְמַעְלָה הֵימֶנָּה."],"Tanya, Part IV; Iggeret HaKodesh 23:10":["עַל כֵּן, אֲהוּבַיי אַחַיי וְרֵעַיי, אַל נָא תָּרֵעוּ הָרָעָה הַגְּדוֹלָה הַזֹּאת, וּתְנוּ כָבוֹד לַה׳ אֱלֹהֵיכֶם בְּטֶרֶם יֶחְשַׁךְ, דְּהַיְינוּ, בֵּין מִנְחָה לְמַעֲרִיב כָּל יְמוֹת הַחוֹל, לִלְמוֹד בַּעֲשָׂרָה פְּנִימִיּוּת הַתּוֹרָה, שֶׁהִיא אַגָּדָה שֶׁבְּסֵפֶר ״עֵין יַעֲקֹב״, שֶׁרוֹב סוֹדוֹת הַתּוֹרָה גְּנוּזִין בָּהּ, וּמְכַפֶּרֶת עֲוֹנוֹתָיו שֶׁל אָדָם, כִּמְבוֹאָר בְּכִתְבֵי הָאֲרִיזַ״ל, וְהַנִּגְלוֹת שֶׁבָּהּ – הֵן דַּרְכֵי ה׳ שֶׁיֵּלֵךְ בָּהֶם הָאָדָם וְיָשִׁית עֵצוֹת בְּנַפְשׁוֹ בְּמִילֵּי דִשְׁמַיָּא וּבְמִילֵּי דְעִלְמָא, וְכַיָּדוּעַ לְכָל חַכְמֵי לֵב."],"Tanya, Part IV; Iggeret HaKodesh 23:12":["וּבְשַׁבָּת קֹדֶשׁ בַּעֲלוֹת הַמִּנְחָה יַעַסְקוּ בְּהִלְכוֹת שַׁבָּת, כִּי ״הִלְכְתָא רַבְּתָא לְשַׁבְּתָא״, וּבְקַל – יָכוֹל הָאָדָם לִיכָּשֵׁל בָּהּ חַס וְשָׁלוֹם, אֲפִילוּ בְּאִיסּוּר כָּרֵת וּסְקִילָה מֵחֶסְרוֹן יְדִיעָה, וְ״שִׁגְגַת תַּלְמוּד – עוֹלָה זָדוֹן״ חַס וְשָׁלוֹם, וְאֵין צָרִיךְ לוֹמַר בְּאִיסּוּרֵי דִּבְרֵי־סוֹפְרִים, שֶׁרַבּוּ כְּמוֹ רַבּוּ לְמַעְלָה, וּבִפְרָט בְּאִיסּוּרֵי מוּקְצֶה דִּשְׁכִיחֵי טוּבָא, וַ״חֲמוּרִים דִּבְרֵי־סוֹפְרִים יוֹתֵר מִדִּבְרֵי תוֹרָה״, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁ״כָּל הָעוֹבֵר עַל דִּבְרֵי חֲכָמִים״ אֲפִילוּ בְּאִיסּוּר קַל שֶׁל דִּבְרֵיהֶם, כְּמוֹ הָאוֹכֵל קוֹדֶם תְּפִלַּת עַרְבִית וּכְהַאי גַּוְנָא – ״חַיָּיב מִיתָה״ כְּעוֹבֵר עַל חֲמוּרוֹת שֶׁבַּתּוֹרָה."],"Tanya, Part IV; Iggeret HaKodesh 23:4":["וְהַהֶפְרֵשׁ שֶׁבֵּין הַשְׁרָאָה לִקְבִיעוּת שָׂכָר מוּבָן לִמְבִינֵי מַדָּע, כִּי, קְבִיעַת שָׂכָר הוּא – שֶׁמֵּאִיר ה׳ ״לְנֶפֶשׁ תִּדְרְשֶׁנּוּ״, בְּאוֹר תּוֹרָתוֹ, שֶׁהוּא מַעֲטֵה לְבוּשׁוֹ מַמָּשׁ, וְלָכֵן נִקְרֵאת הַתּוֹרָה ״אוֹר״, שֶׁנֶּאֱמַר: ״עוֹטֶה אוֹר כַּשַּׂלְמָה״, וְהַנֶּפֶשׁ הִיא בַּעֲלַת גְּבוּל וְתַכְלִית בְּכָל כֹּחוֹתֶיהָ, לָכֵן גַּם אוֹר ה׳ הַמֵּאִיר בָּהּ הוּא גְבוּלִי, מְצוּמְצָם, וּמִתְלַבֵּשׁ בְּתוֹכָהּ, וְעַל כֵּן יִתְפָּעֵל לֵב מְבַקְשֵׁי ה׳ בִּשְׁעַת הַתְּפִלָּה וְכַיּוֹצֵא בָהּ, כִּי בוֹ יִשְׂמַח לִבָּם, וְיָגִיל ״אַף גִּילַת וְרַנֵּן״, וְתִתְעַנֵּג נַפְשָׁם בְּנוֹעַם ה׳ [נוסח אחר: עַל ה׳] וְאוֹרוֹ, בְּהִגָּלוֹתוֹ מִמַּעֲטֵה לְבוּשׁוֹ שֶׁהִיא הַתּוֹרָה, וְיָצָא כַבָּרָק חִצּוֹ, וְזוֹ הִיא קְבִיעַת שְׂכַר הַתּוֹרָה, הַקְּבוּעָה תָּמִיד בְּנֶפֶשׁ עֲמֵלָה בָּהּ."],"Tanya, Part IV; Iggeret HaKodesh 23:5":["אֲבָל הַהַשְׁרָאָה – הִיא הֶאָרָה עֲצוּמָה מֵאוֹר ה׳ הַמֵּאִיר בָּהּ בְּלִי גְבוּל וְתַכְלִית, וְאֵינוֹ יָכוֹל לְהִתְלַבֵּשׁ בְּנֶפֶשׁ גְּבוּלִית, כִּי אִם מַקִּיף עָלֶיהָ מִלְמַעְלָה – מֵרֹאשָׁהּ וְעַד רַגְלָהּ, כְּמוֹ שֶׁאָמְרוּ חֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אַכָּל בֵּי עֲשָׂרָה שְׁכִינְתָּא שַׁרְיָא״, כְּלוֹמַר – עֲלֵיהֶם מִלְמַעְלָה, כְּמוֹ שֶׁכָּתוּב: ״וִיהִי נוֹעַם ה׳ עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ״, כְּלוֹמַר, כִּי ״נוֹעַם ה׳״ אֲשֶׁר הוֹפִיעַ בְּ״מַעֲשֵׂה יָדֵינוּ״, בְּעֵסֶק הַתּוֹרָה וְהַמִּצְוֹת, דְּ״אוֹרַיְיתָא וְקוּדְשָׁא־בְּרִיךְ־הוּא כּוּלָּא חַד״ – יִתְכּוֹנֵן וְיִשְׁרֶה עָלֵינוּ מִלְמַעְלָה, לִהְיוֹתוֹ בְּלִי גְבוּל וְתַכְלִית וְאֵינוֹ מִתְלַבֵּשׁ בְּנַפְשֵׁנוּ וְשִׂכְלֵנוּ."],"Tanya, Part IV; Iggeret HaKodesh 23:8":["וְעַל כֵּן, רַע בְּעֵינַי הַ״מַּעֲשֶׂה אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ״ בִּכְלָל, וּבִפְרָט בֵּין אַחַיי וְרֵעַיי הַנִּגָּשִׁים אֶל ה׳, ״הַגָּשָׁה – זוֹ תְּפִלָּה״ וְאַחַר הַתְּפִלָּה אוֹ לְפָנֶיהָ – נַעֲשֶׂה ״מוֹשַׁב לֵצִים״ רַחֲמָנָא לִצְּלָן, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״שְׁנַיִם שֶׁיּוֹשְׁבִין וְאֵין בֵּינֵיהֶם דִּבְרֵי תוֹרָה כוּ׳״, וְאִם נַעֲשָׂה ״מוֹשַׁב לֵצִים״ בַּעֲשָׂרָה, דִּשְׁכִינְתָּא שַׁרְיָא עֲלַיְיהוּ אֵין לְךָ עֶלְבּוֹנָא וּקְלָנָא דִשְׁכִינְתָּא גָּדוֹל מִזֶּה רַחֲמָנָא־לִיצְּלָן, וְאִם אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה עַל הָעוֹבֵר עֲבֵירָה בַּסֵּתֶר שֶׁ״דּוֹחֵק רַגְלֵי הַשְּׁכִינָה״ חַס וְשָׁלוֹם, הָעוֹבֵר עֲבֵירָה בָּרַבִּים – דּוֹחֵק כָּל שִׁיעוּר קוֹמָה שֶׁל יוֹצֵר בְּרֵאשִׁית כִּבְיָכוֹל, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אֵין אֲנִי וְהוּא וְכוּ׳״, אֶלָּא שֶׁ״מֶּלֶךְ אָסוּר בָּרְהָטִים״ כוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 24:1":["אֲהוּבַיי, אַחַיי, אַל נָא תָּרֵעוּ. רֵיעִים הָאֲהוּבִים לְיוֹצְרָם וּשְׂנוּאִים לְיִצְרָם."],"Tanya, Part IV; Iggeret HaKodesh 24:6":["וְעַל כֵּן קָבְעוּ חֲכָמֵינוּ־זִכְרוֹנָם־לִבְרָכָה בַּתְּפִלָּה: ״כְּאִלּוּ עוֹמֵד לִפְנֵי הַמֶּלֶךְ״, עַל כָּל פָּנִים יִהְיֶה מַרְאֶה בְּעַצְמוֹ כְּאִלּוּ עוֹמֵד כוּ׳ לְעֵין כָּל רוֹאֶה בְּעֵינֵי בָשָׂר אֶל מַעֲשָׂיו וְדִיבּוּרָיו, אַף שֶׁאֵין לוֹ מַחֲשָׁבָה – לַכְּסִיל. וְעַל זֶה הָעִנְיָן נִתְקַן כָּל הַתְּפִלּוֹת, לַמִּתְבּוֹנֵן בָּהֶם הֵיטֵב. וּמִי שֶׁאֵינוֹ מַרְאֶה כֵּן – מִתְחַיֵּיב בְּנַפְשׁוֹ. וְעָלָיו אָמְרוּ בַּזֹּהַר הַקָּדוֹשׁ: ״דְּאַנְהִיג קְלָנָא בְּתִקּוּנָא עִילָּאָה וְאַחֲזֵי פֵרוּדָא, וְלֵית לֵיהּ חוּלָקָא בֶּאֱלָהָא דְּיִשְׂרָאֵל״, רַחֲמָנָא לִצְּלָן."],"Tanya, Part IV; Iggeret HaKodesh 25:1":["לְהָבִין אִמְרֵי בִינָה, מַה שֶּׁכָּתוּב בַּסֵּפֶר הַנִּקְרָא ״צַוָּואַת רִיבָ״שׁ״, הֲגַם שֶׁבֶּאֱמֶת אֵינָהּ צַוָּואָתוֹ כְּלָל, וְלֹא צִיוָּה כְּלָל לִפְנֵי פְטִירָתוֹ, רַק הֵם לִקּוּטֵי אִמְרוֹתָיו הַטְּהוֹרוֹת, שֶׁלִּקְּטוּ לְקוּטֵי בָּתַר לְקוּטֵי, וְלֹא יָדְעוּ לְכַוֵּין הַלָּשׁוֹן עַל מַתְכּוּנְתּוֹ, אַךְ הַמְכֻוָּון – הוּא אֱמֶת לַאֲמִיתּוֹ."],"Tanya, Part IV; Iggeret HaKodesh 25:11":["וְהִנֵּה, נוֹדָע לְיוֹדְעֵי חֵן, כִּי ״דְבַר ה׳״ נִקְרָא בְּשֵׁם ״שְׁכִינָה״ בִּלְשׁוֹן רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, וְ״אִימָּא תַּתָּאָה״ וּ״מַטְרוֹנִיתָא״ בִּלְשׁוֹן הַזֹּהַר, וּבִפְרָט בְּרֵישׁ פָּרָשַׁת וָאֵרָא, לְפִי שֶׁשּׁוֹכֵן וּמִתְלַבֵּשׁ בַּנִּבְרָאִים לְהַחֲיוֹתָם."],"Tanya, Part IV; Iggeret HaKodesh 25:17":["(אֶלָּא שֶׁבְּחוּץ לָאָרֶץ – הַחַיּוּת הוּא עַל־יְדֵי הִתְלַבְּשׁוּת שָׂרִים הַחִיצוֹנִים הַמְמוּנִּים עַל ע׳ אוּמּוֹת. דְּהַיְינוּ, שֶׁיּוֹרֵד נִיצוֹץ מִ״דְּבַר ה׳״, הַנִּקְרָא בְּשֵׁם ״מַלְכוּת דַּעֲשִׂיָּה״, וּמֵאִיר עַל הַשָּׂרִים שֶׁל מַעְלָה בִּבְחִינַת מַקִּיף מִלְמַעְלָה, אַךְ אֵינוֹ מִתְלַבֵּשׁ בָּהֶם מַמָּשׁ, אֶלָּא נִמְשָׁךְ לָהֶם חַיּוּת מֵהֶאָרָה זוֹ שֶׁמֵּאִיר עֲלֵיהֶם מִלְמַעְלָה, בִּבְחִינַת מַקִּיף."],"Tanya, Part IV; Iggeret HaKodesh 25:23":["וְהִנֵּה, אַף כִּי ״ה׳ אֶחָד וּשְׁמוֹ אֶחָד״, דְּהַיְינוּ, דִּבּוּרוֹ וְ״רוּחַ פִּיו״ הַמְכוּנֶּה בַּזּוֹהַר הַקָּדוֹשׁ בְּשֵׁם ״שְׁמוֹ״ – הוּא יָחִיד וּמְיוּחָד, אַף־עַל־פִּי־כֵן, הַהֶאָרָה וְהַמְשָׁכַת הַחַיּוּת הַנִּמְשֶׁכֶת מֵ״רוּחַ פִּיו״ יִתְבָּרֵךְ, מִתְחַלֶּקֶת לְד׳ מַדְרֵגוֹת שׁוֹנוֹת, שֶׁהֵן ד׳ עוֹלָמוֹת: אֲצִילוּת, בְּרִיאָה, יְצִירָה, עֲשִׂיָּה."],"Tanya, Part IV; Iggeret HaKodesh 25:26":["וְהִנֵּה, נֶפֶשׁ הָאָדָם, יָדוּעַ לַכֹּל שֶׁהִיא כְּלוּלָה מִי׳ סְפִירוֹת, חָכְמָה בִּינָה דַּעַת וְכוּ׳. וְאַף שֶׁכּוּלָּן מֵ״רוּחַ פִּיו״ יִתְבָּרֵךְ, כְּדִכְתִיב ״וַיִּפַּח בְּאַפָּיו כוּ׳״, מִכָּל מָקוֹם, דֶּרֶךְ פְּרָט: חָכְמָה־בִּינָה־דַּעַת שֶׁבְּנַפְשׁוֹ הֵן דּוּגְמָא לְחָכְמָה־בִּינָה־דַּעַת שֶׁבְּי׳ סְפִירוֹת, הַמְכוּנּוֹת בְּשֵׁם ״אַבָּא״ וְ״אִמָּא״: וּמִדּוֹת אַהֲבָה וְיִרְאָה וְכוּ׳ שֶׁבְּנַפְשׁוֹ – הֵן דּוּגְמָא לַמִּדּוֹת שֶׁבְּי׳ סְפִירוֹת, הַנִּקְרָאוֹת בְּשֵׁם ״זְעֵיר אַנְפִּין״: וְכֹחַ הַדִּבּוּר שֶׁבְּנַפְשׁוֹ – דּוּגְמָא לַדִּבּוּר הָעֶלְיוֹן, הַנִּקְרָא בְּשֵׁם ״מַלְכוּת״ וּ״שְׁכִינָה״, וְלָכֵן, כְּשֶׁמְּדַבֵּר דִּבְרֵי תוֹרָה – מְעוֹרֵר דִּבּוּר הָעֶלְיוֹן לְיַחֵד הַשְּׁכִינָה, וּמִשּׁוּם הָכֵי קַיְימָא לָן בִּקְרִיאַת־שְׁמַע וּבִרְכַּת הַמָּזוֹן וְדִבְרֵי תוֹרָה – לֹא יָצָא בְּהִרְהוּר בְּלֹא דִבּוּר:"],"Tanya, Part IV; Iggeret HaKodesh 25:27":["וְהִנֵּה, ״זֶה לְעוּמַּת זֶה״, יֵשׁ עֲשָׂרָה כִּתְרֵי דִמְסָאֲבוּתָא, וּמֵהֶן נִמְשָׁכוֹת נַפְשׁוֹת הָאוּמּוֹת – גַּם כֵּן כְּלוּלוֹת מֵעֶשֶׂר בְּחִינוֹת אֵלּוּ מַמָּשׁ. וּמוּדַעַת זֹאת בָּאָרֶץ, מַה שֶּׁכָּתוּב בְּ״סֵפֶר הַגִּלְגּוּלִים״ עַל פָּסוּק ״אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ״: שֶׁהוּא סוֹד גָּלוּת הַשְּׁכִינָה בְּתוֹךְ הַקְּלִיפּוֹת, לְהַחֲיוֹתָם וּלְהַשְׁלִיטָם עַתָּה בִּזְמַן הַגָּלוּת, אֲבָל הוּא ״לְרַע לוֹ״ וְכוּ׳. וְלָכֵן הָאוּמּוֹת שׁוֹלְטִין עַתָּה עַל יִשְׂרָאֵל, לִהְיוֹת – נַפְשׁוֹת הָאוּמּוֹת מֵהַקְּלִיפּוֹת אֲשֶׁר הַשְּׁכִינָה מִתְלַבֶּשֶׁת בִּבְחִינַת גָּלוּת בְּתוֹכָם. וְהִנֵּה, אַף שֶׁזֶּה צָרִיךְ בֵּיאוּר רָחָב אֵיךְ וּמָה, מִכָּל מָקוֹם הָאֱמֶת כֵּן הוּא."],"Tanya, Part IV; Iggeret HaKodesh 25:30":["וְאַחַר הַדְּבָרִים וְהָאֶמֶת הָאֵלֶּה הַגְּלוּיִם וִידוּעִים לַכֹּל, נַחֲזוֹר לְעִנְיָן רִאשׁוֹן, בְּעִנְיַן הַכַּעַס – שֶׁהוּא ״כְּעוֹבֵד עֲבוֹדָה־זָרָה״, וְהַיְינוּ – בְּמִילֵּי דְעָלְמָא, כִּי ״הַכֹּל בִּידֵי שָׁמַיִם חוּץ מִיִּרְאַת שָׁמַיִם״, וְלָכֵן, בְּמִילֵּי דִשְׁמַיָּא – לְאַפְרוּשֵׁי מֵאִיסּוּרָא לֹא שַׁיָּיךְ הַאי טַעֲמָא דַּאֲמָרָן, וּכְמוֹ שֶׁכָּתוּב: ״וַיִּקְצוֹף מֹשֶׁה״, וְהַיְינוּ, מִשּׁוּם כִּי ה׳ הִקְרָה לְפָנָיו מִצְוָה זוֹ, לְאַפְרוּשֵׁי מֵאִיסּוּרָא, כְּדֵי לְזַכּוֹתוֹ:"],"Tanya, Part IV; Iggeret HaKodesh 25:36":["וְכִמְדוּמֶּה לִי, שֶׁתְּפִיסָתָם אֵינָהּ מִצַּד דִּקְדּוּק הַלָּשׁוֹן, אֶלָּא מֵעִיקַּר עִנְיַן הִתְלַבְּשׁוּת הַשְּׁכִינָה בַּקְּלִיפּוֹת, שֶׁאֵין לָהֶם אֱמוּנָה בְּמַה שֶׁאָמַר הָאֲרִיזַ״ל בְּ״סֵפֶר הַגִּלְגּוּלִים״, שֶׁאִם יִרְצוּ לְחַלֵּק בֵּין קְלִיפּוֹת הָרוּחָנִיִּים לְעוֹבְדֵי גִלּוּלִים הַגַּשְׁמִיִּים אֵין לְךָ גַּשְׁמִי כַּעֲפַר הָאָרֶץ, וְאַף־עַל־פִּי־כֵן מִתְלַבֶּשֶׁת בּוֹ מַלְכוּת דְּמַלְכוּת דַּעֲשִׂיָּה וּבְתוֹכָהּ מַלְכוּת דִּיצִירָה כוּ׳, וְכַנִּזְכָּר לְעֵיל. וְאִם מִשּׁוּם טוּמְאַת נַפְשׁוֹת הַנָּכְרִים, הֲרֵי נַפְשׁוֹתֵיהֶם מִזִּיוּוּג זְעֵיר אַנְפִּין וְנוּקְבָא דִּקְלִיפּוֹת הָרוּחָנִיִּים, כְּמוֹ שֶׁכָּתוּב בְּכִתְבֵי הָאֲרִיזַ״ל. נִמְצָא שֶׁהָרוּחָנִיִּים מְקוֹר טוּמְאָתָם."],"Tanya, Part IV; Iggeret HaKodesh 25:5":["(וְזֶהוּ ״כִּי ה׳ אָמַר לוֹ״ – בָּעֵת הַהִיא מַמָּשׁ – ״קַלֵּל״ אֶת דָּוִד, ״וּמִי יֹאמַר לוֹ וְגוֹ׳״."],"Tanya, Part IV; Iggeret HaKodesh 25:6":["וְכַנּוֹדָע מַה שֶּׁאָמַר הַבַּעַל־שֵׁם־טוֹב זִכְרוֹנוֹ־לִבְרָכָה עַל פָּסוּק: ״לְעוֹלָם ה׳ דְּבָרְךָ נִצָּב בַּשָּׁמָיִם״, שֶׁצֵּירוּף אוֹתִיּוֹת שֶׁנִּבְרְאוּ בָּהֶן הַשָּׁמַיִם, שֶׁהוּא מַאֲמַר ״יְהִי רָקִיעַ כוּ׳״ – הֵן נִצָּבוֹת וְעוֹמְדוֹת מְלוּבָּשׁוֹת בַּשָּׁמַיִם לְעוֹלָם לְהַחֲיוֹתָם וּלְקַיְּימָם."],"Tanya, Part IV; Iggeret HaKodesh 26:1":["בְּרַעְיָא מְהֵימְנָא פָּרָשַׁת נָשֹׂא: ״וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ״ – ״בְּהַאי חִבּוּרָא דִילָךְ דְּאִיהוּ סֵפֶר הַזֹּהַר, מִן זָהֳרָא דְּ״אִימָּא עִילָּאָה״ תְּשׁוּבָה, בְּאִילֵּין לֹא צָרִיךְ נִסָּיוֹן. וּבְגִין דַּעֲתִידִין יִשְׂרָאֵל לְמִטְעַם מֵאִילָנָא דְחַיֵּי, דְּאִיהוּ הַאי סֵפֶר הַזֹּהַר – יִפְּקוּן בֵּיהּ מִן גָּלוּתָא בְּרַחֲמִים, וְיִתְקַיֵּים בְּהוֹן: ״ה׳ בָּדָד יַנְחֶנּוּ, וְאֵין עִמּוֹ אֵל נֵכָר״."],"Tanya, Part IV; Iggeret HaKodesh 26:11":["וְעוֹד יֵשׁ לְהַפְלִיא, הַפְלֵא וָפֶלֶא – אֵיךְ אֶפְשָׁר שֶׁלִּימוֹת הַמָּשִׁיחַ לֹא יִצְטָרְכוּ לֵידַע הִלְכוֹת אִיסּוּר וְהֶיתֵּר וְטוּמְאָה וְטָהֳרָה, כִּי אֵיךְ יִשְׁחֲטוּ הַקָּרְבָּנוֹת וְגַם חוּלִּין, אִם לֹא יֵדְעוּ הִלְכוֹת דְּרָסָה וַחֲלָדָה וּשְׁהִיָּה הַפּוֹסְלִים הַשְּׁחִיטָה, וּפְגִימַת הַסַּכִּין, וְכִי יִוָּלֵד אִישׁ בְּטִבְעוֹ שֶׁיְּהֵא שׁוֹחֵט בְּלִי שְׁהִיָּה וּדְרָסָה? וְגַם הַסַּכִּין תִּהְיֶה בְּרִיאָה וְעוֹמֶדֶת בְּלִי פְּגִימָה לְעוֹלָם?"],"Tanya, Part IV; Iggeret HaKodesh 26:15":["אַךְ בֶּאֱמֶת, כְּשֶׁתְּדַקְדֵּק בִּלְשׁוֹן רַעְיָא מְהֵימְנָא דִלְעֵיל, ״וְאִילָנָא דְּטוֹב וָרָע דְּאִיהוּ אִיסּוּר וְהֶיתֵּר כוּ׳״, וְלֹא אָמַר ״תּוֹרַת אִיסּוּר וְהֶיתֵּר״ אוֹ ״הִלְכוֹת אִיסּוּר וְהֶיתֵּר״, אֶלָּא רוֹצֶה לוֹמַר, דְּגוּף דָּבָר הָאָסוּר וְדָבָר הַמּוּתָּר – הוּא מֵאִילָנָא דְטוֹב וָרָע, שֶׁהוּא קְלִיפַּת נוֹגַהּ, כְּמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים."],"Tanya, Part IV; Iggeret HaKodesh 26:20":["וּמַה שֶּׁאָמַר הָאֲרִיזַ״ל שֶׁהַמִּשְׁנָיוֹת הֵן בְּמַלְכוּת דִּיצִירָה, רוֹצֶה לוֹמַר: לְבוּשׁ מַלְכוּת דִּיצִירָה שֶׁנִּתְלַבְּשָׁה בָּהּ מַלְכוּת דַּאֲצִילוּת, וּמַלְכוּת דִּיצִירָה נִקְרָא ״שִׁפְחָה״ לְגַבֵּי מַלְכוּת דַּאֲצִילוּת, וּמַלְכוּת דִּבְרִיאָה נִקְרָא ״אָמָה״."],"Tanya, Part IV; Iggeret HaKodesh 26:22":["וְהִנֵּה, כְּשֶׁהַמַּלְכוּת דַּאֲצִילוּת מִתְלַבֶּשֶׁת בִּקְלִיפַּת נוֹגַהּ, כְּדֵי לְבָרֵר הַנִּיצוֹצוֹת שֶׁנָּפְלוּ בְּחֵטְא אָדָם הָרִאשׁוֹן וְגַם הָרַפַּ״ח נִיצוֹצִין שֶׁנָּפְלוּ בִּשְׁבִירַת הַכֵּלִים, אֲזַי, גַּם הַמַּלְכוּת דַּאֲצִילוּת נִקְרָא בְּשֵׁם ״עֵץ הַדַּעַת טוֹב וָרָע״ לְגַבֵּי ״זְעֵיר אַנְפִּין״ דַּאֲצִילוּת, שֶׁאֵינוֹ יוֹרֵד שָׁם, וְנִקְרָא ״עֵץ חַיִּים״."],"Tanya, Part IV; Iggeret HaKodesh 26:25":["וְהַמַּשְׂכִּיל יָבִין עִנְיַן פֶּלֶא גָּדוֹל מִזֶּה מְאֹד, מַה נַּעֲשֶׂה בַּשָּׁמַיִם מִמַּעַל עַל־יְדֵי עִיּוּן וּבֵירוּר הֲלָכָה פְּסוּקָה מִן הַגְּמָרָא וּפוֹסְקִים רִאשׁוֹנִים וְאַחֲרוֹנִים, מַה שֶּׁהָיָה בְּהֶעְלֵם דָּבָר קוֹדֶם הָעִיּוּן הַלָּז, כִּי עַל־יְדֵי זֶה מַעֲלֶה הֲלָכָה זוֹ מֵהַקְּלִיפּוֹת שֶׁהָיוּ מַעֲלִימִים וּמְכַסִּים אוֹתָהּ, שֶׁלֹּא הָיְתָה יְדוּעָה כְּלָל, אוֹ שֶׁלֹּא הָיְתָה מוּבֶנֶת הֵיטֵב בְּטַעֲמָהּ, שֶׁהַטַּעַם הוּא סוֹד הַסְּפִירָה חָכְמָה עִילָּאָה, שֶׁנָּפְלוּ מִמֶּנָּה נִיצוֹצִין בַּקְּלִיפּוֹת בִּשְׁבִירַת הַכֵּלִים, וְהֵם שָׁם בִּבְחִינַת גָּלוּת, שֶׁהַקְּלִיפּוֹת שׁוֹלְטִים עֲלֵיהֶם וּמַעֲלִימִים חָכְמַת הַתּוֹרָה מֵעֶלְיוֹנִים וְתַחְתּוֹנִים. וְזֶהוּ שֶׁכָּתוּב בְּרַעְיָא מְהֵימְנָא, שֶׁהַקּוּשְׁיָא הִיא מִסִּטְרָא דְרָע."],"Tanya, Part IV; Iggeret HaKodesh 26:26":["וְהִנֵּה, הָעֶלְיוֹנִים אֵין בָּהֶם כֹּחַ לְבָרֵר וּלְהַעֲלוֹת מֵהַשְּׁבִירָה שֶׁבִּקְלִיפַּת נוֹגַהּ, אֶלָּא הַתַּחְתּוֹנִים לְבַד, לְפִי שֶׁהֵם מְלוּבָּשִׁים בְּגוּף חוּמְרִי ״מַשְׁכָּא דְחִוְיָא״ מִקְּלִיפַּת נוֹגַהּ, וְהֵם מַתִּישִׁים כֹּחָהּ בִּשְׁבִירַת הַתַּאֲווֹת, וְאִתְכַּפְיָא סִטְרָא אָחֳרָא, וְ״יִתְפָּרְדוּ כָּל פּוֹעֲלֵי אָוֶן״. וְלָכֵן בָּאִים הָעֶלְיוֹנִים לִשְׁמוֹעַ חִידּוּשֵׁי תּוֹרָה מֵהַתַּחְתּוֹנִים, מַה שֶּׁמְּחַדְּשִׁים וּמְגַלִּים תַּעֲלוּמוֹת הַחָכְמָה שֶׁהָיוּ כְּבוּשִׁים בַּגּוֹלָה עַד עַתָּה."],"Tanya, Part IV; Iggeret HaKodesh 26:30":["אֲבָל בְּצֵאת הַשְּׁכִינָה מִקְּלִיפַּת נוֹגַהּ [נוסח אחר: מֵהַקְּלִיפּוֹת] אַחַר שֶׁיּוּשְׁלַם בֵּירוּר הַנִּיצוֹצוֹת, וְיוּפְרַד הָרַע מֵהַטּוֹב וְ״יִתְפָּרְדוּ כָּל פּוֹעֲלֵי אָוֶן״, וְלָא שָׁלְטָא אִילָנָא דְטוֹב וָרָע בְּצֵאת הַטּוֹב מִמֶּנָּה, אֲזַי – לֹא יִהְיֶה עֵסֶק הַתּוֹרָה וְהַמִּצְוֹת לְבָרֵר בֵּירוּרִין, כִּי אִם – לְיַחֵד יִחוּדִים עֶלְיוֹנִים יוֹתֵר, לְהַמְשִׁיךְ אוֹרוֹת עֶלְיוֹנִים יוֹתֵר מֵהָאֲצִילוּת, כְּמוֹ שֶׁאָמַר הָאֲרִ״י זִכְרוֹנוֹ לִבְרָכָה."],"Tanya, Part IV; Iggeret HaKodesh 26:4":["וְהִנֵּה, הַמּוּבָן מֵהַשְׁקָפָה רִאשׁוֹנָה לִכְאוֹרָה מִלְּשׁוֹן זֶה הַמַּאֲמָר לַחֲסֵירֵי מַדָּע, שֶׁלִּימּוּד אִיסּוּר וְהֶיתֵּר וְסֵדֶר טְהָרוֹת הוּא מֵאִילָנָא דְּטוֹב וָרָע. מִלְּבַד שֶׁהוּא פֶּלֶא גָדוֹל מֵחֲמַת עַצְמוֹ, וְסוֹתֵר פְּשָׁטֵי הַכְּתוּבִים וּמִדְרְשֵׁי רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁכָּל הַתּוֹרָה הַנִּגְלֵית לָנוּ וּלְבָנֵינוּ נִקְרָא ״עֵץ חַיִּים לַמַּחֲזִיקִים בָּהּ״, וְלֹא סֵפֶר הַזֹּהַר לְבַד, וּבִפְרָט – שֶׁהָיָה גָּנוּז בִּימֵיהֶם, וְגַם, כָּל חָכְמַת הַקַּבָּלָה הָיְתָה נִסְתָּרָה בִּימֵיהֶם וְנֶעְלָמָה מִכָּל תַּלְמִידֵי חֲכָמִים, כִּי אִם לִיחִידֵי סְגוּלָּה וְאַף גַּם זֹאת בְּהַצְנֵעַ לֶכֶת וְלֹא בָּרַבִּים, כִּדְאִיתָא בַּגְּמָרָא."],"Tanya, Part IV; Iggeret HaKodesh 27:13":["וְהִנֵּה, בִּהְיוֹת הַצַּדִּיק חַי עַל פְּנֵי הָאֲדָמָה, הָיוּ שְׁלֹשָׁה מִדּוֹת אֵלּוּ בְּתוֹךְ כְּלִי וּלְבוּשׁ שֶׁלָּהֶם בִּבְחִינַת מָקוֹם גַּשְׁמִי, שֶׁהִיא בְּחִינַת נֶפֶשׁ הַקְּשׁוּרָה בְּגוּפוֹ, וְכָל תַּלְמִידָיו אֵינָם מְקַבְּלִים רַק הֶאָרַת מִדּוֹת אֵלּוּ וְזִיוָן, הַמֵּאִיר חוּץ לִכְלִי זֶה עַל־יְדֵי דִּבּוּרָיו וּמַחְשְׁבוֹתָיו הַקְּדוֹשִׁים, וְלָכֵן אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁאֵין אָדָם עוֹמֵד עַל דַּעַת רַבּוֹ וְכוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 27:17":["וְהִנֵּה, יֵשׁ עוֹד בְּחִינַת הֶאָרָה לְתַלְמִידָיו, רַק שֶׁאֵינָהּ מִתְלַבֶּשֶׁת בְּתוֹךְ מוֹחָם מַמָּשׁ כָּרִאשׁוֹנָה, רַק מְאִירָה עֲלֵיהֶם מִלְמַעְלָה, וְהִיא מֵעֲלִיַּית רוּחוֹ וְנִשְׁמָתוֹ לִמְקוֹר חוּצְבּוֹ, דְּהַיְינוּ לַ״חֲקַל תַּפּוּחִין קַדִּישִׁין״, וְעַל־יְדֵי זֶה נַעֲשֶׂה שָׁם יִחוּד, עַל־יְדֵי הַעֲלָאַת ״מַיִּין נוּקְבִין״ מִכָּל מַעֲשָׂיו וְתוֹרָתוֹ וַעֲבוֹדָתוֹ אֲשֶׁר עָבַד כָּל יְמֵי חַיָּיו, וְנִזְרְעוּ בַּ״חֲקַל תַּפּוּחִין קַדִּישִׁין״ אוֹרוֹת עֶלְיוֹנִים מְאֹד, לְעוּמַּת תַּחְתּוֹנִים, אֲשֶׁר הֵם תּוֹרָתוֹ וַעֲבוֹדָתוֹ."],"Tanya, Part IV; Iggeret HaKodesh 27:2":["אֲהוּבַיי אַחַיי וְרֵעַיי אֲשֶׁר כְּנַפְשִׁי כוּ׳, ה׳ עֲלֵיהֶם יִחְיוּ חַיִּים עַד הָעוֹלָם, וְצֶאֱצָאֵיהֶם אִתָּם זֶרַע אֱמֶת בְּרוּכֵי ה׳ הֵמָּה מֵעַתָּה וְעַד עוֹלָם."],"Tanya, Part IV; Iggeret HaKodesh 27:6":["וְזֶהוּ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ דְּ״צַדִּיקָא דְּאִתְפַּטַּר אִשְׁתַּכַּח בְּכֻלְּהוּ עָלְמִין יַתִּיר מִבְּחַיּוֹהִי״, דְּהַיְינוּ, שֶׁגַּם בְּזֶה הָעוֹלַם הַמַּעֲשֶׂה – ״הַיּוֹם לַעֲשׂוֹתָם״ – אִשְׁתַּכַּח יַתִּיר: כִּי הַמַּעֲשֶׂה (גָּדוֹל) [גָּדֵל] וְהוֹלֵךְ, גִּידּוּלֵי גִידּוּלִין, מִן ״אוֹר זָרוּעַ לַצַּדִּיק״ בַּ״שָּׂדֶה אֲשֶׁר בֵּרְכוֹ ה׳״, הַמֵּאִיר לָאָרֶץ וְחוּצוֹת, וְגַם אֲנַחְנוּ אֵלֶּה פֹה הַיּוֹם כּוּלָּנוּ חַיִּים בִּדְרָכָיו – ״דֶּרֶךְ הַקֹּדֶשׁ יִקָּרֵא לָהּ״. זֹאת בַּעֲבוֹדַת ה׳ בְּמִילֵּי דִשְׁמַיָּא."],"Tanya, Part IV; Iggeret HaKodesh 27:8":["ביאור על הנזכר לעיל"],"Tanya, Part IV; Iggeret HaKodesh 28:1":["מַה שֶּׁכָּתַב לִמְחוּתָּנוֹ, הָרַב הַגָּאוֹן הַמְפוּרְסָם, אִישׁ אֱלֹקִים קְדוֹשׁ ה׳, נֵר יִשְׂרָאֵל, עַמּוּד הַיְמָנִי, פַּטִּישׁ הֶחָזָק, מוֹרֵנוּ וְרַבֵּנוּ הָרַב לֵוִי יִצְחָק נִשְׁמָתוֹ עֵדֶן, אַב בֵּית־דִּין דִּקְהִלַּת קוֹדֶשׁ בַּארְדִּיטְשׁוֹב, לְנַחֲמוֹ עַל פְּטִירַת בְּנוֹ הָרַב הֶחָסִיד, מוֹרֵנוּ וְרַבֵּנוּ הָרַב מֵאִיר נִשְׁמָתוֹ עֵדֶן:"],"Tanya, Part IV; Iggeret HaKodesh 28:6":["וְהִנֵּה, מוּדַעַת זֹאת, דְּ״אַבָּא״ יוֹנֵק מִמַּזָּל הַשְּׁמִינִי הוּא תִּיקּוּן ״נוֹצֵר חֶסֶד״, ״נוֹצֵר״ אוֹתִיּוֹת ״רָצוֹן״, וְהִיא עֵת רָצוֹן הַמִּתְגַּלֶּה וּמֵאִיר בִּבְחִינַת גִּילּוּי מִלְמַעְלָה לְמַטָּה, בְּעֵת פְּטִירַת צַדִּיקֵי עֶלְיוֹן, עוֹבְדֵי ה׳ בְּאַהֲבָה, בִּמְסִירַת נַפְשָׁם לַה׳ בְּחַיֵּיהֶם עַרְבִית וְשַׁחֲרִית בִּקְרִיאַת־שְׁמַע, שֶׁעַל־יְדֵי זֶה הָיוּ מַעֲלִים ״מַיִּין נוּקְבִין״ לְ״אַבָּא״ וְ״אִימָּא״ בִּקְרִיאַת־שְׁמַע, כַּיָּדוּעַ. (וְכֵן בְּתַלְמוּד תּוֹרָה דְּמֵחָכְמָה נָפְקָא), וְעַל־יְדֵי זֶה הָיוּ נִמְשָׁכִים וְיוֹרְדִים בְּחִינַת ״מַיִּין דּוּכְרִין״ מִתִּיקּוּן ״וְנוֹצֵר חֶסֶד״, וְהֵם הֵם הַמְּאִירִים בִּבְחִינַת גִּילּוּי בִּפְטִירָתָם, כַּנּוֹדָע – שֶׁכָּל עֲמַל הָאָדָם שֶׁעָמְלָה נַפְשׁוֹ בְּחַיָּיו לְמַעְלָה בִּבְחִינַת הֶעְלֵם וְהֶסְתֵּר, מִתְגַּלֶּה וּמֵאִיר בִּבְחִינַת גִּילּוּי מִלְמַעְלָה לְמַטָּה בְּעֵת פְּטִירָתו."],"Tanya, Part IV; Iggeret HaKodesh 29:1":["אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ כוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 29:14":["וְהִנֵּה, רָצוֹן הָעֶלְיוֹן בָּרוּךְ־הוּא מְכוּנֶּה וְנִקְרָא בְּפִי חַכְמֵי הָאֱמֶת בְּשֵׁם ״כֶּתֶר עֶלְיוֹן״, וּבוֹ תר״ך עַמּוּדֵי אוֹר וְכוּ׳. פֵּירוּשׁ, דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁיֵּשׁ עַמּוּדִים בְּבֵית חוֹמָה גָּדוֹל, נִצָּבִים בָּאָרֶץ וְרֹאשָׁם מְחוּבָּר בַּתִּקְרָה, כָּכָה מַמָּשׁ עַל דֶּרֶךְ מָשָׁל, ״כֶּתֶר עֶלְיוֹן״ בָּרוּךְ־הוּא, הוּא לְמַעְלָה מִבְּחִינַת מַדְרֵגַת הַחָכְמָה, וְהוּא מִלְּשׁוֹן ״כּוֹתֶרֶת״, שֶׁהוּא מַכְתִּיר וּמַקִּיף עַל הַמּוֹחִין שֶׁבָּרֹאשׁ, שֶׁהֵם בְּחִינוֹת חָכְמָה־בִּינָה־דַּעַת."],"Tanya, Part IV; Iggeret HaKodesh 29:19":["וְזֶהוּ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ פָּרָשַׁת פְּקוּדֵי (דַּף רכ״ט עַמּוּד ב׳): ״דְּאִינּוּן עוֹבָדִין טָבִין דְּעָבִיד בַּר נַשׁ מָשְׁכֵי מִנְּהוֹרָא דְּזִיוָוא עִילָּאָה לְבוּשָׁא כוּ׳, וְחָמֵי כוּ׳ בְּנוֹעַם ה׳ וְכוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 29:22":["וְהִנֵּה מוּדַעַת זֹאת, כִּי הִנֵּה, רָצוֹן הָעֶלְיוֹן בָּרוּךְ־הוּא הַמְלוּבָּשׁ בְּתַּרְיַ״ג מִצְוֹת שֶׁבַּתּוֹרָה שֶׁבִּכְתָב, הוּא מוּפְלָא וּמְכוּסֶּה, טָמִיר וְנֶעְלָם, וְאֵינוֹ מִתְגַּלֶּה אֶלָּא בַּתּוֹרָה שֶׁבְּעַל פֶּה, כְּמוֹ מִצְוַת תְּפִילִּין, עַל דֶּרֶךְ מָשָׁל, שֶׁנֶּאֱמַר בַּתּוֹרָה שֶׁבִּכְתָב: ״וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ וְהָיוּ לְטוֹטָפוֹת בֵּין עֵינֶיךָ״, וְהוּא מַאֲמָר סָתוּם וְנֶעְלָם, שֶׁלֹּא פֵירֵשׁ הַכָּתוּב אֵיךְ וּמַה לִּקְשׁוֹר, וּמַהוּ ״טוֹטָפוֹת״, וְהֵיכָן הוּא ״בֵּין עֵינֶיךָ״ וְ״עַל יָדֶךָ״, עַד שֶׁפֵּירְשָׁה תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁצָּרִיךְ לִקְשׁוֹר בַּיִת אֶחָד עַל הַיָּד וְד׳ בָּתִּים עַל הָרֹאשׁ, וּבְתוֹכָם ד׳ פָּרָשִׁיּוֹת, וְהַבָּתִּים יִהְיוּ מֵעוֹר מְעוּבָּד, וּמְרוּבָּעִים דַּוְקָא, וּמְקוּשָּׁרִים בִּרְצוּעוֹת שֶׁל עוֹר שְׁחוֹרוֹת דַּוְקָא, וְכָל שְׁאָר פְּרָטֵי הִלְכוֹת עֲשִׂיַּית הַתְּפִילִּין שֶׁנֶּאֶמְרוּ בְּעַל פֶּה, וְ״עַל יָדֶךָ״ הִיא הַזְּרוֹעַ דַּוְקָא וְלֹא כַּף הַיָּד, וּ״בֵין עֵינֶיךָ״ זֶה קָדְקוֹד וְלֹא הַמֵּצַח."],"Tanya, Part IV; Iggeret HaKodesh 29:9":["וְהִנֵּה, אוֹר זֶה הַגָּנוּז לַצַּדִּיקִים לֶעָתִיד לָבֹא, הַנִּקְרָא בְּשֵׁם ״נוֹעַם ה׳״ וְ״צַחְצָחוֹת״, לְהִתְעַנֵּג עַל ה׳, וְ״ד׳ מֵאוֹת עָלְמִין דְּכִסּוּפִין דְּמִתְעַנְּגֵי בְּהוֹן צַדִּיקַיָּיא כוּ׳״, כְּמוֹ שֶׁכָּתוּב: ״אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף כוּ׳״ הִנֵּה יֵשׁ בּוֹ מַעֲלוֹת וּמַדְרֵגוֹת רַבּוֹת מְאֹד, גָּבוֹהַּ מֵעַל גָּבוֹהַּ, אַךְ הֶאָרָה מוּעֶטֶת הַיּוֹרֶדֶת מַדְרֵגָה אַחַר מַדְרֵגָה לִבְרוֹא לְבוּשׁ זֶה, הִיא מִבְּחִינַת מַדְרֵגָה הָאַחֲרוֹנָה שֶׁבְּאוֹר זֶה, וְנִקְרֵאת בְּשֵׁם ״מַדְרֵגָה הַחִיצוֹנָה״ וַ״אֲחוֹרַיִים״ דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר דַּף ר״ח עַמּוּד ב׳ (עַיֵּין בְּסֵפֶר ״מִקְדַּשׁ מֶלֶךְ״) וְר״י עַמּוּד ב׳: וּמַה דְאִשְׁתְּאַר כוּ׳."],"Tanya, Part IV; Iggeret HaKodesh 2:1":["אחר ביאתו מפטרבורג"],"Tanya, Part IV; Iggeret HaKodesh 30:1":["מוּדַעַת זֹאת מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״כָּל הָרָגִיל לָבֹא לְבֵית הַכְּנֶסֶת וְיוֹם אֶחָד לֹא בָא הַקָּדוֹשׁ־בָּרוּךְ־הוּא שׁוֹאֵל עָלָיו, שֶׁנֶּאֱמַר: ״מִי בָכֶם יְרֵא ה׳ וְכוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 31:1":["נוֹדָע בַּשְּׁעָרִים מַה שֶּׁכָּתוּב בַּתִּיקּוּנִים, דִּ״שְׁכִינְתָּא אִיהִי מַרְעָא בְּגָלוּתָא״ כִּבְיָכוֹל."],"Tanya, Part IV; Iggeret HaKodesh 32:1":["בָּרֵךְ ה׳ חֵילָם וּפוֹעַל יָדָם יִרְצֶה, לְרָצוֹן לָהֶם לִפְנֵי ה׳ תָּמִיד, כֹּה יִתֵּן וְכֹה יוֹסִיף ה׳ לְאַמֵּץ לִבָּם בַּגִּבּוֹרִים, וְנָדִיב עַל נְדִיבוֹת יָקוּם, לִהְיוֹת גָּדוֹל הַמְעַשֶּׂה בְּכָל עִיר וּמִנְיָן, וְתֵחָשֵׁב לוֹ לִצְדָקָה."],"Tanya, Part IV; Iggeret HaKodesh 3:1":["וַיִּלְבַּשׁ צְדָקָה כַּשִּׁרְיוֹן, וְכוֹבַע יְשׁוּעָה בְּרֹאשׁוֹ. וְדָרְשׁוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״מַה שִּׁרְיוֹן זֶה כָּל קְלִיפָּה וּקְלִיפָּה מִצְטָרֶפֶת לְשִׁרְיוֹן גָּדוֹל, אַף צְדָקָה כָּל פְּרוּטָה וּפְרוּטָה מִצְטָרֶפֶת לְחֶשְׁבּוֹן גָּדוֹל״. פֵּירוּשׁ, שֶׁהַשִּׁרְיוֹן עָשׂוּי קַשְׂקַשִּׂים עַל נְקָבִים, וְהֵם מְגִינִּים שֶׁלֹּא יִכָּנֵס חֵץ בַּנְּקָבִים, וְכָכָה הוּא מַעֲשֵׂה הַצְּדָקָה:"],"Tanya, Part IV; Iggeret HaKodesh 3:9":["אַךְ מִי הוּא הַגּוֹרֵם לִירִידַת הָאוֹר וְהַשֶּׁפַע לָעוֹלָם הַזֶּה הַגַּשְׁמִי מִי׳ סְפִירוֹת הַנִּקְרָאִים ״גּוּפָא״, הוּא הַיִּחוּד הַנִּזְכָּר לְעֵיל, שֶׁהִיא תּוֹסֶפֶת הֶאָרָה וְהַשְׁפָּעָה מִבְּחִינַת אוֹר־אֵין־סוֹף הַמַּאֲצִיל הָעֶלְיוֹן בָּרוּךְ־הוּא, בְּיֶתֶר שְׂאֵת עַל הַהֶאָרָה וְהַהַשְׁפָּעָה שֶׁבִּתְחִילַּת הָאֲצִילוּת וְהַהִשְׁתַּלְשְׁלוּת וְכוּ׳. וְרֵאשִׁית תּוֹסֶפֶת הַהֶאָרָה וְהַהַשְׁפָּעָה, הִיא לְרֵאשִׁית הַי׳ סְפִירוֹת."],"Tanya, Part IV; Iggeret HaKodesh 4:1":["אֵין יִשְׂרָאֵל נִגְאָלִין אֶלָּא בִּצְדָקָה, שֶׁנֶּאֱמַר ״וְשָׁבֶיהָ בִּצְדָקָה״. כְּתִיב: ״צֶדֶק לְפָנָיו יְהַלֵּךְ״, וַהֲוָה־לֵיהּ־לְמֵימַר: ״יֵלֵךְ״. אַךְ הָעִנְיָן, עַל פִּי מַה שֶּׁכָּתוּב ״לְךָ אָמַר לִבִּי בַּקְּשׁוּ פָנָי״, פֵּירוּשׁ, בַּקְּשׁוּ פְּנִימִית הַלֵּב. כִּי הִנֵּה, בְּלַהַב יְסוֹד הָאֵשׁ הָאֱלֹקִית שֶׁבַּלֵּב (נוסח אחר: הִנֵּה, בְּהַלֵּב [יְסוֹד הָאֵשׁ הָאֱלֹקִית שֶׁבַּלֵּב]) יֵשׁ ב׳ בְּחִינוֹת: בְּחִינַת חִיצוֹנִיּוּת, וּבְחִינַת פְּנִימִיּוּת."],"Tanya, Part IV; Iggeret HaKodesh 4:10":["אַךְ מוּדַעַת זֹאת, כִּי ״אִתְעָרוּתָא דִלְעֵילָּא״ הִיא בְּ״אִתְעָרוּתָא דִלְתַתָּא״ דַּוְקָא, בִּבְחִינַת הַעֲלָאַת ״מַיִּין נוּקְבִין״, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה ״אֵין טִפָּה יוֹרֶדֶת מִלְמַעְלָה כוּ׳״. וְלָכֵן צָרִיךְ הָאָדָם לַעֲשׂוֹת בְּעַצְמוֹ תְּחִלַּת מִילָה זוֹ, לְהָסִיר עָרְלַת הַלֵּב וּקְלִיפָּה הַגַּסָּה וְדַקָּה, הַמַּלְבִּישׁוֹת וּמְכַסּוֹת עַל בְּחִינַת נְקוּדַּת פְּנִימִית הַלֵּב, שֶׁהִיא בְּחִינַת אַהֲבַת ה׳, בְּחִינַת ״לְמַעַן חַיֶּיךָ״, שֶׁהִיא בַּגָּלוּת בְּתַאֲווֹת עוֹלָם הַזֶּה, שֶׁהֵם גַּם כֵּן בִּבְחִינַת ״לְמַעַן חַיֶּיךָ״ בְּ״זֶה לְעוּמַּת זֶה״, כַּנִּזְכָּר לְעֵיל."],"Tanya, Part IV; Iggeret HaKodesh 4:13":["וְזֶהוּ ״צֶדֶק לְפָנָיו יְהַלֵּךְ״, ״לְפָנָיו״ – הוּא מִלְּשׁוֹן פְּנִימִיּוּת, וִ״יְהַלֵּךְ״ – הוּא מִלְּשׁוֹן הוֹלָכָה, שֶׁמּוֹלִיךְ אֶת פְּנִימִית הַלֵּב לַה׳, וְאַחַר כָּךְ ״יָשִׂים לְדֶרֶךְ״ ה׳ ״פְּעָמָיו״, כְּמוֹ שֶׁכָּתוּב: ״וְהָלַכְתָּ בִּדְרָכָיו״, ״אַחֲרֵי ה׳ אֱלֹהֵיכֶם תֵּלֵכוּ״, בְּכָל מַעֲשֵׂה הַמִּצְוֹת, וְתַלְמוּד תּוֹרָה כְּנֶגֶד כּוּלָּן, שֶׁכּוּלָּן עוֹלִין לַה׳ עַל־יְדֵי פְּנִימִית הַלֵּב, בְּיֶתֶר שְׂאֵת וּמַעְלָה מַּעְלָה מֵעֲלִיָּיתָן לַה׳ עַל־יְדֵי חִיצוֹנִית הַלֵּב, הַנּוֹלָד מֵהַתְּבוּנָה וְהַדַּעַת לְבַדָּן, בְּלִי הֶאָרַת פָּנִים מִלְמַעְלָה אֶלָּא בִּבְחִינַת הֶסְתֵּר פָּנִים, כִּי אֵין הַפָּנִים הָעֶלְיוֹנִים מְאִירִים לְמַטָּה אֶלָּא בְּאִתְעָרוּתָא דִלְתַתָּא, בְּמַעֲשֵׂה הַצְּדָקָה הַנִּקְרָא ״שָׁלוֹם״. וְזֶהוּ שֶׁכָּתוּב: ״פָּדָה בְשָׁלוֹם נַפְשִׁי״ – ״נַפְשִׁי״ דַּיְיקָא."],"Tanya, Part IV; Iggeret HaKodesh 4:5":["וּמַה שֶּׁאֵין כָּל אָדָם זוֹכֶה לְמַדְרֵגָה זוֹ, לַעֲבוֹדָה שֶׁבַּלֵּב מֵעוּמְקָא דְלִבָּא בִּבְחִינַת פְּנִימִיּוּת, הַיְינוּ, לְפִי שֶׁבְּחִינָה זוֹ הִיא אֶצְלוֹ בִּבְחִינַת גָּלוּת וְשִׁבְיָה, וְהִיא בְּחִינַת גָּלוּת הַשְּׁכִינָה מַמָּשׁ, כִּי הִיא הִיא בְּחִינַת נִיצוֹץ אֱלֹהוּת שֶׁבְּנַפְשׁוֹ הָאֱלֹהִית. וְסִבַּת הַגָּלוּת, הוּא מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה ״גָּלוּ לְבָבֶל שְׁכִינָה עִמָּהֶם״, דְּהַיְינוּ מִפְּנֵי שֶׁהִלְבִּישׁ בְּחִינַת פְּנִימִית נְקוּדַּת לְבָבוֹ בְּ״זֶה לְעוּמַּת זֶה״, דְּהַיְינוּ בִּלְבוּשִׁים צוֹאִים דְּמִילֵּי דְּעָלְמָא וְתַאֲוֹת עוֹלָם הַזֶּה, הַנִּקְרָא בְּשֵׁם ״בָּבֶל״, וְהִיא בְּחִינַת עָרְלָה הַמְכַסָּה עַל הַבְּרִית וּנְקוּדָּה הַפְּנִימִית שֶׁבַּלֵּב, וְעַל זֶה נֶאֱמַר: ״וּמַלְתֶּם אֵת עָרְלַת לְבַבְכֶם״."],"Tanya, Part IV; Iggeret HaKodesh 5:1":["וַיַּעַשׂ דָּוִד שֵׁם. וּפֵירֵשׁ בַּזּוֹהַר הַקָּדוֹשׁ, מִשּׁוּם שֶׁנֶּאֱמַר: ״וַיְהִי דָוִד עוֹשֶׂה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ כוּ׳״, ״בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר: מַאן עָבִיד שְׁמָא קַדִּישָׁא בְּכָל יוֹמָא מַאן דְּיָהִיב צְדָקָה לְמִסְכְּנֵי כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 5:10":["אַךְ בֵּיאוּר הָעִנְיָן, לָמָּה אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה שֶׁעוֹלָם הַזֶּה דַוְקָא נִבְרָא בְּה׳? הִנֵּה יָדוּעַ לְכָל חַכְמֵי לֵב, כִּי רִיבּוּי הָעוֹלָמוֹת וְהַהֵיכָלוֹת אֲשֶׁר אֵין לָהֶם מִסְפָּר, כְּמוֹ שֶׁכָּתוּב: ״הֲיֵשׁ מִסְפָּר לִגְדוּדָיו״, וּבְכָל הֵיכָל וּגְדוּד אֶלֶף אַלְפִין וְרִבּוֹא רִבְבָן מַלְאָכִים, וְכֵן נֶפֶשׁ־רוּחַ־נְשָׁמָה־חַיָּה־יְחִידָה מַדְרֵגוֹת לְאֵין קֵץ, וּבְכָל עוֹלָם וְהֵיכָלוֹת מֵרִיבּוּי הֵיכָלוֹת שֶׁבַּאֲצִילוּת־בְּרִיאָה־יְצִירָה."],"Tanya, Part IV; Iggeret HaKodesh 5:13":["אַךְ הָעוֹלָם הַזֶּה הַשָּׁפָל, עִם הַחַיּוּת שֶׁבְּתוֹכוֹ, קָטָן מֵהָכִיל וְלִסְבּוֹל אוֹר וְחַיּוּת מִבְּחִינַת צוּרַת הָאוֹתִיּוֹת וּפְנִימִיּוּתָן, לְהָאִיר וּלְהַשְׁפִּיעַ בּוֹ בְּלִי לְבוּשׁ וְהֶסְתֵּר כְּמוֹ שֶׁמְּאִירוֹת וּמַשְׁפִּיעוֹת לִנְשָׁמוֹת וּמַלְאָכִים, רַק הַהֶאָרָה וְהַהַשְׁפָּעָה בָּאָה וְנִשְׁפָּע לָעוֹלָם הַזֶּה מִבְּחִינַת חוֹמֶר וְגוּף הָאוֹתִיּוֹת וְחִיצוֹנִיוּתָם, שֶׁהוּא בְּחִינַת הַהֶבֶל, הַמִּתְחַלֵּק לְז׳ הֲבָלִים שֶׁבְּקֹהֶלֶת שֶׁעֲלֵיהֶם הָעוֹלָם עוֹמֵד, כְּמוֹ שֶׁכָּתוּב בַּזּוֹהַר הַקָּדוֹשׁ."],"Tanya, Part IV; Iggeret HaKodesh 5:15":["וְהִנֵּה, בָּאָדָם הַתַּחְתּוֹן לְמָשָׁל, מִי שֶׁהוּא חָכָם גָּדוֹל לְהַשְׂכִּיל נִפְלְאוֹת חָכְמָה, וּמְצַמְצֵם שִׂכְלוֹ וּמַחֲשַׁבְתּוֹ בְּאוֹת אֶחָד מִדִּבּוּרוֹ, הִנֵּה זֶה הוּא צִמְצוּם עָצוּם וִירִידָה גְדוֹלָה לְחָכְמָתוֹ הַנִּפְלָאָה, כָּכָה מַמָּשׁ עַל דֶּרֶךְ מָשָׁל, וְיָתֵר מִזֶּה לְאֵין קֵץ – הָיָה צִמְצוּם גָּדוֹל עָצוּם וְרַב, כַּאֲשֶׁר ״בִּדְבַר ה׳ שָׁמַיִם נַעֲשׂוּ״, בְּשֵׁשֶׁת יְמֵי בְרֵאשִׁית, ״וּבְרוּחַ פִּיו כָּל צְבָאָם״, הִיא אוֹת ה׳ שֶׁל שֵׁם הַוָיָ׳ בָּרוּךְ־הוּא, ״אָתָא קַלִּילָא״, כְּמוֹ שֶׁכָּתוּב: ״בְּהִבָּרְאָם״ – ״בְּה׳ בְּרָאָם״, הִיא מְקוֹר הַט׳ מַאֲמָרוֹת שֶׁנִמְשְׁכוּ מִמַּאֲמָר רִאשׁוֹן ״בְּרֵאשִׁית״ דְּ״נַמֵי מַאֲמָר הוּא״, הִיא בְּחִינַת חָכְמָה הַנִּקְרֵאת ״רֵאשִׁית״."],"Tanya, Part IV; Iggeret HaKodesh 5:17":["אַךְ אַחַר בְּרִיאַת הָאָדָם ״לְעָבְדָהּ כוּ׳״, אֲזַי כָּל אִתְעָרוּתָא דִלְעֵילָּא לְעוֹרֵר מִדַּת חֶסֶד עֶלְיוֹן, הוּא בְּאִתְעָרוּתָא דִלְתַתָּא, בִּצְדָקָה וָחֶסֶד שֶׁיִּשְׂרָאֵל עוֹשִׂין בָּעוֹלָם הַזֶּה. לָכֵן אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: כָּל הָאוֹמֵר אֵין לוֹ אֶלָּא תּוֹרָה בְּלִי גְּמִילוּת חֲסָדִים, אֲפִילוּ תּוֹרָה אֵין לוֹ, אֶלָּא לַעֲסוֹק בַּתּוֹרָה וּבִגְמִילוּת חֲסָדִים."],"Tanya, Part IV; Iggeret HaKodesh 5:20":["וּבָזֶה יוּבַן מַה שֶׁאָמַר הָאֲרִיזַ״ל, שֶׁיֵּשׁ ב׳ מִינֵי נְשָׁמוֹת בְּיִשְׂרָאֵל – נִשְׁמוֹת תַּלְמִידֵי חֲכָמִים הָעוֹסְקִים בַּתּוֹרָה כָּל יְמֵיהֶם, וְנִשְׁמוֹת בַּעֲלֵי מִצְוֹת הָעוֹסְקִים בִּצְדָקָה וּגְמִילוּת חֲסָדִים. דְּלִכְאוֹרָה, הֲרֵי גַּם תַּלְמִידֵי חֲכָמִים צְרִיכִים לַעֲסוֹק בִּגְמִילוּת חֲסָדִים, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁ״אֲפִילוּ תּוֹרָה אֵין לוֹ״."],"Tanya, Part IV; Iggeret HaKodesh 5:6":["אַךְ הָאוֹתִיּוֹת הֵן בִּבְחִינַת חוֹמֶר וְצוּרָה, הַנִּקְרָא פְּנִימִית וְחִיצוֹנִית, כִּי הֲגַם שֶׁמְּקוֹרָן הוּא מִקַּדְמוּת הַשֵּׂכֶל וּרְצוֹן הַנֶּפֶשׁ, זוֹ הִיא בְּחִינַת צוּרַת שִׁינּוּי הַמִּבְטָא שֶׁבְּכ״ב אוֹתִיּוֹת, אֲבָל בְּחִינַת הַחוֹמֶר וְגוּף הִתְהַוּוּתָן, וְהוּא בְּחִינַת חִיצוֹנִיּוּתָן, הוּא הַהֶבֶל הַיּוֹצֵא מֵהַלֵּב, שֶׁמִּמֶּנּוּ מִתְהַוֶּה קוֹל פָּשׁוּט הַיּוֹצֵא מֵהַגָּרוֹן, וְאַחַר כָּךְ נֶחְלָק לְכ״ב הֲבָרוֹת, וּבִיטּוּי כ״ב אוֹתִיּוֹת בְּה׳ מוֹצָאוֹת הַיְדוּעוֹת: אחה״ע מֵהַגָּרוֹן, גיכ״ק מֵהַחֵיךְ כוּ׳. וּמִבְטָא הַהֶבֶל הוּא אוֹת ה׳ ״אָתָא קַלִּילָא כוּ׳״, וְהוּא מְקוֹר הַחוֹמֶר וְגוּף הָאוֹתִיּוֹת טֶרֶם הִתְחַלְּקוּתָן לְכ״ב, וְלָכֵן אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה, שֶׁ״עוֹלָם הַזֶּה נִבְרָא בְּה׳״:"],"Tanya, Part IV; Iggeret HaKodesh 5:7":["וְהִנֵּה, הֲגַם שֶׁהִיא ה׳ תַּתָּאָה, ה׳ אַחֲרוֹנָה שֶׁבְּשֵׁם הַוָיָ׳, וְרַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה דָּרְשׁוּ זֶה עַל פָּסוּק: ״כִּי בְּיָהּ״, הַיְינוּ לְפִי שֶׁמְּקוֹרָהּ וְרֵאשִׁיתָהּ לָבֹא לִבְחִינַת גִּילּוּי מֵהֶעְלֵם הַיּוּ״ד הוּא מוּשְׁפָּע וְנִמְשָׁךְ מִבְּחִינַת ה׳ עִילָּאָה, שֶׁיֵּשׁ לָהּ הִתְפַּשְּׁטוּת אוֹרֶךְ וְרוֹחַב, לְהוֹרוֹת עַל בְּחִינַת בִּינָה, שֶׁהִיא הִתְפַּשְּׁטוּת הַשֵּׂכֶל הַנֶּעְלָם בִּבְחִינַת גִּילּוּי וְהַשָּׂגָה בְּהַרְחָבַת הַדַּעַת, וְהַשְׁפָּעָתָהּ מִסְתַּיֶּימֶת בַּלֵּב, וּכְמוֹ שֶׁכָּתוּב בַּתִּיקּוּנִים, דְּ״בִינָה לִבָּא, וּבָהּ הַלֵּב מֵבִין״, וּמִשָּׁם יוֹצֵא הַהֶבֶל מְקוֹר גִּילּוּי גּוּף הָאוֹתִיּוֹת הַדִּבּוּר, הַמִּתְגַּלּוֹת בְּה׳ מוֹצָאוֹת מֵהֶעְלֵם הַיּוּ״ד."],"Tanya, Part IV; Iggeret HaKodesh 6:1":["זוֹרֵעַ צְדָקָה שֶׂכֶר אֱמֶת (בְּמִשְׁלֵי י״א). פֵּירוּשׁ, שֶׁשְּׂכַר זְרִיעַת הַצְּדָקָה הִיא מִדַּת אֱמֶת."],"Tanya, Part IV; Iggeret HaKodesh 6:9":["וְהִנֵּה מוּדַעַת זֹאת, דְּיֵשׁ ב׳ מִינֵי דְּחִילוּ וּרְחִימוּ: הָרִאשׁוֹנוֹת, הֵן הַנּוֹלָדוֹת מֵהַתְּבוּנָה וְהַדַּעַת בִּגְדוּלַּת ה׳ וּבִדְבָרִים הַמְּבִיאִין לִידֵי אַהֲבַת ה׳ וְיִרְאָתוֹ, וְהָאַחֲרוֹנוֹת, הֵן הַבָּאוֹת אַחַר כָּךְ מִלְמַעְלָה בִּבְחִינַת מַתָּנָה, וּכְמוֹ שֶׁנִּתְבָּאֵר בְּמָקוֹם אַחֵר עַל פָּסוּק: ״עֲבוֹדַת מַתָּנָה אֶתֵּן אֶת כְּהוּנַּתְכֶם״, שֶׁהִיא מִדַּת אַהֲבָה, וְכֵן הוּא גַם כֵּן בְּיִּרְאָה."],"Tanya, Part IV; Iggeret HaKodesh 7:1":["אַשְׁרֵינוּ מַה טּוֹב חֶלְקֵנוּ וּמַה נָּעִים גּוֹרָלֵנוּ כוּ׳, ״ה׳ מְנָת חֶלְקִי וְכוֹסִי וְגוֹ׳״, ״חֲבָלִים נָפְלוּ לִי וְגוֹ׳״."],"Tanya, Part IV; Iggeret HaKodesh 7:12":["וְהִנֵּה, אַף שֶׁגִּילּוּי זֶה עַל־יְדֵי עֵסֶק הַתּוֹרָה וְהַמִּצְוֹת הוּא שָׁוֶה לְכָל נֶפֶשׁ מִיִּשְׂרָאֵל בְּדֶרֶךְ כְּלָל, כִּי תּוֹרָה אַחַת וּמִשְׁפָּט אֶחָד לְכוּלָּנוּ, אַף־עַל־פִּי־כֵן, בְּדֶרֶךְ פְּרָט, אֵין כָּל הַנְּפָשׁוֹת אוֹ הָרוּחוֹת וְהַנְּשָׁמוֹת שָׁווֹת בְּעִנְיָן זֶה לְפִי עֵת וּזְמַן גִּלְגּוּלָם וּבוֹאָם בָּעוֹלָם הַזֶּה וּכְמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אֲבוּךְ בְּמַאי הֲוֵי זָהִיר טְפֵי, אָמַר לֵיהּ בְּצִיצִית כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 7:6":["וְהִנֵּה, הֶאָרָה זוֹ, אַף שֶׁלְּמַעְלָה הִיא מְאִירָה וּמִתְפַּשֶּׁטֶת בִּבְחִינַת בְּלִי גְבוּל וְתַכְלִית, לְהַחֲיוֹת עוֹלָמוֹת נֶעְלָמִים לְאֵין קֵץ וְתַכְלִית, כְּמוֹ שֶׁכָּתוּב בְּאִדְרָא רַבָּא, אַף־עַל־פִּי־כֵן, בְּרִדְתָּהּ לְמַטָּה עַל־יְדֵי צִמְצוּמִים רַבִּים לְהַחֲיוֹת הַנִּבְרָאִים וְהַיְצוּרִים וְהַנַּעֲשִׂים, הִיא נֶחְלֶקֶת דֶּרֶךְ כְּלָל לְמִסְפַּר תַּרְיַ״ג, כְּנֶגֶד תַּרְיַ״ג מִצְוֹת הַתּוֹרָה, שֶׁהֵן הֵן תַּרְיַ״ג מִינֵי הַמְשָׁכוֹת הֶאָרָה זוֹ מֵאוֹר־אֵין־סוֹף בָּרוּךְ־הוּא, לְהָאִיר לְנִשְׁמַת הָאָדָם הַכְּלוּלָה מֵרַמַ״ח אֵבָרִים וְשַׁסַ״ה גִידִים, אֲשֶׁר בַּעֲבוּרָהּ הוּא עִיקַּר תַּכְלִית יְרִידַת וְהַמְשָׁכַת הֶאָרָה זוֹ לְמַטָּה לְכָל הַנִּבְרָאִים וְהַיְצוּרִים וְהַנַּעֲשִׂים, שֶׁתַּכְלִית כּוּלָּן הוּא הָאָדָם, כַּנּוֹדָע:"],"Tanya, Part IV; Iggeret HaKodesh 7:9":["וְהִנֵּה, ״שׁוּפְרֵיהּ דְּיַעֲקֹב מֵעֵין שׁוּפְרֵיהּ דְּאָדָם הָרִאשׁוֹן״, שֶׁתִּיקֵּן חֵטְא אָדָם הָרִאשׁוֹן, וְהָיְתָה נִשְׁמָתוֹ גַם כֵּן כְּלוּלָה מִכָּל הַנְּשָׁמוֹת שֶׁבְּיִשְׂרָאֵל, מֵעוֹלָם וְעַד עוֹלָם, וְהָיָה מֶרְכָּבָה לַתּוֹרָה שֶׁלְּמַעְלָה, שֶׁנִּקְרֵאת בְּשֵׁם ״אָדָם״, כְּמוֹ שֶׁכָּתוּב: ״וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם וְכוּ׳״, וּכְמוֹ שֶׁכָּתוּב: ״וְזֹאת לְפָנִים בְּיִשְׂרָאֵל כוּ׳״ – ״אֵין זֹאת אֶלָּא תּוֹרָה כוּ׳״, שֶׁהָיְתָה כְּלוּלָה וּמְלוּבֶּשֶׁת בְּנִשְׁמַת ״יִשְׂרָאֵל סָבָא״, הַכְּלוּלָה מִכָּל הַנְּשָׁמוֹת."],"Tanya, Part IV; Iggeret HaKodesh 8:1":["זוֹרֵעַ צְדָקוֹת, מַצְמִיחַ יְשׁוּעוֹת. הִנֵּה, מַה שֶּׁכָּתוּב לְשׁוֹן ״זְרִיעָה״ בְּמִצְוַת הַצְּדָקָה, וּכְמוֹ שֶׁכָּתוּב בַּפָּסוּק: ״זִרְעוּ לָכֶם לִצְדָקָה כוּ׳״, יוּבַן עַל פִּי מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״רַבִּי אֶלְעָזָר יָהִיב פְּרוּטָה לְעָנִי וַהֲדַר מַצְלֵּי, דִּכְתִיב: אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ״. פֵּירוּשׁ, כִּי גִּילּוּי אֱלֹקוּתוֹ יִתְבָּרֵךְ הַמִּתְגַּלֶּה בְּמַחֲשַׁבְתּוֹ שֶׁל אָדָם וְכַוָּנָתוֹ בִּתְפִלָּתוֹ, כָּל חַד לְפוּם שִׁיעוּרָא דִילֵיהּ, הוּא בְּתוֹרַת צְדָקָה ״וְחֶסֶד ה׳ מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 8:4":["וְהִנֵּה, מוּדַעַת זֹאת, שֶׁיֵּשׁ לְמַעְלָה גַּם כֵּן מִדַּת הַגְּבוּרָה וְהַצִּמְצוּם, לְצַמְצֵם וּלְהַסְתִּיר אוֹרוֹ יִתְבָּרֵךְ לְבַל יִתְגַּלֶּה לַתַּחְתּוֹנִים. אַךְ הַכֹּל תָּלוּי בְּ״אִתְעָרוּתָא דִלְתַתָּא״, שֶׁאִם הָאָדָם מִתְנַהֵג בַּחֲסִידוּת לְהַשְׁפִּיעַ חַיִּים וָחֶסֶד כוּ׳ כָּךְ מְעוֹרֵר לְמַעְלָה, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״בְּמִדָּה שֶׁאָדָם מוֹדֵד – בָּהּ מוֹדְדִין לוֹ״."],"Tanya, Part IV; Iggeret HaKodesh 8:6":["אַךְ הָעִנְיָן הוּא, עַל דֶּרֶךְ מָשָׁל, כְּמוֹ שֶׁזּוֹרְעִין זְרָעִים אוֹ נוֹטְעִין גַּרְעִין, שֶׁהַשִּׁבּוֹלֶת הַצּוֹמַחַת מֵהַזֶּרַע, וְהָאִילָן וּפֵירוֹתָיו מֵהַגַּרְעִין, אֵינָן מַהוּתָן וְעַצְמוּתָן שֶׁל הַזֶּרַע וְהַגַּרְעִין כְּלָל, כִּי מַהוּתָם וְעַצְמוּתָם כָּלֶה וְנִרְקָב בָּאָרֶץ, וְכֹחַ הַצּוֹמֵחַ שֶׁבָּאָרֶץ עַצְמָהּ [נוסח אחר: עַצְמוֹ] הוּא הַמּוֹצִיא וְהַמְגַדֵּל הַשִּׁבּוֹלֶת וְהָאִילָן וּפֵירוֹתָיו. רַק שֶׁאֵינוֹ מוֹצִיא וּמְגַלֶּה כֹּחוֹ לַחוּץ מֵהַכֹּחַ אֶל הַפּוֹעַל, כִּי אִם עַל־יְדֵי הַזֶּרַע וְהַגַּרְעִין שֶׁנִּרְקָבִין בָּאָרֶץ וְכָלֶה כָּל כֹּחָם בְּכֹחַ הַצּוֹמֵחַ שֶׁבָּאָרֶץ, וְנִתְאַחֲדוּ וְהָיוּ לַאֲחָדִים, וְעַל־יְדֵי זֶה מוֹצִיא כֹּחַ הַצּוֹמֵחַ אֶת כֹּחוֹ אֶל הַפּוֹעַל, וּמַשְׁפִּיעַ חַיּוּת לְגַדֵּל שִׁבּוֹלֶת כְּעֵין הַזֶּרַע, אֲבָל בְּרִיבּוּי הַרְבֵּה מְאֹד בְּשִׁבּוֹלֶת אַחַת, וְכֵן פֵּירוֹת הַרְבֵּה עַל אִילָן אֶחָד, וְגַם מַהוּתָן וְעַצְמוּתָן שֶׁל הַפֵּירוֹת מְעוּלָּה בְּעִילּוּי רַב וְעָצוּם לְמַעְלָה מַּעְלָה מִמַּהוּתוֹ וְעַצְמוּתוֹ שֶׁל הַגַּרְעִין הַנָּטוּעַ. וְכֵן כְּהַאי גַּוְנָא בְּפֵירוֹת הָאָרֶץ הַגְּדֵלִים מִזֵּרְעוֹנִין כְּעֵין גַּרְעִינִין, כְּמוֹ קִשּׁוּאִים וּכְהַאי גַּוְנָא."],"Tanya, Part IV; Iggeret HaKodesh 8:8":["וְכָכָה מַמָּשׁ עַל דֶּרֶךְ מָשָׁל, כָּל מַעֲשֵׂה הַצְּדָקָה שֶׁעוֹשִׂין יִשְׂרָאֵל, עוֹלֶה לְמַעְלָה בִּבְחִינַת ״הַעֲלָאַת מַיִּין נוּקְבִין״ לְשׁוֹרֶשׁ נִשְׁמוֹתֵיהֶן לְמַעְלָה, הַנִּקְרָא בְּשֵׁם ״כְּנֶסֶת יִשְׂרָאֵל״ וְ״אִימָּא תַּתָּאָה״ בִּלְשׁוֹן הַזֹּהַר, וּ״שְׁכִינָה״ בִּלְשׁוֹן הַגְּמָרָא, הַכְּלוּלָה מִכָּל מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וּמְיוּחֶדֶת בָּהֶן בְּתַכְלִית, וְרֵאשִׁיתָן – הִיא מִדַּת הַחֶסֶד. וְעַל־יְדֵי הַעֲלָאָה זוֹ מִתְעוֹרֵר ״חֶסֶד ה׳״ מַמָּשׁ, שֶׁהוּא גִילּוּי אוֹרוֹ יִתְבָּרֵךְ, לֵירֵד וּלְהָאִיר לְמַטָּה לְנִשְׁמוֹת יִשְׂרָאֵל, בִּבְחִינַת גִּילּוּי רַב וְעָצוּם בִּשְׁעַת הַתְּפִלָּה עַל כָּל פָּנִים. כִּי אַף שֶׁ״לִּגְדוּלָּתוֹ אֵין חֵקֶר״, עַד דְּ״כוּלָּא קַמֵּיהּ כְּלָא חֲשִׁיבֵי״ הֲרֵי ״בְּמָקוֹם שֶׁאַתָּה מוֹצֵא גְּדוּלָּתוֹ, שָׁם אַתָּה מוֹצֵא עַנְוְתָנוּתוֹ״, כְּ״מַיִם שֶׁיּוֹרְדִין כוּ׳״."],"Tanya, Part IV; Iggeret HaKodesh 9:1":["אֲהוּבַיי אַחַיי וְרֵעַיי אֲשֶׁר כְּנַפְשִׁי, בָּאתִי כְּמַזְכִּיר וּמְעוֹרֵר יְשֵׁנִים בְּתַרְדֵּמַת הַבְלֵי הֲבָלִים, וְלִפְקוֹחַ עֵינֵי הָעִוְרִים יַבִּיטוּ לִרְאוֹת, לִהְיוֹת כָּל יִשְׁעָם וְחֶפְצָם וּמְגַמָּתָם לְכָל בָּהֶם חַיֵּי רוּחָם בִּ״מְקוֹר מַיִם חַיִּים״ חַיֵּי הַחַיִּים, כָּל יְמֵי חַיֵּיהֶם, מִנֶּפֶשׁ וְעַד בָּשָׂר. דְּהַיְינוּ, כָּל מִילֵּי דְעָלְמָא וְעִסְקֵי פַּרְנָסָה לֹא יִהְיֶה כְּאֵלּוּ דְּעָבְדִין לְגַרְמַיְיהוּ, וְלֹא יִהְיֶה בֵּית יִשְׂרָאֵל כְּכָל הַגּוֹיִם, דְּזָנִין וּמְפַרְנְסִין וּמוֹקְרִין לִנְשַׁיְיהוּ וּבְנַיְיהוּ מֵאַהֲבָה, כִּי – ״מִי כְּעַמְּךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ״ כְּתִיב, דְּהַיְינוּ – שֶׁגַּם בְּעִנְיְנֵי אֶרֶץ לֹא יַפְרִידוּ [נוסח אחר: יִפָּרְדוּ] מֵאֶחָד הָאֱמֶת חַס וְשָׁלוֹם, לְהָעִיד עֵדוּת שֶׁקֶר חַס וְשָׁלוֹם, בִּקְרִיאַת־שְׁמַע עֶרֶב וָבוֹקֶר, בְּעֵינַיִם סְגוּרוֹת, ״ה׳ אֶחָד״ בְּד׳ רוּחוֹת וּבַשָּׁמַיִם מִמַּעַל וּבָאָרֶץ מִתָּחַת, וּבִפְקוֹחַ עֵינֵי הָעִוְרִים ״הֲתָעִיף עֵינֶיךָ בּוֹ וְאֵינֶנּוּ״ חַס וְשָׁלוֹם."],"Tanya, Part IV; Iggeret HaKodesh 9:3":["עַל כֵּן, אֲהוּבַיי אַחַיי, שִׂימוּ נָא לְבַבְכֶם לָאֵלֶּה הַדְּבָרִים הַנֶּאֱמָרִים בִּקְצָרָה מְאֹד (וְאִם יִרְצֶה ה׳ פֶּה אֶל פֶּה אֲדַבֵּר בָּם בַּאֲרוּכָּה), אֵיךְ הֱיוֹת כָּל עִיקַּר עֲבוֹדַת ה׳ בָּעִתִּים הַלָּלוּ בְּעִקְּבוֹת מְשִׁיחָא הִיא עֲבוֹדַת הַצְּדָקָה, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״אֵין יִשְׂרָאֵל נִגְאָלִין אֶלָּא בִּצְדָקָה״. וְלֹא אָמְרוּ רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה ״תַּלְמוּד תּוֹרָה שָׁקוּל כְּנֶגֶד גְּמִילוּת חֲסָדִים״, אֶלָּא בִּימֵיהֶם, שֶׁתַּלְמוּד תּוֹרָה הָיָה עִיקַּר הָעֲבוֹדָה אֶצְלָם, וְעַל כֵּן הָיוּ חֲכָמִים גְּדוֹלִים תַּנָּאִים וְאַמוֹרָאִים. מַה שֶּׁאֵין כֵּן בְּעִקְּבוֹת מְשִׁיחָא, שֶׁנָּפְלָה ״סוּכַּת דָּוִד״ עַד בְּחִינַת רַגְלַיִם וַעֲקֵבַיִים, שֶׁהִיא בְּחִינַת עֲשִׂיָּה, אֵין דֶּרֶךְ לְדָבְקָה בָּהּ בֶּאֱמֶת וּלְהַפְּכָא חֲשׁוֹכָא לִנְהוֹרָא דִּילָהּ [נוסח אחר: דִּילֵיהּ] כִּי אִם בִּבְחִינַת עֲשִׂיָּה גַם כֵּן, שֶׁהִיא מַעֲשֵׂה הַצְּדָקָה, כַּיָּדוּעַ לַמַּשְׂכִּילִים, שֶׁבְּחִינַת עֲשִׂיָּה בֵּאלֹקוּת – הִיא בְּחִינַת הַשְׁפָּעַת וְהַמְשָׁכַת הַחַיּוּת לְמַטָּה מַּטָּה לְמַאן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם. וְכָל הַזּוֹבֵחַ אֶת יִצְרוֹ בָּזֶה וּפוֹתֵחַ יָדוֹ וּלְבָבוֹ, אִתְכַּפְיָא סִטְרָא אָחֳרָא וּמְהַפֵּךְ חֲשׁוֹכָא לְאוֹר הַשֵּׁם יִתְבָּרֵךְ, הַשּׁוֹכֵן עָלֵינוּ בִּבְחִינַת עֲשִׂיָּה בְּעִקְּבוֹת מְשִׁיחָא, וְיִזְכֶּה לִרְאוֹת ״עַיִן בְּעַיִן בְּשׁוּב ה׳ צִיּוֹן״ כוּ׳:"],"Tanya, Part V; Kuntres Acharon 1:1":["קוּנְטְרֵס אַחֲרוֹן עַל כַּמָּה פְּרָקִיםעיין בלקוטי אמרים חלק א׳ פרק מ׳"],"Tanya, Part V; Kuntres Acharon 2:1":["עַיֵּין עֵץ חַיִּים שַׁעַר הַנְּקוּדּוֹת שַׁעַר ח׳ פֶּרֶק ו׳, שֶׁאֵין הַחֲזָרַת פָּנִים בְּפָנִים כִּי אִם עַל־יְדֵי מִצְוֹת מַעֲשִׂיּוֹת דַּוְקָא. וְטַעַם הַדָּבָר, כִּי עַל־יְדֵי מַעֲשִׂים טוֹבִים גּוֹרֵם זִיוּוּג הָעֶלְיוֹן וְכוּ׳."],"Tanya, Part V; Kuntres Acharon 3:1":["לְהָבִין מַה שֶּׁכָּתוּב בְּשַׁעַר הַיִּחוּדִים פֶּרֶק ב׳, דְּעַל־יְדֵי תּוֹרָה שֶׁלֹּא בְכַוָּונָה נִבְרָאִים מַלְאָכִים בְּעוֹלַם הַיְצִירָה, וְשָׁם הֵבִיא מֵהַזֹּהַר פָּרָשַׁת שְׁלַח: ״דְּלֵית קָלָא דְּאִתְאֲבִיד כוּ׳ בַּר קָלָא דְּאוֹרַיְיתָא וּצְלוֹתָא דְּסָלִיק וּבָקַע כוּ׳״. וְהִנֵּה, מִכַּוָּונַת הַתְּפִלָּה נִבְרְאוּ מַלְאָכִים בְּעוֹלַם הַבְּרִיאָה כְּמוֹ מִכַּוָּונַת הַתּוֹרָה, וּבְלֹא כַוָּונָה – נִדְחֵית לְמַטָּה לְגַמְרֵי, כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר פָּרָשַׁת פְּקוּדֵי דַּף רמ״ה עַמּוּד ב׳: ״גּוֹ רָקִיעַ תַּתָּאָה כוּ׳ דְּאִקְּרִין צְלוֹתִין פְּסִילָאן כוּ׳״, וְעַיֵּין שָׁם פָּרָשַׁת וַיַּקְהֵל דַּף ר״א עַמּוּד ב׳: ״אִי הִיא מִלָּה כִּדְקָא יָאוּת כוּ׳״."],"Tanya, Part V; Kuntres Acharon 3:2":["אַךְ הַהֶפְרֵשׁ בֵּין תּוֹרָה לִתְפִלָּה שֶׁלֹּא בְכַוָּונָה, מוּבָן מֵאֵלָיו, כִּי לִימּוּד הַתּוֹרָה הוּא מֵבִין וְיוֹדֵעַ מַה שֶּׁלּוֹמֵד, דִּבְלָאו הָכֵי לָא מִיקְרֵי לִימּוּד כְּלָל, רַק, שֶׁלּוֹמֵד סְתָם, בְּלֹא כַּוָּונָה לִשְׁמָהּ מֵאַהֲבַת ה׳ שֶׁבְּלִבּוֹ בִּבְחִינַת גִּילּוּי, רַק מֵאַהֲבָה הַמְסוּתֶּרֶת הַטִּבְעִית, אַךְ אֵינוֹ לוֹמֵד שֶׁלֹּא לִשְׁמָהּ מַמָּשׁ לְהִתְגַּדֵּל כוּ׳, דְּהָא לָא סָלִיק לְעֵילָּא מִן שִׁמְשָׁא, כְּמוֹ שֶׁכָּתוּב בְּפָרָשַׁת וַיְחִי דַּף רכ״ג עַמּוּד ב׳, וְהַיְינוּ מִשּׁוּם שֶׁמַּחֲשַׁבְתּוֹ וְכַוָּונָתוֹ הֵן מִתְלַבְּשׁוֹת בְּאוֹתִיּוֹת הַדִּבּוּר וְאֵינָן מַנִּיחוֹת אוֹתָן לְסָלְקָא לְעֵילָא."],"Tanya, Part V; Kuntres Acharon 3:4":["וּמַה שֶּׁכָּתוּב בְּפָרָשַׁת פְּקוּדֵי: ״גּוֹ רָקִיעַ תַּתָּאָה״, וּבְפָרָשַׁת וַיַּקְהֵל מַשְׁמַע דְּדַוְקָא ״אִי אִיהִי מִלָּא כִּדְקָא יָאוּת סָלְקִין עִמָּהּ״ עַד אֲוִירָא דְּרָקִיעַ דִּלְעֵילָּא כוּ׳ – לֹא קָשֶׁה מִידֵי: דְּרָקִיעַ תַּתָּאָה מֵאִינּוּן רְקִיעִין דְּמִדַּבְּרֵי גּוֹ עָלְמָא שֶׁבְּפָרָשַׁת פְּקוּדֵי – הֵן דְּמַלְכוּת דַּעֲשִׂיָּה, וּדְפָרָשַׁת וַיַּקְהֵל – הֵן דִּ״זְעֵיר אַנְפִּין״ דַּעֲשִׂיָּה, כְּמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים שַׁעַר הַשֵּׁמוֹת פֶּרֶק ג׳ גַּבֵּי ״זְעֵיר אַנְפִּין״ דַּעֲשִׂיָּיה, עַיֵּין שָׁם."],"Tanya, Part V; Kuntres Acharon 3:7":["וְהִנֵּה, תְּפִלָּה פְּסוּלָה עֲדִיפָא מִתּוֹרָה שֶׁלֹּא לִשְׁמָהּ מַמָּשׁ, שֶׁהִיא תַּחַת הַשֶּׁמֶשׁ, וְהַתְּפִלָּה הִיא גּוֹ רָקִיעַ כוּ׳. אֲבָל תּוֹרָה סְתָם, שֶׁאֵינָהּ שֶׁלֹּא לִשְׁמָהּ רַק מֵאַהֲבָה מְסוּתֶּרֶת טִבְעִית, לָא גָרְעָא מֵהֶבֶל פִּיהֶן שֶׁל תִּינוֹקֹת־שֶׁל־בֵּית־רַבָּן, דְּסָלִיק לְעֵילָּא מִפְּנֵי שֶׁהוּא הֶבֶל שֶׁאֵין בּוֹ חֵטְא, וְסָלִיק לְעֵילָּא, אַף אִם הוּא שֶׁלֹּא לִשְׁמָהּ מַמָּשׁ, מִיִּרְאַת הָרְצוּעָה שֶׁבְּיַד הַסּוֹפֵר, וְעַיֵּין שָׁם דַּף רנ״ה עַמּוּד ב׳, שֶׁהַמַּלְאָכִים הֵם מַעֲלִים הַהֶבֶל שֶׁל תִּינוֹקֹת־שֶׁל־בֵּית־רַבָּן עַד אֲצִילוּת:"],"Tanya, Part V; Kuntres Acharon 4:1":["לְהָבִין מַה שֶּׁכָּתוּב בִּפְרִי עֵץ חַיִּים, דְּבִזְמַן הַזֶּה, עִיקַּר הַבֵּירוּר עַל יְדֵי הַתְּפִלָּה דַּוְקָא, אַף שֶׁתַּלְמוּד תּוֹרָה לְמַעְלָה מֵהַתְּפִלָּה."],"Tanya, Part V; Kuntres Acharon 4:10":["וְהִנֵּה, בְּמָקוֹם אֶחָד כָּתַב שֶׁרַמַ״ח מִצְוֹת עֲשֵׂה – הֵן בְּה׳ חֲסָדִים וְשַׁסַ״ה לֹא תַעֲשֶׂה בְּה׳ גְּבוּרוֹת וְכוּ׳, וּבְמָקוֹם אַחֵר כָּתַב שֶׁהֵן תַּרְיַ״ג אָרְחִין נִמְשָׁכִין מֵחַד אָרְחָא כוּ׳, שֶׁהוּא לַבְנוּנִית וְכוּ׳."],"Tanya, Part V; Kuntres Acharon 4:14":["וְהִנֵּה, לְקִיּוּם מִצְוָה שֶׁאִי אֶפְשָׁר לַעֲשׂוֹת עַל־יְדֵי אֲחֵרִים מְבַטְּלִין תַּלְמוּד תּוֹרָה, וַאֲפִילוּ מַעֲשֵׂה מֶרְכָּבָה, וְכָל שֶׁכֵּן תְּפִלָּה שֶׁהִיא בְּחִינַת מוֹחִין וּדְחִילוּ וּרְחִימוּ שִׂכְלִיִּים, וְהַטַּעַם – כַּנִּזְכָּר לְעֵיל."],"Tanya, Part V; Kuntres Acharon 4:18":["מַה־שֶּׁאֵין־כֵּן מַעֲשֵׂה הַמִּצְוֹת ״מַעֲשֵׂה אֱלֹקִים הֵמָּה״ הֵנָּה בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת מִכֵּלִים דַּאֲצִילוּת לִבְרִיאָה־יְצִירָה־עֲשִׂיָּה, מִמַּהוּתָן וְעַצְמוּתָן דְּחִיצוֹנִיּוּתָן, כְּמוֹ עַל דֶּרֶךְ מָשָׁל אֶתְרוֹג וּמִינָיו, הִלְבִּישׁ בָּהֶן הַקָּדוֹשׁ־בָּרוּךְ־הוּא מִמַּהוּתָן וְעַצְמוּתָן דַּחֲסָדִים [פְּנִימִית] [פְּנִימִים] דִּ״זְעֵיר אַנְפִּין״, וְהַיְינוּ מִבְּחִינַת חִיצוֹנִיּוּתָן, כַּנּוֹדָע בְּכָל מִצְוֹת מַעֲשִׂיּוֹת."],"Tanya, Part V; Kuntres Acharon 4:24":["מַה־שֶּׁאֵין־כֵּן בְּכַוָּונָתוֹ, אֵינוֹ מַשִּׂיג וְתוֹפֵס, אַף הַיּוֹדֵעַ הַסּוֹד. – אֶלָּא מְצִיאוּתָהּ, וְלֹא מַהוּתָהּ. אַךְ בְּלִימּוּד הִלְכוֹת אֶתְרוֹג מַשִּׂיג וְתוֹפֵס הָאֶתְרוֹג מַמָּשׁ וּמִצְוָתוֹ כַּהֲלָכָה, בִּבְחִינַת דִּבּוּר וּמַחֲשָׁבָה, וְכָל שֶׁכֵּן הַלּוֹמֵד הַסּוֹד. אֲבָל דַּוְקָא סוֹדוֹת הַמִּצְוָה, דְּלֹא גָרַע מִלִּימּוּד הִלְכוֹתֶיהָ, וְאַדְּרַבָּה כוּ׳, אַף שֶׁאֵינוֹ מַשִּׂיג הַמַּהוּת."],"Tanya, Part V; Kuntres Acharon 4:28":["וְעוֹד זֹאת, שֶׁבֶּאֱמֶת הַבֵּירוּרִין שֶׁבִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה מֵרַפַּ״ח, עַל־יְדֵי תּוֹרָה וּמִצְוֹת בְּמַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה, גְּבוֹהִין בְּשָׁרְשָׁן מִנֶּפֶשׁ־רוּחַ־נְשָׁמָה שֶׁבָּאָדָם, כִּי הֵן מִ״סַּ״ג״ שֶׁבִּפְנִימִית ״אָדָם קַדְמוֹן״, וְנֶפֶשׁ־רוּחַ־נְשָׁמָה שֶׁכְּבָר נִתְקְנוּ עַל־יְדֵי ״מַ״ה״, הוּא יוֹצֵא מֵהַ״מֵּצַח״ הֶאָרָה בְּעָלְמָא. וְזֶהוּ שֶׁכָּתוּב: ״לִפְנֵי מְלוֹךְ מֶלֶךְ כוּ׳״. וְהַיְינוּ טַעֲמָא שֶׁהָאָדָם חַי בִּמְזוֹנוֹת דּוֹמֵם־צוֹמֵחַ־חַי, וּמְבָרְרָן בְּ״מַ״ה״ שֶׁבּוֹ, וְחַי בָּהֶם, לְפִי שֶׁהֵם מִ״סַ״ג״."],"Tanya, Part V; Kuntres Acharon 4:35":["וּבַר מִן כָּל דֵּין, אֲפִילוּ בִּנְשָׁמָה דַאֲצִילוּת, אַף שֶׁהִיא מִכֵּלִים דַּאֲצִילוּת, וְכֵן בְּנֶפֶשׁ־רוּחַ מִכֵּלִים דִּיצִירָה־עֲשִׂיָּה הִנֵּה רְחִימוּ [אולי צריך להיות: דְּחִילוּ וּרְחִימוּ] שִׂכְלִיִּים שֶׁלָּהֶם – מְעוֹרְרִים גַּם כֵּן בְּכֵלִים דִּיצִירָה־עֲשִׂיָּה בְּחִינַת הַעֲלָאָה מִמַּטָּה לְמַעְלָה בְּ״אִתְעָרוּתָא דִלְתַתָּא״, וְזֶהוּ בְּחִינַת הִסְתַּלְּקוּת לְבַד חַס וְשָׁלוֹם."],"Tanya, Part V; Kuntres Acharon 4:40":["אַךְ לְהָבִין, אֵיךְ הָאֶתְרוֹג שֶׁהוּא מֵרַפַּ״ח שֶׁלֹּא נִבְרְרוּ עֲדַיִין, וְכֵן קְלַף הַתְּפִילִּין, יַמְשִׁיךְ אוֹר בְּכֵלִים דִּזְעֵיר אַנְפִּין וְנוּקְבָא דַּאֲצִילוּת, שֶׁכְּבָר נִבְרְרוּ וְנִתְקְנוּ עַל־יְדֵי שֵׁם ״מַ״ה״ לִהְיוֹת בְּחִינַת אֱלֹקוּת?"],"Tanya, Part V; Kuntres Acharon 4:44":["אַךְ עוֹד זֹאת הַשָּׁוֶה בַּכֹּל, כִּי כָּל דְּחִילוּ וּרְחִימוּ שִׂכְלִיִּים שֶׁל הַמַּלְאָכִים הֵן בְּחִינוֹת נִבְרָאִים מֵאַיִן לְיֵשׁ, וְהֵן בְּחִינוֹת נֶפֶשׁ רוּחַ דִּבְרִיאָה־יְצִירָה־עֲשִׂיָּה."],"Tanya, Part V; Kuntres Acharon 4:46":["מַה־שֶּׁאֵין־כֵּן הַהֲלָכוֹת, הֲרֵי הֶאָרַת הַחָכְמָה מְאִירָה בָּהֶן בְּגִילּוּי, וּלְבוּשׁ הָעֲשִׂיָּה הוּא דֶּרֶךְ מַעֲבָר לְבַד, כְּמוֹ בְּיוֹם טוֹב, שֶׁחֶסֶד דַּאֲצִילוּת הַמְלוּבָּשׁ לְגַמְרֵי בְּחֶסֶד דִּבְרִיאָה מְחַיֶּה עוֹלָם הַזֶּה הַגַּשְׁמִי, עַל־יְדֵי מַעֲבַר חֶסֶד דִּיצִירָה וַעֲשִׂיָּה, הַנִּקְרָא גַּם כֵּן הִתְלַבְּשׁוּת, שֶׁאִם לֹא כֵן, לֹא הָיָה פּוֹעֵל בְּגַשְׁמִיּוּת עוֹלָם הַזֶּה."],"Tanya, Part V; Kuntres Acharon 4:50":["וְהַטַּעַם, מִשּׁוּם דְּחָכְמָה־בִּינָה־דַּעַת דַּעֲשִׂיָּה דִּבְחִינַת נְשָׁמָה הוּא מְקוֹר הַחַיּוּת דְּחָכְמָה־בִּינָה־דַּעַת דְּנֶפֶשׁ־רוּחַ וְתוֹלְדוֹתֵיהֶן, וְהִתְהַוּוּתָן מֵאַיִן לְיֵשׁ עִם תּוֹלְדוֹתֵיהֶן, עַד סוֹף הָעֲשִׂיָּה, הִיא הָאָרֶץ וְכָל צְבָאָהּ."],"Tanya, Part V; Kuntres Acharon 4:54":["וּמַה שֶּׁכָּתוּב בְּעֵץ חַיִּים (וְשַׁעַר הַיִּחוּדִים) שֶׁעַל־יְדֵי הַכַּוָּונָה נַעֲשֶׂה לְבוּשׁ נְשָׁמָה, וְעַל־יְדֵי הַתּוֹרָה לְבוּשׁ רוּחַ דְּרוּחַ עַל־יְדֵי מִשְׁנָה דִיצִירָה, וְרוּחַ דִּנְשָׁמָה דִבְרִיאָה עַל־יְדֵי הַגְּמָרָא, יֵשׁ לוֹמַר דְּהַיְינוּ דַוְקָא עַל־יְדֵי תּוֹרַת הָאָדָם בָּעוֹלָם הַזֶּה הָעוֹלָה לְמַעְלָה. אֲבָל הַתַּלְמוּד עַצְמוֹ שֶׁנִּיתַּן בְּסִינַי הוּא בִּנְשָׁמָה, וְלָכֵן הוּא מְבָרֵר הָרוּחַ, וְכֵן בְּמִשְׁנָה דִיצִירָה."],"Tanya, Part V; Kuntres Acharon 5:1":["וּלְהָבִין פְּרָטֵי הַהֲלָכוֹת דְּלָא שְׁכִיחֵי כְּלָל, וְאֶפְשָׁר שֶׁלֹּא הָיוּ מֵעוֹלָם בִּמְצִיאוּת, מִכָּל שֶׁכֵּן שֶׁלֹּא יִהְיוּ לֶעָתִיד לָבֹא, כְּמוֹ פְּרָטֵי דִּינֵי פִּיגּוּל וּכְהַאי גַוְנָא."],"Tanya, Part V; Kuntres Acharon 6:1":["דָּוִד, זְמִירוֹת קָרִית לְהוּ כוּ׳. הִנֵּה בַּזֹּהַר: ״שְׁבָחָא דְאוֹרַיְיתָא וּרְנָנָה כוּ׳״. וּלְהָבִין, מַהוּ הַשֶּׁבַח לְהַקָּדוֹשׁ־בָּרוּךְ־הוּא כְּשֶׁזֶּה אָסוּר אוֹ מוּתָּר?"],"Tanya, Part V; Kuntres Acharon 6:8":["אַךְ מַה שֶּׁהָיָה מִשְׁתַּבֵּחַ בִּתְהִלַּת הַתּוֹרָה בְּמַעֲלָתָהּ זוֹ, וְאָמַר: ״זְמִירוֹת הָיוּ לִי כוּ׳״ נֶעֱנַשׁ עַל זֶה, וְאָמַר לוֹ הַקָּדוֹשׁ־בָּרוּךְ־הוּא ״זְמִירוֹת קָרִית לְהוּ״?! מִשּׁוּם שֶׁבֶּאֱמֶת, מַעֲלָתָהּ זוֹ – שֶׁכָּל הָעוֹלָמוֹת בְּטֵלִים לְגַבֵּי דִּקְדּוּק אֶחָד מִמֶּנָּה, הִיא מִבְּחִינַת אֲחוֹרַיִים שֶׁל עוֹמֶק הַמַּחֲשָׁבָה, כְּמוֹ שֶּׁכָּתוּב בְּמָקוֹם אַחֵר בְּשֵׁם הָאֲרִיזַ״ל עַל מַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: ״נוֹבְלוֹת חָכְמָה שֶׁלְּמַעְלָה תּוֹרָה״."],"Tanya, Part V; Kuntres Acharon 7:1":["וּצְדָקָה כְּנַחַל אֵיתָן (בְּעָמוֹס סוֹף סִימָן ה׳). פֵּירוּשׁ, כְּמוֹ שֶׁ״נַּחַל אֵיתָן״ הוּא הַמְשָׁכָה הַנִּמְשֶׁכֶת מִבְּחִינַת ״אֵיתָן״, שֶׁהִיא בְּחִינַת ״נְקוּדָּה בְּהֵיכָלָא״ וּ״תְרֵין רֵיעִין וְכוּ׳״, וְאוֹתִיּוֹת ״אֵיתָן״ מְשַׁמְּשׁוֹת לֶעָתִיד, פֵּירוּשׁ: אֲנָא עָתִיד לְאִתְגַּלְיָא, כְּמוֹ שֶׁכָּתוּב: ״הִנֵּה יַשְׂכִּיל עַבְדִּי וְגוֹ׳״, וְהַיְינוּ שֶׁיִּתְגַּלֶּה אָז אוֹר־אֵין־סוֹף בָּרוּךְ־הוּא וְיִחוּדוֹ יִתְבָּרֵךְ תּוֹךְ פְּנִימִיּת נְקוּדַּת הַלֵּב, עַל־יְדֵי הַמְשָׁכַת ״נַחַל אֵיתָן״, הוּא הֶאָרַת חָכְמָה עִילָּאָה, שֶׁיָּאִיר בִּפְנִימִיּוּת הַלֵּב, לִיבָּטֵל בְּיִחוּדוֹ יִתְבָּרֵךְ בְּתַכְלִית מֵעוּמְקָא דְלִבָּא, אַחֲרֵי הֲסָרַת הָעָרְלָה מִתַּאֲווֹת הַגַּשְׁמִיּוֹת וְכוּ׳."],"Tanya, Part V; Kuntres Acharon 8:1":["הִנֵּה, לֹא טוֹבָה הַשְּׁמוּעָה, שָׁמַעְתִּי וַתִּרְגַּז בִּטְנִי, אֲשֶׁר עַם ה׳ מַעֲבִירִים מִלִּפְנֵי הַתֵּיבָה הָאִישׁ הֶחָפֵץ בַּחַיִּים וַאֲרִיכוּת יָמִים שֶׁל כָּל אַנְשֵׁי שְׁלוֹמֵנוּ שֶׁבְּ״מִקְדָּשׁ מְעַט״ הַזֶּה שֶׁל אַנְשֵׁי שְׁלוֹמֵנוּ, כְּמַאֲמַר רַבּוֹתֵינוּ־זִכְרוֹנָם־לִבְרָכָה: שְׁלֹשָׁה דְבָרִים מַאֲרִיכִים יָמָיו שֶׁל אָדָם, וְאֶחָד מֵהֶם – הַמַּאֲרִיךְ בִּתְפִלָּתוֹ."],"Tanya, Part V; Kuntres Acharon 9:1":["הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ – ״אֲפִילוּ מֵאָה פְעָמִים״."]} as Record<string, string[]>;
export default TANYA_TEXT;
